#[test]
fn nested_match_guards_use_selected_branch_bindings_for_coverage() {
    for (ty, guard, inputs) in [
        (
            ".i8'builtin",
            "value match {0 => value == 0, other => other != 0}",
            "-128,-1,0,127",
        ),
        (
            ".i8'builtin",
            "value match {negative if negative < 0 => negative < 0, other => other >= 0}",
            "-128,-1,0,127",
        ),
        (
            ".BitVec'builtin<2>",
            "value match {0b00 => value matches 0b00, other => not (other matches 0b00)}",
            "0,1,2,3",
        ),
        (
            ".BitVec'builtin<2>",
            "value match {0b00 => true, other => other match {0b01 => true, rest => not (rest matches (0b00 or 0b01))}}",
            "0,1,2,3",
        ),
    ] {
        let calls = inputs
            .split(',')
            .map(|value| format!("classify({value})"))
            .collect::<Vec<_>>()
            .join(",");
        let source = format!(
            "typealias Input={ty};
            fn classify(value:Input)->bool {{value match {{value if ({guard}) => true}}}}
            fn run()->Tuple<bool,bool,bool,bool> {{({calls})}}"
        );
        assert_eq!(
            luna::execution::interpret(
                &execution_support::compile_with_tuple(&source),
                "run",
                100_000
            )
            .unwrap(),
            Value::Tuple(vec![Value::Bool(true); 4]),
            "{guard}"
        );
    }
}

#[test]
fn nested_match_guard_coverage_preserves_order_and_unknown_results() {
    for (ty, zero) in [(".i8'builtin", "0"), (".BitVec'builtin<2>", "0b00")] {
        for guard in [
            format!("value match {{{zero} => false, _ => true}}"),
            "value match {first => false, _ => true}".to_owned(),
            format!("value match {{{zero} => unknown(value), _ => true}}"),
            "value match {first if unknown(first) => true, _ => true}".to_owned(),
        ] {
            let source = format!(
                "typealias Input={ty};
                fn unknown(value:Input)->bool {{true}}
                fn classify(value:Input)->bool {{value match {{value if ({guard}) => true}}}}"
            );
            let error =
                execution_support::compile_with_tuple_protocols(&source, &Default::default())
                    .unwrap_err();
            assert!(error.contains("non-exhaustive match"), "{guard}: {error}");
        }
        let source = format!(
            "typealias Input={ty};
            fn unknown(value:Input)->bool {{assumes false;false}}
            fn classify(value:Input)->bool {{value match {{
                value if (value match {{first => true, _ => unknown(value)}}) => true
            }}}}
            fn run()->Tuple<bool,bool> {{(classify(0),classify(1))}}"
        );
        assert_eq!(
            luna::execution::interpret(
                &execution_support::compile_with_tuple(&source),
                "run",
                100_000
            )
            .unwrap(),
            Value::Tuple(vec![Value::Bool(true); 2])
        );
    }
}

