#[test]
fn derived_bitvec_locals_forward_through_logic_slices_and_concat() {
    for width in [0, 1, 33, 129] {
        let twice = width * 2;
        let nonempty = width != 0;
        let source = format!(
            "typealias Bits=.BitVec'builtin<{width}>;
            fn keep(comptime value:T)->T where T {{value}}
            fn forward(comptime bits:Bits)->bool {{
                let inverse=not bits;let joined=inverse ++ bits;
                let low=joined[0..{width}];let high=joined[{width}..{twice}];
                let combined=bits or inverse;let intersection=bits and inverse;
                let equal=low == bits;let unequal=high != bits;
                keep(equal) and (keep(high) == inverse) and
                    (keep(combined) == not keep(intersection)) and
                    (keep(unequal) == {nonempty})
            }}
            fn run()->bool {{forward(0)}}"
        );
        let package = compile(&source);
        assert_eq!(
            luna::execution::interpret(&package, "run", 100_000).unwrap(),
            Value::Bool(true),
            "width={width}"
        );
        let runtime = source.replace("comptime bits:", "bits:");
        assert!(compile_with_bindings(&runtime, &Default::default(), None).is_err());
    }
}

