#[test]
fn projected_comptime_record_fields_forward_through_aliases() {
    let source="comptime fn schema(...properties:T)->T where T {properties}
        const INNER=schema {flag:true};
        const SAMPLE=schema {inner:INNER,payload:(false,true)};
        typealias Options=SAMPLE'type;
        fn accept(comptime flag:bool,comptime left:bool,comptime right:bool)->bool {flag and not left and right}
        fn forward(comptime options:Options)->bool {
            let flag=options.inner.flag;let pair=options.payload;let (left,right)=pair;accept(flag,left,right)
        }
        fn entry()->bool {forward(SAMPLE)}";
    for comptime in [false, true] {
        let source = if comptime {
            source.replace("\n        fn ", "\n        comptime fn ")
        } else {
            source.into()
        };
        let package = compile(&source);
        let result = if comptime {
            luna::invocation::invoke(&package, "entry", 100_000)
        } else {
            luna::execution::interpret(&package, "entry", 100_000)
        };
        assert_eq!(result.unwrap(), Value::Bool(true));
    }
    let computed = source.replace(
        "let flag=options.inner.flag;",
        "let flag=not (not options.inner.flag);",
    );
    let package = compile(&computed);
    assert_eq!(
        luna::execution::interpret(&package, "entry", 100_000).unwrap(),
        Value::Bool(true)
    );
    let runtime = source.replace("fn forward(comptime options", "fn forward(options");
    assert!(compile_with_bindings(&runtime, &Default::default(), None).is_err());
    let escaped = source.replace(
        "let pair=options.payload;",
        "let pointer=flag.ref;pointer.* = false;let pair=options.payload;",
    );
    let package = compile(&escaped);
    let error = luna::execution::interpret(&package, "entry", 100_000).unwrap_err();
    assert!(error.contains("writes or address escape"), "{error}");
}

