#[test]
fn conditional_type_callables_specialize_selected_targets() {
    let source = "typealias Type=.Type'builtin;
        fn first(comptime T:Type,value:bool)->bool where requires T == bool {value}
        fn second(comptime T:Type,value:bool)->bool where requires T == bool {not value}
        fn generic(comptime T:Type,value:bool)->bool where X, requires T == bool {not value}
        trait Select {fn pick(comptime T:Type,value:bool)->bool where requires T == bool;}
        impl Select for bool {fn pick(comptime T:Type,value:bool)->bool where requires T == bool {value}}
        impl Select for .u8'builtin {fn pick(comptime T:Type,value:bool)->bool where requires T == bool {not value}}
        fn choose(flag:bool)->bool {let action=if flag {first} else {second};action(bool,true)}
        fn generic_choice(flag:bool)->bool {let action=if flag {first} else {generic<bool>};action(bool,true)}
        fn method_choice(flag:bool)->bool {let action=if flag {bool.as(Select).pick} else {.u8'builtin.as(Select).pick};action(bool,true)}
        fn ordered(flag:bool)->bool {
            var seen=false;
            let action=if (do {seen=true;flag}) {first} else {second};
            action(bool,(do {let before=seen;seen=false;before}))
        }
        fn entry()->Tuple<bool,bool,bool,bool,bool,bool,bool,bool> {(choose(true),choose(false),ordered(true),ordered(false),generic_choice(true),generic_choice(false),method_choice(true),method_choice(false))}";
    for comptime in [false, true] {
        let source = if comptime {
            source.replace("fn ", "comptime fn ")
        } else {
            source.into()
        };
        let package = execution_support::compile_with_tuple(&source);
        let invoke = |fuel| {
            if comptime {
                luna::invocation::invoke(&package, "entry", fuel)
            } else {
                luna::execution::interpret(&package, "entry", fuel)
            }
        };
        assert!(invoke(1).is_err());
        assert_eq!(
            invoke(100_000).unwrap(),
            Value::Tuple(vec![
                Value::Bool(true),
                Value::Bool(false),
                Value::Bool(true),
                Value::Bool(false),
                Value::Bool(true),
                Value::Bool(false),
                Value::Bool(true),
                Value::Bool(false)
            ])
        );
        let invalid = source.replace(
            "where X, requires T == bool",
            "where X, requires T == .u8'builtin",
        );
        let package = execution_support::compile_with_tuple(&invalid);
        let rejected = if comptime {
            luna::invocation::invoke(&package, "entry", 100_000)
        } else {
            luna::execution::interpret(&package, "entry", 100_000)
        }
        .unwrap_err();
        assert!(
            rejected.contains("IIR function type requirement is not established"),
            "{rejected}"
        );
    }
}

#[test]
fn stored_functions_retain_transitive_type_staging() {
    let package = compile(
        "typealias Type=.Type'builtin;
        trait Flag {comptime fn flag()->bool;}
        impl Flag for bool {comptime fn flag()->bool {true}}
        comptime fn selected(comptime T:Type)->bool where requires T :- Flag {T.as(Flag).flag()}
        comptime fn helper()->bool {selected(bool)}
        comptime fn apply(action:comptime fn()->bool)->bool {action()}
        comptime fn stored()->bool {let action=helper;action()}
        comptime fn passed()->bool {apply(helper)}
        comptime fn choose()->comptime fn()->bool {helper}
        comptime fn returned()->bool {choose()()}
        comptime fn generic()->bool where T :- Flag {selected(T)}
        comptime fn instantiated()->bool {let action=generic<bool>;apply(action)}
        comptime fn unused()->bool {let action=selected;true}
        comptime fn open_generic(comptime T:Type)->bool where X, requires T :- Flag {selected(T)}
        comptime fn unused_instance()->bool {let action=open_generic<bool>;true}
        comptime fn bound_call()->bool {let action=selected;action(bool)}
        comptime fn bound_instance()->bool {let earlier=true;let action=open_generic<bool>;action(bool)}
        comptime fn chained()->bool {let first=selected;let second=first;let third=second;third(bool)}
        trait Picker {comptime fn pick(comptime T:Type)->bool where requires T :- Flag;}
        impl Picker for bool {comptime fn pick(comptime T:Type)->bool where requires T :- Flag {selected(T)}}
        comptime fn bound_method()->bool {let action=bool.as(Picker).pick;action(bool)}
        trait DefaultPicker {comptime fn pick(comptime T:Type)->bool where requires T :- Flag {selected(T)}}
        impl DefaultPicker for bool {}
        comptime fn bound_default()->bool {let first=bool.as(DefaultPicker).pick;let second=first;second(bool)}
        comptime fn echo(comptime T:Type,value:bool)->bool where requires T :- Flag {value}
        comptime fn once()->bool {var seen=false;let action=echo;action(bool,(do {let before=seen;seen=true;not before}))}",
    );
    for entry in [
        "stored",
        "passed",
        "returned",
        "instantiated",
        "unused",
        "unused_instance",
        "bound_call",
        "bound_instance",
        "chained",
        "bound_method",
        "bound_default",
        "once",
    ] {
        assert_eq!(
            luna::invocation::invoke(&package, entry, 100_000)
                .unwrap_or_else(|error| panic!("{entry}: {error}")),
            Value::Bool(true),
            "{entry}"
        );
    }
    assert!(luna::invocation::invoke(&package, "stored", 1).is_err());
    assert_eq!(
        luna::invocation::invoke(&package, "stored", 100_000).unwrap(),
        Value::Bool(true)
    );
    // A requested execution root is not merely a retained function value.
    assert!(
        elaboration::materialization::dispatch_instances_for_roots(
            &package,
            &[iir::InstanceKey {
                declaration: id(&package, "selected"),
                arguments: vec![]
            }],
            elaboration::ptc::Budget::default(),
        )
        .is_err()
    );
    let invalid = "typealias Type=.Type'builtin;
        trait Flag {comptime fn flag()->bool;}
        comptime fn selected(comptime T:Type)->bool where requires T :- Flag {T.as(Flag).flag()}
        comptime fn bad()->bool {selected(bool)}";
    assert!(compile_with_bindings(invalid, &Default::default(), None).is_err());
    let invalid_alias = invalid.replace("{selected(bool)}", "{let action=selected;action(bool)}");
    if let Ok(package) = compile_with_bindings(&invalid_alias, &Default::default(), None) {
        assert!(luna::invocation::invoke(&package, "bad", 100_000).is_err());
    }
}

#[test]
fn stored_staged_methods_reject_erased_interface_contracts() {
    for value in [true, false] {
        let source = format!(
            "typealias Type=.Type'builtin;
            trait Guard {{comptime fn check(comptime T:Type,value:bool)->bool;}}
            impl Guard for bool {{comptime fn check(comptime T:Type,value:bool)->bool {{true}}}}
            comptime fn entry()->bool {{let first=bool.as(Guard).check;let second=first;second(bool,{value})}}"
        );
        let mut package = compile(&source);
        // Exercise materialization independently: source formation currently
        // rejects method values with program contracts. Attach only interface
        // metadata so an implementation-side check cannot mask its loss.
        let method = &mut package
            .traits
            .iter_mut()
            .find(|t| t.name == "Guard")
            .unwrap()
            .methods[0];
        method.program.preconditions.push(nir::program::Expr {
            source: nir::program::SourceRange { start: 0, end: 1 },
            ty: nir::Term::Primitive(nir::Primitive::Bool),
            kind: nir::program::ExprKind::Local(method.parameter_bindings[1]),
        });
        let error = luna::invocation::invoke(&package, "entry", 100_000).unwrap_err();
        assert!(
            error.contains("trait method value would erase program contracts"),
            "{error}"
        );
    }
}

#[test]
fn open_function_capabilities_are_checked_after_input_binding() {
    let mut package = compile(
        "typealias Type=.Type'builtin;
        trait Flag {comptime fn flag()->bool;}
        comptime fn open(comptime T:Type)->bool where X, requires T :- Flag {true}",
    );
    let declaration = id(&package, "open");
    // Isolate the capability metadata from its duplicate source predicate.
    let definition = package
        .functions
        .iter_mut()
        .find(|f| f.declaration == declaration)
        .unwrap();
    assert!(!definition.capabilities.is_empty());
    definition.requirements.clear();
    let calls = std::cell::Cell::new(0);
    let solver = |predicate: &nir::program::TypePredicate| {
        let nir::program::TypePredicate::Trait(requirement) = predicate else {
            panic!("{predicate}");
        };
        assert_eq!(
            requirement.subject,
            nir::Term::Primitive(nir::Primitive::Bool)
        );
        calls.set(calls.get() + 1);
        comptime_interpretor::ContractOutcome::Rejected
    };
    let mut vm = Interpreter::for_comptime(&package, Budget::default())
        .unwrap()
        .with_type_solver(&solver);
    for _ in 0..2 {
        let error = vm
            .invoke_instantiated(
                declaration,
                vec![nir::Term::Primitive(nir::Primitive::Bool)],
                vec![Value::Type(nir::Term::Primitive(nir::Primitive::Bool))],
            )
            .unwrap_err();
        assert_eq!(
            error.kind,
            comptime_interpretor::ErrorKind::TypeContractRejected
        );
    }
    assert_eq!(calls.get(), 2);
}

#[test]
fn ordinary_type_static_methods_survive_higher_order_comptime_calls() {
    let prefix = "typealias Type=.Type'builtin;
        trait Flag {comptime fn flag()->bool;}
        impl Flag for bool {comptime fn flag()->bool {true}}
        impl Flag for .u8'builtin {comptime fn flag()->bool {false}}
        comptime fn apply(action:comptime fn()->bool)->bool {action()}
        comptime fn selected(comptime T:Type)->comptime fn()->bool
        where requires T :- Flag {T.as(Flag).flag}";
    let package=execution_support::compile_with_tuple(&format!("{prefix}
        comptime fn stored(comptime T:Type)->bool where requires T :- Flag {{let action=T.as(Flag).flag;apply(action)}}
        comptime fn entry()->Tuple<bool,bool,bool> {{(stored(bool),selected(.u8'builtin)(),apply(selected(bool)))}}
        trait Thunk {{comptime fn run()->bool;}}
        impl Thunk for bool {{comptime fn run()->bool {{selected(bool)()}}}}
        comptime fn hidden()->bool {{let action=bool.as(Thunk).run;action()}}
        trait DefaultThunk :- Flag {{comptime fn run()->bool {{selected(Self)()}}}}
        impl DefaultThunk for bool {{}}
        comptime fn hidden_default()->bool {{let action=bool.as(DefaultThunk).run;apply(action)}}"));
    assert_eq!(
        luna::invocation::invoke(&package, "entry", 100_000).unwrap(),
        Value::Tuple(vec![
            Value::Bool(true),
            Value::Bool(false),
            Value::Bool(true)
        ])
    );
    assert_eq!(
        luna::invocation::invoke(&package, "hidden", 100_000).unwrap(),
        Value::Bool(true)
    );

    assert_eq!(
        luna::invocation::invoke(&package, "hidden_default", 100_000).unwrap(),
        Value::Bool(true)
    );
    let invalid = format!(
        "{prefix} comptime fn wrong(comptime T:Type)->fn()->bool
        where requires T :- Flag {{T.as(Flag).flag}}"
    );
    assert!(
        execution_support::compile_with_tuple_protocols(&invalid, &Default::default()).is_err()
    );
}

