#[test]
fn automatic_splice_comptime_results_keep_runtime_cleanup_obligations() {
    let source = "typealias Type=.Type'builtin;
        trait Copy {} trait Drop {fn drop(*self);}
        trait Splice {assoc RuntimeTarget:Type;fn splice(comptime data:Self)->RuntimeTarget;}
        struct Token {valid:bool,}
        impl Drop for Token {fn drop(*self) {let valid=self.valid.*;assumes valid;}}
        impl Splice for bool {assoc RuntimeTarget:Type=Token;fn splice(comptime data:bool)->Token {Token {valid:data}}}
        comptime fn identity(value:bool)->bool {value}
        fn good()->bool {let token=identity(true);true}
        fn bad()->bool {let token=identity(false);true}";
    for source in [
        source.to_owned(),
        source.replace("{Token {valid:data}}", "= Token {valid:data};"),
    ] {
        let package = compile_with_bindings(&source, &Default::default(), Some("Splice")).unwrap();
        assert_eq!(
            luna::execution::interpret_with_protocols(&package, "good", "Copy", "Drop", 100_000)
                .unwrap(),
            Value::Bool(true)
        );
        let error =
            luna::execution::interpret_with_protocols(&package, "bad", "Copy", "Drop", 100_000)
                .unwrap_err();
        assert!(error.contains("ProgramContractRejected"), "{error}");
    }
}

#[test]
fn automatic_splice_uses_bound_identity_and_runs_each_conversion() {
    let explicit = include_str!("../../../development/examples/explicit-splice.fl");
    let baseline = compile_explicit_splice(explicit);
    let protocols = elaboration::program::Protocols {
        splice: Some(baseline.traits[0].declaration),
        ..Default::default()
    };
    let source = explicit
        .replace("bool.as(Splice).splice(FLAG)", "FLAG")
        .replace("bool.as(Splice).splice(false)", "OTHER")
        + "\nconst OTHER = false;";
    assert!(
        compile_explicit_splice_with_protocols(&source, &Default::default())
            .unwrap_err()
            .contains("bound Splice")
    );
    for source in [
        source.clone(),
        source
            .replace("trait Splice", "trait Conversion")
            .replace("impl Splice", "impl Conversion"),
    ] {
        let package = compile_explicit_splice_with_protocols(&source, &protocols).unwrap();
        let graph = luna::instantiation::instantiate(&package, "run", 100_000).unwrap();
        let mut vm = Interpreter::from_iir(&graph, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke_instance(&graph.roots[0], vec![]).unwrap(),
            Value::Tuple(vec![
                Value::Tuple(vec![Value::Bool(true), Value::Bool(false)]),
                Value::Tuple(vec![Value::Bool(false), Value::Bool(true)]),
            ])
        );
        assert_eq!(
            calls(&package, &vm)
                .iter()
                .filter(|name| **name == "construct")
                .count(),
            2
        );
    }
    let mut foreign = protocols.clone();
    foreign.splice.as_mut().unwrap().package += 1;
    assert!(
        compile_explicit_splice_with_protocols(&source, &foreign)
            .unwrap_err()
            .contains("not a declared trait")
    );
}

#[test]
fn automatic_splice_keeps_staged_inputs_and_runtime_failures_separate() {
    let explicit = include_str!("../../../development/examples/explicit-splice.fl");
    let baseline = compile_explicit_splice(explicit);
    let protocols = elaboration::program::Protocols {
        splice: Some(baseline.traits[0].declaration),
        ..Default::default()
    };
    let source = format!(
        "{explicit}
        fn staged(comptime flag:bool)->bool {{flag}}
        fn take(value:Tuple<bool,bool>)->Tuple<bool,bool> {{value}}
        fn forward()->Tuple<bool,bool> {{take(FLAG)}}
        fn mixed()->Tuple<bool,Tuple<bool,bool>> {{(staged(FLAG),FLAG)}}
        const BAD = false;
        fn fail()->Tuple<bool,bool> {{BAD}}"
    );
    let source = source.replace("construct(data)", "assumes data; construct(data)");
    let package = compile_explicit_splice_with_protocols(&source, &protocols).unwrap();
    for entry in ["mixed", "forward"] {
        let graph = luna::instantiation::instantiate(&package, entry, 100_000).unwrap();
        let mut vm = Interpreter::from_iir(&graph, Budget::default()).unwrap();
        let converted = Value::Tuple(vec![Value::Bool(true), Value::Bool(false)]);
        let expected = if entry == "mixed" {
            Value::Tuple(vec![Value::Bool(true), converted])
        } else {
            converted
        };
        assert_eq!(
            vm.invoke_instance(&graph.roots[0], vec![]).unwrap(),
            expected
        );
        assert_eq!(
            calls(&package, &vm)
                .iter()
                .filter(|name| **name == "splice")
                .count(),
            1
        );
    }
    let graph = luna::instantiation::instantiate(&package, "fail", 100_000).unwrap();
    let mut vm = Interpreter::from_iir(&graph, Budget::default()).unwrap();
    assert_eq!(
        vm.invoke_instance(&graph.roots[0], vec![])
            .unwrap_err()
            .kind,
        ErrorKind::ProgramContractRejected
    );
    assert!(!calls(&package, &vm).iter().any(|name| name == "construct"));
    let wrong_target = format!("{explicit} fn wrong()->bool {{FLAG}}");
    assert!(compile_explicit_splice_with_protocols(&wrong_target, &protocols).is_err());
    // A spelling-identical trait without the required protocol surface must
    // not be accepted merely because it has an applicable implementation.
    let malformed = explicit
        .replace("comptime data: Self", "data: Self")
        .replace("comptime data: bool", "data: bool")
        .replace("bool.as(Splice).splice(FLAG)", "FLAG");
    assert!(
        compile_explicit_splice_with_protocols(&malformed, &protocols)
            .unwrap_err()
            .contains("runtime fn splice(comptime data: Self)")
    );
}

#[test]
fn automatic_splice_specializes_structural_comptime_values() {
    let declarations = "typealias Type=.Type'builtin;
        trait Splice {assoc RuntimeTarget:Type;fn splice(comptime data:Self)->RuntimeTarget;}
        comptime fn schema(...fields:T)->T where T {fields}
        const OPTIONS=schema {enabled:true,nested:schema {disabled:false}};
        typealias Config=OPTIONS'type;
        impl Splice for Config {
            assoc RuntimeTarget:Type=bool;
            fn splice(comptime config:Config)->bool {config.enabled and not config.nested.disabled}
        }";
    let baseline = compile(&format!(
        "{declarations} fn run()->bool {{Config.as(Splice).splice(OPTIONS)}}"
    ));
    let protocols = elaboration::program::Protocols {
        splice: Some(baseline.traits[0].declaration),
        ..Default::default()
    };
    let source = format!("{declarations} fn run()->bool {{let converted=OPTIONS;converted}}");
    let package = compile_with_protocols(&source, &protocols).unwrap();
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    let missing = source
        .replace("impl Splice for Config", "impl Splice for bool")
        .replace("comptime config:Config", "comptime config:bool")
        .replace("config.enabled and not config.nested.disabled", "config");
    assert!(compile_with_protocols(&missing, &protocols).is_err());
}

