#[test]
fn splice_protocol_requires_bound_identity_and_runtime_staged_signature() {
    use intrinsic::{LangItem, LangItemDef, LangItems};
    use luna::protocols::splice::protocol;
    let package = compile_explicit_splice(include_str!(
        "../../../development/examples/explicit-splice.fl"
    ));
    let id = package.traits[0].declaration;
    let mut items = LangItems::new();
    assert!(protocol(&package, &items).is_err());
    items
        .bind_source_traits(&package, &[(LangItem::Splice, id)])
        .unwrap();
    let checked = protocol(&package, &items).unwrap();
    assert_eq!(checked.interface.declaration, id);
    assert!(
        checked
            .to_string()
            .starts_with("(splice-protocol (interface (declaration")
    );
    let mut renamed = package.clone();
    renamed.traits[0].name = "DifferentSpelling".into();
    protocol(&renamed, &items).unwrap();

    for case in 0..8 {
        let mut invalid = package.clone();
        let interface = &mut invalid.traits[0];
        match case {
            0 => {
                interface.methods[0].signature = interface.methods[0]
                    .signature
                    .ordinary()
                    .unwrap()
                    .clone()
                    .with_comptime_phase(true)
                    .into()
            }
            1 => {
                if let nir::code_interfaces::MethodSignature::Callable(nir::Term::Function {
                    parameters,
                    ..
                }) = &mut interface.methods[0].signature
                {
                    parameters[0].sort = nir::Sort::Runtime;
                }
            }
            2 => interface.associated[0].ty = nir::Term::Primitive(nir::Primitive::Bool),
            3 => interface.methods.push(interface.methods[0].clone()),
            4 => interface.associated.push(interface.associated[0].clone()),
            5 => interface.declaration.package += 1,
            6 => {
                if let nir::code_interfaces::MethodSignature::Callable(nir::Term::Function {
                    result,
                    ..
                }) = &mut interface.methods[0].signature
                {
                    *result = Box::new(nir::Term::Primitive(nir::Primitive::Bool));
                }
            }
            _ => interface.methods[0].by_value_receiver = true,
        }
        assert!(
            protocol(&invalid, &items).is_err(),
            "accepted malformed protocol {case}"
        );
        protocol(&package, &items).unwrap();
    }
    let mut builtin = LangItems::new();
    builtin.set(LangItem::Splice, LangItemDef::Builtin).unwrap();
    assert!(protocol(&package, &builtin).is_err());
}

