#[test]
fn extended_post_do_routes_receiver_methods_and_reordered_markers() {
    let schema = "comptime fn schema(...properties:T)->T where T {properties} const SAMPLE=schema {flag:true};typealias Options=SAMPLE'type;struct Host {}";
    for (definition, access) in [
        (
            "impl Host {fn apply(*self,lambda action:fn(bool)->bool,value:bool,...properties:Options)->bool {properties.flag and action(value)}}",
            "host.apply",
        ),
        (
            "trait Apply {fn apply(*self,lambda action:fn(bool)->bool,value:bool,...properties:Options)->bool;} impl Apply for Host {fn apply(*self,action:fn(bool)->bool,value:bool,properties:Options)->bool {properties.flag and action(value)}}",
            "host.as(Apply).apply",
        ),
    ] {
        let package = compile(&format!(
            "{schema} {definition} fn run()->bool {{let host=Host {{}};{access} {{true,flag:true}} do {{_0}}}}"
        ));
        assert_eq!(
            luna::execution::interpret(&package, "run", 100_000).unwrap(),
            Value::Bool(true)
        );
    }
}

#[test]
fn extended_post_do_preserves_property_order_and_marked_target() {
    let schema = "comptime fn schema(...properties:T)->T where T {properties} const SAMPLE=schema {flag:true};typealias Options=SAMPLE'type;";
    for call in [
        "apply {first(),flag:property(),last()} do |a,b| body(a,b)",
        "apply {first(),flag:property(),last()} do {body(_0,_1)}",
        "apply {body(_0,_1),first(),flag:property(),last()}",
    ] {
        let package = compile(&format!(
            "{schema} fn first()->bool {{true}} fn property()->bool {{true}} fn last()->bool {{false}} fn body(a:bool,b:bool)->bool {{a and not b}} fn apply(lambda action:fn(bool,bool)->bool,a:bool,...properties:Options,b:bool)->bool {{properties.flag and action(a,b)}} fn run()->bool {{{call}}}"
        ));
        let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke(id(&package, "run"), vec![]).unwrap(),
            Value::Bool(true),
            "{call}"
        );
        assert_eq!(
            calls(&package, &vm),
            vec!["run", "first", "property", "last", "apply", "body"],
            "{call}"
        );
        assert_eq!(
            luna::execution::interpret(&package, "run", 100_000).unwrap(),
            Value::Bool(true)
        );
    }
}

