#[test]
fn tactic_lambda_uses_full_target_arity_and_shared_parameter_bindings() {
    for (body, expected) in [
        ("_0", true),
        ("_1", false),
        ("_0 == _0", true),
        ("_0 and not _1", true),
    ] {
        let package = compile(&format!(
            "fn apply(first:bool,second:bool,lambda action:fn(bool,bool)->bool)->bool {{action(first,second)}} fn run()->bool {{apply(true,false,{body})}}"
        ));
        assert_eq!(
            luna::execution::interpret(&package, "run", 100_000).unwrap(),
            Value::Bool(expected),
            "{body}"
        );
        let run = package.functions.iter().find(|f| f.name == "run").unwrap();
        let mut arities = Vec::new();
        iir::visit::expressions(run, &mut 100_000, |expr, _| {
            if let nir::program::ExprKind::Closure { parameters, .. } = &expr.kind {
                arities.push(parameters.len());
            }
            Ok(())
        })
        .unwrap();
        assert_eq!(arities, vec![2]);
    }
}

#[test]
fn tactic_lambda_preserves_nested_marked_and_ordinary_expression_boundaries() {
    for source in [
        "fn outer(lambda action:fn(bool)->bool)->bool {action(true)} fn inner(lambda action:fn(bool)->bool)->bool {action(false)} fn run()->bool {outer(_0 and not inner(_0))}",
        "fn identity(value:bool)->bool {value} fn apply(lambda action:fn(bool)->bool)->bool {action(true)} fn run()->bool {apply(identity(_0))}",
        "fn apply(lambda action:fn(bool)->bool)->bool {action(true)} fn run()->bool {apply() do {_0}}",
        "fn apply(lambda action:fn(bool,bool)->bool)->bool {action(true,false)} fn run()->bool {apply() do {true}}",
        "fn apply(lambda action:fn(T)->T,value:T)->T where T {action(value)} fn run()->bool {apply(_0,...(true,))}",
        "fn apply(lambda action:fn(T)->T,value:T)->T where T {action(value)} fn run()->bool {apply(_0,true)}",
        "fn apply(lambda action:fn(bool)->Tuple<bool,bool>)->bool {let (a,b)=action(true);a and b} fn run()->bool {apply((_0,_0))}",
        "fn identity(value:bool)->bool {value} fn apply(lambda action:fn(bool)->bool)->bool {action(true)} fn run()->bool {apply(identity)}",
        "fn apply(lambda action:%{flag:bool} fn(bool)->bool)->bool {action(true)} fn run()->bool {let flag=true;apply(_0 and flag)}",
        "enum Choice {none,some(bool),} fn apply(lambda action:fn(bool)->Choice)->bool {action(true) match {.some(value)=>value,.none=>false,}} fn run()->bool {apply(.some(_0))}",
    ] {
        let package = execution_support::compile_with_tuple(source);
        assert_eq!(
            luna::execution::interpret(&package, "run", 100_000).unwrap(),
            Value::Bool(true),
            "{source}"
        );
    }
}

