#[test]
fn direct_passing_usage_match_preserves_branch_returns_and_guard_fallthrough() {
    let prefix = "trait Duplicate {} trait Retire {fn drop(*self);} struct Token {} ^attrs.effects.direct_passing effect token()->Token;";
    for flag in [false, true] {
        for body in [
            "flag match {true=>{return token()#;},false=>{},};token()#",
            "flag match {_ if flag=>{return token()#;},_=>{},};token()#",
            "true match {false if do {let ignored=token()#;true}=>{},_=>{},};token()#",
            "flag match {_=>{return token()#;},true=>{let first=token()#;return token()#;},}",
            "let value if flag = true else {return token()#;};token()#",
            "flag match {_ if do {let ignored=token()#;false}=>{let second=token()#;},_=>{},};Token {}",
            "flag match {_ if do {let ignored=token()#;true}=>{},_=>{let second=token()#;},};Token {}",
        ] {
            let package = compile(&format!(
                "{prefix} fn subject(flag:bool)->#token Token {{{body}}} fn run()->Token {{subject({flag})# {{token()=>Token {{}},}}}}"
            ));
            assert!(
                matches!(
                    luna::execution::interpret_effects_with_protocols(
                        &package,
                        "run",
                        "Duplicate",
                        "Retire",
                        100_000
                    )
                    .unwrap(),
                    Value::Record { .. }
                ),
                "{body}"
            );
        }
    }
}

#[test]
fn direct_passing_usage_match_retains_consumption_from_failed_guards() {
    let prefix = "trait Duplicate {} trait Retire {fn drop(*self);} struct Token {} ^attrs.effects.direct_passing effect token()->Token;";
    for body in [
        "flag match {_ if do {let ignored=token()#;false}=>{},_=>{},};token()#",
        "flag match {true=>{let first=token()#;},false=>{},};token()#",
        "let value if do {let ignored=token()#;false} = true else {return token()#;};token()#",
    ] {
        let package = compile(&format!(
            "{prefix} fn subject(flag:bool)->#token Token {{{body}}} fn run()->Token {{subject(true)# {{token()=>Token {{}},}}}}"
        ));
        let error = luna::execution::interpret_effects_with_protocols(
            &package,
            "run",
            "Duplicate",
            "Retire",
            100_000,
        )
        .unwrap_err();
        assert!(error.contains("affine effect slot"), "{body}: {error}");
    }
}

#[test]
fn direct_passing_usage_tracks_selected_factory_values() {
    let prefix = "trait Duplicate {} trait Retire {fn drop(*self);} struct Token {} ^attrs.effects.direct_passing effect token()->Token; fn one()->#token Token {token()#} fn twice()->#token Token {let lost=token()#;token()#} typealias Callback=fn()->#token Token; typealias Factory=fn()->Callback; fn good()->Callback {one} fn bad()->Callback {twice} struct Makers {make:Factory,} fn maker()->Factory {good} fn make_record()->Makers {Makers {make:good}}";
    for (body, accepted) in [
        ("let make=good;make()()", true),
        ("let make=bad;make()()", false),
        ("let make=if flag {good} else {good};make()()", true),
        ("let make=if flag {good} else {bad};make()()", false),
        (
            "let make=false match {true=>bad,false=>good,};make()()",
            true,
        ),
        (
            "let make=flag match {_ if false=>bad,_=>good,};make()()",
            true,
        ),
        ("let (make,)=(good,);make()()", true),
        ("let makers=Makers {make:good};makers.make()()", true),
        ("let makers=Makers {make:bad};makers.make()()", false),
        ("let {make}=Makers {make:good};make()()", true),
        ("(do {good})()()", true),
        ("(do {let lost=token()#;good})()()", false),
        ("maker()()()", true),
        ("let make=|| one;make()()", true),
        ("let make=|| {return one;};make()()", true),
        ("let make=|| twice;make()()", false),
        (
            "let make:fn()->#token Callback=|| {let lost=token()#;one};make()()",
            false,
        ),
        ("make_record().make()()", true),
        ("var make=good;make=bad;make()()", false),
        ("let make=good;let p=make.ref;make()()", false),
        ("let make=good;let lost=make()();make()()", false),
    ] {
        for flag in [false, true] {
            let package = compile(&format!(
                "{prefix} fn subject(flag:bool)->#token Token {{{body}}} fn run()->Token {{subject({flag})# {{token()=>Token {{}},}}}}"
            ));
            let result = luna::execution::interpret_effects_with_protocols(
                &package,
                "run",
                "Duplicate",
                "Retire",
                100_000,
            );
            if accepted {
                assert!(matches!(result.unwrap(), Value::Record { .. }), "{body}");
            } else {
                let error = result.unwrap_err();
                assert!(error.contains("affine effect slot"), "{body}: {error}");
            }
        }
    }
}

#[test]
fn direct_passing_usage_tracks_factory_returned_aggregate_callables() {
    let prefix = "trait Duplicate {} trait Retire {fn drop(*self);} struct Token {} ^attrs.effects.direct_passing effect token()->Token; fn one()->#token Token {token()#} fn twice()->#token Token {let lost=token()#;token()#} typealias Callback=fn()->#token Token; struct Action {call:Callback,} struct Nested {action:Action,} enum Choice {none,some(Action),}";
    for (factory, body, accepted) in [
        (
            "fn make(flag:bool)->Action {Action {call:one}}",
            "make(flag).call()",
            true,
        ),
        (
            "fn make(flag:bool)->Action {Action {call:twice}}",
            "make(flag).call()",
            false,
        ),
        (
            "fn make(flag:bool)->Action {if flag {return Action {call:twice};} Action {call:one}}",
            "make(flag).call()",
            false,
        ),
        (
            "fn make(flag:bool)->Action {let action=Action {call:one};action}",
            "let {call:f}=make(flag);f()",
            true,
        ),
        (
            "fn make(flag:bool)->Nested {Nested {action:Action {call:one}}}",
            "make(flag).action.call()",
            true,
        ),
        (
            "fn make(flag:bool)->Tuple<Callback, Callback> {(one,twice)}",
            "let (f,_)=make(flag);f()",
            true,
        ),
        (
            "fn make(flag:bool)->Tuple<Callback, Callback> {(one,twice)}",
            "let (_,f)=make(flag);f()",
            false,
        ),
        (
            "fn make(flag:bool)->Choice {Choice.some(Action {call:one})}",
            "let .some({call:f})=make(flag) else {return Token {};};f()",
            true,
        ),
        (
            "fn make(flag:bool)->Choice {Choice.some(Action {call:twice})}",
            "let .some({call:f})=make(flag) else {return Token {};};f()",
            false,
        ),
        (
            "fn inner()->Action {Action {call:one}} fn make(flag:bool)->Action {inner()}",
            "make(flag).call()",
            true,
        ),
        (
            "fn make(flag:bool)->#token Action {let lost=token()#;Action {call:one}}",
            "make(flag).call()",
            false,
        ),
        (
            "fn make(flag:bool)->Action {Action {call:one}}",
            "var action=make(flag);action.call=twice;action.call()",
            false,
        ),
        (
            "fn make(flag:bool)->Action {Action {call:one}}",
            "let action=make(flag);let p=action.ref;action.call()",
            false,
        ),
        (
            "fn make(value:T)->Action where T {Action {call:one}}",
            "make(flag).call()",
            true,
        ),
    ] {
        for flag in [false, true] {
            let package = execution_support::compile_with_tuple(&format!(
                "{prefix} {factory} fn subject(flag:bool)->#token Token {{{body}}} fn run()->Token {{subject({flag})# {{token()=>Token {{}},}}}}"
            ));
            let result = luna::execution::interpret_effects_with_protocols(
                &package,
                "run",
                "Duplicate",
                "Retire",
                100_000,
            );
            if accepted {
                assert!(
                    matches!(result.unwrap(), Value::Record { .. }),
                    "{factory}: {body}"
                );
            } else {
                let error = result.unwrap_err();
                assert!(
                    error.contains("affine effect slot"),
                    "{factory}: {body}: {error}"
                );
            }
        }
    }
}

