#[test]
fn direct_passing_usage_factory_dependencies_converge_in_both_orders() {
    for (factory, expected) in [("one", 1), ("twice", 2)] {
        let package = compile(&format!(
            "^attrs.effects.direct_passing effect hit()->bool; fn one()->#hit bool {{hit()#}} fn twice()->#hit bool {{let lost=hit()#;hit()#}} fn make()->fn()->#hit bool {{{factory}}} fn subject()->#hit bool {{make()()}} fn entry()->bool {{subject()# {{hit()=>true,}}}}"
        ));
        let key = iir::InstanceKey {
            declaration: id(&package, "entry"),
            arguments: vec![],
        };
        let mut graph = elaboration::materialization::instantiate(
            &package,
            &[key.clone()],
            Default::default(),
            elaboration::ptc::Budget::default(),
        )
        .unwrap();
        for _ in 0..2 {
            graph.functions.reverse();
            let plan = iir::effect_values::Plan::acquire(&graph, &mut 100_000, |_, _| {
                Ok(iir::effect_values::Delivery::Copy)
            })
            .unwrap();
            assert!(elaboration::verification::effect_usage::check(&graph, &plan, &mut 1).is_err());
            let report =
                elaboration::verification::effect_usage::check(&graph, &plan, &mut 100_000)
                    .unwrap();
            assert_eq!(report.installations.len(), 1);
            assert_eq!(report.installations[0].upper, expected);
            let mut vm = Interpreter::from_iir(&graph, Budget::default())
                .unwrap()
                .with_effect_values(&plan)
                .unwrap();
            assert_eq!(vm.invoke_instance(&key, vec![]).unwrap(), Value::Bool(true));
        }
    }
}

