#[test]
fn direct_passing_usage_normal_boolean_results_preserve_prefix_effects() {
    let prefix = "trait Duplicate {} trait Retire {fn drop(*self);} struct Token {} ^attrs.effects.direct_passing effect token()->Token; fn one()->#token bool {let value=token()#;true} fn twice()->#token bool {one() and one()}";
    for (body, accepted) in [
        ("if do {true} {one()} else {twice()}", true),
        ("if not do {false} {one()} else {twice()}", true),
        ("(do {false}) and twice();true", true),
        ("(do {one();false}) and one();true", true),
        ("(do {one();true}) or one()", true),
        ("(if do {true} {one} else {twice})()", true),
        ("if do {return true;false} {twice()} else {twice()}", true),
        ("(do {one();true}) and one()", false),
        ("(do {one();false}) or one()", false),
        ("if do {one();true} {one()} else {false}", false),
    ] {
        let package = compile(&format!(
            "{prefix} fn subject()->#token bool {{{body}}} fn run()->bool {{subject()# {{token()=>Token {{}},}}}}"
        ));
        let result = luna::execution::interpret_effects_with_protocols(
            &package,
            "run",
            "Duplicate",
            "Retire",
            100_000,
        );
        if accepted {
            assert_eq!(result.unwrap(), Value::Bool(true), "{body}");
        } else {
            assert!(result.unwrap_err().contains("affine effect slot"), "{body}");
        }
    }
    let package = compile(&format!(
        "{prefix} fn subject()->#token bool {{assumes do {{false}};twice()}} fn run()->bool {{subject()# {{token()=>Token {{}},}}}}"
    ));
    assert!(
        luna::execution::interpret_effects_with_protocols(
            &package,
            "run",
            "Duplicate",
            "Retire",
            100_000
        )
        .unwrap_err()
        .contains("ProgramContractRejected")
    );
}

#[test]
fn direct_passing_usage_upper_bounds_reference_execution_across_compositions() {
    let prefix = "^attrs.effects.direct_passing effect token()->bool; fn hit()->#token bool {token()#} fn one()->#token bool {hit()} fn twice()->#token bool {let first=hit();hit()} struct Action {call:fn()->#token bool,} enum Choice {none,some(fn()->#token bool),}";
    let mut observed = std::collections::BTreeSet::new();
    for selector in [
        "one",
        "twice",
        "if flag {one} else {twice}",
        "do {let ignored=hit();one}",
    ] {
        let wrappers = [
            format!("({selector})()"),
            format!("let f={selector};f()"),
            format!("let (f,unused)=({selector},false);f()"),
            format!("let action=Action {{call:{selector}}};action.call()"),
            format!("let .some(f)=Choice.some({selector}) else {{return false;}};f()"),
            format!("let (unused and {selector} is f)=false else {{return false;}};f()"),
            format!(
                "let ((true,f,_) or (false,_,f))=(flag,{selector},{selector}) else {{return false;}};f()"
            ),
            format!("let (f,) if flag = ({selector},) else {{return false;}};f()"),
            format!(
                "let (f,) if do {{let ignored=hit();flag}} = ({selector},) else {{return false;}};f()"
            ),
            format!(
                "var (f,) if do {{if flag {{f=twice;}}true}} = ({selector},) else {{return false;}};f()"
            ),
            format!("({selector},false) match {{(f,_)=>f(),}}"),
            format!("Action {{call:{selector}}} match {{{{call:f}}=>f(),}}"),
            format!("Choice.some({selector}) match {{.some(f)=>f(),.none=>false,}}"),
            format!(
                "({selector},false) match {{(f,_) if do {{let ignored=hit();flag}}=>f(),_=>false,}}"
            ),
            "factory(flag)()".into(),
            "let make=factory;make(flag)()".into(),
            "let (make,)=(factory,);make(flag)()".into(),
            format!("let make:fn(bool)->#token FactoryCallback=|flag| {{{selector}}};make(flag)()"),
            "record_factory(flag).call()".into(),
            "let (f,)=tuple_factory(flag);f()".into(),
            "let .some(f)=variant_factory(flag) else {return false;};f()".into(),
        ];
        for wrapped in wrappers {
            for body in [
                wrapped.clone(),
                format!("false and do {{{wrapped}}}"),
                format!("if flag {{do {{{wrapped}}}}} else {{false}}"),
                format!("let value=do {{{wrapped}}};hit()"),
            ] {
                for flag in [false, true] {
                    let factories = format!(
                        "typealias FactoryCallback=fn()->#token bool; typealias FactoryPacket=Tuple<FactoryCallback>; fn factory(flag:bool)->#token FactoryCallback {{{selector}}} fn record_factory(flag:bool)->#token Action {{Action {{call:{selector}}}}} fn tuple_factory(flag:bool)->#token FactoryPacket {{({selector},)}} fn variant_factory(flag:bool)->#token Choice {{Choice.some({selector})}}"
                    );
                    let package = execution_support::compile_with_tuple(&format!(
                        "{prefix} {factories} fn subject(flag:bool)->#token bool {{{body}}} fn entry()->bool {{subject({flag})# {{token()=>true,}}}}"
                    ));
                    let hit = id(&package, "hit");
                    let key = iir::InstanceKey {
                        declaration: id(&package, "entry"),
                        arguments: vec![],
                    };
                    let graph = elaboration::materialization::instantiate(
                        &package,
                        &[key.clone()],
                        Default::default(),
                        elaboration::ptc::Budget::default(),
                    )
                    .unwrap();
                    let plan = iir::effect_values::Plan::acquire(&graph, &mut 100_000, |ty, _| {
                        assert_eq!(*ty, nir::Term::Primitive(nir::Primitive::Bool));
                        Ok(iir::effect_values::Delivery::Copy)
                    })
                    .unwrap();
                    let report =
                        elaboration::verification::effect_usage::check(&graph, &plan, &mut 100_000)
                            .unwrap();
                    assert_eq!(report.installations.len(), 1);
                    let mut vm = Interpreter::from_iir(&graph, Budget::default())
                        .unwrap()
                        .with_effect_values(&plan)
                        .unwrap();
                    vm.invoke_instance(&key, vec![]).unwrap();
                    // Each hit body makes exactly one request. Count actual VM
                    // function entries independently of the static analysis.
                    let actual = vm.events().iter().filter(|event| matches!(event, Event::EnterFunction(declaration) if *declaration == hit)).count().min(2) as u8;
                    observed.insert(actual);
                    assert!(
                        report.installations[0].upper >= actual,
                        "underestimated {body}, flag={flag}: static={}, actual={actual}",
                        report.installations[0].upper
                    );
                    if selector == "one"
                        && body == wrapped
                        && !wrapped.contains("let ignored=hit();")
                        && !wrapped.contains("f=twice")
                    {
                        assert_eq!(report.installations[0].upper, 1, "lost precision: {body}");
                    }
                }
            }
        }
    }
    assert_eq!(observed.into_iter().collect::<Vec<_>>(), vec![0, 1, 2]);
}

