#[test]
fn direct_passing_usage_worklist_revisits_recursive_and_late_handler_dependencies() {
    let prefix = "struct Token {} ^attrs.effects.direct_passing effect token()->Token;";
    for declarations in [
        "effect ask()->bool; fn subject()->#token bool {request()# {ask()=>provider(),}} fn request()->#ask bool {ask()#} fn provider()->#token bool {leaf() and leaf()} fn leaf()->#token bool {let value=token()#;true}",
        "fn subject()->#token bool {first(true)} fn first(flag:bool)->#token bool {let value=token()#;if flag {second(false)} else {true}} fn second(flag:bool)->#token bool {first(flag)}",
    ] {
        let package = compile(&format!(
            "{prefix} {declarations} fn entry()->bool {{subject()# {{token()=>Token {{}},}}}}"
        ));
        let key = iir::InstanceKey {
            declaration: id(&package, "entry"),
            arguments: vec![],
        };
        let mut graph = elaboration::materialization::instantiate(
            &package,
            &[key],
            Default::default(),
            elaboration::ptc::Budget::default(),
        )
        .unwrap();
        for _ in 0..2 {
            graph.functions.reverse();
            let plan = iir::effect_values::Plan::acquire(&graph, &mut 100_000, |_, _| {
                Ok(iir::effect_values::Delivery::Copy)
            })
            .unwrap();
            assert!(elaboration::verification::effect_usage::check(&graph, &plan, &mut 1).is_err());
            let report =
                elaboration::verification::effect_usage::check(&graph, &plan, &mut 100_000)
                    .unwrap();
            assert_eq!(report.installations.len(), 1);
            assert_eq!(report.installations[0].upper, 2, "{declarations}");
        }
    }
}

#[test]
fn direct_passing_usage_worklist_scales_with_reverse_ordered_call_chain() {
    let mut costs = vec![];
    for count in [8, 32] {
        let mut source =
            "struct Token {} ^attrs.effects.direct_passing effect token()->Token;".to_string();
        for index in 0..count {
            let body = if index + 1 == count {
                "token()#".to_string()
            } else {
                format!("step{}()", index + 1)
            };
            source.push_str(&format!("fn step{index}()->#token Token {{{body}}}"));
        }
        source.push_str("fn entry()->Token {step0()# {token()=>Token {},}}");
        let package = compile(&source);
        let key = iir::InstanceKey {
            declaration: id(&package, "entry"),
            arguments: vec![],
        };
        let mut graph = elaboration::materialization::instantiate(
            &package,
            &[key],
            Default::default(),
            elaboration::ptc::Budget::default(),
        )
        .unwrap();
        graph.functions.sort_by_key(|f| {
            f.function
                .name
                .strip_prefix("step")
                .and_then(|n| n.parse::<usize>().ok())
                .unwrap_or(usize::MAX)
        });
        let plan = iir::effect_values::Plan::acquire(&graph, &mut 100_000, |_, _| {
            Ok(iir::effect_values::Delivery::Move)
        })
        .unwrap();
        let mut fuel = 1_000_000;
        let report =
            elaboration::verification::effect_usage::check(&graph, &plan, &mut fuel).unwrap();
        assert_eq!(report.installations[0].upper, 1);
        costs.push(1_000_000 - fuel);
        let expected = report.to_string();
        drop(plan);
        graph.functions.reverse();
        let plan = iir::effect_values::Plan::acquire(&graph, &mut 100_000, |_, _| {
            Ok(iir::effect_values::Delivery::Move)
        })
        .unwrap();
        assert_eq!(
            elaboration::verification::effect_usage::check(&graph, &plan, &mut 1_000_000)
                .unwrap()
                .to_string(),
            expected
        );
    }
    eprintln!("reverse call-chain costs: {costs:?}");
    assert!(
        costs[1] < costs[0] * 5,
        "whole-graph fixed-point rescanning: {costs:?}"
    );
}

#[test]
fn direct_passing_usage_instance_index_keeps_generic_summaries_distinct() {
    use nir::program::ExprKind as K;
    let package = compile(
        "struct Token {} ^attrs.effects.direct_passing effect token()->Token; fn generic(value:T)->#token Token where T {token()#} fn entry()->bool {let a=generic(true)# {token()=>Token {},};let b=generic('x')# {token()=>Token {},};true}",
    );
    let key = iir::InstanceKey {
        declaration: id(&package, "entry"),
        arguments: vec![],
    };
    let mut graph = elaboration::materialization::instantiate(
        &package,
        &[key],
        Default::default(),
        elaboration::ptc::Budget::default(),
    )
    .unwrap();
    let generic: Vec<_> = graph
        .functions
        .iter()
        .filter(|f| f.function.name == "generic")
        .map(|f| f.key.clone())
        .collect();
    assert_eq!(generic.len(), 2);
    assert_eq!(generic[0].declaration, generic[1].declaration);
    assert_ne!(generic[0].arguments, generic[1].arguments);
    let function = &mut graph
        .functions
        .iter_mut()
        .find(|f| {
            f.function.name == "generic"
                && f.key.arguments == vec![nir::Term::Primitive(nir::Primitive::Char)]
        })
        .unwrap()
        .function;
    let mut changed = false;
    iir::visit::expression_mut(&mut function.body, &mut 100_000, |expr, _| {
        if !changed && matches!(expr.kind, K::EffectRequest { .. }) {
            let request = expr.clone();
            expr.kind = K::Block {
                statements: vec![request.clone()],
                result: Some(Box::new(request)),
            };
            changed = true;
        }
        Ok(())
    })
    .unwrap();
    assert!(changed);
    let plan = iir::effect_values::Plan::acquire(&graph, &mut 100_000, |_, _| {
        Ok(iir::effect_values::Delivery::Copy)
    })
    .unwrap();
    let report =
        elaboration::verification::effect_usage::check(&graph, &plan, &mut 100_000).unwrap();
    let mut upper: Vec<_> = report
        .installations
        .iter()
        .map(|entry| entry.upper)
        .collect();
    upper.sort();
    assert_eq!(upper, vec![1, 2]);
}

