#[test]
fn direct_passing_usage_tracks_constructed_anonymous_callable_fields() {
    use nir::program::ExprKind as K;
    for target in ["one", "twice"] {
        let package = compile(&format!(
            "struct Token {{}} ^attrs.effects.direct_passing effect token()->Token; fn one()->#token Token {{token()#}} fn twice()->#token Token {{let lost=token()#;token()#}} struct Action {{call:fn()->#token Token,}} fn subject()->#token Token {{(Action {{call:{target}}}).call()}} fn entry()->Token {{subject()# {{token()=>Token {{}},}}}}"
        ));
        let key = iir::InstanceKey {
            declaration: id(&package, "entry"),
            arguments: vec![],
        };
        let mut graph = elaboration::materialization::instantiate(
            &package,
            &[key.clone()],
            Default::default(),
            elaboration::ptc::Budget::default(),
        )
        .unwrap();
        let function = &mut graph
            .functions
            .iter_mut()
            .find(|f| f.function.name == "subject")
            .unwrap()
            .function;
        let mut changed = 0;
        iir::visit::expression_mut(&mut function.body, &mut 100_000, |expr, _| {
            if let K::Field { value, index, .. } = &mut expr.kind {
                if let K::Record { fields, .. } = &mut value.kind {
                    assert_eq!(fields.len(), 1);
                    let fields = std::mem::take(fields);
                    value.ty = nir::Term::Record(vec![("call".into(), fields[0].ty.clone())]);
                    value.kind = K::AnonymousRecord { fields };
                    expr.kind = K::AnonymousField {
                        value: value.clone(),
                        name: "call".into(),
                        index: *index,
                    };
                    changed += 1;
                }
            }
            Ok(())
        })
        .unwrap();
        assert_eq!(changed, 1);
        let plan = iir::effect_values::Plan::acquire(&graph, &mut 100_000, |_, _| {
            Ok(iir::effect_values::Delivery::Move)
        })
        .unwrap();
        let result = elaboration::verification::effect_usage::check(&graph, &plan, &mut 100_000);
        let mut vm = Interpreter::from_iir(&graph, Budget::default())
            .unwrap()
            .with_effect_values(&plan)
            .unwrap();
        if target == "one" {
            result.unwrap();
            assert!(matches!(
                vm.invoke_instance(&key, vec![]).unwrap(),
                Value::Record { .. }
            ));
        } else {
            assert!(result.unwrap_err().contains("affine effect slot"));
            assert_eq!(
                vm.invoke_instance(&key, vec![]).unwrap_err().kind,
                ErrorKind::EffectValueConsumed
            );
        }
    }
}

