#[test]
fn direct_passing_usage_product_mismatch_keeps_earlier_guard_consumption() {
    use nir::program::{ExprKind as K, Literal, Pattern};
    let package = compile(
        "struct Token {} ^attrs.effects.direct_passing effect token()->Token; fn subject()->#token Token {(true,true) match {(a,b) if do {let lost=token()#;true}=>{},_=>{},};token()#} fn entry()->Token {subject()# {token()=>Token {},}}",
    );
    let key = iir::InstanceKey {
        declaration: id(&package, "entry"),
        arguments: vec![],
    };
    let original = elaboration::materialization::instantiate(
        &package,
        &[key.clone()],
        Default::default(),
        elaboration::ptc::Budget::default(),
    )
    .unwrap();
    // Isolate ordered product-pattern probing from source pattern elaboration.
    // The first field's guard consumes the slot; the second field can fail.
    for second in [false, true] {
        let mut graph = original.clone();
        let function = &mut graph
            .functions
            .iter_mut()
            .find(|f| f.function.name == "subject")
            .unwrap()
            .function;
        let mut rewritten = 0;
        iir::visit::expression_mut(&mut function.body, &mut 100_000, |expr, _| {
            if let K::Match { arms, .. } = &mut expr.kind {
                let condition = arms[0]
                    .guard
                    .take()
                    .unwrap_or_else(|| match &arms[0].pattern {
                        Pattern::Guard { condition, .. } => condition.as_ref().clone(),
                        pattern => panic!("expected source guard, got {pattern:?}"),
                    });
                arms[0].pattern = Pattern::Tuple(vec![
                    Pattern::Guard {
                        pattern: Box::new(Pattern::Wild),
                        condition: Box::new(condition),
                    },
                    Pattern::Literal(Literal::Bool(second)),
                ]);
                rewritten += 1;
            }
            Ok(())
        })
        .unwrap();
        assert_eq!(rewritten, 1);
        let plan = iir::effect_values::Plan::acquire(&graph, &mut 100_000, |_, _| {
            Ok(iir::effect_values::Delivery::Move)
        })
        .unwrap();
        let error = elaboration::verification::effect_usage::check(&graph, &plan, &mut 100_000)
            .unwrap_err();
        assert!(error.contains("affine effect slot"), "{error}");
        let mut vm = Interpreter::from_iir(&graph, Budget::default())
            .unwrap()
            .with_effect_values(&plan)
            .unwrap();
        assert_eq!(
            vm.invoke_instance(&key, vec![]).unwrap_err().kind,
            ErrorKind::EffectValueConsumed
        );
    }
}

