#[test]
fn direct_passing_usage_checks_installations_in_contract_roots() {
    use nir::program::{ExprKind as K, Literal};
    let package = compile(
        "struct Token {} ^attrs.effects.direct_passing effect token()->Token; fn twice()->#token bool {let first=token()#;let second=token()#;true} fn entry()->bool {twice()# {token()=>Token {},}}",
    );
    let key = iir::InstanceKey {
        declaration: id(&package, "entry"),
        arguments: vec![],
    };
    let original = elaboration::materialization::instantiate(
        &package,
        &[key],
        Default::default(),
        elaboration::ptc::Budget::default(),
    )
    .unwrap();
    for post in [false, true] {
        let mut graph = original.clone();
        let function = &mut graph
            .functions
            .iter_mut()
            .find(|f| f.function.name == "entry")
            .unwrap()
            .function;
        let contract = function.body.clone();
        function.body.kind = K::Literal(Literal::Bool(true));
        if post {
            function.postconditions.push(contract);
        } else {
            function.preconditions.push(contract);
        }
        let plan = iir::effect_values::Plan::acquire(&graph, &mut 100_000, |_, _| {
            Ok(iir::effect_values::Delivery::Move)
        })
        .unwrap();
        assert!(
            elaboration::verification::effect_usage::check(&graph, &plan, &mut 100_000)
                .unwrap_err()
                .contains("affine effect slot")
        );
    }
}

