#[test]
fn direct_passing_copy_plan_repeats_nominal_results_without_aliasing_inline_fields() {
    let package = compile(
        "trait Duplicate {} trait Retire {fn drop(*self);} struct Config {flag:bool} impl Duplicate for Config {} ^attrs.effects.direct_passing effect config()->Config; fn subject()->#config bool {var first=config()#;first.flag=false;let second=config()#;not first.flag and second.flag} fn run()->bool {subject()# {config()=>Config {flag:true},}}",
    );
    assert_eq!(
        luna::execution::interpret_effects_with_protocols(
            &package,
            "run",
            "Duplicate",
            "Retire",
            100_000
        )
        .unwrap(),
        Value::Bool(true)
    );
    // Plain reference execution has not been supplied a source Copy identity.
    assert!(
        luna::execution::interpret(&package, "run", 100_000)
            .unwrap_err()
            .contains("EffectValueConsumed")
    );
    // The checked path now acquires the direct-passing plan and cleanup.
    // Mutating the first delivered Config must not alias the provider's slot.
    assert_eq!(
        luna::execution::interpret_with_protocols(&package, "run", "Duplicate", "Retire", 100_000)
            .unwrap(),
        Value::Bool(true)
    );
    let mut changed = package.clone();
    changed.implementations.clear();
    assert!(
        luna::execution::interpret_effects_with_protocols(
            &changed,
            "run",
            "Duplicate",
            "Retire",
            100_000
        )
        .unwrap_err()
        .contains("affine effect slot")
    );
}

