#[test]
fn direct_passing_copy_plan_is_bound_to_one_immutable_graph() {
    use iir::effect_values::{Delivery, Plan};
    let package = compile(
        "^attrs.effects.direct_passing effect setting()->bool; fn run()->#setting bool {(setting()#) and (setting()#)} fn entry()->bool {run()# {setting()=>true,}}",
    );
    let key = iir::InstanceKey {
        declaration: id(&package, "entry"),
        arguments: vec![],
    };
    let graph = elaboration::materialization::instantiate(
        &package,
        &[key.clone()],
        Default::default(),
        elaboration::ptc::Budget::default(),
    )
    .unwrap();
    assert!(Plan::acquire(&graph, &mut 1, |_, _| Ok(Delivery::Copy)).is_err());
    assert!(
        Plan::acquire(&graph, &mut 100_000, |_, _| Err(
            "Copy not authorized".into()
        ))
        .is_err()
    );
    let mut queries = 0;
    let plan = Plan::acquire(&graph, &mut 100_000, |ty, _| {
        assert_eq!(*ty, nir::Term::Primitive(nir::Primitive::Bool));
        queries += 1;
        Ok(Delivery::Copy)
    })
    .unwrap();
    assert_eq!(queries, 1);
    assert!(plan.to_string().contains("(delivery copy)"));
    let other = graph.clone();
    assert!(
        Interpreter::from_iir(&other, Budget::default())
            .unwrap()
            .with_effect_values(&plan)
            .is_err()
    );
    assert!(elaboration::verification::effect_usage::check(&other, &plan, &mut 100_000).is_err());
    assert!(
        elaboration::verification::effect_usage::check(&graph, &plan, &mut 1)
            .unwrap_err()
            .contains("budget")
    );
    let report =
        elaboration::verification::effect_usage::check(&graph, &plan, &mut 100_000).unwrap();
    assert_eq!(report.installations.len(), 1);
    assert_eq!(report.installations[0].upper, 2);
    assert!(report.to_string().contains("(upper many)"));
    let mut vm = Interpreter::from_iir(&graph, Budget::default())
        .unwrap()
        .with_effect_values(&plan)
        .unwrap();
    assert_eq!(vm.invoke_instance(&key, vec![]).unwrap(), Value::Bool(true));
}

