#[test]
fn malformed_call_plans_fail_without_panics() {
    let mut package = compile(&format!(
        "{FLAG} fn identity(x: Flag) -> Flag {{ x }} fn run() -> Flag {{ identity(true) }}"
    ));
    let entry = id(&package, "run");
    let function = package
        .functions
        .iter_mut()
        .find(|f| f.declaration == entry)
        .unwrap();
    let nir::program::ExprKind::Block {
        result: Some(result),
        ..
    } = &mut function.body.kind
    else {
        panic!("expected body")
    };
    let nir::program::ExprKind::Call { arguments, .. } = &mut result.kind else {
        panic!("expected call")
    };
    arguments[0].parameter = usize::MAX;
    let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        interpreter.invoke(entry, vec![]).unwrap_err().kind,
        ErrorKind::InvalidCallPlan
    );
}

