#[test]
fn struct_host_values_require_matching_identity_arity_and_field_types() {
    let package = compile(
        "typealias Flag = bool; struct S { value: Flag, } struct T { value: Flag, } fn read(value: S) -> Flag { value.value }",
    );
    let struct_id = |name: &str| {
        package
            .structs
            .iter()
            .find(|s| s.name == name)
            .unwrap()
            .declaration
    };
    for value in [
        Value::Record {
            arguments: vec![],
            declaration: struct_id("S"),
            fields: vec![],
        },
        Value::Record {
            arguments: vec![],
            declaration: struct_id("S"),
            fields: vec![Value::Char('x')],
        },
        Value::Record {
            arguments: vec![],
            declaration: struct_id("T"),
            fields: vec![Value::Bool(true)],
        },
    ] {
        let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
        assert_eq!(
            interpreter
                .invoke(id(&package, "read"), vec![value])
                .unwrap_err()
                .kind,
            ErrorKind::Type
        );
        assert!(interpreter.events().is_empty());
    }
    let mut duplicate = package.clone();
    duplicate.structs.push(duplicate.structs[0].clone());
    assert!(matches!(
        Interpreter::new(&duplicate, Budget::default()),
        Err(comptime_interpretor::Error {
            kind: ErrorKind::InvalidCallPlan,
            ..
        })
    ));
}

