#[test]
fn deferred_inputs_roll_back_capture_and_return_observations() {
    let package = compile(
        "fn keep(value: T) -> T where T { value } fn apply(callback: fn(T) -> T, value: T) -> T where T { callback(value) } fn run() -> bool { let flag = false; let outer = || apply(do { if flag { return true; } keep(|x| x) }, flag); outer() }",
    );
    let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        interpreter.invoke(id(&package, "run"), vec![]).unwrap(),
        Value::Bool(false)
    );
    let captures: Vec<_> = interpreter
        .events()
        .iter()
        .filter_map(|event| match event {
            Event::CreateClosure { captures, .. } => Some(*captures),
            _ => None,
        })
        .collect();
    assert_eq!(captures, [1, 0]);
}

#[test]
fn result_context_propagates_through_deep_generic_call_chains() {
    // Keep the regression independent of RUST_MIN_STACK. Ordinary nested
    // calls must not retain the full expression dispatcher on every level.
    std::thread::Builder::new()
        .stack_size(2 * 1024 * 1024)
        .spawn(|| {
            let mut callback = "|value| value".to_owned();
            for _ in 0..12 {
                callback = format!("keep({callback})");
            }
            let package = compile(&format!(
                "fn keep(value: T) -> T where T {{ value }} fn apply(callback: fn(T) -> T, value: T) -> T where T {{ callback(value) }} fn run() -> bool {{ apply({callback}, true) }}"
            ));
            let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
            assert_eq!(
                interpreter.invoke(id(&package, "run"), vec![]).unwrap(),
                Value::Bool(true)
            );
            assert_eq!(
                calls(&package, &interpreter)
                    .iter()
                    .filter(|name| name.as_str() == "keep")
                    .count(),
                12
            );
        })
        .unwrap()
        .join()
        .unwrap();
}

