#[test]
fn partial_callback_context_flows_through_blocks_and_branch_expressions() {
    for callback in [
        "do { |x| x }",
        "do { do { keep } }",
        "if true { |x| x } else { keep }",
        "if false { keep } else { |x| not x }",
        "true match { true => |x| x, false => keep, }",
        "false match { true => keep, false => |x| not x, }",
        "when { true => |x| x, else => keep, }",
        "when { false => keep, else => |x| not x, }",
    ] {
        let package = compile(&format!(
            "fn keep(value: T) -> T where T {{ value }} fn map(value: T, callback: fn(T) -> U) -> U where T, U {{ callback(value) }} fn run() -> bool {{ let result = map(true, {callback}); result }}"
        ));
        let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
        let expected = !callback.contains("not x");
        assert_eq!(
            interpreter.invoke(id(&package, "run"), vec![]).unwrap(),
            Value::Bool(expected),
            "{callback}"
        );
    }
}

