#[test]
fn nominal_contracts_support_defaults_nested_fields_and_generic_forwarding() {
    let package = compile(
        "typealias Flag = bool;
         struct Outer where U, requires U == Flag { inner: Checked<U>, }
         struct Checked where T, requires T == Flag { value: T = true, }
         fn build() -> Outer<V> where V, requires V == Flag {
             Outer<V> { inner: Checked<V> {} }
         }
         fn read(value: Outer<W>) -> Flag where W, requires W == Flag { value.inner.value }
         fn run() -> Flag { read(build<Flag>()) }",
    );
    assert_eq!(
        Interpreter::new(&package, Budget::default())
            .unwrap()
            .invoke(id(&package, "run"), vec![])
            .unwrap(),
        Value::Bool(true)
    );
    let checked = package
        .structs
        .iter()
        .find(|d| d.name == "Checked")
        .unwrap();
    assert_eq!(checked.requirements.len(), 1);
    assert!(checked.to_string().contains("(requires (type-equal"));
}

