#[test]
fn interpreter_rejects_malformed_default_dispatch_worlds_before_execution() {
    let original = compile(
        r#"
        trait Read {
            fn read() -> bool { true }
            fn indirect() -> bool { Self.as(Read).read() }
        }
        struct Flag {}
        impl Read for Flag {}
        fn run() -> bool { Flag.as(Read).indirect() }
    "#,
    );
    for corruption in 0..4 {
        let mut package = original.clone();
        match corruption {
            0 => package
                .implementations
                .push(package.implementations[0].clone()),
            1 => {
                package.implementations[0].methods.pop();
            }
            2 => package.traits.push(package.traits[0].clone()),
            3 => {
                let entry = package.implementations[0].methods[0].clone();
                package.implementations[0].methods.push(entry);
            }
            _ => unreachable!(),
        }
        let error = Interpreter::new(&package, Budget::default()).err().unwrap();
        assert_eq!(error.kind, ErrorKind::InvalidCallPlan);
    }
}

#[test]
