#[test]
fn generic_implementation_nir_preserves_selected_substitution_and_contract() {
    let package = compile(
        "trait Read { fn read(self) -> bool; } struct Box where T { value: T, } impl Read for Box<T> where T, requires T == bool { fn read(self) -> bool { self.value } } fn run() -> bool { Box<bool> { value: true }.as(Read).read() }",
    );
    let implementation = &package.implementations[0];
    assert_eq!(implementation.type_parameters.len(), 1);
    assert_eq!(implementation.requirements.len(), 1);
    let body = package.functions.iter().find(|f| f.name == "read").unwrap();
    assert_eq!(body.type_parameters, implementation.type_parameters);
    assert_eq!(body.requirements, implementation.requirements);
    let run = package.functions.iter().find(|f| f.name == "run").unwrap();
    let dump = run.body.to_string();
    assert!(dump.contains("trait-method"), "{dump}");
    assert!(package.dispatch_instances.iter().any(|instance| {
        instance.implementation == implementation.declaration
            && instance
                .methods
                .iter()
                .any(|method| method.body == body.declaration)
    }));
    assert!(
        !dump.contains(&implementation.type_parameters[0].to_string()),
        "unsubstituted implementation parameter in call: {dump}"
    );
    let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        interpreter.invoke(id(&package, "run"), vec![]).unwrap(),
        Value::Bool(true)
    );
}

