#[test]
fn generic_dispatch_checks_materialized_member_identity_and_substitution() {
    let original = compile(
        r#"
        trait Read { fn read(self) -> bool; }
        struct Box where T { value: T, }
        impl Read for Box<T> where T, requires T == bool { fn read(self) -> bool { self.value } }
        fn forward(value: U) -> bool where U :- Read { value.read() }
        fn run() -> bool { forward(Box<bool> { value: true }) }
    "#,
    );
    for mutation in 0..5 {
        let mut package = original.clone();
        match mutation {
            0 => {
                let row = package.dispatch_instances[0].clone();
                package.dispatch_instances.push(row);
            }
            1 => package.dispatch_instances[0].arguments.clear(),
            2 => package.dispatch_instances[0].methods[0].arguments.clear(),
            3 => package.dispatch_instances[0].methods.clear(),
            4 => package.dispatch_instances[0].methods[0].member = id(&package, "run"),
            _ => unreachable!(),
        }
        if mutation == 3 {
            // Partial dispatch tables are valid; an omitted demanded member
            // must fail at use rather than being supplied from another table.
            let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
            assert_eq!(
                interpreter
                    .invoke(id(&package, "run"), vec![])
                    .unwrap_err()
                    .kind,
                ErrorKind::UnmaterializedDispatch
            );
            continue;
        }
        assert_eq!(
            Interpreter::new(&package, Budget::default())
                .err()
                .unwrap()
                .kind,
            ErrorKind::InvalidCallPlan
        );
    }
    let mut missing = original.clone();
    missing.dispatch_instances.clear();
    let mut interpreter = Interpreter::new(&missing, Budget::default()).unwrap();
    assert_eq!(
        interpreter
            .invoke(id(&missing, "run"), vec![])
            .unwrap_err()
            .kind,
        ErrorKind::InvalidCallPlan
    );
}

