#[test]
fn generic_dispatch_materialization_is_repeatable_and_budgeted() {
    let package = compile(
        r#"
        trait Read { fn read(self) -> bool; }
        struct Box where T { value: T, }
        impl Read for Box<T> where T { fn read(self) -> bool { true } }
        fn forward(value: U) -> bool where U :- Read { value.read() }
        fn run() -> bool { forward(Box<bool> { value: true }) }
    "#,
    );
    let budget = elaboration::ptc::Budget::default();
    let rebuilt = elaboration::materialization::dispatch_instances(&package, budget).unwrap();
    assert_eq!(rebuilt, package.dispatch_instances);
    let error = elaboration::materialization::dispatch_instances(
        &package,
        elaboration::ptc::Budget { steps: 0, ..budget },
    )
    .unwrap_err();
    assert!(
        error.contains("budget") || error.contains("Budget"),
        "{error}"
    );
    assert_eq!(
        elaboration::materialization::dispatch_instances(&package, budget).unwrap(),
        rebuilt
    );
}

