#[test]
fn inherent_optional_methods_use_previous_parameters_and_per_call_defaults() {
    let package = execution_support::compile_with_tuple(
        r#"
        struct S {}
        impl S {
            fn choose(self, value: bool, .flip: bool = not value, .last: bool = flip) -> bool { last }
        }
        fn run() -> Tuple<bool, bool, bool> {
            (S {}.choose(true), S {}.choose(false), S {}.choose(true, .flip = true))
        }
    "#,
    );
    let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        interpreter.invoke(id(&package, "run"), vec![]).unwrap(),
        Value::Tuple(vec![
            Value::Bool(false),
            Value::Bool(true),
            Value::Bool(true)
        ])
    );
}

#[test]
fn inherent_named_inputs_follow_receiver_in_source_order() {
    let package = compile(
        r#"
        struct S {}
        impl S { fn choose(self, .first: bool = false, .second: bool = first) -> bool { first and second } }
        fn receiver() -> S { S {} }
        fn first() -> bool { true }
        fn second() -> bool { false }
        fn run() -> bool { receiver().choose(.second = second(), .first = first()) }
    "#,
    );
    let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        interpreter.invoke(id(&package, "run"), vec![]).unwrap(),
        Value::Bool(false)
    );
    assert_eq!(
        calls(&package, &interpreter),
        vec!["run", "receiver", "second", "first", "choose"]
    );
}

