#[test]
fn trait_default_entry_is_independent_of_implementation_optional_entry() {
    let package = compile(
        r#"
        trait Choose { fn choose(.option: bool = true) -> bool; }
        struct Host {}
        impl Choose for Host {
            fn choose(.internal: bool = false) -> bool { internal }
        }
        fn entry() -> bool { Host.as(Choose).choose() }
    "#,
    );
    let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        interpreter.invoke(id(&package, "entry"), vec![]).unwrap(),
        Value::Bool(true)
    );
    let mut malformed = package.clone();
    malformed.traits[0].methods[0].parameter_bindings.clear();
    assert_eq!(
        Interpreter::new(&malformed, Budget::default())
            .err()
            .unwrap()
            .kind,
        ErrorKind::InvalidCallPlan
    );
    let mut wrong_frame = package.clone();
    wrong_frame.traits[0].methods[0].parameter_bindings[0].index += 1;
    let mut interpreter = Interpreter::new(&wrong_frame, Budget::default()).unwrap();
    assert_eq!(
        interpreter
            .invoke(id(&wrong_frame, "entry"), vec![])
            .unwrap_err()
            .kind,
        ErrorKind::InvalidCallPlan
    );
}

