#[test]
fn integer_runtime_proxies_defer_defaulting_until_other_arguments_supply_context() {
    let package = compile(
        r#"
        typealias U16 = .u16'builtin;
        typealias I32 = .i32'builtin;
        fn identity(value: T) -> T where T { value }
        fn choose(left: T, right: T) -> T where T { left }
        fn word() -> U16 { 0 }
        fn contextual() -> bool { choose(identity(300), word()) match { 300 => true, _ => false } }
        fn reversed() -> bool { choose(word(), identity(300)) match { 0 => true, _ => false } }
        fn defaulted() -> I32 { let value = identity(42); value }
        fn outer() -> U16 { identity(identity(65535)) }
        fn branch() -> bool { choose(if true { 300 } else { 400 }, word()) match { 300 => true, _ => false } }
    "#,
    );
    let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
    for entry in ["contextual", "reversed", "branch"] {
        assert_eq!(
            interpreter.invoke(id(&package, entry), vec![]).unwrap(),
            Value::Bool(true)
        );
    }
    assert_eq!(
        interpreter
            .invoke(id(&package, "defaulted"), vec![])
            .unwrap(),
        Value::SignedInteger(42)
    );
    assert_eq!(
        interpreter.invoke(id(&package, "outer"), vec![]).unwrap(),
        Value::UnsignedInteger(65535)
    );
}

#[test]
