#[test]
fn bitvec_or_keeps_rhs_effects_and_views_are_value_snapshots() {
    let package = execution_support::compile_with_tuple(
        r#"
        typealias Bits = do { let v: .u8'builtin = 0; v'bitvec }'type;
        fn entry() -> Tuple<Bits, Bits, bool> {
            var byte: .u8'builtin = 1;
            let saved = byte'bitvec;
            byte = 2;
            var reached = false;
            let full: Bits = 255;
            let result = full or do { reached = true; byte'bitvec };
            (saved, result, reached)
        }
    "#,
    );
    let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
    let Value::Tuple(values) = interpreter.invoke(id(&package, "entry"), vec![]).unwrap() else {
        panic!("tuple")
    };
    let Value::BitVec(saved) = &values[0] else {
        panic!("bits")
    };
    let Value::BitVec(result) = &values[1] else {
        panic!("bits")
    };
    assert_eq!(saved.words(), &[1]);
    assert_eq!(result.words(), &[255]);
    assert_eq!(values[2], Value::Bool(true));
}

