#[test]
fn bitvec_cross_word_slices_preserve_all_128_integer_bits() {
    let package = compile(
        r#"
        typealias U128 = .u128'builtin;
        typealias U64 = .u64'builtin;
        fn word() -> U128 { 0x123456789abcdef00123456789abcdef }
        fn entry() -> U128 { (word()'bitvec ++ word()'bitvec)[64..192].as(U128) }
        fn crossing() -> U64 { word()'bitvec[31..95].as(U64) }
        fn last() -> .u8'builtin { word()'bitvec[127].as(.u8'builtin) }
    "#,
    );
    let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        interpreter.invoke(id(&package, "entry"), vec![]).unwrap(),
        Value::UnsignedInteger(0x0123456789abcdef123456789abcdef0)
    );
    assert_eq!(
        interpreter
            .invoke(id(&package, "crossing"), vec![])
            .unwrap(),
        Value::UnsignedInteger((0x123456789abcdef00123456789abcdefu128 >> 31) & u64::MAX as u128)
    );
    assert_eq!(
        interpreter.invoke(id(&package, "last"), vec![]).unwrap(),
        Value::UnsignedInteger(0)
    );
    assert_eq!(
        calls(&package, &interpreter)
            .iter()
            .filter(|name| *name == "word")
            .count(),
        4
    );
}

