#[test]
fn bitvec_writeback_overlaps_snapshots_fields_and_sign_bits_execute() {
    let package = compile_bound_tuple_fixture(include_str!(
        "../../../development/examples/bitvec-writeback.fl"
    ));
    let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
    for (name, expected) in [
        ("overlap", Value::UnsignedInteger(0x1344)),
        (
            "snapshot",
            Value::Tuple(vec![
                Value::UnsignedInteger(0x12ab),
                Value::UnsignedInteger(0x1234),
            ]),
        ),
        ("nested", Value::UnsignedInteger(0x3c0)),
        (
            "rhs_update",
            Value::Tuple(vec![
                Value::UnsignedInteger(0xab12),
                Value::UnsignedInteger(99),
            ]),
        ),
        ("sign", Value::SignedInteger(-128)),
        ("saved_value", Value::UnsignedInteger(0x1234)),
        ("empty", Value::UnsignedInteger(0x1234)),
    ] {
        let function = package.functions.iter().find(|f| f.name == name).unwrap();
        elaboration::verification::moves::analyze_in_package(
            &package,
            function,
            |ty| {
                Ok(
                    if matches!(ty, nir::Term::Primitive(_) | nir::Term::Pointer(_)) {
                        elaboration::verification::moves::Delivery::Copy
                    } else {
                        elaboration::verification::moves::Delivery::Move
                    },
                )
            },
            100000,
        )
        .unwrap();
        assert_eq!(
            luna::execution::interpret(&package, name, 100000).unwrap(),
            expected,
            "{name}"
        );
        assert_eq!(
            interpreter.invoke(id(&package, name), vec![]).unwrap(),
            expected,
            "{name}"
        );
    }
}

#[test]
fn bitvec_writeback_handles_128_bit_sign_and_cross_word_nested_views() {
    let package = compile(
        r#"
        fn negative() -> .i128'builtin {
            var value: .i128'builtin = 0;
            value'bitvec[127] = 1;
            value
        }
        fn positive() -> .i128'builtin {
            var value: .i128'builtin = -1;
            value'bitvec[127] = 0;
            value
        }
        fn spanning() -> .u128'builtin {
            var value: .u128'builtin = 0;
            value'bitvec[31..97] = 0x3ffffffffffffffff;
            value
        }
        fn wider() -> .u128'builtin {
            let zero: .u128'builtin = 0;
            var value = zero'bitvec ++ zero'bitvec;
            value[100..228] = 0xffffffffffffffffffffffffffffffff;
            value[96..224].as(.u128'builtin)
        }
        fn transfer() -> .u16'builtin {
            var value: .u16'builtin = 0;
            value'bitvec[0..8] = do { return 7; };
            value
        }
    "#,
    );
    let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
    for (entry, expected) in [
        ("negative", Value::SignedInteger(i128::MIN)),
        ("positive", Value::SignedInteger(i128::MAX)),
        (
            "spanning",
            Value::UnsignedInteger(((1u128 << 66) - 1) << 31),
        ),
        ("wider", Value::UnsignedInteger(u128::MAX << 4)),
        ("transfer", Value::UnsignedInteger(7)),
    ] {
        assert_eq!(
            interpreter.invoke(id(&package, entry), vec![]).unwrap(),
            expected,
            "{entry}"
        );
    }
}

