#[test]
fn float_bit_views_preserve_ieee_layout_and_every_special_bit_pattern() {
    let package = compile_bound_tuple_fixture(include_str!(
        "../../../development/examples/float-bit-patterns.fl"
    ));
    let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
    for (bits, sign, exponent, mantissa) in [
        (0x415a0000, 0, 130, 0x5a0000),
        (0x80000000, 1, 0, 0),
        (0x00000001, 0, 0, 1),
        (0x7f800000, 0, 255, 0),
        (0xff800000, 1, 255, 0),
        (0x7fc00042, 0, 255, 0x400042),
        (0x7f800001, 0, 255, 1),
        (0xffffffff, 1, 255, 0x7fffff),
    ] {
        assert_eq!(
            interpreter
                .invoke(id(&package, "decode"), vec![Value::Float32(bits)])
                .unwrap(),
            Value::Tuple(vec![
                Value::UnsignedInteger(sign),
                Value::UnsignedInteger(exponent),
                Value::UnsignedInteger(mantissa)
            ])
        );
        assert_eq!(
            interpreter
                .invoke(id(&package, "is_nan"), vec![Value::Float32(bits)])
                .unwrap(),
            Value::Bool(exponent == 255 && mantissa != 0)
        );
    }
    for (bits, sign, exponent, mantissa) in [
        (0x402b400000000000, 0, 1026, 0xb400000000000),
        (0x8000000000000000, 1, 0, 0),
        (1, 0, 0, 1),
        (0x7ff0000000000000, 0, 2047, 0),
        (0x7ff0000000000001, 0, 2047, 1),
        (0x7ff8000000000042, 0, 2047, 0x8000000000042),
    ] {
        assert_eq!(
            interpreter
                .invoke(id(&package, "decode_double"), vec![Value::Float64(bits)])
                .unwrap(),
            Value::Tuple(vec![
                Value::UnsignedInteger(sign),
                Value::UnsignedInteger(exponent),
                Value::UnsignedInteger(mantissa)
            ])
        );
    }
    assert_eq!(
        interpreter.invoke(id(&package, "example"), vec![]).unwrap(),
        Value::Tuple(vec![
            Value::UnsignedInteger(0),
            Value::UnsignedInteger(130),
            Value::UnsignedInteger(5898240)
        ])
    );
    assert_eq!(
        interpreter.invoke(id(&package, "flipped"), vec![]).unwrap(),
        Value::Float32(0xc15a0000)
    );
    assert_eq!(
        interpreter
            .invoke(id(&package, "nan_payload"), vec![])
            .unwrap(),
        Value::Float32(0x7fc00042)
    );
    assert_eq!(
        interpreter
            .invoke(id(&package, "infinity"), vec![])
            .unwrap(),
        Value::Float64(0x7ff0000000000000)
    );
}

#[test]
fn float_bit_writeback_preserves_payload_snapshots_and_rhs_updates() {
    let package = execution_support::compile_with_tuple(
        r#"
        typealias Single = .f32'builtin;
        typealias Double = .f64'builtin;
        struct Sample { value: Single }
        fn entry() -> Tuple<.u32'builtin, .u32'builtin> {
            let sample = Sample { value: -0.0 };
            let saved = sample.value'bitvec;
            sample.value'bitvec[0..8] = do { sample.value = 13.625; 0x42 };
            (sample.value'bitvec.as(.u32'builtin), saved.as(.u32'builtin))
        }
        fn preserve(value: Double) -> Double {
            var copy = value;
            copy'bitvec[64..64] = 0;
            copy
        }
    "#,
    );
    let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        interpreter.invoke(id(&package, "entry"), vec![]).unwrap(),
        Value::Tuple(vec![
            Value::UnsignedInteger(0x415a0042),
            Value::UnsignedInteger(0x80000000)
        ])
    );
    for bits in [
        0u64,
        1,
        1 << 63,
        0x7ff0000000000001,
        0xfff8000000000042,
        u64::MAX,
    ] {
        assert_eq!(
            interpreter
                .invoke(id(&package, "preserve"), vec![Value::Float64(bits)])
                .unwrap(),
            Value::Float64(bits)
        );
    }
}

