#[test]
fn interpreter_depth_budget_fires_on_a_two_mebibyte_host_stack_and_recovers() {
    use nir::program::{Expr, ExprKind, Pattern};
    let mut package = compile(
        "comptime fn recurse() -> bool { recurse() } comptime fn deep() -> bool { true } comptime fn good() -> bool { true } comptime fn pattern() -> bool { true match { _ => true, } }",
    );
    let deep = package
        .functions
        .iter_mut()
        .find(|f| f.name == "deep")
        .unwrap();
    let mut body = deep.body.clone();
    for _ in 0..384 {
        body = Expr {
            ty: body.ty.clone(),
            source: body.source,
            kind: ExprKind::Not(Box::new(body)),
        };
    }
    deep.body = body;
    let pattern_fn = package
        .functions
        .iter_mut()
        .find(|f| f.name == "pattern")
        .unwrap();
    let ExprKind::Block {
        result: Some(result),
        ..
    } = &mut pattern_fn.body.kind
    else {
        panic!("block")
    };
    let ExprKind::Match { arms, .. } = &mut result.kind else {
        panic!("match")
    };
    let mut pattern = Pattern::Wild;
    for _ in 0..384 {
        pattern = Pattern::Or(vec![pattern]);
    }
    arms[0].pattern = pattern;

    std::thread::Builder::new()
        .stack_size(2 * 1024 * 1024)
        .spawn(move || {
            for depth in [128, 256, usize::MAX] {
                let mut engine = Interpreter::for_comptime(
                    &package,
                    Budget {
                        steps: 100000,
                        depth,
                    },
                )
                .unwrap();
                for name in ["recurse", "pattern"] {
                    assert_eq!(
                        engine.invoke(id(&package, name), vec![]).unwrap_err().kind,
                        ErrorKind::DepthExhausted
                    );
                    assert_eq!(
                        engine.invoke(id(&package, "good"), vec![]).unwrap(),
                        Value::Bool(true)
                    );
                }
                // Linear Not chains use a heap continuation. They still pay
                // for every node, but do not consume recursive call depth.
                let before = engine.remaining_steps();
                assert_eq!(
                    engine.invoke(id(&package, "deep"), vec![]).unwrap(),
                    Value::Bool(true)
                );
                assert!(before - engine.remaining_steps() >= 384);
                let mut limited = Interpreter::for_comptime(
                    &package,
                    Budget {
                        steps: 100_000,
                        depth,
                    },
                )
                .unwrap();
                limited
                    .charge_preparation((limited.remaining_steps() - 128) as usize)
                    .unwrap();
                assert_eq!(
                    limited
                        .invoke(id(&package, "deep"), vec![])
                        .unwrap_err()
                        .kind,
                    ErrorKind::StepsExhausted
                );
                assert_eq!(
                    engine.invoke(id(&package, "good"), vec![]).unwrap(),
                    Value::Bool(true)
                );
            }
        })
        .unwrap()
        .join()
        .unwrap();
}

