#[test]
fn normal_form_types_keep_head_identity_and_cannot_be_invoked() {
    use nir::program::FunctionPhase;
    use nir::{Primitive, Sort, Term};
    let package = compile(include_str!(
        "../../../development/examples/normal-form-types.fl"
    ));
    let head = id(&package, "Identity");
    let definition = package
        .functions
        .iter()
        .find(|f| f.declaration == head)
        .unwrap();
    assert_eq!(definition.phase, FunctionPhase::NormalForm);
    assert!(definition.pure);
    let expected = Term::NormalForm {
        head,
        sort: Sort::Type,
        arguments: vec![Term::Primitive(Primitive::U8)],
    };
    let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    assert_eq!(
        engine.invoke(id(&package, "Observed"), vec![]).unwrap(),
        Value::Type(expected.clone())
    );
    let same = package.functions.iter().find(|f| f.name == "same").unwrap();
    let Term::Function { parameters, result } = &same.signature else {
        panic!("signature")
    };
    assert_eq!(parameters[0].ty, expected);
    assert_eq!(**result, expected);
    assert_eq!(
        engine.invoke(head, vec![]).unwrap_err().kind,
        ErrorKind::PhaseMismatch
    );
    let mut raw = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        raw.invoke(head, vec![]).unwrap_err().kind,
        ErrorKind::PhaseMismatch
    );
}

#[test]
fn normal_form_integer_arguments_preserve_exact_canonical_values() {
    use nir::{Primitive, Sort, Term};
    let package = compile(include_str!(
        "../../../development/examples/normal-form-values.fl"
    ));
    let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    let Value::Type(Term::NormalForm {
        head,
        sort,
        arguments,
    }) = engine.invoke(id(&package, "Observed"), vec![]).unwrap()
    else {
        panic!("normal form")
    };
    assert_eq!(head, id(&package, "Tagged"));
    assert_eq!(sort, Sort::Type);
    assert_eq!(arguments[0], Term::Primitive(Primitive::U8));
    let Term::Integer(value) = &arguments[1] else {
        panic!("integer")
    };
    assert_eq!(value.to_u128(), Ok(18446744073709551616));
    let Value::Type(Term::NormalForm { arguments, .. }) =
        engine.invoke(id(&package, "Negative"), vec![]).unwrap()
    else {
        panic!("negative head argument")
    };
    let [Term::Integer(value)] = arguments.as_slice() else {
        panic!("integer argument")
    };
    assert_eq!(value.to_signed(128), Ok(-1));
    let same = package.functions.iter().find(|f| f.name == "same").unwrap();
    let Term::Function { parameters, result } = &same.signature else {
        panic!("signature")
    };
    assert_eq!(&parameters[0].ty, result.as_ref());
    assert!(
        !calls(&package, &engine)
            .iter()
            .any(|name| ["Bits", "Tagged", "Forward", "width"].contains(&name.as_str()))
    );
}

#[test]
fn mixed_normal_form_inputs_keep_boolean_and_integer_identity() {
    use nir::{Primitive, Term};
    let package = compile(include_str!(
        "../../../development/examples/normal-form-mixed.fl"
    ));
    let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    let Value::Type(Term::NormalForm {
        head, arguments, ..
    }) = engine.invoke(id(&package, "Observed"), vec![]).unwrap()
    else {
        panic!("head")
    };
    assert_eq!(head, id(&package, "Select"));
    assert_eq!(arguments, vec![Term::Bool(true)]);
    let Value::Type(Term::NormalForm { arguments, .. }) =
        engine.invoke(id(&package, "Disabled"), vec![]).unwrap()
    else {
        panic!("head")
    };
    assert_eq!(arguments[0], Term::Primitive(Primitive::U16));
    assert_eq!(arguments[2], Term::Bool(false));
    let Term::Integer(value) = &arguments[1] else {
        panic!("integer")
    };
    assert_eq!(value.to_signed(128), Ok(-1));
    for (name, expected) in [("Maximum", 255), ("Minimum", -128)] {
        let Value::Type(Term::NormalForm { arguments, .. }) =
            engine.invoke(id(&package, name), vec![]).unwrap()
        else {
            panic!("head")
        };
        let [Term::Integer(value)] = arguments.as_slice() else {
            panic!("integer")
        };
        assert_eq!(value.to_signed(128), Ok(expected));
    }
    let same = package.functions.iter().find(|f| f.name == "same").unwrap();
    let Term::Function { parameters, result } = &same.signature else {
        panic!("signature")
    };
    assert_eq!(&parameters[0].ty, result.as_ref());
}

