#[test]
fn normal_form_metadata_preserves_order_dependencies_and_rejects_corruption() {
    use nir::normal_forms::Kind;
    use nir::{Primitive, Sort, Term};
    let package = compile_bound_tuple_fixture(include_str!(
        "../../../development/examples/normal-form-dependent.fl"
    ));
    let pair = id(&package, "Pair");
    let head = package
        .normal_forms
        .iter()
        .find(|h| h.declaration == pair)
        .unwrap();
    assert_eq!(
        head.parameters.iter().map(|p| p.kind).collect::<Vec<_>>(),
        vec![Kind::Type, Kind::Value, Kind::Type, Kind::Value]
    );
    for (ty, value) in [(0, 1), (2, 3)] {
        assert_eq!(
            head.parameters[value].ty,
            Term::Rigid {
                declaration: head.parameters[ty].declaration,
                sort: Sort::Type
            }
        );
    }
    assert!(head.to_string().contains("(normal-form-head"));
    for mutation in 0..8 {
        let mut invalid = package.clone();
        let head = invalid
            .normal_forms
            .iter_mut()
            .find(|h| h.declaration == pair)
            .unwrap();
        let function = invalid
            .functions
            .iter_mut()
            .find(|f| f.declaration == pair)
            .unwrap();
        match mutation {
            0 => invalid.normal_forms.clear(),
            1 => head.parameters.swap(0, 1),
            2 => head.parameters[1].binding = head.parameters[0].binding,
            3 => function.parameters.swap(0, 1),
            4 => function.type_parameters.clear(),
            5 => function.pure = false,
            6 => {
                let Term::Function { parameters, .. } = &mut function.signature else {
                    panic!("signature")
                };
                parameters[0].ty = Term::Primitive(Primitive::Bool);
            }
            7 => head
                .requirements
                .push(nir::program::TypePredicate::Bool(false)),
            _ => unreachable!(),
        }
        assert!(
            nir::normal_forms::validate(&invalid).is_err(),
            "mutation {mutation}"
        );
        assert_eq!(
            Interpreter::new(&invalid, Budget::default())
                .err()
                .unwrap()
                .kind,
            ErrorKind::InvalidCallPlan
        );
        assert!(nir::phases::validate(&invalid).is_err());
    }
}

#[test]
fn known_normal_form_applications_reject_corrupt_arguments_in_values_and_inputs() {
    use nir::program::{Expr, ExprKind};
    use nir::{Primitive, Sort, Term};
    let source = format!(
        "{} comptime fn Accept(value: Type) -> Type {{ value }} comptime fn Large() -> Type {{ Tagged<.Integer'builtin, 256> }}",
        include_str!("../../../development/examples/normal-form-dependent.fl")
    );
    let package = compile_bound_tuple_fixture(&source);
    let accept = id(&package, "Accept");
    let entry = id(&package, "Large");
    let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    let Value::Type(valid) = engine.invoke(entry, vec![]).unwrap() else {
        panic!("type")
    };
    for mutation in 0..5 {
        let mut bad = valid.clone();
        let Term::NormalForm {
            arguments, sort, ..
        } = &mut bad
        else {
            panic!("head")
        };
        match mutation {
            0 => {
                arguments.pop();
            }
            1 => arguments[0] = Term::Bool(true),
            2 => arguments[1] = Term::Bool(false),
            3 => arguments[0] = Term::Primitive(Primitive::U8),
            4 => *sort = Sort::ComptimeValue,
            _ => unreachable!(),
        }
        assert_eq!(
            engine
                .invoke(accept, vec![Value::Type(bad.clone())])
                .unwrap_err()
                .kind,
            ErrorKind::Type,
            "host mutation {mutation}"
        );
        assert_eq!(
            engine
                .invoke(accept, vec![Value::Type(valid.clone())])
                .unwrap(),
            Value::Type(valid.clone())
        );
        // Hide the application below a structural type to check recursive
        // inspection rather than only the root TypeValue constructor.
        let mut changed = package.clone();
        let function = changed
            .functions
            .iter_mut()
            .find(|f| f.declaration == entry)
            .unwrap();
        function.body = Expr {
            ty: Term::Primitive(Primitive::Type),
            source: function.body.source,
            kind: ExprKind::TypeValue(Term::Tuple(vec![bad])),
        };
        let mut changed_engine = Interpreter::for_comptime(&changed, Budget::default()).unwrap();
        assert_eq!(
            changed_engine.invoke(entry, vec![]).unwrap_err().kind,
            ErrorKind::Type,
            "literal mutation {mutation}"
        );
    }
}

#[test]
fn dynamic_normal_form_construction_evaluates_inputs_without_invoking_heads() {
    use nir::{Primitive, Term};
    let package = compile(include_str!(
        "../../../development/examples/dynamic-normal-form.fl"
    ));
    let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    let integer = comptime_runtime::Integer::from_u128(8);
    for (function, head, inputs, expected) in [
        (
            "Build",
            "Bits",
            vec![Value::Integer(integer.clone())],
            vec![Term::Integer(integer.clone())],
        ),
        (
            "Wrap",
            "Identity",
            vec![Value::Type(Term::Primitive(Primitive::U8))],
            vec![Term::Primitive(Primitive::U8)],
        ),
        (
            "Tag",
            "Tagged",
            vec![Value::Integer(integer.clone())],
            vec![Term::Primitive(Primitive::Integer), Term::Integer(integer)],
        ),
        (
            "Ordered",
            "Pair",
            vec![],
            vec![
                Term::Integer(comptime_runtime::Integer::from_u128(1)),
                Term::Integer(comptime_runtime::Integer::from_u128(2)),
            ],
        ),
    ] {
        assert_eq!(
            engine.invoke(id(&package, function), inputs).unwrap(),
            Value::Type(Term::NormalForm {
                head: id(&package, head),
                sort: nir::Sort::Type,
                arguments: expected,
            })
        );
    }
    assert_eq!(
        engine.invoke(id(&package, "Early"), vec![]).unwrap(),
        Value::Type(Term::Primitive(Primitive::U8))
    );
    assert_eq!(
        calls(&package, &engine),
        ["Build", "Wrap", "Tag", "Ordered", "Early"]
    );
    let function = package.functions.iter().find(|f| f.name == "same").unwrap();
    let Term::Function { parameters, result } = &function.signature else {
        panic!("signature")
    };
    assert_eq!(&parameters[0].ty, result.as_ref());
}

#[test]
fn dynamic_normal_form_constructor_rejects_corrupt_nir() {
    use nir::program::{Expr, ExprKind as K};
    use nir::{Primitive, Term};
    let package = compile(include_str!(
        "../../../development/examples/dynamic-normal-form.fl"
    ));
    let head = id(&package, "Identity");
    let target = id(&package, "Wrap");
    for corruption in 0..6 {
        let mut invalid = package.clone();
        let function = invalid
            .functions
            .iter_mut()
            .find(|f| f.declaration == target)
            .unwrap();
        let source = function.body.source;
        function.body = Expr {
            source,
            ty: Term::Primitive(Primitive::Type),
            kind: K::NormalFormType {
                plan: None,
                head,
                arguments: vec![nir::program::NormalFormArgument::Value(Expr {
                    source,
                    ty: Term::Primitive(Primitive::Type),
                    kind: K::TypeValue(Term::Primitive(Primitive::U8)),
                })],
            },
        };
        let K::NormalFormType {
            head, arguments, ..
        } = &mut function.body.kind
        else {
            unreachable!()
        };
        match corruption {
            0 => arguments.clear(),
            1 => head.local = u32::MAX,
            2 => function.body.ty = Term::Primitive(Primitive::Bool),
            3 => arguments[0].expression_mut().unwrap().kind = K::TypeValue(Term::Bool(true)),
            4 | 5 => {
                arguments[0] = nir::program::NormalFormArgument::Integer {
                    source,
                    spelling: if corruption == 4 {
                        "not-an-integer".into()
                    } else {
                        "1".into()
                    },
                    negative: false,
                }
            }
            _ => unreachable!(),
        }
        match Interpreter::for_comptime(&invalid, Budget::default()) {
            Err(_) => {}
            Ok(mut engine) => assert!(
                engine
                    .invoke(target, vec![Value::Type(Term::Primitive(Primitive::U8))])
                    .is_err(),
                "corruption {corruption}"
            ),
        }
    }
}

