#[test]
fn residual_normal_form_contracts_check_actual_inputs_and_recover() {
    use comptime_interpretor::ContractOutcome;
    use elaboration::ptc::{Context, Formula, Outcome};
    use nir::{Primitive, Sort, Term};
    let package = compile(include_str!(
        "../../../development/examples/residual-normal-form-contracts.fl"
    ));
    let solver = |predicate: &nir::program::TypePredicate| match Context::default()
        .prove(Formula::from_predicate(predicate), Default::default())
    {
        Outcome::Entailed(_) => ContractOutcome::Satisfied,
        Outcome::NotEntailed(_) => ContractOutcome::Rejected,
        _ => ContractOutcome::Unknown,
    };
    let mut engine = Interpreter::for_comptime(&package, Budget::default())
        .unwrap()
        .with_type_solver(&solver);
    let byte = Value::Type(Term::Primitive(Primitive::U8));
    let word = Value::Type(Term::Primitive(Primitive::U16));
    let expected = Value::Type(Term::NormalForm {
        head: id(&package, "Checked"),
        sort: Sort::Type,
        arguments: vec![Term::Primitive(Primitive::U8)],
    });
    assert_eq!(
        engine
            .invoke(id(&package, "Build"), vec![byte.clone()])
            .unwrap(),
        expected
    );
    assert_eq!(
        engine
            .invoke(id(&package, "Build"), vec![word.clone()])
            .unwrap_err()
            .kind,
        ErrorKind::TypeContractRejected
    );
    assert_eq!(
        engine.invoke(id(&package, "Build"), vec![byte]).unwrap(),
        expected
    );
    assert_eq!(
        engine
            .invoke(id(&package, "Selected"), vec![Value::Bool(true)])
            .unwrap(),
        expected
    );
    assert_eq!(
        engine
            .invoke(id(&package, "Selected"), vec![Value::Bool(false)])
            .unwrap_err()
            .kind,
        ErrorKind::TypeContractRejected
    );
    assert_eq!(engine.invoke(id(&package, "Early"), vec![]).unwrap(), word);
    assert!(
        engine
            .invoke(
                id(&package, "Width"),
                vec![Value::Integer(comptime_runtime::Integer::from_u128(9))]
            )
            .is_err()
    );
    for name in ["Ordered", "Correlated"] {
        let inputs = if name == "Correlated" {
            vec![Value::Integer(comptime_runtime::Integer::from_u128(1))]
        } else {
            vec![]
        };
        let one = Term::Integer(comptime_runtime::Integer::from_u128(1));
        assert_eq!(
            engine.invoke(id(&package, name), inputs).unwrap(),
            Value::Type(Term::NormalForm {
                head: id(&package, "Pair"),
                sort: Sort::Type,
                arguments: vec![
                    Term::NormalForm {
                        head: id(&package, "Bits"),
                        sort: Sort::Type,
                        arguments: vec![one.clone()]
                    },
                    one
                ],
            })
        );
    }
    let mut without_solver = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    assert_eq!(
        without_solver
            .invoke(
                id(&package, "Build"),
                vec![Value::Type(Term::Primitive(Primitive::U16))]
            )
            .unwrap_err()
            .kind,
        ErrorKind::TypeContractUnresolved
    );
}

#[test]
fn dependent_normal_form_inputs_convert_literals_after_type_inputs_arrive() {
    use nir::{Primitive, Sort, Term};
    let package = compile_bound_tuple_fixture(include_str!(
        "../../../development/examples/dependent-normal-form-inputs.fl"
    ));
    let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    let ty = |p| Value::Type(Term::Primitive(p));
    for (name, primitive, expected) in [
        ("Number", Primitive::U8, 255),
        ("Number", Primitive::Integer, 255),
        ("Negative", Primitive::I8, -128),
        ("Negative", Primitive::Integer, -128),
    ] {
        assert_eq!(
            engine
                .invoke(id(&package, name), vec![ty(primitive)])
                .unwrap(),
            Value::Type(Term::NormalForm {
                head: id(&package, "Tagged"),
                sort: Sort::Type,
                arguments: vec![
                    Term::Primitive(primitive),
                    Term::Integer(comptime_runtime::Integer::from_i128(expected))
                ],
            })
        );
    }
    for (name, primitive) in [
        ("Number", Primitive::I8),
        ("Negative", Primitive::U8),
        ("Number", Primitive::Bool),
        ("Number", Primitive::Type),
    ] {
        assert_eq!(
            engine
                .invoke(id(&package, name), vec![ty(primitive)])
                .unwrap_err()
                .kind,
            ErrorKind::Type
        );
    }
    assert!(
        engine
            .invoke(
                id(&package, "Pass"),
                vec![ty(Primitive::U8), Value::UnsignedInteger(8)]
            )
            .is_ok()
    );
    assert!(
        engine
            .invoke(
                id(&package, "Pass"),
                vec![ty(Primitive::U16), Value::UnsignedInteger(8)]
            )
            .is_err()
    );
    assert!(
        engine
            .invoke(
                id(&package, "Truth"),
                vec![ty(Primitive::Bool), Value::Bool(false)]
            )
            .is_ok()
    );
    assert!(
        engine
            .invoke(
                id(&package, "TypeInput"),
                vec![ty(Primitive::Type), ty(Primitive::U8)]
            )
            .is_ok()
    );
    assert_eq!(
        engine
            .invoke(id(&package, "Early"), vec![ty(Primitive::U8)])
            .unwrap(),
        ty(Primitive::U16)
    );
    let ordered = engine.invoke(id(&package, "Ordered"), vec![]).unwrap();
    assert_eq!(
        ordered,
        engine
            .invoke(
                id(&package, "Interleaved"),
                vec![ty(Primitive::U8), ty(Primitive::I8)]
            )
            .unwrap()
    );
    let one = Term::Integer(comptime_runtime::Integer::from_i128(1));
    let minus_two = Term::Integer(comptime_runtime::Integer::from_i128(-2));
    assert_eq!(
        engine
            .invoke(
                id(&package, "Interleaved"),
                vec![ty(Primitive::U8), ty(Primitive::I8)]
            )
            .unwrap(),
        Value::Type(Term::NormalForm {
            head: id(&package, "Pair"),
            sort: Sort::Type,
            arguments: vec![
                Term::Primitive(Primitive::U8),
                one,
                Term::Primitive(Primitive::I8),
                minus_two
            ],
        })
    );
}

#[test]
fn contextual_normal_form_control_flow_preserves_checks_scope_and_effect_order() {
    use nir::{Primitive, Sort, Term};
    let package = compile_bound_tuple_fixture(include_str!(
        "../../../development/examples/contextual-normal-form-inputs.fl"
    ));
    let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    let byte = Value::Type(Term::Primitive(Primitive::U8));
    let tag = |integer| {
        Value::Type(Term::NormalForm {
            head: id(&package, "Tagged"),
            sort: Sort::Type,
            arguments: vec![
                Term::Primitive(Primitive::U8),
                Term::Integer(comptime_runtime::Integer::from_u128(integer)),
            ],
        })
    };
    assert_eq!(
        engine
            .invoke(
                id(&package, "Choice"),
                vec![byte.clone(), Value::Bool(true)]
            )
            .unwrap(),
        tag(1)
    );
    assert_eq!(
        engine
            .invoke(
                id(&package, "Choice"),
                vec![byte.clone(), Value::Bool(false)]
            )
            .unwrap(),
        tag(2)
    );
    assert_eq!(
        engine
            .invoke(id(&package, "Skipped"), vec![byte.clone()])
            .unwrap(),
        tag(1)
    );
    assert_eq!(
        engine
            .invoke(id(&package, "Early"), vec![byte.clone(), Value::Bool(true)])
            .unwrap(),
        Value::Type(Term::Primitive(Primitive::U16))
    );
    assert_eq!(
        engine
            .invoke(
                id(&package, "Early"),
                vec![byte.clone(), Value::Bool(false)]
            )
            .unwrap(),
        tag(3)
    );
    assert_eq!(
        engine
            .invoke(id(&package, "Locals"), vec![byte.clone()])
            .unwrap(),
        tag(4)
    );
    assert_eq!(
        engine
            .invoke(id(&package, "GenericObserved"), vec![byte.clone()])
            .unwrap(),
        tag(7)
    );
    let Value::Type(Term::NormalForm { arguments, .. }) = engine
        .invoke(id(&package, "Ordered"), vec![byte.clone()])
        .unwrap()
    else {
        panic!("head")
    };
    assert_eq!(
        arguments[1],
        Term::Integer(comptime_runtime::Integer::from_u128(7))
    );
    assert_eq!(
        arguments[3],
        Term::Integer(comptime_runtime::Integer::from_u128(2))
    );
    assert_eq!(
        engine
            .invoke(id(&package, "UnselectedOverflow"), vec![byte.clone()])
            .unwrap_err()
            .kind,
        ErrorKind::Type
    );
    assert_eq!(
        engine
            .invoke(id(&package, "Choice"), vec![byte, Value::Bool(false)])
            .unwrap(),
        tag(2)
    );
    assert!(
        !calls(&package, &engine)
            .iter()
            .any(|call| call == "diverge")
    );
}

#[test]
fn contextual_normal_form_depth_limit_recovers_on_a_small_host_stack() {
    use nir::{
        Primitive, Term,
        program::{Expr, ExprKind as K, NormalFormArgument as A},
    };
    let mut package = compile_bound_tuple_fixture(include_str!(
        "../../../development/examples/dependent-normal-form-inputs.fl"
    ));
    let target = id(&package, "Number");
    let head = id(&package, "Tagged");
    let function = package
        .functions
        .iter_mut()
        .find(|f| f.declaration == target)
        .unwrap();
    let source = function.body.source;
    let mut input = A::Integer {
        source,
        spelling: "1".into(),
        negative: false,
    };
    for _ in 0..384 {
        input = A::Block {
            source,
            statements: vec![],
            result: Some(Box::new(input)),
        };
    }
    function.body = Expr {
        source,
        ty: Term::Primitive(Primitive::Type),
        kind: K::NormalFormType {
            plan: None,
            head,
            arguments: vec![
                A::Value(Expr {
                    source,
                    ty: Term::Primitive(Primitive::Type),
                    kind: K::TypeValue(Term::Primitive(Primitive::U8)),
                }),
                input,
            ],
        },
    };
    std::thread::Builder::new()
        .stack_size(2 * 1024 * 1024)
        .spawn(move || {
            let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
            assert_eq!(
                engine
                    .invoke(target, vec![Value::Type(Term::Primitive(Primitive::U8))])
                    .unwrap_err()
                    .kind,
                ErrorKind::DepthExhausted
            );
            assert!(
                engine
                    .invoke(
                        id(&package, "Negative"),
                        vec![Value::Type(Term::Primitive(Primitive::I8))]
                    )
                    .is_ok()
            );
        })
        .unwrap()
        .join()
        .unwrap();
}

#[test]
fn contextual_normal_form_match_preserves_guards_bindings_and_generic_extractors() {
    use nir::{Primitive, Sort, Term};
    let package = compile(include_str!(
        "../../../development/examples/contextual-normal-form-match.fl"
    ));
    let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    let byte = Value::Type(Term::Primitive(Primitive::U8));
    let tag = |integer| {
        Value::Type(Term::NormalForm {
            head: id(&package, "Tagged"),
            sort: Sort::Type,
            arguments: vec![
                Term::Primitive(Primitive::U8),
                Term::Integer(comptime_runtime::Integer::from_u128(integer)),
            ],
        })
    };
    for (flag, result) in [(true, 1), (false, 2)] {
        assert_eq!(
            engine
                .invoke(
                    id(&package, "Select"),
                    vec![byte.clone(), Value::Bool(flag)]
                )
                .unwrap(),
            tag(result)
        );
        assert_eq!(
            engine
                .invoke(
                    id(&package, "Chained"),
                    vec![byte.clone(), Value::Bool(!flag)]
                )
                .unwrap(),
            tag(result)
        );
    }
    let Value::Type(Term::NormalForm { arguments, .. }) = engine
        .invoke(id(&package, "Guarded"), vec![byte.clone()])
        .unwrap()
    else {
        panic!("head")
    };
    assert_eq!(
        arguments[1],
        Term::Integer(comptime_runtime::Integer::from_u128(8))
    );
    assert_eq!(
        arguments[2],
        Term::Integer(comptime_runtime::Integer::from_u128(2))
    );
    assert_eq!(
        engine
            .invoke(id(&package, "GenericObserved"), vec![byte.clone()])
            .unwrap(),
        tag(7)
    );
    assert_eq!(
        engine
            .invoke(id(&package, "Early"), vec![byte.clone(), Value::Bool(true)])
            .unwrap(),
        Value::Type(Term::Primitive(Primitive::U16))
    );
    assert_eq!(
        engine
            .invoke(
                id(&package, "Early"),
                vec![byte.clone(), Value::Bool(false)]
            )
            .unwrap(),
        tag(3)
    );
    assert_eq!(
        engine
            .invoke(id(&package, "UnselectedOverflow"), vec![byte])
            .unwrap_err()
            .kind,
        ErrorKind::Type
    );
    assert_eq!(
        calls(&package, &engine)
            .iter()
            .filter(|name| *name == "flip")
            .count(),
        2
    );
    assert_eq!(
        calls(&package, &engine)
            .iter()
            .filter(|name| *name == "keep")
            .count(),
        1
    );
}

#[test]
fn contextual_normal_form_when_preserves_priority_effects_and_nested_constructs() {
    use nir::{Primitive, Sort, Term};
    let package = compile(include_str!(
        "../../../development/examples/contextual-normal-form-when.fl"
    ));
    let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    let byte = Value::Type(Term::Primitive(Primitive::U8));
    let tag = |integer| {
        Value::Type(Term::NormalForm {
            head: id(&package, "Tagged"),
            sort: Sort::Type,
            arguments: vec![
                Term::Primitive(Primitive::U8),
                Term::Integer(comptime_runtime::Integer::from_u128(integer)),
            ],
        })
    };
    for (first, second, result) in [(true, true, 1), (false, true, 2), (false, false, 3)] {
        assert_eq!(
            engine
                .invoke(
                    id(&package, "Choose"),
                    vec![byte.clone(), Value::Bool(first), Value::Bool(second)]
                )
                .unwrap(),
            tag(result)
        );
    }
    let Value::Type(Term::NormalForm { arguments, .. }) = engine
        .invoke(id(&package, "Ordered"), vec![byte.clone()])
        .unwrap()
    else {
        panic!("head")
    };
    assert_eq!(
        arguments[1],
        Term::Integer(comptime_runtime::Integer::from_u128(5))
    );
    assert_eq!(
        arguments[2],
        Term::Integer(comptime_runtime::Integer::from_u128(12))
    );
    assert_eq!(
        engine
            .invoke(id(&package, "Fallback"), vec![byte.clone()])
            .unwrap(),
        tag(9)
    );
    assert_eq!(
        engine
            .invoke(id(&package, "Early"), vec![byte.clone(), Value::Bool(true)])
            .unwrap(),
        Value::Type(Term::Primitive(Primitive::U16))
    );
    assert_eq!(
        engine
            .invoke(
                id(&package, "Early"),
                vec![byte.clone(), Value::Bool(false)]
            )
            .unwrap(),
        tag(8)
    );
    for (flag, result) in [(true, 10), (false, 13)] {
        assert_eq!(
            engine
                .invoke(id(&package, "Mixed"), vec![byte.clone(), Value::Bool(flag)])
                .unwrap(),
            tag(result)
        );
    }
    assert_eq!(
        engine
            .invoke(id(&package, "UnselectedOverflow"), vec![byte])
            .unwrap_err()
            .kind,
        ErrorKind::Type
    );
}

#[test]
fn normal_form_text_inputs_preserve_contents_contracts_and_work_limits() {
    use nir::{Primitive, Sort, Term};
    let package = compile(include_str!(
        "../../../development/examples/normal-form-text.fl"
    ));
    let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    let head = |name: &str, arguments| Term::NormalForm {
        head: id(&package, name),
        sort: Sort::Type,
        arguments,
    };
    let name: std::sync::Arc<str> = "flurry λ".into();
    let named = head("Named", vec![Term::String(name.clone())]);
    assert_eq!(
        engine
            .invoke(id(&package, "Build"), vec![Value::String(name.clone())])
            .unwrap(),
        Value::Type(named.clone())
    );
    assert_eq!(
        engine
            .invoke(id(&package, "Verified"), vec![Value::String(name.clone())])
            .unwrap(),
        Value::Type(head("Checked", vec![named, Term::String(name.clone())]))
    );
    assert_eq!(
        engine
            .invoke(id(&package, "Character"), vec![Value::Char('λ')])
            .unwrap(),
        Value::Type(head("Symbol", vec![Term::Char('λ')]))
    );
    assert_eq!(
        engine
            .invoke(
                id(&package, "Typed"),
                vec![
                    Value::Type(Term::Primitive(Primitive::Str)),
                    Value::String(name.clone())
                ]
            )
            .unwrap(),
        Value::Type(head(
            "Tagged",
            vec![Term::Primitive(Primitive::Str), Term::String(name)]
        ))
    );
    let escaped: std::sync::Arc<str> = "a\"\\\n\tλ".into();
    assert_eq!(
        engine.invoke(id(&package, "Escaped"), vec![]).unwrap(),
        Value::Type(head("Named", vec![Term::String(escaped)]))
    );
    for bad in [
        head("Named", vec![Term::Char('x')]),
        head("Symbol", vec![Term::String("x".into())]),
        Term::String("not a type".into()),
    ] {
        assert_eq!(
            engine
                .invoke(id(&package, "IdentityType"), vec![Value::Type(bad)])
                .unwrap_err()
                .kind,
            ErrorKind::Type
        );
    }
    let mut small = Interpreter::for_comptime(
        &package,
        Budget {
            steps: 64,
            depth: 128,
        },
    )
    .unwrap();
    assert_eq!(
        small
            .invoke(
                id(&package, "Build"),
                vec![Value::String("x".repeat(1024).into())]
            )
            .unwrap_err()
            .kind,
        ErrorKind::StepsExhausted
    );
    let mut large = Interpreter::for_comptime(
        &package,
        Budget {
            steps: 2_000_000,
            depth: 128,
        },
    )
    .unwrap();
    assert_eq!(
        large
            .invoke(
                id(&package, "Build"),
                vec![Value::String("x".repeat(100_001).into())]
            )
            .unwrap_err()
            .kind,
        ErrorKind::Type
    );
    assert!(
        engine
            .invoke(id(&package, "Build"), vec![Value::String("ok".into())])
            .is_ok()
    );
}

#[test]
fn normal_form_tuple_values_preserve_shape_types_contracts_and_order() {
    use nir::{Primitive, Sort, Term};
    let package = compile_bound_tuple_fixture(include_str!(
        "../../../development/examples/normal-form-tuples.fl"
    ));
    let tuple = |elements| Term::NormalForm {
        head: id(&package, "Tuple"),
        sort: Sort::Type,
        arguments: vec![Term::TypeListValue(elements)],
    };
    let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    let int = |n| Term::Integer(comptime_runtime::Integer::from_u128(n));
    let config = Term::TupleValue(vec![int(8), Term::Bool(true)]);
    let head = |name: &str, arguments| Term::NormalForm {
        head: id(&package, name),
        sort: Sort::Type,
        arguments,
    };
    let value = || {
        Value::Tuple(vec![
            Value::Integer(comptime_runtime::Integer::from_u128(8)),
            Value::Bool(true),
        ])
    };
    assert_eq!(
        engine.invoke(id(&package, "Build"), vec![value()]).unwrap(),
        Value::Type(head("Config", vec![config.clone()]))
    );
    assert_eq!(
        engine
            .invoke(id(&package, "Verified"), vec![value()])
            .unwrap(),
        Value::Type(head(
            "Checked",
            vec![head("Config", vec![config.clone()]), config]
        ))
    );
    let pair = tuple(vec![
        Term::Primitive(Primitive::U8),
        Term::Primitive(Primitive::Bool),
    ]);
    assert_eq!(
        engine
            .invoke(id(&package, "Typed"), vec![Value::Type(pair.clone())])
            .unwrap(),
        Value::Type(head(
            "Tagged",
            vec![pair, Term::TupleValue(vec![int(255), Term::Bool(true)])]
        ))
    );
    let nested = tuple(vec![
        tuple(vec![
            Term::Primitive(Primitive::U8),
            Term::Primitive(Primitive::Bool),
        ]),
        Term::Primitive(Primitive::Str),
    ]);
    assert_eq!(
        engine
            .invoke(id(&package, "Nested"), vec![Value::Type(nested.clone())])
            .unwrap(),
        Value::Type(head(
            "Tagged",
            vec![
                nested,
                Term::TupleValue(vec![
                    Term::TupleValue(vec![int(1), Term::Bool(false)]),
                    Term::String("λ".into())
                ])
            ]
        ))
    );
    let ordered = tuple(vec![
        Term::Primitive(Primitive::U8),
        Term::Primitive(Primitive::Integer),
    ]);
    assert_eq!(
        engine
            .invoke(id(&package, "Ordered"), vec![Value::Type(ordered.clone())])
            .unwrap(),
        Value::Type(head(
            "Tagged",
            vec![ordered, Term::TupleValue(vec![int(7), int(2)])]
        ))
    );
}

#[test]
fn normal_form_bitvec_inputs_keep_width_bits_and_dynamic_literal_checks() {
    use nir::{Primitive, Sort, Term};
    let package = compile(include_str!(
        "../../../development/examples/normal-form-bitvec.fl"
    ));
    let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    let bits = |width, value| {
        comptime_runtime::Integer::from_u128(value)
            .to_bitvec(width, &mut comptime_runtime::Budget::default())
            .unwrap()
    };
    let head = |name, arguments| Term::NormalForm {
        head: id(&package, name),
        sort: Sort::Type,
        arguments,
    };
    assert_eq!(
        engine
            .invoke(id(&package, "Build"), vec![Value::BitVec(bits(8, 0x50))])
            .unwrap(),
        Value::Type(head("Mask", vec![Term::BitVec(bits(8, 0xAF))]))
    );
    assert_eq!(
        engine
            .invoke(id(&package, "Verified"), vec![Value::BitVec(bits(8, 3))])
            .unwrap(),
        Value::Type(head(
            "Checked",
            vec![
                head("Mask", vec![Term::BitVec(bits(8, 3))]),
                Term::BitVec(bits(8, 3))
            ]
        ))
    );
    for width in [8, 16, 129] {
        let ty = Term::Primitive(Primitive::BitVec(width));
        assert_eq!(
            engine
                .invoke(id(&package, "Typed"), vec![Value::Type(ty.clone())])
                .unwrap(),
            Value::Type(head("Tagged", vec![ty, Term::BitVec(bits(width, 255))]))
        );
    }
    assert!(
        engine
            .invoke(
                id(&package, "Typed"),
                vec![Value::Type(Term::Primitive(Primitive::BitVec(7)))]
            )
            .is_err()
    );
    let empty = Term::Primitive(Primitive::BitVec(0));
    assert_eq!(
        engine
            .invoke(id(&package, "Empty"), vec![Value::Type(empty.clone())])
            .unwrap(),
        Value::Type(head("Tagged", vec![empty, Term::BitVec(bits(0, 0))]))
    );
}

#[test]
fn explicit_nir_integer_division_reports_zero_and_recovers() {
    use nir::program::{ExprKind as K, IntegerOp};
    for operation in [IntegerOp::DivideTrunc, IntegerOp::RemainderTrunc] {
        // Source operator rounding is deliberately not selected by this test.
        let mut package = compile(
            "typealias Int = .Integer'builtin; comptime fn calculate(a: Int, b: Int) -> Int = a + b;",
        );
        let K::IntegerBinary { op, .. } = &mut package.functions[0].body.kind else {
            panic!("expected arithmetic expression")
        };
        *op = operation;
        let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
        let value = |n| Value::Integer(comptime_runtime::Integer::from_i128(n));
        let failure = engine
            .invoke(id(&package, "calculate"), vec![value(-7), value(0)])
            .unwrap_err();
        assert_eq!(failure.kind, ErrorKind::DivisionByZero);
        assert!(failure.source.is_some());
        let expected = if operation == IntegerOp::DivideTrunc {
            -2
        } else {
            -1
        };
        assert_eq!(
            engine
                .invoke(id(&package, "calculate"), vec![value(-7), value(3)])
                .unwrap(),
            value(expected)
        );
    }
}

#[test]
fn symbolic_tuple_normal_contracts_instantiate_all_nested_fields() {
    use nir::program::TypePredicate;
    use nir::{Primitive, Sort, Term};
    let package = compile_bound_tuple_fixture(include_str!(
        "../../../development/examples/normal-form-symbolic-tuples.fl"
    ));
    let descriptor = package
        .normal_forms
        .iter()
        .find(|head| head.declaration == id(&package, "NestedForward"))
        .unwrap();
    let parameters = descriptor
        .parameters
        .iter()
        .map(|p| p.declaration)
        .collect::<Vec<_>>();
    let integer = Term::Integer(comptime_runtime::Integer::from_u128(19));
    let byte = Term::Primitive(Primitive::U8);
    let actual = descriptor.requirements[0]
        .instantiate_rigids(&parameters, &[byte.clone(), integer.clone()])
        .unwrap();
    let identity = Term::NormalForm {
        head: id(&package, "Nested"),
        sort: Sort::Type,
        arguments: vec![Term::TupleValue(vec![
            Term::TupleValue(vec![integer, Term::Bool(false)]),
            byte,
        ])],
    };
    assert_eq!(actual, TypePredicate::Equal(identity.clone(), identity));
    assert_eq!(actual.trivial_truth(), Some(true));
}

