fn module_constants_feed_comptime_values_and_type_positions() {
    let package = compile_bound_tuple_fixture(include_str!(
        "../../../development/examples/comptime-constants.fl"
    ));
    let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    let integer = |value| Value::Integer(comptime_runtime::Integer::from_i128(value));
    assert_eq!(
        engine.invoke(id(&package, "width"), vec![]).unwrap(),
        integer(8)
    );
    assert_eq!(
        engine.invoke(id(&package, "negative"), vec![]).unwrap(),
        integer(-9)
    );
    assert_eq!(
        engine.invoke(id(&package, "pair"), vec![]).unwrap(),
        Value::Tuple(vec![integer(8), Value::Bool(true)])
    );
    let bits = comptime_runtime::Integer::from_u128(0xAF)
        .to_bitvec(8, &mut comptime_runtime::Budget::default())
        .unwrap();
    assert_eq!(
        engine.invoke(id(&package, "mask"), vec![]).unwrap(),
        Value::BitVec(bits)
    );
    let mut runtime = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        runtime
            .invoke(id(&package, "use_type"), vec![Value::UnsignedInteger(7)])
            .unwrap(),
        Value::UnsignedInteger(7)
    );
}

