#[test]
fn owned_function_instances_preserve_declaration_arguments_without_exporting_closures() {
    use nir::program::ExprKind as K;
    use nir::{Primitive, Term};
    let mut package = compile(
        "typealias Int = .Integer'builtin; comptime fn identity(value: T) -> T where T { value } comptime fn run(value: Int) -> Int = identity(value); comptime fn call(value: Int) -> Int = identity(value);",
    );
    let origin = id(&package, "identity");
    let run = id(&package, "run");
    let function = package
        .functions
        .iter_mut()
        .find(|f| f.declaration == run)
        .unwrap();
    let K::Call { callee, .. } = &function.body.kind else {
        panic!("expected instantiated call")
    };
    let instance = (**callee).clone();
    let Term::Function { result, .. } = &mut function.signature else {
        panic!("expected function signature")
    };
    *result = Box::new(instance.ty.clone());
    function.body = instance;
    // The phase-bearing instance remains callable through the checked interpreter.
    let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    let value = engine
        .invoke(
            run,
            vec![Value::Integer(comptime_runtime::Integer::from_u128(7))],
        )
        .unwrap();
    let Value::Closure(instance) = &value else {
        panic!("expected function instance")
    };
    assert!(value.to_string().contains("(instance (declaration"));
    assert!(
        value
            .to_string()
            .contains("(arguments (primitive Integer))")
    );
    assert_eq!(
        instance.declaration_instance(),
        Some((origin, [Term::Primitive(Primitive::Integer)].as_slice()))
    );
    assert_eq!(
        engine
            .invoke(
                id(&package, "call"),
                vec![Value::Integer(comptime_runtime::Integer::from_u128(9))]
            )
            .unwrap(),
        Value::Integer(comptime_runtime::Integer::from_u128(9))
    );
}

