#[test]
fn comptime_callback_admission_rejects_runtime_values_and_recovers() {
    let mut package = compile(
        r#"
        fn runtime_flag() -> bool { true }
        comptime fn flag() -> bool { true }
        comptime fn apply(callback: comptime fn() -> bool) -> bool { callback() }
        comptime fn produce() -> comptime fn() -> bool = flag;
    "#,
    );
    {
        let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
        let error = engine
            .invoke(
                id(&package, "apply"),
                vec![Value::Function(id(&package, "runtime_flag"))],
            )
            .unwrap_err();
        assert_eq!(error.kind, ErrorKind::Type);
        assert_eq!(
            engine
                .invoke(
                    id(&package, "apply"),
                    vec![Value::Function(id(&package, "flag"))]
                )
                .unwrap(),
            Value::Bool(true)
        );
    }
    let produce = package
        .functions
        .iter_mut()
        .find(|f| f.name == "produce")
        .unwrap();
    produce.body.ty = produce.body.ty.callable_signature().clone();
    assert!(
        nir::phases::validate(&package)
            .unwrap_err()
            .message
            .contains("preserve its declaration phase")
    );
}

