#[test]
fn comptime_constant_closures_restore_nested_environments_and_named_instances() {
    let package = execution_support::compile_with_tuple(
        r#"
        typealias Int = .Integer'builtin;
        comptime fn identity(value: T) -> T where T { value }
        const NESTED = do {
            let offset: Int = 4;
            let inner = |value: Int| value + offset;
            |value: Int| inner(value)
        };
        const GENERIC = do {
            let callback = identity<Int>;
            |value: Int| callback(value)
        };
        const COMBINED = do {
            let left = NESTED;
            let right = GENERIC;
            |value: Int| right(left(value))
        };
        const WIDTH = COMBINED(4);
        typealias Byte = .BitVec'builtin<WIDTH>;
        comptime fn run() -> Tuple<Int, Int> { (COMBINED(4), COMBINED(6)) }
    "#,
    );
    let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    assert_eq!(
        engine.invoke(id(&package, "run"), vec![]).unwrap(),
        Value::Tuple(vec![
            Value::Integer(comptime_runtime::Integer::from_u128(8)),
            Value::Integer(comptime_runtime::Integer::from_u128(10)),
        ])
    );
    assert_eq!(calls(&package, &engine), ["run", "identity", "identity"]);
    assert!(package.to_string().contains("(capture (binding"));
}

