#[test]
fn restored_closure_environment_neither_reads_nor_overwrites_colliding_caller_binding() {
    use nir::program::ExprKind as K;
    let package = execution_support::compile_with_tuple(
        "const CALLBACK = do { let flag = true; || flag }; comptime fn run(flag: bool) -> Tuple<bool, bool> { (CALLBACK(), flag) }",
    );
    let function = package.functions.iter().find(|f| f.name == "run").unwrap();
    let K::Block {
        result: Some(result),
        ..
    } = &function.body.kind
    else {
        panic!("body block");
    };
    let K::Tuple(fields) = &result.kind else {
        panic!("tuple");
    };
    let K::Call { callee, .. } = &fields[0].kind else {
        panic!("call");
    };
    let K::Call {
        callee: builder, ..
    } = &callee.kind
    else {
        panic!("snapshot invocation");
    };
    let K::Closure {
        body,
        captures: builder_captures,
        ..
    } = &builder.kind
    else {
        panic!("snapshot builder");
    };
    assert!(builder_captures.is_empty());
    let K::Block { statements, .. } = &body.kind else {
        panic!("snapshot graph");
    };
    let K::Let {
        binding: materialized,
        value,
    } = &statements.last().unwrap().kind
    else {
        panic!("materialized binding");
    };
    let K::Closure { captures, .. } = &value.kind else {
        panic!("closure");
    };
    assert!(captures[0].value.is_some());
    // Both original capture names and synthesized graph bindings may collide
    // with a caller name. Snapshot construction must restore the caller scope.
    for binding in [captures[0].binding, *materialized] {
        let mut package = package.clone();
        let function = package
            .functions
            .iter_mut()
            .find(|f| f.name == "run")
            .unwrap();
        function.parameters[0] = binding;
        let K::Block {
            result: Some(result),
            ..
        } = &mut function.body.kind
        else {
            unreachable!();
        };
        let K::Tuple(fields) = &mut result.kind else {
            unreachable!();
        };
        fields[1].kind = K::Local(binding);
        let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
        assert_eq!(
            engine
                .invoke(id(&package, "run"), vec![Value::Bool(false)])
                .unwrap(),
            Value::Tuple(vec![Value::Bool(true), Value::Bool(false)])
        );
    }
}

