#[test]
fn computed_type_patterns_evaluate_only_attempted_candidates_in_order() {
    let package = compile(
        r#"
        typealias Type = .Type'builtin;
        typealias Bool = bool;
        comptime fn FirstType() -> Type { Bool }
        comptime fn SecondType() -> Type { 'z''type }
        comptime fn choose(value: Type) -> Bool {
            value match { < FirstType() > => true, < SecondType() > => false, _ => true }
        }
    "#,
    );
    let context = elaboration::ptc::Context::from_package(&package).unwrap();
    let solver = |predicate: &nir::program::TypePredicate| {
        use comptime_interpretor::ContractOutcome;
        use elaboration::ptc::{Budget, Formula, Outcome};
        match context.prove(Formula::from_predicate(predicate), Budget::default()) {
            Outcome::Entailed(_) => ContractOutcome::Satisfied,
            Outcome::NotEntailed(_) => ContractOutcome::Rejected,
            _ => ContractOutcome::Unknown,
        }
    };
    let mut interpreter = Interpreter::for_comptime(&package, Budget::default())
        .unwrap()
        .with_type_solver(&solver);
    for (primitive, expected, attempted) in [
        (nir::Primitive::Bool, true, vec![id(&package, "FirstType")]),
        (
            nir::Primitive::Char,
            false,
            vec![id(&package, "FirstType"), id(&package, "SecondType")],
        ),
        (nir::Primitive::Bool, true, vec![id(&package, "FirstType")]),
    ] {
        let start = interpreter.events().len();
        assert_eq!(
            interpreter
                .invoke(
                    id(&package, "choose"),
                    vec![Value::Type(nir::Term::Primitive(primitive))]
                )
                .unwrap(),
            Value::Bool(expected)
        );
        let mut entries: Vec<_> = interpreter.events()[start..]
            .iter()
            .filter_map(|event| match event {
                comptime_interpretor::Event::EnterFunction(id) => Some(*id),
                _ => None,
            })
            .collect();
        assert_eq!(entries.remove(0), id(&package, "choose"));
        assert_eq!(entries, attempted);
    }
}

