#[test]
fn computed_value_patterns_preserve_candidate_order_and_rollback() {
    let package = compile_bound_tuple_fixture(include_str!(
        "../../../development/examples/computed-value-patterns.fl"
    ));
    let integer = |value| Value::Integer(comptime_runtime::Integer::from_u128(value));
    assert_eq!(
        luna::invocation::invoke(&package, "run", 100_000).unwrap(),
        Value::Tuple(vec![
            integer(1),
            integer(2),
            integer(0),
            Value::Bool(true),
            Value::Bool(false),
            Value::Bool(true),
            Value::Bool(true),
            integer(37)
        ])
    );
    assert_eq!(
        luna::invocation::invoke(&package, "scalar_equal", 100_000).unwrap(),
        Value::Tuple(vec![Value::Bool(true); 6])
    );
    for (value, expected_calls) in [
        (11, vec!["choose", "first"]),
        (17, vec!["choose", "first", "second"]),
        (23, vec!["choose", "first", "second"]),
    ] {
        let mut interpreter = Interpreter::for_comptime(&package, Budget::default()).unwrap();
        interpreter
            .invoke(id(&package, "choose"), vec![integer(value)])
            .unwrap();
        assert_eq!(calls(&package, &interpreter), expected_calls);
    }
    let mut interpreter = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    assert_eq!(
        interpreter
            .invoke(id(&package, "early"), vec![Value::Bool(false)])
            .unwrap(),
        Value::Bool(true)
    );
    assert_eq!(
        luna::invocation::invoke(&package, "unreachable_pattern", 100_000).unwrap(),
        Value::Bool(true)
    );
    let mut interpreter = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    assert_eq!(
        interpreter
            .invoke(id(&package, "ordered_equal"), vec![])
            .unwrap(),
        Value::Bool(true)
    );
    assert_eq!(
        calls(&package, &interpreter),
        ["ordered_equal", "first_text", "second_text"]
    );
    assert!(package.to_string().contains("scalar-equal"));
}

