#[test]
fn range_patterns_preserve_bounds_and_evaluate_endpoints_once() {
    let package = compile_bound_tuple_fixture(include_str!(
        "../../../development/examples/range-patterns.fl"
    ));
    let integer = |value| Value::Integer(comptime_runtime::Integer::from_u128(value));
    assert_eq!(
        luna::invocation::invoke(&package, "run", 100_000).unwrap(),
        Value::Tuple(vec![
            integer(1),
            integer(2),
            integer(3),
            integer(4),
            Value::Bool(true),
            Value::Bool(true),
            Value::Bool(false),
            Value::Bool(true)
        ])
    );
    let mut interpreter = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    assert_eq!(
        interpreter
            .invoke(id(&package, "early"), vec![integer(5)])
            .unwrap(),
        Value::Bool(true)
    );
    assert_eq!(calls(&package, &interpreter), ["early"]);
    for value in [-128, 0, 127] {
        let mut interpreter = Interpreter::for_comptime(&package, Budget::default()).unwrap();
        assert_eq!(
            interpreter
                .invoke(
                    id(&package, "signed"),
                    vec![
                        Value::SignedInteger(value),
                        Value::SignedInteger(-128),
                        Value::SignedInteger(127)
                    ]
                )
                .unwrap(),
            Value::Bool(true)
        );
    }
    for (name, value, expected) in [
        ("to_inclusive", 0, true),
        ("to_inclusive", 1, false),
        ("guarded", 5, false),
    ] {
        let mut interpreter = Interpreter::for_comptime(&package, Budget::default()).unwrap();
        assert_eq!(
            interpreter
                .invoke(id(&package, name), vec![integer(value)])
                .unwrap(),
            Value::Bool(expected)
        );
    }
    for (value, expected) in [(2, false), (3, true), (9, true), (10, false)] {
        let mut interpreter = Interpreter::for_comptime(&package, Budget::default()).unwrap();
        assert_eq!(
            interpreter
                .invoke(id(&package, "computed"), vec![integer(value)])
                .unwrap(),
            Value::Bool(expected)
        );
        assert_eq!(
            calls(&package, &interpreter),
            ["computed", "lower", "upper"]
        );
    }
    for (value, low, high, expected) in [
        (3, 3, 4, true),
        (4, 3, 4, false),
        (3, 3, 3, false),
        (9, 7, 2, false),
    ] {
        let mut interpreter = Interpreter::for_comptime(&package, Budget::default()).unwrap();
        assert_eq!(
            interpreter
                .invoke(
                    id(&package, "bounded"),
                    vec![integer(value), integer(low), integer(high)]
                )
                .unwrap(),
            Value::Bool(expected)
        );
    }
}

