#[test]
fn scalar_ordering_preserves_width_extrema_and_operand_order() {
    let package = compile_bound_tuple_fixture(include_str!(
        "../../../development/examples/scalar-ordering.fl"
    ));
    assert_eq!(
        luna::invocation::invoke(&package, "run", 100_000).unwrap(),
        Value::Tuple(vec![Value::Bool(true); 4])
    );
    for entry in ["early_right", "specialized"] {
        assert_eq!(
            luna::invocation::invoke(&package, entry, 100_000).unwrap(),
            Value::Bool(true)
        );
    }
    let expected = |order: std::cmp::Ordering| {
        Value::Tuple(vec![
            Value::Bool(order.is_lt()),
            Value::Bool(!order.is_gt()),
            Value::Bool(order.is_gt()),
            Value::Bool(!order.is_lt()),
        ])
    };
    for a in [0u128, 1, 127, 128, 254, 255] {
        for b in [0u128, 1, 127, 128, 254, 255] {
            let mut interpreter = Interpreter::for_comptime(&package, Budget::default()).unwrap();
            assert_eq!(
                interpreter
                    .invoke(
                        id(&package, "byte"),
                        vec![Value::UnsignedInteger(a), Value::UnsignedInteger(b)]
                    )
                    .unwrap(),
                expected(a.cmp(&b))
            );
        }
    }
    for a in [i128::MIN, -1, 0, 1, i128::MAX] {
        for b in [i128::MIN, -1, 0, 1, i128::MAX] {
            let mut interpreter = Interpreter::for_comptime(&package, Budget::default()).unwrap();
            assert_eq!(
                interpreter
                    .invoke(
                        id(&package, "signed"),
                        vec![Value::SignedInteger(a), Value::SignedInteger(b)]
                    )
                    .unwrap(),
                expected(a.cmp(&b))
            );
        }
    }
    for a in ['\0', 'a', '\u{d7ff}', '\u{e000}', '\u{10ffff}'] {
        for b in ['\0', 'a', '\u{d7ff}', '\u{e000}', '\u{10ffff}'] {
            let mut interpreter = Interpreter::for_comptime(&package, Budget::default()).unwrap();
            assert_eq!(
                interpreter
                    .invoke(
                        id(&package, "character"),
                        vec![Value::Char(a), Value::Char(b)]
                    )
                    .unwrap(),
                expected(a.cmp(&b))
            );
        }
    }
    for (entry, result) in [
        ("less", false),
        ("less_equal", false),
        ("greater", true),
        ("greater_equal", true),
    ] {
        let mut interpreter = Interpreter::for_comptime(&package, Budget::default()).unwrap();
        assert_eq!(
            interpreter.invoke(id(&package, entry), vec![]).unwrap(),
            Value::Bool(result)
        );
        assert_eq!(calls(&package, &interpreter), [entry, "left", "right"]);
    }
    let mut interpreter = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    assert_eq!(
        interpreter.invoke(id(&package, "early"), vec![]).unwrap(),
        Value::Bool(true)
    );
    assert_eq!(calls(&package, &interpreter), ["early"]);
}

