#[test]
fn comptime_methods_preserve_interface_phase_through_defaults_and_dispatch() {
    let package = compile_bound_tuple_fixture(include_str!(
        "../../../development/examples/comptime-methods.fl"
    ));
    assert_eq!(
        luna::invocation::invoke(&package, "run", 100_000).unwrap(),
        Value::Tuple(vec![
            Value::Bool(true),
            Value::Bool(true),
            Value::Bool(false),
            Value::Bool(true)
        ])
    );
    for entry in [
        "first_class",
        "associated",
        "parameterized",
        "optional",
        "parent",
    ] {
        assert_eq!(
            luna::invocation::invoke(&package, entry, 100_000).unwrap(),
            Value::Bool(true),
            "{entry}"
        );
    }
    let mut forged = package.clone();
    let read = forged
        .functions
        .iter_mut()
        .find(|function| function.name == "read")
        .unwrap();
    read.phase = nir::program::FunctionPhase::Runtime;
    assert!(
        matches!(Interpreter::new(&forged, Budget::default()), Err(error) if error.kind == ErrorKind::InvalidCallPlan)
    );
    let mut forged = package.clone();
    let contract = forged
        .traits
        .iter_mut()
        .flat_map(|interface| interface.methods.iter_mut())
        .find(|method| method.name == "read")
        .unwrap();
    contract.signature = contract
        .signature
        .callable_signature()
        .unwrap()
        .clone()
        .into();
    assert!(nir::phases::validate(&forged).is_err());
}

