#[test]
fn ieee_float_comparisons_preserve_unordered_values_zero_and_operand_order() {
    let package = compile_bound_tuple_fixture(include_str!(
        "../../../development/examples/float-comparisons.fl"
    ));
    let single: Vec<(u64, Option<i8>)> = vec![
        (0x7fc00001, None),
        (0xffc00002, None),
        (0x7f800001, None),
        (f32::NEG_INFINITY.to_bits() as u64, Some(-3)),
        ((-1.0f32).to_bits() as u64, Some(-2)),
        (0x80000001, Some(-1)),
        (0x80000000, Some(0)),
        (0, Some(0)),
        (1, Some(1)),
        (1.0f32.to_bits() as u64, Some(2)),
        (f32::INFINITY.to_bits() as u64, Some(3)),
    ];
    let double = vec![
        (0x7ff8000000000001, None),
        (0xfff8000000000002, None),
        (0x7ff0000000000001, None),
        (f64::NEG_INFINITY.to_bits(), Some(-3)),
        ((-1.0f64).to_bits(), Some(-2)),
        (0x8000000000000001, Some(-1)),
        (0x8000000000000000, Some(0)),
        (0, Some(0)),
        (1, Some(1)),
        (1.0f64.to_bits(), Some(2)),
        (f64::INFINITY.to_bits(), Some(3)),
    ];
    let mut interpreter = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    for (name, inputs) in [("single", single), ("double", double)] {
        for &(a, rank_a) in &inputs {
            for &(b, rank_b) in &inputs {
                let flags = match (rank_a, rank_b) {
                    (Some(a), Some(b)) => [a == b, a != b, a < b, a <= b, a > b, a >= b],
                    _ => [false, true, false, false, false, false],
                };
                let value = |bits| {
                    if name == "single" {
                        Value::Float32(bits as u32)
                    } else {
                        Value::Float64(bits)
                    }
                };
                assert_eq!(
                    interpreter
                        .invoke(id(&package, name), vec![value(a), value(b)])
                        .unwrap(),
                    Value::Tuple(flags.into_iter().map(Value::Bool).collect()),
                    "{name}: {a:x} compared with {b:x}",
                );
            }
        }
    }
    assert_eq!(
        interpreter.invoke(id(&package, "run"), vec![]).unwrap(),
        Value::Tuple(vec![Value::Bool(true); 4])
    );
    assert_eq!(
        interpreter
            .invoke(
                id(&package, "contextual"),
                vec![Value::Float32(2.0f32.to_bits())]
            )
            .unwrap(),
        Value::Tuple(vec![
            Value::Bool(false),
            Value::Bool(true),
            Value::Bool(true),
            Value::Bool(true)
        ])
    );
    assert_eq!(
        interpreter
            .invoke(id(&package, "pattern"), vec![Value::Float32(0x7fc00001); 2])
            .unwrap(),
        Value::Bool(false)
    );
}

