#[test]
fn checked_machine_arithmetic_executes_guarded_operations_at_byte_boundaries() {
    let package = compile(include_str!(
        "../../../development/examples/checked-machine-arithmetic.fl"
    ));
    let mut interpreter = Interpreter::new(
        &package,
        Budget {
            steps: 1_000_000,
            depth: 128,
        },
    )
    .unwrap();
    for value in 0..=255 {
        let increment = interpreter.invoke(
            id(&package, "increment"),
            vec![Value::UnsignedInteger(value)],
        );
        if value == 255 {
            assert_eq!(
                increment.unwrap_err().kind,
                ErrorKind::ProgramContractRejected
            );
        } else {
            assert_eq!(increment.unwrap(), Value::UnsignedInteger(value + 1));
        }
        assert_eq!(
            interpreter
                .invoke(id(&package, "guarded"), vec![Value::UnsignedInteger(value)])
                .unwrap(),
            Value::UnsignedInteger((value + 1).min(255))
        );
        let difference = interpreter.invoke(
            id(&package, "difference"),
            vec![Value::UnsignedInteger(value)],
        );
        if value < 10 {
            assert_eq!(
                difference.unwrap_err().kind,
                ErrorKind::ProgramContractRejected
            );
        } else {
            assert_eq!(difference.unwrap(), Value::UnsignedInteger(value - 10));
        }
    }
    for value in -128..=127 {
        let result =
            interpreter.invoke(id(&package, "negative"), vec![Value::SignedInteger(value)]);
        if value == -128 {
            assert_eq!(result.unwrap_err().kind, ErrorKind::ProgramContractRejected);
        } else {
            assert_eq!(result.unwrap(), Value::SignedInteger(-value));
        }
    }
    for a in 0..=15 {
        for b in 0..=17 {
            assert_eq!(
                interpreter
                    .invoke(
                        id(&package, "product"),
                        vec![Value::UnsignedInteger(a), Value::UnsignedInteger(b)]
                    )
                    .unwrap(),
                Value::UnsignedInteger(a * b)
            );
        }
    }
    let mut interpreter = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    assert_eq!(
        interpreter.invoke(id(&package, "run"), vec![]).unwrap(),
        Value::Bool(true)
    );
}

#[test]
fn checked_machine_arithmetic_covers_all_fixed_widths_and_rejects_forged_overflow() {
    for width in [8, 16, 32, 64, 128] {
        for signed in [false, true] {
            let ty = format!(".{}{width}'builtin", if signed { "i" } else { "u" });
            let source = format!("comptime fn calculate() -> {ty} {{ (7 + 3) * 2 - 5 }}");
            let package = compile(&source);
            let mut interpreter = Interpreter::for_comptime(&package, Budget::default()).unwrap();
            assert_eq!(
                interpreter
                    .invoke(id(&package, "calculate"), vec![])
                    .unwrap(),
                if signed {
                    Value::SignedInteger(15)
                } else {
                    Value::UnsignedInteger(15)
                }
            );
        }
    }
    let mut package = compile("comptime fn calculate() -> .u8'builtin { 250 + 5 }");
    let nir::program::ExprKind::Block {
        result: Some(body), ..
    } = &mut package.functions[0].body.kind
    else {
        panic!("block")
    };
    let nir::program::ExprKind::IntegerBinary { right, .. } = &mut body.kind else {
        panic!("arithmetic")
    };
    right.kind = nir::program::ExprKind::Literal(nir::program::Literal::UnsignedInteger(6));
    assert!(elaboration::verification::flow::validate_machine_operations(&package).is_err());
    let mut interpreter = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    assert_eq!(
        interpreter
            .invoke(id(&package, "calculate"), vec![])
            .unwrap_err()
            .kind,
        ErrorKind::MachineOverflow
    );
}

