#[test]
fn checked_machine_tuples_preserve_element_snapshots_joins_captures_and_patterns() {
    let package = compile_bound_tuple_fixture(include_str!(
        "../../../development/examples/checked-machine-tuples.fl"
    ));
    let mut interpreter = Interpreter::new(
        &package,
        Budget {
            steps: 1_000_000,
            depth: 128,
        },
    )
    .unwrap();
    for (name, result) in [
        ("literal_pair", 9),
        ("element_order", 14),
        ("capture_snapshot", 9),
        ("snapshot", 5),
        ("reassigned", 200),
        ("capture", 9),
        ("remapped", 9),
        ("run", 255),
    ] {
        assert_eq!(
            interpreter.invoke(id(&package, name), vec![]).unwrap(),
            Value::UnsignedInteger(result),
            "{name}"
        );
    }
    for flag in [false, true] {
        assert_eq!(
            interpreter
                .invoke(id(&package, "selected"), vec![Value::Bool(flag)])
                .unwrap(),
            Value::UnsignedInteger(if flag { 9 } else { 30 })
        );
        assert_eq!(
            interpreter
                .invoke(id(&package, "branches"), vec![Value::Bool(flag)])
                .unwrap(),
            Value::UnsignedInteger(if flag { 9 } else { 30 })
        );
    }
    for a in [0, 1, 55, 100, 101, 255] {
        for b in [0, 1, 55, 100, 101, 255] {
            let result = interpreter.invoke(
                id(&package, "parameter"),
                vec![Value::Tuple(vec![
                    Value::UnsignedInteger(a),
                    Value::UnsignedInteger(b),
                ])],
            );
            if a <= 100 && b <= 100 {
                assert_eq!(result.unwrap(), Value::UnsignedInteger(a + b));
            } else {
                assert_eq!(result.unwrap_err().kind, ErrorKind::ProgramContractRejected);
            }
            for c in [0, 55, 56, 255] {
                let value = Value::Tuple(vec![
                    Value::UnsignedInteger(a),
                    Value::Tuple(vec![Value::UnsignedInteger(b), Value::UnsignedInteger(c)]),
                ]);
                assert_eq!(
                    interpreter
                        .invoke(id(&package, "nested"), vec![value])
                        .unwrap(),
                    Value::UnsignedInteger(if a <= 100 && b <= 100 && c <= 55 {
                        a + b + c
                    } else {
                        0
                    })
                );
            }
        }
    }
    let function = package
        .functions
        .iter()
        .find(|f| f.name == "branches")
        .unwrap();
    let report = elaboration::verification::flow::analyze_in_package(
        &package,
        function,
        &mut elaboration::verification::Limits::default(),
    )
    .unwrap();
    println!("{report}");
}

