#[test]
fn checked_field_predicates_refine_paths_and_snapshot_copies() {
    let source = include_str!("../../../development/examples/checked-field-predicates.fl");
    let package = execution_support::compile_with_tuple(&format!("{source}
        fn inputs(value: Byte, flag: bool) -> Tuple<Byte, Byte, Byte, Byte, Byte, Byte, Byte, Byte, Byte> {{
            let pair = Pair {{ left: value, right: 255 }};
            let outer = Outer {{ inner: pair, tail: 255 }};
            (direct(pair), nested(outer), generic(Box<Byte> {{ value: value }}), sibling(pair,flag), nested_sibling(outer), copies(pair), capture(pair), match_scope(pair,flag), nested_capture(outer))
        }}
        fn boolean_inputs() -> Tuple<Byte, Byte, Byte> {{ (conjunction(Pair {{ left: 99, right: 99 }}), disjunction(Pair {{ left: 99, right: 255 }}), block_condition(Pair {{ left: 99, right: 99 }})) }}
        fn branch_inputs(flag: bool) -> Tuple<Byte, Byte> {{ (both_branches(Pair {{ left: 99, right: 255 }}, flag), both_replaced(Pair {{ left: 255, right: 255 }}, flag)) }}
        fn guarded_input(value: Byte) -> Byte {{ guarded(Pair {{ left: value, right: 255 }}) }}"));
    let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
    for value in 0..255 {
        for flag in [false, true] {
            let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
            assert_eq!(
                interpreter
                    .invoke(
                        id(&package, "inputs"),
                        vec![Value::UnsignedInteger(value), Value::Bool(flag)]
                    )
                    .unwrap(),
                Value::Tuple(vec![Value::UnsignedInteger(value + 1); 9])
            );
        }
    }
    assert_eq!(
        interpreter
            .invoke(id(&package, "boolean_inputs"), vec![])
            .unwrap(),
        Value::Tuple(vec![
            Value::UnsignedInteger(198),
            Value::UnsignedInteger(100),
            Value::UnsignedInteger(198)
        ])
    );
    for flag in [false, true] {
        assert_eq!(
            interpreter
                .invoke(id(&package, "branch_inputs"), vec![Value::Bool(flag)])
                .unwrap(),
            Value::Tuple(vec![
                Value::UnsignedInteger(100),
                Value::UnsignedInteger(if flag { 101 } else { 201 })
            ])
        );
    }
    for value in 0..=255 {
        assert_eq!(
            interpreter
                .invoke(
                    id(&package, "guarded_input"),
                    vec![Value::UnsignedInteger(value)]
                )
                .unwrap(),
            Value::UnsignedInteger((value + 1).min(255))
        );
    }
    for name in ["run", "closure_parameter"] {
        assert_eq!(
            interpreter.invoke(id(&package, name), vec![]).unwrap(),
            Value::UnsignedInteger(255)
        );
    }
    assert_eq!(
        interpreter
            .invoke(
                id(&package, "inputs"),
                vec![Value::UnsignedInteger(255), Value::Bool(false)]
            )
            .unwrap_err()
            .kind,
        ErrorKind::ProgramContractRejected
    );
    let function = package
        .functions
        .iter()
        .find(|f| f.name == "sibling")
        .unwrap();
    let report = elaboration::verification::flow::analyze_in_package(
        &package,
        function,
        &mut elaboration::verification::Limits::default(),
    )
    .unwrap();
    assert!(report.to_string().contains("(field-paths ((field-path"));
    println!("{report}");
}

#[test]
fn checked_relational_arithmetic_preserves_correlations_and_runtime_checks() {
    let source = include_str!("../../../development/examples/checked-relational-arithmetic.fl");
    let package=compile(&format!("{source}
        fn fields(start:Byte,end:Byte) -> Byte {{ field_distance(Pair {{ start: start, end: end }}) }}"));
    for start in 0..=255 {
        for end in [0, 1, 99, 100, 150, 254, 255] {
            let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
            let args = vec![Value::UnsignedInteger(start), Value::UnsignedInteger(end)];
            for name in ["distance", "fields"] {
                let result = interpreter.invoke(id(&package, name), args.clone());
                if start <= end {
                    assert_eq!(result.unwrap(), Value::UnsignedInteger(end - start));
                } else {
                    assert_eq!(result.unwrap_err().kind, ErrorKind::ProgramContractRejected);
                }
            }
            assert_eq!(
                interpreter
                    .invoke(id(&package, "guarded_distance"), args.clone())
                    .unwrap(),
                Value::UnsignedInteger(start.abs_diff(end))
            );
            let next = interpreter.invoke(id(&package, "next"), args.clone());
            if start < end {
                assert_eq!(next.unwrap(), Value::UnsignedInteger(start + 1));
            } else {
                assert_eq!(next.unwrap_err().kind, ErrorKind::ProgramContractRejected);
            }
            for flag in [false, true] {
                let result = interpreter.invoke(
                    id(&package, "branches"),
                    vec![args[0].clone(), args[1].clone(), Value::Bool(flag)],
                );
                if start <= end {
                    assert_eq!(result.unwrap(), Value::UnsignedInteger(end - start));
                } else {
                    assert_eq!(result.unwrap_err().kind, ErrorKind::ProgramContractRejected);
                }
            }
        }
    }
    let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
    for (name, args, expected) in [
        (
            "sum_after_bounds",
            vec![Value::UnsignedInteger(75), Value::UnsignedInteger(75)],
            250,
        ),
        (
            "triangle",
            vec![
                Value::UnsignedInteger(97),
                Value::UnsignedInteger(98),
                Value::UnsignedInteger(99),
            ],
            254,
        ),
        (
            "equality",
            vec![Value::UnsignedInteger(255), Value::UnsignedInteger(255)],
            0,
        ),
        ("cancellation", vec![Value::UnsignedInteger(255)], 0),
        (
            "cubic",
            vec![
                Value::UnsignedInteger(4),
                Value::UnsignedInteger(5),
                Value::UnsignedInteger(5),
            ],
            255,
        ),
        (
            "quartic_with_plain_bounds",
            vec![Value::UnsignedInteger(2)],
            16,
        ),
        (
            "variable_limit",
            vec![
                Value::UnsignedInteger(75),
                Value::UnsignedInteger(75),
                Value::UnsignedInteger(150),
            ],
            250,
        ),
        ("closure_parameter", vec![], 254),
        ("run", vec![], 155),
    ] {
        assert_eq!(
            interpreter.invoke(id(&package, name), args).unwrap(),
            Value::UnsignedInteger(expected),
            "{name}"
        );
    }
    let function = package
        .functions
        .iter()
        .find(|f| f.name == "sum_after_bounds")
        .unwrap();
    let report = elaboration::verification::flow::analyze_in_package(
        &package,
        function,
        &mut elaboration::verification::Limits::default(),
    )
    .unwrap();
    assert!(
        report
            .to_string()
            .contains("(inequalities (less-equal-zero")
    );
    println!("{report}");
}

#[test]
fn checked_transitive_arithmetic_joins_alternative_proofs_and_rounds_coefficients() {
    let source = include_str!("../../../development/examples/checked-transitive-arithmetic.fl");
    let package = compile(&format!(
        "{source} fn fields(a:Byte,b:Byte,c:Byte) -> Byte {{ field_chain(Triple {{ first:a,middle:b,last:c }}) }}"
    ));
    for a in [0, 1, 99, 100, 127, 254, 255] {
        for b in [0, 1, 99, 100, 127, 254, 255] {
            for c in [0, 1, 99, 100, 127, 254, 255] {
                let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
                let args = vec![
                    Value::UnsignedInteger(a),
                    Value::UnsignedInteger(b),
                    Value::UnsignedInteger(c),
                ];
                for name in ["transitive", "fields", "strict"] {
                    let valid = if name == "strict" {
                        a < b && b < c
                    } else {
                        a <= b && b <= c
                    };
                    let result = interpreter.invoke(id(&package, name), args.clone());
                    if valid {
                        assert_eq!(
                            result.unwrap(),
                            Value::UnsignedInteger(c - a - if name == "strict" { 2 } else { 0 })
                        );
                    } else {
                        assert_eq!(result.unwrap_err().kind, ErrorKind::ProgramContractRejected);
                    }
                }
                let d = 100;
                let args = vec![
                    Value::UnsignedInteger(a),
                    Value::UnsignedInteger(b),
                    Value::UnsignedInteger(c),
                    Value::UnsignedInteger(d),
                ];
                let valid = (a <= b && b <= c) || (a <= d && d <= c);
                let result = interpreter.invoke(id(&package, "alternatives"), args.clone());
                if valid {
                    assert_eq!(result.unwrap(), Value::UnsignedInteger(c - a));
                } else {
                    assert_eq!(result.unwrap_err().kind, ErrorKind::ProgramContractRejected);
                }
                for flag in [false, true] {
                    let mut args = args.clone();
                    args.push(Value::Bool(flag));
                    let valid = if flag {
                        a <= b && b <= c
                    } else {
                        a <= d && d <= c
                    };
                    let result = interpreter.invoke(id(&package, "branches"), args);
                    if valid {
                        assert_eq!(result.unwrap(), Value::UnsignedInteger(c - a));
                    } else {
                        assert_eq!(result.unwrap_err().kind, ErrorKind::ProgramContractRejected);
                    }
                }
            }
        }
    }
    for x in -128i128..=127 {
        let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
        for name in ["negative_floor", "positive_ceiling"] {
            let valid = if name == "negative_floor" {
                (-20..=-3).contains(&x)
            } else {
                (3..=20).contains(&x)
            };
            let result = interpreter.invoke(id(&package, name), vec![Value::SignedInteger(x)]);
            if valid {
                assert_eq!(
                    result.unwrap(),
                    Value::SignedInteger(if name == "negative_floor" {
                        x + 127
                    } else {
                        x - 127
                    })
                );
            } else {
                assert_eq!(result.unwrap_err().kind, ErrorKind::ProgramContractRejected);
            }
        }
    }
    let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        interpreter
            .invoke(
                id(&package, "variable_coefficient_bound"),
                vec![Value::UnsignedInteger(50), Value::UnsignedInteger(101)]
            )
            .unwrap(),
        Value::UnsignedInteger(255)
    );
    for value in 0..=255 {
        let result = interpreter.invoke(
            id(&package, "variable_coefficient_bound"),
            vec![Value::UnsignedInteger(value), Value::UnsignedInteger(101)],
        );
        if value <= 50 {
            assert_eq!(result.unwrap(), Value::UnsignedInteger(value + 205));
        } else {
            assert_eq!(result.unwrap_err().kind, ErrorKind::ProgramContractRejected);
        }
    }
    for (name, expected) in [("closure_parameter", 255), ("run", 253)] {
        assert_eq!(
            interpreter.invoke(id(&package, name), vec![]).unwrap(),
            Value::UnsignedInteger(expected)
        );
    }
    let function = package
        .functions
        .iter()
        .find(|f| f.name == "branches")
        .unwrap();
    let report = elaboration::verification::flow::analyze_in_package(
        &package,
        function,
        &mut elaboration::verification::Limits::default(),
    )
    .unwrap();
    println!("{report}");
}

#[test]
fn checked_relational_copies_freeze_values_and_transfer_capture_evidence() {
    let source = include_str!("../../../development/examples/checked-relational-copies.fl");
    let package = execution_support::compile_with_tuple(&format!(
        "{source}
        fn records(start: Byte,end: Byte) -> Tuple<Byte, Byte, Byte, Byte, Byte, Byte, Byte, Byte, Byte, Byte, Byte> {{
            let pair=Pair {{ start:start,end:end }};
            let outer=Outer {{ pair:pair,tag:255 }};
            (record_copy(pair),nested_copy(outer),record_capture(pair),nested_capture(outer),field_write(pair),pattern_copy(pair),remapped_copy(pair,true),remapped_copy(pair,false),generic_copy(Span<Byte> {{ start:start,end:end }}),branch_copy(pair,true),branch_copy(pair,false))
        }}"
    ));
    for start in [0, 1, 100, 127, 254, 255] {
        for end in [0, 1, 100, 127, 254, 255] {
            let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
            let args = vec![Value::UnsignedInteger(start), Value::UnsignedInteger(end)];
            for name in [
                "scalar_copy",
                "scalar_capture",
                "nested_closure",
                "scalar_field_write",
            ] {
                let result = interpreter.invoke(id(&package, name), args.clone());
                if start <= end {
                    assert_eq!(
                        result.unwrap(),
                        Value::UnsignedInteger(end - start),
                        "{name}"
                    );
                } else {
                    assert_eq!(result.unwrap_err().kind, ErrorKind::ProgramContractRejected);
                }
            }
            let result = interpreter.invoke(id(&package, "records"), args.clone());
            if start <= end {
                assert_eq!(
                    result.unwrap(),
                    Value::Tuple(vec![Value::UnsignedInteger(end - start); 11])
                );
            } else {
                assert_eq!(result.unwrap_err().kind, ErrorKind::ProgramContractRejected);
            }
        }
    }
    let mut interpreter = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        interpreter
            .invoke(
                id(&package, "transitive_capture"),
                vec![
                    Value::UnsignedInteger(0),
                    Value::UnsignedInteger(127),
                    Value::UnsignedInteger(255)
                ]
            )
            .unwrap(),
        Value::UnsignedInteger(255)
    );
    assert_eq!(
        interpreter
            .invoke(
                id(&package, "sum_binding"),
                vec![Value::UnsignedInteger(75), Value::UnsignedInteger(75)]
            )
            .unwrap(),
        Value::UnsignedInteger(250)
    );
    for value in 0..=255 {
        assert_eq!(
            interpreter
                .invoke(
                    id(&package, "same_value_copy"),
                    vec![Value::UnsignedInteger(value)]
                )
                .unwrap(),
            Value::UnsignedInteger(0)
        );
    }
    assert_eq!(
        interpreter.invoke(id(&package, "run"), vec![]).unwrap(),
        Value::UnsignedInteger(155)
    );
    let function = package
        .functions
        .iter()
        .find(|f| f.name == "nested_closure")
        .unwrap();
    let report = elaboration::verification::flow::analyze_in_package(
        &package,
        function,
        &mut elaboration::verification::Limits::default(),
    )
    .unwrap();
    assert!(report.points.iter().any(|p| p.closure_context.len() == 2));
    let dump = report.to_string();
    let mut budget = elaboration::verification::Limits::default();
    let initial = budget.arithmetic.steps;
    let repeated =
        elaboration::verification::flow::analyze_in_package(&package, function, &mut budget)
            .unwrap();
    assert_eq!(dump, repeated.to_string());
    let used = initial - budget.arithmetic.steps;
    let mut restricted = elaboration::verification::Limits::default();
    restricted.arithmetic.steps = used / 2;
    assert!(
        elaboration::verification::flow::analyze_in_package(&package, function, &mut restricted)
            .is_err()
    );
    assert_eq!(
        dump,
        elaboration::verification::flow::analyze_in_package(
            &package,
            function,
            &mut elaboration::verification::Limits::default()
        )
        .unwrap()
        .to_string()
    );
    println!("{report}");
}

#[test]
fn checked_relational_capture_initializers_preserve_evaluation_versions() {
    use nir::program::{Expr, ExprKind as K, Literal, Place};
    use nir::{Primitive as P, Term};
    let original = compile(
        "typealias Byte = .u8'builtin; fn run(a: Byte, b: Byte) -> Byte { var x = a; var y = b; assumes x <= y; let callback = || { let saved = x; y - saved }; callback() }",
    );
    for mode in 0..3 {
        let mut package = original.clone();
        let function = package
            .functions
            .iter_mut()
            .find(|f| f.name == "run")
            .unwrap();
        let K::Block { statements, .. } = &mut function.body.kind else {
            panic!("block")
        };
        let callback = statements
            .iter_mut()
            .find_map(|s| match &mut s.kind {
                K::Let { value, .. } if matches!(value.kind, K::Closure { .. }) => Some(value),
                _ => None,
            })
            .unwrap();
        let source = callback.source;
        let K::Closure { captures, .. } = &mut callback.kind else {
            unreachable!()
        };
        assert_eq!(captures.len(), 2);
        let first = captures[0].binding;
        let second = captures[1].binding;
        let ty = Term::Primitive(P::U8);
        captures[1].value = Some(Box::new(if mode == 2 {
            Expr {
                ty: ty.clone(),
                source,
                kind: K::Local(first),
            }
        } else {
            Expr {
                ty: ty.clone(),
                source,
                kind: K::Block {
                    statements: vec![Expr {
                        ty: Term::Primitive(P::Void),
                        source,
                        kind: K::Assign {
                            place: Place {
                                root: if mode == 0 { first } else { second },
                                fields: vec![],
                            },
                            value: Box::new(Expr {
                                ty: ty.clone(),
                                source,
                                kind: K::Literal(Literal::UnsignedInteger(if mode == 0 {
                                    255
                                } else {
                                    0
                                })),
                            }),
                        },
                    }],
                    result: Some(Box::new(Expr {
                        ty: ty.clone(),
                        source,
                        kind: K::Local(second),
                    })),
                },
            }
        }));
        let report = elaboration::verification::flow::validate_machine_operations(&package);
        let result = Interpreter::new(&package, Budget::default())
            .unwrap()
            .invoke(
                id(&package, "run"),
                vec![Value::UnsignedInteger(1), Value::UnsignedInteger(2)],
            );
        if mode == 1 {
            assert!(matches!(
                report.unwrap_err().reason,
                elaboration::verification::flow::Reason::MissingMachineProof
            ));
            assert!(result.is_err());
        } else {
            report.unwrap();
            assert_eq!(
                result.unwrap(),
                Value::UnsignedInteger(if mode == 0 { 1 } else { 0 })
            );
        }
    }
}

