#[test]
fn pointer_normalized_types_and_fields_are_checked() {
    let mut package = compile(
        "struct Cell { value: bool, } fn run() -> bool { let cell = Cell { value: true }; cell.ref.value.* }",
    );
    let nir::program::ExprKind::Block {
        result: Some(result),
        ..
    } = &mut package.functions[0].body.kind
    else {
        panic!("block")
    };
    let nir::program::ExprKind::ReadPointer(pointer) = &mut result.kind else {
        panic!("read")
    };
    let nir::program::ExprKind::PointerField { index, .. } = &mut pointer.kind else {
        panic!("projection")
    };
    *index = 99;
    let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        vm.invoke(id(&package, "run"), vec![]).unwrap_err().kind,
        ErrorKind::InvalidPointer
    );
    let nir::program::ExprKind::Block {
        result: Some(result),
        ..
    } = &mut package.functions[0].body.kind
    else {
        panic!("block")
    };
    result.ty = nir::Term::Primitive(nir::Primitive::Char);
    assert!(nir::phases::validate(&package).is_err());
    let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        vm.invoke(id(&package, "run"), vec![]).unwrap_err().kind,
        ErrorKind::Type
    );
    assert!(luna::instantiation::instantiate(&package, "run", 100_000).is_err());
}

