#[test]
fn aggregate_pointer_origins_preserve_declared_field_order_and_moved_view_identity() {
    for (declaration, expected, events) in [
        ("ptr:*bool,mark:bool,", true, vec!["run", "pointer", "mark"]),
        (
            "mark:bool,ptr:*bool,",
            false,
            vec!["run", "mark", "pointer"],
        ),
    ] {
        let package = compile(&format!(
            "struct Holder {{{declaration}}} fn pointer(p:*bool)->*bool {{p}} fn mark()->bool {{true}} fn run()->bool {{let first=true; let second=false; var p=first.ref; let holder=do {{let initial=Holder {{mark:do {{p=second.ref; mark()}},ptr:pointer(p)}}; initial}}; let moved=holder; moved.ptr.*}}"
        ));
        let run = package.functions.iter().find(|f| f.name == "run").unwrap();
        elaboration::verification::moves::analyze_in_package(
            &package,
            run,
            |ty| {
                Ok(
                    if matches!(ty, nir::Term::Primitive(_) | nir::Term::Pointer(_)) {
                        elaboration::verification::moves::Delivery::Copy
                    } else {
                        elaboration::verification::moves::Delivery::Move
                    },
                )
            },
            100000,
        )
        .unwrap();
        let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke(id(&package, "run"), vec![]).unwrap(),
            Value::Bool(expected)
        );
        assert_eq!(calls(&package, &vm), events);
        assert_eq!(
            luna::execution::interpret(&package, "run", 100_000).unwrap(),
            Value::Bool(expected)
        );
    }
}

