#[test]
fn checked_closure_resource_paths_agree_with_runtime_failure_and_repeat_calls() {
    let package = compile(
        "struct Token {} fn take(value:Token) {} fn checked(flag:bool)->bool {let value=Token {}; let action=|| {if flag {take(value); assumes false;}}; action(); action(); true} fn accepted()->bool {checked(false)} fn rejected()->bool {checked(true)}",
    );
    let function = package
        .functions
        .iter()
        .find(|f| f.name == "checked")
        .unwrap();
    elaboration::verification::moves::analyze_in_package(
        &package,
        function,
        |ty| {
            Ok(if matches!(ty, nir::Term::Primitive(_)) {
                elaboration::verification::moves::Delivery::Copy
            } else {
                elaboration::verification::moves::Delivery::Move
            })
        },
        100000,
    )
    .unwrap();
    for flag in [false, true] {
        let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
        let result = vm.invoke(id(&package, "checked"), vec![Value::Bool(flag)]);
        if flag {
            assert_eq!(result.unwrap_err().kind, ErrorKind::ProgramContractRejected);
            assert_eq!(calls(&package, &vm), vec!["checked", "take"]);
            assert_eq!(
                vm.events()
                    .iter()
                    .filter(|e| matches!(e, Event::CheckPredicate { passed: false, .. }))
                    .count(),
                1
            );
        } else {
            assert_eq!(result.unwrap(), Value::Bool(true));
            assert_eq!(calls(&package, &vm), vec!["checked"]);
        }
    }
    assert_eq!(
        luna::execution::interpret(&package, "accepted", 100000).unwrap(),
        Value::Bool(true)
    );
    assert!(luna::execution::interpret(&package, "rejected", 100000).is_err());
}

#[test]
fn summarized_call_rejection_agrees_with_runtime_check_order() {
    let package = compile(
        "struct Token {} fn checked(flag:bool,p:*bool)->bool {assumes flag; p.* = false; p.*} fn next()->bool {true} fn run(flag:bool)->bool {let owner=Token {}; let value=true; let ignored=checked(flag,value.ref); next()} fn accepted()->bool {run(true)} fn rejected()->bool {run(false)}",
    );
    let run = package.functions.iter().find(|f| f.name == "run").unwrap();
    let report = elaboration::verification::moves::analyze_in_package(
        &package,
        run,
        |ty| {
            Ok(
                if matches!(ty, nir::Term::Primitive(_) | nir::Term::Pointer(_)) {
                    elaboration::verification::moves::Delivery::Copy
                } else {
                    elaboration::verification::moves::Delivery::Move
                },
            )
        },
        100000,
    )
    .unwrap();
    assert_eq!(report.failed_exits.len(), 1, "{report}");
    for flag in [false, true] {
        let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
        let result = vm.invoke(id(&package, "run"), vec![Value::Bool(flag)]);
        if flag {
            assert_eq!(result.unwrap(), Value::Bool(true));
            assert_eq!(calls(&package, &vm), vec!["run", "checked", "next"]);
        } else {
            assert_eq!(result.unwrap_err().kind, ErrorKind::ProgramContractRejected);
            assert_eq!(calls(&package, &vm), vec!["run", "checked"]);
        }
        assert_eq!(
            vm.events()
                .iter()
                .filter(|e| matches!(e, Event::CheckPredicate { .. }))
                .count(),
            1
        );
    }
    assert_eq!(
        luna::execution::interpret(&package, "accepted", 100000).unwrap(),
        Value::Bool(true)
    );
    assert!(luna::execution::interpret(&package, "rejected", 100000).is_err());
}

