#[test]
fn mutable_capture_cells_persist_and_each_construction_is_independent() {
    for source in [
        "fn run()->bool {var flag=false;let toggle=|| {flag=not flag;flag};let first=toggle();let second=toggle();first and not second and not flag}",
        "fn run()->bool {var flag=false;let left=|| {flag=not flag;flag};let right=|| {flag=not flag;flag};let first=left();let other=right();let second=left();first and other and not second and not flag}",
        "typealias Counter=%{flag:bool} fn()->bool; fn make()->Counter {var flag=false;|| {flag=not flag;flag}} fn apply(counter:Counter)->bool {let first=counter();let second=counter();first and not second} fn run()->bool {apply(make())}",
        "struct State {flag:bool,} fn run()->bool {let state=State {flag:false};let toggle=|| {state.flag=not state.flag;state.flag};let first=toggle();let second=toggle();first and not second}",
        "fn run()->bool {var bits:.u8'builtin=0;let write=|| {bits'bitvec[0..4]=3;bits'bitvec[4..8]=10;bits==163};write() and bits==0}",
        "fn run()->bool {var flag=false;let outer=|| {flag=not flag;|| flag};let first=outer();let second=outer();first() and not second()}",
        "fn run()->bool {var flag=false;let write=|| {flag=true;};write();not flag}",
        "fn first()->bool {true} fn second()->bool {false} fn run()->bool {var callback=first;let next=|| {let previous=callback();callback=second;previous};let before=next();let after=next();before and not after}",
    ] {
        let package = compile(source);
        let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke(id(&package, "run"), vec![]).unwrap(),
            Value::Bool(true),
            "{source}"
        );
        assert_eq!(
            luna::execution::interpret(&package, "run", 100000).unwrap(),
            Value::Bool(true),
            "{source}"
        );
    }
}

#[test]
fn comptime_mutable_capture_snapshots_preserve_current_values_and_internal_sharing() {
    let package = compile_bound_tuple_fixture(include_str!(
        "../../../development/examples/comptime-stateful-closures.fl"
    ));
    let integer = |value| Value::Integer(comptime_runtime::Integer::from_u128(value));
    let mut interpreter = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    for (entry, expected) in [
        (
            "run",
            Value::Tuple(vec![integer(3), integer(4), integer(3)]),
        ),
        ("shared", Value::Tuple(vec![integer(1), integer(2)])),
        ("distinct", Value::Tuple(vec![integer(1), integer(1)])),
        ("nested", Value::Tuple(vec![integer(1), integer(2)])),
        ("replaced", Value::Bool(false)),
        ("with_default", Value::Tuple(vec![integer(3), integer(4)])),
        ("record", integer(4)),
        (
            "run",
            Value::Tuple(vec![integer(3), integer(4), integer(3)]),
        ),
    ] {
        assert_eq!(
            interpreter.invoke(id(&package, entry), vec![]).unwrap(),
            expected,
            "{entry}"
        );
    }
    let width = package
        .functions
        .iter()
        .find(|function| function.name == "width")
        .unwrap();
    assert!(
        matches!(width.signature.callable_signature(), nir::Term::Function {result, ..} if result.as_ref()==&nir::Term::Primitive(nir::Primitive::BitVec(3)))
    );
    println!(
        "COMPTIME_SNAPSHOT={}\nCOMPTIME_SNAPSHOT_END",
        package
            .functions
            .iter()
            .find(|function| function.name == "shared")
            .unwrap()
    );
}

#[test]
fn mutable_capture_checks_cannot_be_elided_using_creation_values() {
    use elaboration::verification::{self as v, optimization};
    for source in [
        "fn run() {var value:.u8'builtin=0;let next=|| {assumes value==0;value=1;};next();next();}",
        "struct State {value:.u8'builtin,} fn run() {let state=State {value:0};let next=|| {assumes state.value==0;state.value=1;};next();next();}",
        "fn run() {var value:.u8'builtin=0;let next=|| {assumes value==0;value'bitvec[0]=1;};next();next();}",
        "struct State {value:.u8'builtin,} fn run() {let state=State {value:0};let next=|| {assumes state.value==0;let pointer=state.value.ref;pointer.* = 1;};next();next();}",
        "struct State {value:.u8'builtin,} fn write(pointer:*.u8'builtin) {pointer.* = 1;} fn run() {let state=State {value:0};let next=|| {assumes state.value==0;write(state.value.ref);};next();next();}",
        "fn run() {var value:.u8'builtin=0;let next=|change:bool| {assumes value==0;if change {value=1;return;}};next(true);next(false);}",
        "fn run() {var value:.u8'builtin=7;let stable=value;let next=|| {assumes value==stable;value=0;};next();next();}",
    ] {
        let baseline = compile(source);
        let mut optimized = baseline.clone();
        let report = optimization::elide_proven_checks(&mut optimized, &mut v::Limits::default());
        for package in [&baseline, &optimized] {
            let mut interpreter = Interpreter::new(package, Budget::default()).unwrap();
            assert_eq!(
                interpreter
                    .invoke(id(package, "run"), vec![])
                    .unwrap_err()
                    .kind,
                ErrorKind::ProgramContractRejected,
                "{source}: {report}"
            );
        }
    }
}

