#[test]
fn default_memory_summary_invalidates_caller_even_when_callee_body_is_readonly() {
    use elaboration::verification::{self as v, optimization};
    use nir::program::{Expr, ExprKind as K, Literal};
    let mut baseline = compile(
        "fn read(p:*.u8'builtin,.copy:.u8'builtin=0)->.u8'builtin {copy} fn run() {let n:.u8'builtin=0;let stable:.u8'builtin=7;read(n.ref);assumes stable==7;assumes n==0;}",
    );
    // Source-level mutating defaults await P3 evidence. Exercise the lower IR
    // boundary independently so body-only summaries cannot hide default writes.
    let function = baseline
        .functions
        .iter_mut()
        .find(|f| f.name == "run")
        .unwrap();
    let K::Block { statements, .. } = &mut function.body.kind else {
        panic!("block")
    };
    let mut replaced = false;
    for statement in statements {
        let expression = match &mut statement.kind {
            K::Discard(value) => value.as_mut(),
            _ => statement,
        };
        let K::Call {
            arguments,
            parameter_bindings,
            ..
        } = &mut expression.kind
        else {
            continue;
        };
        let pointer_type = arguments
            .iter()
            .find(|a| a.parameter == 0)
            .unwrap()
            .value
            .ty
            .clone();
        let argument = arguments.iter_mut().find(|a| a.is_default).unwrap();
        let source = argument.value.source;
        let ty = argument.value.ty.clone();
        argument.value.kind = K::Block {
            statements: vec![Expr {
                source,
                ty: nir::Term::Primitive(nir::Primitive::Void),
                kind: K::WritePointer {
                    pointer: Box::new(Expr {
                        source,
                        ty: pointer_type,
                        kind: K::Local(parameter_bindings[0]),
                    }),
                    value: Box::new(Expr {
                        source,
                        ty: ty.clone(),
                        kind: K::Literal(Literal::UnsignedInteger(1)),
                    }),
                },
            }],
            result: Some(Box::new(Expr {
                source,
                ty,
                kind: K::Literal(Literal::UnsignedInteger(0)),
            })),
        };
        replaced = true;
    }
    assert!(replaced);
    let mut optimized = baseline.clone();
    let report = optimization::elide_proven_checks(&mut optimized, &mut v::Limits::default());
    assert_eq!(report.fallback_functions, 0, "{report}");
    assert_eq!(report.eliminated.len(), 1, "{report}");
    for package in [&baseline, &optimized] {
        let mut vm = Interpreter::new(package, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke(id(package, "run"), vec![]).unwrap_err().kind,
            ErrorKind::ProgramContractRejected
        );
    }
}

