#[test]
fn default_frame_pointer_rebinding_requires_conservative_call_invalidation() {
    use elaboration::verification::{self as v, optimization};
    use nir::program::{Expr, ExprKind as K, Literal, Place};
    let mut baseline = compile(
        "fn write(p:*.u8'builtin,q:*.u8'builtin,.ignored:.u8'builtin=0,.target:*.u8'builtin=p) {target.* = 1;} fn run() {let first:.u8'builtin=0;let second:.u8'builtin=0;write(first.ref,second.ref);assumes second==0;}",
    );
    // Model an unsupported source default which rebinds an earlier prepared
    // pointer. The following default observes that rebinding, unlike the
    // already snapshotted positional argument delivered to the callee body.
    let function = baseline
        .functions
        .iter_mut()
        .find(|f| f.name == "run")
        .unwrap();
    let K::Block { statements, .. } = &mut function.body.kind else {
        panic!("block")
    };
    let mut replaced = false;
    for statement in statements {
        let expression = match &mut statement.kind {
            K::Discard(value) => value.as_mut(),
            _ => statement,
        };
        let K::Call {
            arguments,
            parameter_bindings,
            ..
        } = &mut expression.kind
        else {
            continue;
        };
        let pointer_type = arguments
            .iter()
            .find(|a| a.parameter == 0)
            .unwrap()
            .value
            .ty
            .clone();
        let argument = arguments.iter_mut().find(|a| a.parameter == 2).unwrap();
        let source = argument.value.source;
        let ty = argument.value.ty.clone();
        argument.value.kind = K::Block {
            statements: vec![Expr {
                source,
                ty: nir::Term::Primitive(nir::Primitive::Void),
                kind: K::Assign {
                    place: Place {
                        root: parameter_bindings[0],
                        fields: vec![],
                    },
                    value: Box::new(Expr {
                        source,
                        ty: pointer_type,
                        kind: K::Local(parameter_bindings[1]),
                    }),
                },
            }],
            result: Some(Box::new(Expr {
                source,
                ty,
                kind: K::Literal(Literal::UnsignedInteger(0)),
            })),
        };
        replaced = true;
    }
    assert!(replaced);
    let mut optimized = baseline.clone();
    let report = optimization::elide_proven_checks(&mut optimized, &mut v::Limits::default());
    assert_eq!(report.fallback_functions, 0, "{report}");
    assert!(report.eliminated.is_empty(), "{report}");
    for package in [&baseline, &optimized] {
        let mut vm = Interpreter::new(package, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke(id(package, "run"), vec![]).unwrap_err().kind,
            ErrorKind::ProgramContractRejected
        );
    }
}

#[test]
fn local_pointer_origins_follow_copies_projections_and_rebinding() {
    for source in [
        "fn run()->.u8'builtin {let n:.u8'builtin=7;let p=n.ref;let q=p;q.* + 1}",
        "struct State {value:.u8'builtin,stable:.u8'builtin} fn run()->.u8'builtin {let state=State {value:0,stable:7};let p=state.ref;let q=p.value;q.* = 1;p.stable.* + 1}",
        "struct Holder {pointer:*.u8'builtin} fn run()->.u8'builtin {let n:.u8'builtin=7;let holder=Holder {pointer:n.ref};holder.pointer.* + 1}",
        "fn run()->.u8'builtin {let n:.u8'builtin=7;let pair=(n.ref,n.ref);let (p,q)=pair;p.* + 1}",
        "fn choose(flag:bool)->.u8'builtin {let n:.u8'builtin=7;let p=if flag {n.ref} else {n.ref};p.* + 1} fn run()->.u8'builtin {choose(false)}",
        "fn run()->.u8'builtin {let first:.u8'builtin=0;let second:.u8'builtin=7;var p=first.ref;p=second.ref;p.* + 1}",
        "fn run()->.u8'builtin {let n:.u8'builtin=7;let p=n.ref;let pp=p.ref;let q=pp.*;q.* + 1}",
    ] {
        let package = execution_support::compile_with_tuple(source);
        let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke(id(&package, "run"), vec![]).unwrap(),
            Value::UnsignedInteger(8),
            "{source}"
        );
        let function = package.functions.iter().find(|f| f.name == "run").unwrap();
        let report = elaboration::verification::flow::analyze_in_package(
            &package,
            function,
            &mut elaboration::verification::Limits::default(),
        )
        .unwrap();
        println!("POINTER_ORIGIN={report}");
    }
    let package = execution_support::compile_with_tuple(
        "fn run()->Tuple<.u8'builtin, .u8'builtin, .u8'builtin> {let first:.u8'builtin=0;let second:.u8'builtin=7;var p=first.ref;p.* = do {p=second.ref;1};(first,second,p.*)}",
    );
    let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        vm.invoke(id(&package, "run"), vec![]).unwrap(),
        Value::Tuple(vec![
            Value::UnsignedInteger(1),
            Value::UnsignedInteger(7),
            Value::UnsignedInteger(7)
        ])
    );
}

