#[test]
fn pointer_target_sets_scale_across_matches_and_recover_after_budget_exhaustion() {
    use elaboration::verification::{self as v, flow};
    let mut source = "fn choose(index:.u8'builtin)->.u8'builtin {".to_owned();
    for index in 0..16 {
        source.push_str(&format!("let value{index}:.u8'builtin={index};"));
    }
    source.push_str("let pointer=index match {");
    for index in 0..15 {
        source.push_str(&format!("{index} => value{index}.ref,"));
    }
    source.push_str("_ => value15.ref,};pointer.* + 1}");
    let package = compile(&source);
    let function = package
        .functions
        .iter()
        .find(|f| f.name == "choose")
        .unwrap();
    for value in (0..16).chain([255]) {
        let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke(function.declaration, vec![Value::UnsignedInteger(value)])
                .unwrap(),
            Value::UnsignedInteger(value.min(15) + 1)
        );
    }
    let mut small = v::Limits::default();
    small.arithmetic.steps = 32;
    assert!(matches!(
        flow::analyze_in_package(&package, function, &mut small),
        Err(flow::Error {
            reason: flow::Reason::Unknown(_),
            ..
        })
    ));
    let report = flow::analyze_in_package(&package, function, &mut v::Limits::default()).unwrap();
    println!("POINTER_SET={report}");
}

#[test]
fn loop_invariant_pointer_origins_preserve_unwritten_ranges() {
    for source in [
        "struct State {value:.u8'builtin,stable:.u8'builtin} fn run()->.u8'builtin {let state=State {value:0,stable:7};let p=state.value.ref;var again=true;while again {p.* = 1;let checked=state.stable + 1;again=false;}state.stable + 1}",
        "struct State {value:.u8'builtin,stable:.u8'builtin} fn write(p:*.u8'builtin) {p.* = 1;} fn run()->.u8'builtin {let state=State {value:0,stable:7};let p=state.value.ref;var again=true;while again {write(p);let checked=state.stable + 1;again=false;}state.stable + 1}",
        "struct Holder {pointer:*.u8'builtin,stable:.u8'builtin} fn run()->.u8'builtin {let value:.u8'builtin=0;let holder=Holder {pointer:value.ref,stable:7};var again=true;while again {holder.pointer.* = 1;let checked=holder.stable + 1;again=false;}holder.stable + 1}",
        "fn choose(flag:bool)->.u8'builtin {let first:.u8'builtin=0;let second:.u8'builtin=0;let stable:.u8'builtin=7;let p=if flag {first.ref} else {second.ref};var again=true;while again {p.* = 1;let checked=stable + 1;again=false;}stable + 1} fn run()->.u8'builtin {choose(false)}",
        "struct Holder {pointer:*.u8'builtin,count:.u8'builtin} fn run()->.u8'builtin {let value:.u8'builtin=0;let stable:.u8'builtin=7;let holder=Holder {pointer:value.ref,count:0};var again=true;while again {holder.pointer.* = 1;holder.count=1;let checked=stable + 1;again=false;}stable + 1}",
    ] {
        let package = compile(source);
        let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke(id(&package, "run"), vec![]).unwrap(),
            Value::UnsignedInteger(8),
            "{source}"
        );
    }
}

