#[test]
fn variadic_preparation_ir_validates_its_binding_and_result_contract() {
    use nir::program::ExprKind as K;
    let package = execution_support::compile_with_tuple(
        "fn take(...items:Tuple<bool, bool>)->Tuple<bool, bool> {items} fn run()->Tuple<bool, bool> {take(true,false)}",
    );
    nir::phases::validate(&package).unwrap();
    assert!(
        package
            .to_string()
            .contains("(call-preparation (statements")
    );
    println!("VARIADIC_NIR_DUMP={package}\nVARIADIC_NIR_END");
    for duplicate in [false, true] {
        let mut invalid = package.clone();
        let run = invalid
            .functions
            .iter_mut()
            .find(|f| f.name == "run")
            .unwrap();
        let K::Block {
            result: Some(result),
            ..
        } = &mut run.body.kind
        else {
            panic!("function body")
        };
        let K::CallPreparation { statements, result } = &mut result.kind else {
            panic!("call preparation")
        };
        if duplicate {
            statements.push(statements[0].clone());
        } else {
            *result = None;
        }
        let error = nir::phases::validate(&invalid).unwrap_err();
        assert!(
            error.message.contains(if duplicate {
                "bindings must be distinct"
            } else {
                "normalized call, variant or expanded call block"
            }),
            "{error:?}"
        );
    }
}

