#[test]
fn tuple_spreads_validate_ir_unpackings_and_dump_their_preparation() {
    use nir::program::ExprKind as K;
    let package = execution_support::compile_with_tuple(
        "fn packet()->Tuple<bool, bool> {(true,false)} fn take(a:bool,b:bool)->bool {a} fn run()->bool {take(...packet())}",
    );
    println!("SPREAD_NIR_DUMP={package}\nSPREAD_NIR_END");
    for duplicate in [false, true] {
        let mut invalid = package.clone();
        let function = invalid
            .functions
            .iter_mut()
            .find(|f| f.name == "run")
            .unwrap();
        let K::Block {
            result: Some(call), ..
        } = &mut function.body.kind
        else {
            panic!("body")
        };
        let K::CallPreparation { statements, .. } = &mut call.kind else {
            panic!("preparation")
        };
        let K::LetPattern {
            pattern: nir::program::Pattern::Tuple(fields),
            guard,
            ..
        } = &mut statements[0].kind
        else {
            panic!("unpacking")
        };
        if duplicate {
            fields[1] = fields[0].clone();
        } else {
            *guard = Some(Box::new(nir::program::Expr {
                ty: nir::Term::Primitive(nir::Primitive::Bool),
                source: call.source,
                kind: K::Literal(nir::program::Literal::Bool(false)),
            }));
        }
        let error = nir::phases::validate(&invalid).unwrap_err();
        assert!(
            error.message.contains(if duplicate {
                "bindings must be distinct"
            } else {
                "requires binding statements"
            }),
            "{error:?}"
        );
    }
}

