#[test]
fn anonymous_record_writes_invalidate_observations_without_losing_siblings() {
    use elaboration::verification::{self as v, optimization};
    for write in [
        "state.bits=1;",
        "state.bits'bitvec[0..4]=1;",
        "let p=state.ref;p.bits.* = 1;",
        "let next=|| {state.bits=1;assumes state.bits==0;};next();",
        "var again=true;while again {state.bits=1;again=false;}",
    ] {
        let baseline = compile(&format!(
            "fn keep(...properties:T)->T where T {{properties}} fn run() {{let zero:.u8'builtin=0;let seven:.u8'builtin=7;let state=keep {{bits:zero,stable:seven}};{write} assumes state.stable==7;assumes state.bits==0;}}"
        ));
        let mut optimized = baseline.clone();
        let report = optimization::elide_proven_checks(&mut optimized, &mut v::Limits::default());
        assert_eq!(report.fallback_functions, 0, "{write}: {report}");
        for package in [&baseline, &optimized] {
            let mut vm = Interpreter::new(package, Budget::default()).unwrap();
            assert_eq!(
                vm.invoke(id(package, "run"), vec![])
                    .expect_err(&format!("{write}: {report}"))
                    .kind,
                ErrorKind::ProgramContractRejected,
                "{write}: {report}"
            );
        }
    }
}

