#[test]
fn generic_trait_reference_phase_checks_method_arguments_separately() {
    use nir::program::{CallArgument, Expr, ExprKind};
    use nir::{Parameter, Primitive, Sort, Term};
    let mut package =
        compile("trait Mapper where A {fn keep(value:T)->T where T;} fn run()->bool {true}");
    let interface = package.traits[0].declaration;
    let member = package.traits[0].methods[0].declaration;
    let run = package
        .functions
        .iter_mut()
        .find(|f| f.name == "run")
        .unwrap();
    let value = run.body.clone();
    let boolean = Term::Primitive(Primitive::Bool);
    let callee = Expr {
        source: value.source,
        ty: Term::Function {
            parameters: vec![Parameter {
                sort: Sort::Runtime,
                ty: boolean.clone(),
            }],
            result: Box::new(boolean.clone()),
        },
        kind: ExprKind::TraitMethod {
            interface,
            interface_arguments: vec![Term::Primitive(Primitive::Char)],
            member,
            subject: boolean.clone(),
            method_arguments: vec![boolean.clone()],
        },
    };
    run.body = Expr {
        source: value.source,
        ty: boolean.clone(),
        kind: ExprKind::Call {
            callee: Box::new(callee),
            arguments: vec![CallArgument {
                passing: Default::default(),
                parameter: 0,
                value,
                is_default: false,
            }],
            parameter_bindings: vec![],
        },
    };
    nir::phases::validate(&package).unwrap();
    for (types, expected) in [
        (vec![], "trait method type argument count mismatch"),
        (
            vec![boolean.clone(), boolean.clone()],
            "trait method type argument count mismatch",
        ),
        (
            vec![Term::Primitive(Primitive::Char)],
            "trait method value type does not preserve its contract",
        ),
    ] {
        let mut wrong = package.clone();
        let run = wrong
            .functions
            .iter_mut()
            .find(|f| f.name == "run")
            .unwrap();
        let ExprKind::Call { callee, .. } = &mut run.body.kind else {
            panic!()
        };
        let ExprKind::TraitMethod {
            method_arguments, ..
        } = &mut callee.kind
        else {
            panic!()
        };
        *method_arguments = types;
        assert_eq!(nir::phases::validate(&wrong).unwrap_err().message, expected);
    }
    assert!(
        package
            .to_string()
            .contains("(method-arguments (primitive bool))")
    );
    println!("GENERIC_METHOD_DUMP={}\nGENERIC_METHOD_END", package);
}

