#[test]
fn generic_trait_dispatch_validation_rejects_duplicate_or_missing_specializations() {
    let package = compile(
        "trait Mapper {fn keep(value:T)->T where T;} struct Holder {} impl Mapper for Holder {fn keep(value:U)->U where U {value}} fn run()->bool {let a=Holder.as(Mapper).keep(true);let b=Holder.as(Mapper).keep('x');a and b=='x'}",
    );
    let graph = luna::instantiation::instantiate(&package, "run", 100_000).unwrap();
    let dispatch = graph
        .dispatch
        .iter()
        .position(|d| d.methods.len() == 2)
        .unwrap();
    assert_ne!(
        graph.dispatch[dispatch].methods[0].method_arguments,
        graph.dispatch[dispatch].methods[1].method_arguments
    );
    let mut duplicate = graph.clone();
    duplicate.dispatch[dispatch].methods[1].method_arguments = duplicate.dispatch[dispatch].methods
        [0]
    .method_arguments
    .clone();
    assert!(
        duplicate
            .validate(&mut 100_000)
            .unwrap_err()
            .contains("duplicate IIR dispatch member")
    );
    let mut missing = graph.clone();
    let key = iir::InstanceKey {
        declaration: missing.dispatch[dispatch].methods[1].body,
        arguments: missing.dispatch[dispatch].methods[1].arguments.clone(),
    };
    missing.functions.retain(|f| f.key != key);
    assert!(
        missing
            .validate(&mut 100_000)
            .unwrap_err()
            .contains("missing function instance")
    );
    let mut duplicate_contract = graph.clone();
    let contract = duplicate_contract
        .interfaces
        .iter_mut()
        .find(|i| i.methods.len() == 2)
        .unwrap();
    contract.methods[1].type_arguments = contract.methods[0].type_arguments.clone();
    assert!(
        duplicate_contract
            .validate(&mut 100_000)
            .unwrap_err()
            .contains("duplicate IIR interface member")
    );
    let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        vm.invoke(id(&package, "run"), vec![]).unwrap(),
        Value::Bool(true)
    );
}

