#[test]
fn associated_function_values_call_defaults_overrides_and_inherited_origins() {
    for call in [
        "Holder.as(Child).action(false)",
        "Holder.as(Child).action {false}",
        "Holder.as(Child).action(...do {(false,)})",
        "do {let action=Holder.as(Child).action;action(false)}",
    ] {
        for (default, implementation) in [
            ("=invert", ""),
            ("=identity", "assoc action:fn(bool)->bool=invert;"),
        ] {
            let package = compile(&format!(
                "fn invert(value:bool)->bool {{not value}} fn identity(value:bool)->bool {{value}} trait Parent {{assoc action:fn(bool)->bool{default};}} trait Child :- Parent {{}} struct Holder {{}} impl Parent for Holder {{{implementation}}} impl Child for Holder {{}} fn run()->bool {{{call}}}"
            ));
            let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
            assert_eq!(
                vm.invoke(id(&package, "run"), vec![]).unwrap(),
                Value::Bool(true)
            );
            assert_eq!(calls(&package, &vm), ["run", "invert"]);
            assert_eq!(
                luna::execution::interpret(&package, "run", 100_000).unwrap(),
                Value::Bool(true)
            );
        }
    }
}

