#[test]
fn associated_dependencies_follow_selected_overrides_and_type_values() {
    for implementation in [
        "impl Source for Holder {assoc base:.u8'builtin=9;}",
        "impl Source for Holder {assoc base:.u8'builtin=9;assoc capacity:.u8'builtin=Holder.as(Source).base + 2;}",
    ] {
        let package = compile(&format!(
            "trait Source {{assoc capacity:.u8'builtin=Holder.as(Source).base + 1;assoc Alias:.Type'builtin=Holder.as(Source).Element;assoc base:.u8'builtin=1;assoc Element:.Type'builtin=bool;}} struct Holder {{}} {implementation} fn run()->bool {{let flag:Holder.as(Source).Alias=true;flag and Holder.as(Source).capacity > 9}}"
        ));
        let contract = package.traits.iter().find(|t| t.name == "Source").unwrap();
        let implementation = package
            .implementations
            .iter()
            .find(|i| i.interface == Some(contract.declaration))
            .unwrap();
        assert_eq!(
            implementation
                .associated
                .iter()
                .map(|(id, _)| *id)
                .collect::<Vec<_>>(),
            contract
                .associated
                .iter()
                .map(|a| a.declaration)
                .collect::<Vec<_>>()
        );
        assert_eq!(
            luna::execution::interpret(&package, "run", 100_000).unwrap(),
            Value::Bool(true)
        );
    }
}

