#[test]
fn computed_associated_trait_method_values_preserve_origins_and_generic_arguments() {
    for method in [
        "fn keep(value:bool)->bool {value}",
        "fn keep(value:T)->T where T {value}",
    ] {
        let access = if method.contains("where") {
            "Holder.as(Mapper).keep<bool>"
        } else {
            "Holder.as(Mapper).keep"
        };
        let package = compile(&format!(
            "trait Mapper {{{method}}} struct Holder {{}} impl Mapper for Holder {{}} comptime fn choose()->fn(bool)->bool {{{access}}} trait Source {{assoc action:fn(bool)->bool=choose();}} impl Source for Holder {{}} fn run()->bool {{Holder.as(Source).action(true)}}"
        ));
        let source = package.traits.iter().find(|t| t.name == "Source").unwrap();
        let implementation = package
            .implementations
            .iter()
            .find(|i| i.interface == Some(source.declaration))
            .unwrap();
        let nir::program::ExprKind::TraitMethod {
            method_arguments, ..
        } = &implementation.associated[0].1.kind
        else {
            panic!("trait method origin was erased")
        };
        assert_eq!(
            method_arguments.len(),
            usize::from(method.contains("where"))
        );
        assert_eq!(
            luna::execution::interpret(&package, "run", 100_000).unwrap(),
            Value::Bool(true)
        );
    }
}

#[test]
fn computed_trait_method_values_preserve_parent_and_implementation_substitution() {
    let package = compile(
        "trait Mapper where A {fn keep(value:A)->A;} trait Child :- Mapper<A> where A {} struct Holder where X {} impl Mapper<X> for Holder<X> where X {fn keep(value:X)->X {value}} impl Child<X> for Holder<X> where X {} comptime fn choose()->fn(bool)->bool {Holder<bool>.as(Child<bool>).keep} trait Source {assoc action:fn(bool)->bool=choose();} struct Client {} impl Source for Client {} fn run()->bool {Client.as(Source).action(true)}",
    );
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    let source = package.traits.iter().find(|t| t.name == "Source").unwrap();
    let mapper = package.traits.iter().find(|t| t.name == "Mapper").unwrap();
    let implementation = package
        .implementations
        .iter()
        .find(|i| i.interface == Some(source.declaration))
        .unwrap();
    let nir::program::ExprKind::TraitMethod {
        interface,
        interface_arguments,
        ..
    } = &implementation.associated[0].1.kind
    else {
        panic!("trait origin was erased")
    };
    assert_eq!(*interface, mapper.declaration);
    assert_eq!(
        interface_arguments,
        &[nir::Term::Primitive(nir::Primitive::Bool)]
    );
}

