#[test]
fn associated_type_query_uses_evidence_from_the_compiled_implementation_world() {
    let package = compile(
        "trait Source where X {assoc Element:.Type'builtin=bool;} struct Holder where T {} impl Source<T> for Holder<T> where T {assoc Element:.Type'builtin=T;} fn run()->bool {true}",
    );
    let contract = package.traits.iter().find(|t| t.name == "Source").unwrap();
    let implementation = &package.implementations[0];
    let argument = nir::Term::Primitive(nir::Primitive::Char);
    let subject = implementation
        .subject
        .instantiate_types(&implementation.type_parameters, &[argument.clone()])
        .unwrap();
    let projection = nir::Term::AssociatedType {
        origin: Box::new(nir::AssociatedTypeOrigin {
            interface: contract.declaration,
            member: contract.associated[0].declaration,
        }),
        arguments: vec![argument.clone()],
        subject: Box::new(subject),
    };
    let mut index = elaboration::implementation::Index::default();
    for item in &package.implementations {
        index
            .insert(
                elaboration::implementation::ImplementationHead {
                    parameter_types: item.parameter_types.clone(),
                    declaration: item.declaration,
                    interface: item.interface,
                    interface_arguments: item.interface_arguments.clone(),
                    subject: item.subject.clone(),
                    type_parameters: item.type_parameters.clone(),
                    requirements: item.requirements.clone(),
                },
                elaboration::ptc::Budget::default(),
            )
            .unwrap();
    }
    let context = elaboration::ptc::Context::from_package(&package).unwrap();
    let world = elaboration::capabilities::World {
        index: &index,
        implementations: &package.implementations,
        traits: &package.traits,
        assumptions: &[],
        context: &context,
    };
    let result = world
        .resolve_associated_type(&projection, elaboration::ptc::Budget::default())
        .unwrap();
    assert_eq!(result.value, argument);
    assert_eq!(result.evidence.implementation, implementation.declaration);
    let normalized = world
        .normalize_associated_types(
            &nir::Term::Tuple(vec![projection.clone(), projection]),
            elaboration::ptc::Budget::default(),
        )
        .unwrap();
    assert_eq!(
        normalized.value,
        nir::Term::Tuple(vec![argument.clone(), argument])
    );
    assert_eq!(normalized.steps.len(), 1);
}

#[test]
fn associated_type_layout_roots_materialize_the_selected_nominal() {
    let package = compile(
        "trait Source {assoc Element:.Type'builtin;} struct Holder {} struct Payload {flag:bool} impl Source for Holder {assoc Element:.Type'builtin=Payload;} fn run()->bool {true}",
    );
    let contract = &package.traits[0];
    let projection = nir::Term::AssociatedType {
        origin: Box::new(nir::AssociatedTypeOrigin {
            interface: contract.declaration,
            member: contract.associated[0].declaration,
        }),
        arguments: vec![],
        subject: Box::new(package.implementations[0].subject.clone()),
    };
    let instantiated = elaboration::materialization::instantiate_with_types(
        &package,
        &[],
        &[projection],
        std::collections::BTreeSet::new(),
        elaboration::ptc::Budget::default(),
    )
    .unwrap();
    let payload = package
        .structs
        .iter()
        .find(|s| s.name == "Payload")
        .unwrap();
    assert!(instantiated.nominals.iter().any(|n| n.ty
        == nir::Term::Nominal {
            declaration: payload.declaration,
            arguments: vec![]
        }));
}

#[test]
fn associated_projections_in_instantiated_nominal_fields_resolve_per_instance() {
    let mut package = compile(
        "trait Source where X {assoc Element:.Type'builtin;} struct Holder where T {} impl Source<T> for Holder<T> where T {assoc Element:.Type'builtin=T;} struct Packet where T {item:T} enum Choice where T {item(T),} fn run()->bool {true}",
    );
    let contract = &package.traits[0];
    let origin = nir::AssociatedTypeOrigin {
        interface: contract.declaration,
        member: contract.associated[0].declaration,
    };
    let holder = package
        .structs
        .iter()
        .find(|s| s.name == "Holder")
        .unwrap()
        .declaration;
    let make = |parameter| {
        let argument = nir::Term::Rigid {
            declaration: parameter,
            sort: nir::Sort::Type,
        };
        nir::Term::AssociatedType {
            origin: Box::new(origin.clone()),
            arguments: vec![argument.clone()],
            subject: Box::new(nir::Term::Nominal {
                declaration: holder,
                arguments: vec![argument],
            }),
        }
    };
    // Inject the abstract NIR form at the lowering boundary: source generation
    // of this projection is a separate, still unfinished frontend feature.
    let packet = package
        .structs
        .iter_mut()
        .find(|s| s.name == "Packet")
        .unwrap();
    packet.fields[0].1 = make(packet.type_parameters[0]);
    let packet_id = packet.declaration;
    let choice = package
        .enums
        .iter_mut()
        .find(|e| e.name == "Choice")
        .unwrap();
    choice.variants[0].fields[0] = nir::Term::Pointer(Box::new(make(choice.type_parameters[0])));
    let choice_id = choice.declaration;
    let mut roots = Vec::new();
    for declaration in [packet_id, choice_id] {
        for primitive in [nir::Primitive::Bool, nir::Primitive::Char] {
            roots.push(nir::Term::Nominal {
                declaration,
                arguments: vec![nir::Term::Primitive(primitive)],
            });
        }
    }
    let result = elaboration::materialization::instantiate_with_types(
        &package,
        &[],
        &roots,
        std::collections::BTreeSet::new(),
        elaboration::ptc::Budget::default(),
    )
    .unwrap();
    for root in &roots {
        let nir::Term::Nominal { arguments, .. } = root else {
            panic!()
        };
        let instance = result.nominals.iter().find(|n| &n.ty == root).unwrap();
        match &instance.definition {
            iir::NominalDefinition::Struct(s) => assert_eq!(s.fields[0].1, arguments[0]),
            iir::NominalDefinition::Newtype(_) => panic!("unexpected newtype in struct/enum test"),
            iir::NominalDefinition::Enum(e) => assert_eq!(
                e.variants[0].fields[0],
                nir::Term::Pointer(Box::new(arguments[0].clone()))
            ),
        }
    }
    let packet = package
        .structs
        .iter_mut()
        .find(|s| s.declaration == packet_id)
        .unwrap();
    packet.requirements = vec![nir::program::TypePredicate::Equal(
        make(packet.type_parameters[0]),
        nir::Term::Primitive(nir::Primitive::Bool),
    )];
    for primitive in [nir::Primitive::Bool, nir::Primitive::Char] {
        let root = nir::Term::Nominal {
            declaration: packet_id,
            arguments: vec![nir::Term::Primitive(primitive)],
        };
        let result = elaboration::materialization::instantiate_with_types(
            &package,
            &[],
            &[root.clone()],
            std::collections::BTreeSet::new(),
            elaboration::ptc::Budget::default(),
        );
        if primitive == nir::Primitive::Bool {
            let output = result.unwrap();
            let definition = &output
                .nominals
                .iter()
                .find(|n| n.ty == root)
                .unwrap()
                .definition;
            let iir::NominalDefinition::Struct(s) = definition else {
                panic!()
            };
            assert!(!s.requirements[0].to_string().contains("associated-type"));
        } else {
            assert!(
                result
                    .unwrap_err()
                    .contains("type formation requirement is not established")
            );
        }
    }
    package
        .structs
        .iter_mut()
        .find(|s| s.declaration == packet_id)
        .unwrap()
        .requirements
        .clear();
    let cyclic = make(package.implementations[0].type_parameters[0]);
    package.implementations[0].associated[0].1.kind = nir::program::ExprKind::TypeValue(cyclic);
    let failed = elaboration::materialization::instantiate_with_types(
        &package,
        &[],
        &roots,
        std::collections::BTreeSet::new(),
        elaboration::ptc::Budget::default(),
    )
    .unwrap_err();
    assert!(failed.contains("cyclic associated Type"), "{failed}");
    package.implementations[0].associated.clear();
    let failed = elaboration::materialization::instantiate_with_types(
        &package,
        &[],
        &roots,
        std::collections::BTreeSet::new(),
        elaboration::ptc::Budget::default(),
    )
    .unwrap_err();
    assert!(failed.contains("no associated Type value"), "{failed}");
}

#[test]
fn associated_function_annotations_normalize_together_before_iir_execution() {
    let mut package = compile(
        "trait Source where X {assoc Element:.Type'builtin;} struct Holder where T {} impl Source<T> for Holder<T> where T {assoc Element:.Type'builtin=T;} fn keep(value:T)->T where T {value}",
    );
    let contract = &package.traits[0];
    let holder = package
        .structs
        .iter()
        .find(|s| s.name == "Holder")
        .unwrap()
        .declaration;
    let function = package
        .functions
        .iter_mut()
        .find(|f| f.name == "keep")
        .unwrap();
    let parameter = function.type_parameters[0];
    let argument = nir::Term::Rigid {
        declaration: parameter,
        sort: nir::Sort::Type,
    };
    let projection = nir::Term::AssociatedType {
        origin: Box::new(nir::AssociatedTypeOrigin {
            interface: contract.declaration,
            member: contract.associated[0].declaration,
        }),
        arguments: vec![argument.clone()],
        subject: Box::new(nir::Term::Nominal {
            declaration: holder,
            arguments: vec![argument],
        }),
    };
    // Source abstract projection formation is not yet connected. Exercise the
    // instantiated NIR boundary without claiming that frontend feature.
    function.signature = function
        .signature
        .instantiate_types(&[parameter], &[projection.clone()])
        .unwrap();
    function
        .body
        .rewrite_types(&mut |ty| ty.instantiate_types(&[parameter], &[projection.clone()]))
        .unwrap();
    let roots: Vec<_> = [nir::Primitive::Bool, nir::Primitive::Char]
        .into_iter()
        .map(|p| iir::InstanceKey {
            declaration: function.declaration,
            arguments: vec![nir::Term::Primitive(p)],
        })
        .collect();
    let output = elaboration::materialization::instantiate(
        &package,
        &roots,
        std::collections::BTreeSet::new(),
        elaboration::ptc::Budget::default(),
    )
    .unwrap();
    let mut vm = Interpreter::from_iir(&output, Budget::default()).unwrap();
    assert_eq!(
        vm.invoke_instance(&roots[0], vec![Value::Bool(true)])
            .unwrap(),
        Value::Bool(true)
    );
    assert_eq!(
        vm.invoke_instance(&roots[1], vec![Value::Char('x')])
            .unwrap(),
        Value::Char('x')
    );
}

#[test]
fn associated_type_predicates_are_normalized_then_proved_at_instantiation() {
    let mut package = compile(
        "trait Source where X {assoc Element:.Type'builtin;} struct Holder where T {} impl Source<T> for Holder<T> where T {assoc Element:.Type'builtin=T;} trait Ready where Y {} impl Ready<bool> for bool {} fn keep(value:T)->T where T {value}",
    );
    let ready = package
        .traits
        .iter()
        .find(|t| t.name == "Ready")
        .unwrap()
        .declaration;
    let contract = package.traits.iter().find(|t| t.name == "Source").unwrap();
    let holder = package
        .structs
        .iter()
        .find(|s| s.name == "Holder")
        .unwrap()
        .declaration;
    let function = package
        .functions
        .iter_mut()
        .find(|f| f.name == "keep")
        .unwrap();
    let argument = nir::Term::Rigid {
        declaration: function.type_parameters[0],
        sort: nir::Sort::Type,
    };
    let projection = nir::Term::AssociatedType {
        origin: Box::new(nir::AssociatedTypeOrigin {
            interface: contract.declaration,
            member: contract.associated[0].declaration,
        }),
        arguments: vec![argument.clone()],
        subject: Box::new(nir::Term::Nominal {
            declaration: holder,
            arguments: vec![argument],
        }),
    };
    use nir::program::TypePredicate as P;
    function.requirements = vec![P::And(vec![
        P::Bool(true),
        P::Not(Box::new(P::Not(Box::new(P::Equal(
            projection.clone(),
            nir::Term::Primitive(nir::Primitive::Bool),
        ))))),
    ])];
    let declaration = function.declaration;
    for primitive in [nir::Primitive::Bool, nir::Primitive::Char] {
        let root = iir::InstanceKey {
            declaration,
            arguments: vec![nir::Term::Primitive(primitive)],
        };
        let result = elaboration::materialization::instantiate(
            &package,
            &[root.clone()],
            std::collections::BTreeSet::new(),
            elaboration::ptc::Budget::default(),
        );
        if primitive == nir::Primitive::Bool {
            let output = result.unwrap();
            assert!(
                !output.functions[0].function.requirements[0]
                    .to_string()
                    .contains("associated-type")
            );
            let mut vm = Interpreter::from_iir(&output, Budget::default()).unwrap();
            assert_eq!(
                vm.invoke_instance(&root, vec![Value::Bool(true)]).unwrap(),
                Value::Bool(true)
            );
        } else {
            assert!(
                result
                    .unwrap_err()
                    .contains("function type requirement is not established")
            );
        }
    }
    let function = package
        .functions
        .iter_mut()
        .find(|f| f.name == "keep")
        .unwrap();
    function.requirements.clear();
    function.capabilities = vec![nir::program::TraitRequirement {
        interface: ready,
        interface_arguments: vec![projection.clone()],
        subject: projection,
    }];
    for primitive in [nir::Primitive::Bool, nir::Primitive::Char] {
        let root = iir::InstanceKey {
            declaration,
            arguments: vec![nir::Term::Primitive(primitive)],
        };
        let result = elaboration::materialization::instantiate(
            &package,
            &[root],
            std::collections::BTreeSet::new(),
            elaboration::ptc::Budget::default(),
        );
        if primitive == nir::Primitive::Bool {
            let output = result.unwrap();
            assert_eq!(
                output.functions[0].function.capabilities[0].subject,
                nir::Term::Primitive(nir::Primitive::Bool)
            );
            assert_eq!(
                output.functions[0].function.capabilities[0].interface_arguments,
                vec![nir::Term::Primitive(nir::Primitive::Bool)]
            );
        } else {
            assert!(
                result
                    .unwrap_err()
                    .contains("dispatch selection is unresolved")
            );
        }
    }
}

#[test]
fn retained_interface_method_signatures_resolve_associated_projections() {
    for generic in [false, true] {
        let method = if generic {
            "fn keep(value:X,other:T)->X where T {value}"
        } else {
            "fn keep(value:X)->X {value}"
        };
        let call = if generic {
            "Holder<bool>.as(Source<bool>).keep(true,'x')"
        } else {
            "Holder<bool>.as(Source<bool>).keep(true)"
        };
        let mut package = compile(&format!(
            "trait Source where X {{assoc Element:.Type'builtin;{method}}} struct Holder where T {{}} impl Source<T> for Holder<T> where T {{assoc Element:.Type'builtin=T;}} fn run()->bool {{{call}}}"
        ));
        let contract = package
            .traits
            .iter_mut()
            .find(|t| t.name == "Source")
            .unwrap();
        let argument = nir::Term::Rigid {
            declaration: contract.type_parameters[0],
            sort: nir::Sort::Type,
        };
        let projection = nir::Term::AssociatedType {
            origin: Box::new(nir::AssociatedTypeOrigin {
                interface: contract.declaration,
                member: contract.associated[0].declaration,
            }),
            arguments: vec![argument],
            subject: Box::new(nir::Term::Rigid {
                declaration: contract.self_parameter,
                sort: nir::Sort::Type,
            }),
        };
        // Test retained-contract lowering directly until source-level abstract
        // projection formation is implemented.
        contract.methods[0].signature = contract.methods[0]
            .signature
            .instantiate_types(&contract.type_parameters, &[projection.clone()])
            .unwrap();
        contract.methods[0]
            .requirements
            .push(nir::program::TypePredicate::Equal(
                projection,
                nir::Term::Rigid {
                    declaration: contract.type_parameters[0],
                    sort: nir::Sort::Type,
                },
            ));
        let contract = contract.clone();
        assert!(
            nir::phases::validate(&package)
                .unwrap_err()
                .message
                .contains("trait method value type does not preserve its contract")
        );
        fn update_callee(expr: &mut nir::program::Expr, contract: &nir::program::Trait) {
            use nir::program::ExprKind as K;
            match &mut expr.kind {
                K::TraitMethod {
                    subject,
                    interface_arguments,
                    method_arguments,
                    ..
                } => {
                    let method = &contract.methods[0];
                    let parameters: Vec<_> = contract
                        .parameters_with_self()
                        .into_iter()
                        .chain(method.type_parameters.iter().copied())
                        .collect();
                    let arguments: Vec<_> = std::iter::once(subject.clone())
                        .chain(interface_arguments.iter().cloned())
                        .chain(method_arguments.iter().cloned())
                        .collect();
                    expr.ty = method
                        .signature
                        .ordinary()
                        .unwrap()
                        .instantiate_types(&parameters, &arguments)
                        .unwrap();
                }
                K::Call { callee, .. } => update_callee(callee, contract),
                K::Block { statements, result } | K::CallPreparation { statements, result } => {
                    for statement in statements {
                        update_callee(statement, contract);
                    }
                    if let Some(result) = result {
                        update_callee(result, contract);
                    }
                }
                _ => (),
            }
        }
        update_callee(
            &mut package
                .functions
                .iter_mut()
                .find(|f| f.name == "run")
                .unwrap()
                .body,
            &contract,
        );
        let root = iir::InstanceKey {
            declaration: id(&package, "run"),
            arguments: vec![],
        };
        let output = elaboration::materialization::instantiate(
            &package,
            &[root.clone()],
            std::collections::BTreeSet::new(),
            elaboration::ptc::Budget::default(),
        )
        .unwrap();
        assert!(
            output
                .interfaces
                .iter()
                .flat_map(|c| &c.methods)
                .all(|m| !m.signature.to_string().contains("associated-type"))
        );
        assert!(
            output
                .interfaces
                .iter()
                .flat_map(|c| &c.methods)
                .flat_map(|m| &m.requirements)
                .all(|r| !r.to_string().contains("associated-type"))
        );
        let mut vm = Interpreter::from_iir(&output, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke_instance(&root, vec![]).unwrap(),
            Value::Bool(true)
        );
    }
}

#[test]
fn trait_signatures_and_default_bodies_preserve_abstract_associated_types() {
    let package = compile(
        "trait Source where X {assoc Element:.Type'builtin=bool;fn keep(value:Element)->Element {value}} fn run()->bool {true}",
    );
    let contract = package.traits.iter().find(|t| t.name == "Source").unwrap();
    let nir::Term::Function { parameters, result } =
        contract.methods[0].signature.ordinary().unwrap()
    else {
        panic!()
    };
    let nir::Term::AssociatedType {
        origin,
        arguments,
        subject,
    } = &parameters[0].ty
    else {
        panic!()
    };
    assert_eq!(origin.interface, contract.declaration);
    assert_eq!(origin.member, contract.associated[0].declaration);
    assert_eq!(
        arguments,
        &vec![nir::Term::Rigid {
            declaration: contract.type_parameters[0],
            sort: nir::Sort::Type
        }]
    );
    assert_eq!(
        **subject,
        nir::Term::Rigid {
            declaration: contract.self_parameter,
            sort: nir::Sort::Type
        }
    );
    assert_eq!(result.as_ref(), &parameters[0].ty);
    assert_ne!(result.as_ref(), &nir::Term::Primitive(nir::Primitive::Bool));
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
}

