#[test]
fn abstract_associated_values_execute_from_selected_reference_dispatch() {
    let mut package = compile(include_str!(
        "../../../development/examples/associated-values.fl"
    ));
    package.dispatch_instances =
        elaboration::materialization::dispatch_instances(&package, Default::default()).unwrap();
    assert!(
        package
            .dispatch_instances
            .iter()
            .any(|i| !i.associated.is_empty())
    );
    let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        vm.invoke(id(&package, "entry"), vec![]).unwrap(),
        Value::Bool(true)
    );
    println!("ASSOCIATED_DISPATCH_DUMP={package}");
    let mut damaged = package.clone();
    let value = &mut damaged
        .dispatch_instances
        .iter_mut()
        .find(|i| !i.associated.is_empty())
        .unwrap()
        .associated[0]
        .1;
    value.kind = nir::program::ExprKind::Literal(nir::program::Literal::Bool(!matches!(
        value.kind,
        nir::program::ExprKind::Literal(nir::program::Literal::Bool(true))
    )));
    assert!(Interpreter::new(&damaged, Budget::default()).is_err());
    for instance in &mut package.dispatch_instances {
        instance.associated.clear();
    }
    let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        vm.invoke(id(&package, "entry"), vec![]).unwrap_err().kind,
        ErrorKind::UnmaterializedDispatch
    );
}

