#[test]
fn abstract_associated_values_reject_duplicate_and_executable_dispatch_payloads() {
    let mut package = compile(include_str!(
        "../../../development/examples/associated-values.fl"
    ));
    assert!(
        elaboration::materialization::dispatch_instances(
            &package,
            elaboration::ptc::Budget {
                steps: 1,
                ..Default::default()
            }
        )
        .is_err()
    );
    package.dispatch_instances =
        elaboration::materialization::dispatch_instances(&package, Default::default()).unwrap();
    for mutation in 0..3 {
        let mut damaged = package.clone();
        let instance = damaged
            .dispatch_instances
            .iter_mut()
            .find(|i| !i.associated.is_empty())
            .unwrap();
        match mutation {
            0 => instance.associated.push(instance.associated[0].clone()),
            1 => instance.associated[0].0 = instance.interface,
            _ => {
                // Even matching a malformed implementation must not authorize
                // deferred computation in a purported completed value.
                let value = &mut instance.associated[0].1;
                value.kind = nir::program::ExprKind::Not(Box::new(value.clone()));
                let implementation = damaged
                    .implementations
                    .iter_mut()
                    .find(|i| i.declaration == instance.implementation)
                    .unwrap();
                implementation
                    .associated
                    .iter_mut()
                    .find(|(id, _)| *id == instance.associated[0].0)
                    .unwrap()
                    .1 = value.clone();
            }
        }
        assert!(
            Interpreter::new(&damaged, Budget::default()).is_err(),
            "mutation {mutation}"
        );
    }
    let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        vm.invoke(id(&package, "entry"), vec![]).unwrap(),
        Value::Bool(true)
    );
}

