#[test]
fn dependent_associated_defaults_keep_symbolic_templates_and_completed_implementations() {
    let package = compile_bound_tuple_fixture(include_str!(
        "../../../development/examples/dependent-associated-values.fl"
    ));
    assert_eq!(
        luna::execution::interpret(&package, "entry", 100_000).unwrap(),
        Value::Bool(true)
    );
    let mut symbolic = 0;
    for member in &package.traits[0].associated {
        if let Some(default) = &member.default {
            iir::visit::expression(default, &mut 100_000, |expr, _| {
                if matches!(expr.kind, nir::program::ExprKind::AssociatedValue { .. }) {
                    symbolic += 1;
                }
                Ok(())
            })
            .unwrap();
        }
    }
    assert!(symbolic >= 3);
    for implementation in &package.implementations {
        for (_, value) in &implementation.associated {
            iir::visit::expression(value, &mut 100_000, |expr, _| {
                assert!(!matches!(
                    expr.kind,
                    nir::program::ExprKind::AssociatedValue { .. }
                ));
                Ok(())
            })
            .unwrap();
        }
    }
    println!("DEPENDENT_ASSOCIATED_DUMP={package}");
}

