#[test]
fn comptime_given_premises_discharge_obligations_without_inventing_dispatch() {
    let mut package = compile(
        "trait Token {assoc enabled:bool=true;comptime fn answer()->bool {true}} comptime fn read()->bool where T :- Token {T.as(Token).enabled} comptime fn call()->bool where T :- Token {T.as(Token).answer()} comptime fn witness()->bool where T :- Token {true} comptime fn good()->bool {true}",
    );
    let bool_type = nir::Term::Primitive(nir::Primitive::Bool);
    for function in package
        .functions
        .iter_mut()
        .filter(|f| matches!(f.name.as_str(), "read" | "call" | "witness"))
    {
        let parameters = function.type_parameters.clone();
        function.signature = function
            .signature
            .instantiate_types(&parameters, &[bool_type.clone()])
            .unwrap();
        function.body = function
            .body
            .instantiate_types(&parameters, &[bool_type.clone()])
            .unwrap();
        function.capabilities = function
            .capabilities
            .iter()
            .map(|c| {
                c.instantiate_types(&parameters, &[bool_type.clone()])
                    .unwrap()
            })
            .collect();
        function.type_parameters.clear();
    }
    let wrappers: Vec<_> = package
        .functions
        .iter()
        .filter(|f| matches!(f.name.as_str(), "read" | "call" | "witness"))
        .map(|function| {
            let mut wrapper = function.clone();
            wrapper.declaration.local += 1000;
            wrapper.name.push_str("_entry");
            wrapper.capabilities.clear();
            wrapper.body = nir::program::Expr {
                source: function.body.source,
                ty: bool_type.clone(),
                kind: nir::program::ExprKind::Call {
                    callee: Box::new(nir::program::Expr {
                        source: function.body.source,
                        ty: function.signature.clone().with_comptime_phase(true),
                        kind: nir::program::ExprKind::FunctionInstance {
                            declaration: function.declaration,
                            arguments: vec![],
                        },
                    }),
                    arguments: vec![],
                    parameter_bindings: vec![],
                },
            };
            wrapper
        })
        .collect();
    package.functions.extend(wrappers);
    let premise = nir::program::TraitRequirement {
        interface: package.traits[0].declaration,
        interface_arguments: vec![],
        subject: bool_type.clone(),
    };
    let before = package.to_string();
    let mut vm =
        Interpreter::for_comptime_with_assumptions(&package, &[premise.clone()], Budget::default())
            .unwrap();
    assert_eq!(
        vm.invoke(id(&package, "witness_entry"), vec![]).unwrap(),
        Value::Bool(true)
    );
    for name in ["read_entry", "call_entry"] {
        assert_eq!(
            vm.invoke(id(&package, name), vec![]).unwrap_err().kind,
            ErrorKind::UnmaterializedDispatch
        );
        assert_eq!(
            vm.invoke(id(&package, "good"), vec![]).unwrap(),
            Value::Bool(true)
        );
    }
    assert_eq!(package.to_string(), before);
    let mut plain = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    assert_eq!(
        plain
            .invoke(id(&package, "witness_entry"), vec![])
            .unwrap_err()
            .kind,
        ErrorKind::InvalidCallPlan
    );
    let mut malformed = premise.clone();
    malformed.interface_arguments.push(bool_type);
    assert!(
        Interpreter::for_comptime_with_assumptions(&package, &[malformed], Budget::default())
            .is_err()
    );
    assert!(
        Interpreter::for_comptime_with_assumptions(
            &package,
            &[premise.clone()],
            Budget {
                steps: 0,
                ..Budget::default()
            }
        )
        .is_err()
    );
    assert!(
        Interpreter::for_comptime_with_assumptions(&package, &[premise], Budget::default()).is_ok()
    );
}

