#[test]
fn associated_type_predicate_reference_rejection_uses_selected_operands_and_recovers() {
    use comptime_interpretor::ContractOutcome;
    let mut package = compile(
        "trait Source {assoc Item:.Type'builtin;} impl Source for bool {assoc Item:.Type'builtin=bool;} comptime fn agrees()->bool where T :- Source, requires T.as(Source).Item == bool {true} comptime fn entry()->bool {agrees<bool>()} comptime fn good()->bool {true}",
    );
    for rejected in [false, true] {
        let value = &mut package.implementations[0].associated[0].1;
        value.kind = nir::program::ExprKind::TypeValue(nir::Term::Primitive(if rejected {
            nir::Primitive::Char
        } else {
            nir::Primitive::Bool
        }));
        package.dispatch_instances =
            elaboration::materialization::dispatch_instances(&package, Default::default()).unwrap();
        let calls = std::cell::Cell::new(0);
        let solver = |predicate: &nir::program::TypePredicate| {
            calls.set(calls.get() + 1);
            assert_eq!(
                predicate,
                &nir::program::TypePredicate::Equal(
                    nir::Term::Primitive(nir::Primitive::Char),
                    nir::Term::Primitive(nir::Primitive::Bool)
                )
            );
            ContractOutcome::Rejected
        };
        let mut vm = Interpreter::for_comptime(&package, Budget::default())
            .unwrap()
            .with_type_solver(&solver);
        let result = vm.invoke(id(&package, "entry"), vec![]);
        if rejected {
            assert_eq!(result.unwrap_err().kind, ErrorKind::TypeContractRejected);
            assert_eq!(calls.get(), 1);
        } else {
            assert_eq!(result.unwrap(), Value::Bool(true));
            assert_eq!(calls.get(), 0);
        }
        assert_eq!(
            vm.invoke(id(&package, "good"), vec![]).unwrap(),
            Value::Bool(true)
        );
    }
}

