#[test]
fn associated_projection_snapshots_are_independent_of_implementation_order() {
    let source = "trait Source {assoc Item:.Type'builtin;}";
    let implementation = "impl Source for bool {assoc Item:.Type'builtin=bool;}";
    let result = "trait Result {assoc value:bool=read<bool>(true);} impl Result for bool {}";
    let function =
        "comptime fn read(value:T.as(Source).Item)->T.as(Source).Item where T :- Source {value}";
    let entry = "fn run()->bool {bool.as(Result).value}";
    let declarations = [source, implementation, result, function];
    for a in 0..4 {
        for b in 0..4 {
            for c in 0..4 {
                for d in 0..4 {
                    if [a, b, c, d]
                        .into_iter()
                        .collect::<std::collections::BTreeSet<_>>()
                        .len()
                        != 4
                    {
                        continue;
                    }
                    let source = [a, b, c, d].map(|i| declarations[i]).join(" ");
                    let package = compile(&format!("{source} {entry}"));
                    assert_eq!(
                        luna::execution::interpret(&package, "run", 100_000).unwrap(),
                        Value::Bool(true)
                    );
                }
            }
        }
    }
}

