            let call = if enabled {
                "bool.as(Service).extra(true)"
            } else {
                "bool.as(Service).basic()"
            };
            let package = compile(&format!(
                "trait Source {{assoc Item:.Type'builtin;}} {implementation} trait Service {{{phase}fn basic()->bool; {phase}fn extra(value:Self.as(Source).Item)->Self.as(Source).Item where requires Self :- Source {{value}}}} impl Service for bool {{{phase}fn basic()->bool {{true}}}} {phase}fn entry()->bool {{{call}}}"
            ));
