fn associated_closure_dispatch_missing_payload_is_rejected_and_recoverable() {
    let mut package = compile_bound_tuple_fixture(include_str!(
        "../../../development/examples/associated-closure-values.fl"
    ));
    let root = iir::InstanceKey {
        declaration: id(&package, "shared"),
        arguments: vec![],
    };
    package.dispatch_instances = elaboration::materialization::dispatch_instances_for_roots(
        &package,
        &[root],
        Default::default(),
    )
    .unwrap();
    let complete = package.dispatch_instances.clone();
    for instance in &mut package.dispatch_instances {
        instance.associated.clear();
    }
    let mut vm = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    assert_eq!(
        vm.invoke(id(&package, "shared"), vec![]).unwrap_err().kind,
        ErrorKind::UnmaterializedDispatch
    );
    drop(vm);
    package.dispatch_instances = complete;
    let mut vm = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    let integer = |n| Value::Integer(comptime_runtime::Integer::from_u128(n));
    assert_eq!(
        vm.invoke(id(&package, "shared"), vec![]).unwrap(),
        Value::Tuple(vec![integer(1), integer(2)])
    );
}

