#[test]
fn direct_effect_iir_execution_matches_reference_for_mapping_forwarding_and_control() {
    let package = execution_support::compile_with_tuple(
        r#"
        effect input()->bool;
        effect read()->bool;
        effect echo(value:bool)->bool;
        fn callee(value:bool,.extra:bool=value)->#read bool {value and extra and read()#}
        fn caller()->#[input,read] bool {callee(true,.extra=input()#)}
        fn mapped()->bool {caller()# {input()=>true,read()=>false,}}
        typealias Triple=Tuple<bool,bool,bool>;
        fn sequence()->#echo Triple {(echo(false)#,echo(true)#,echo(false)#)}
        fn inner()->#echo Triple {sequence()# {echo(true)=>false,}}
        fn forwarded()->Triple {inner()# {echo(value)=>true,}}
        fn subject(recurse:bool)->#read bool {if recurse {subject(false)} else {read()#}}
        fn escaped()->'x''type {subject(true)# {read()=>return 'x',}; 'y'}
        fn resumed()->bool {subject(false)# {read()=>resume true,}}
        fn stopped()->bool {while:exit true {subject(true)# {read()=>break exit,};} true}
        fn captured()->bool {var flag=false; read()# {read()=> {flag=not flag;flag},};flag}
    "#,
    );
    for name in [
        "mapped",
        "forwarded",
        "escaped",
        "resumed",
        "stopped",
        "captured",
    ] {
        let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
        let expected = vm.invoke(id(&package, name), vec![]).unwrap();
        assert_eq!(
            luna::execution::interpret(&package, name, 100_000).unwrap(),
            expected,
            "{name}"
        );
    }
}

#[test]
fn direct_effect_iir_rejects_corrupted_request_handler_and_resume_evidence() {
    use nir::program::{ExprKind as K, Literal};
    use nir::{Primitive as P, Term};
    let package = compile(
        "effect read()->bool; fn subject()->#read bool {read()#} fn run()->bool {subject()# {read()=>true,}}",
    );
    let graph = elaboration::materialization::instantiate(
        &package,
        &[iir::InstanceKey {
            declaration: id(&package, "run"),
            arguments: vec![],
        }],
        Default::default(),
        elaboration::ptc::Budget::default(),
    )
    .unwrap();
    graph.validate(&mut 100_000).unwrap();
    // Closed direct handlers now have a resource protocol, but execution still
    // requires the independently published per-function/handler schedules.
    graph.validate_cleanup_control(&mut 100_000).unwrap();
    let schedule = iir::cleanup::Schedule::default();
    let result = Interpreter::from_iir(&graph, Budget::default())
        .unwrap()
        .with_cleanup_schedule(&schedule);
    assert!(matches!(result,Err(error) if error.kind==ErrorKind::InvalidCallPlan));
    for mode in [
        "request",
        "outer",
        "fallback",
        "branch",
        "contract",
        "abi",
        "resume",
        "boundary",
        "block_result",
    ] {
        let mut invalid = graph.clone();
        let mut changed = false;
        for function in &mut invalid.functions {
            if mode == "resume" && function.function.name == "run" {
                let mut value = function.function.body.clone();
                value.ty = Term::Primitive(P::Bool);
                value.kind = K::Literal(Literal::Bool(true));
                function.function.body.kind = K::EffectResume(Box::new(value));
                function.function.body.ty = Term::Primitive(P::Never);
                changed = true;
                continue;
            }
            iir::visit::expression_mut(&mut function.function.body, &mut 10_000, |expr, _| {
                match (&mut expr.kind, mode) {
                    (K::EffectComputation { .. }, "boundary") if !changed => {
                        expr.kind = K::Literal(Literal::Bool(true));
                        changed = true;
                    }
                    (K::EffectRun { computation, .. }, "block_result") if !changed => {
                        let mut original = computation.as_ref().clone();
                        let Term::Computation { result, .. } = &mut original.ty else {
                            panic!()
                        };
                        **result = Term::Primitive(P::Char);
                        computation.kind = K::Block {
                            statements: vec![],
                            result: Some(Box::new(original)),
                        };
                        changed = true;
                    }
                    (K::EffectRequest { allowed_index, .. }, "request") => {
                        *allowed_index = 99;
                        changed = true;
                    }
                    (
                        K::EffectHandle {
                            handlers, outer, ..
                        },
                        "outer",
                    ) => {
                        outer.push(handlers[0].operation.clone());
                        changed = true;
                    }
                    (K::EffectHandle { handlers, .. }, "fallback") => {
                        handlers[0].fallback = Some(0);
                        changed = true;
                    }
                    (K::EffectHandle { handlers, .. }, "abi") => {
                        handlers[0].abi = nir::effects::Abi::DirectPassing;
                        changed = true;
                    }
                    (K::EffectHandle { handlers, .. }, "branch" | "contract") => {
                        handlers[0].arms[0].body.ty = Term::Primitive(P::Char);
                        handlers[0].arms[0].body.kind = K::Literal(Literal::Char('x'));
                        if mode == "contract" {
                            let Term::Function { result, .. } = &mut handlers[0].signature else {
                                panic!()
                            };
                            **result = Term::Primitive(P::Char);
                        }
                        changed = true;
                    }
                    _ => {}
                }
                Ok(())
            })
            .unwrap();
        }
        assert!(changed, "{mode}");
        let failure = invalid.validate(&mut 100_000).unwrap_err();
        assert!(failure.contains("IIR"), "{mode}: {failure}");
        if mode == "boundary" {
            assert!(
                failure.contains("explicit environment boundary"),
                "{failure}"
            );
        }
        if mode == "block_result" {
            assert!(failure.contains("block result mismatch"), "{failure}");
        }
        assert!(
            Interpreter::from_iir(&invalid, Budget::default()).is_err(),
            "{mode}"
        );
    }
    assert!(graph.validate(&mut 1).unwrap_err().contains("budget"));
    graph.validate(&mut 100_000).unwrap();
}

#[test]
fn direct_effect_iir_maps_computation_results_through_control_carriers() {
    use nir::program::{ExprKind as K, Literal, MatchArm, Pattern};
    use nir::{Primitive as P, Term};
    let package = compile(
        "effect read()->bool; fn subject()->#read bool {read()#} fn run()->bool {subject()# {read()=>true,}}",
    );
    let key = iir::InstanceKey {
        declaration: id(&package, "run"),
        arguments: vec![],
    };
    let graph = elaboration::materialization::instantiate(
        &package,
        &[key.clone()],
        Default::default(),
        elaboration::ptc::Budget::default(),
    )
    .unwrap();
    for mode in ["block", "preparation", "if", "match"] {
        let mut wrapped = graph.clone();
        let mut changed = false;
        for function in &mut wrapped.functions {
            iir::visit::expression_mut(&mut function.function.body, &mut 10_000, |expr, _| {
                if let K::EffectRun { computation, .. } = &mut expr.kind {
                    if changed {
                        return Ok(());
                    }
                    let original = computation.as_ref().clone();
                    let mut condition = original.clone();
                    condition.ty = Term::Primitive(P::Bool);
                    condition.kind = K::Literal(Literal::Bool(true));
                    computation.kind = match mode {
                        "block" => K::Block {
                            statements: vec![],
                            result: Some(Box::new(original)),
                        },
                        "preparation" => K::CallPreparation {
                            statements: vec![],
                            result: Some(Box::new(original)),
                        },
                        "if" => K::If {
                            condition: Box::new(condition),
                            then_branch: Box::new(original.clone()),
                            else_branch: Some(Box::new(original)),
                        },
                        "match" => K::Match {
                            value: Box::new(condition),
                            arms: vec![MatchArm {
                                pattern: Pattern::Wild,
                                guard: None,
                                body: original,
                            }],
                        },
                        _ => unreachable!(),
                    };
                    changed = true;
                }
                Ok(())
            })
            .unwrap();
        }
        assert!(changed, "{mode}");
        wrapped.validate(&mut 100_000).unwrap();
        let mut vm = Interpreter::from_iir(&wrapped, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke_instance(&key, vec![]).unwrap(),
            Value::Bool(true),
            "{mode}"
        );
    }
}

#[test]
fn direct_effect_iir_resets_resume_at_closure_boundaries() {
    use nir::program::ExprKind as K;
    use nir::{Primitive as P, Term};
    let package =
        compile("effect read()->bool; fn run()->bool {read()# {read()=> {let f=|| true; f()},}}");
    let mut graph = elaboration::materialization::instantiate(
        &package,
        &[iir::InstanceKey {
            declaration: id(&package, "run"),
            arguments: vec![],
        }],
        Default::default(),
        elaboration::ptc::Budget::default(),
    )
    .unwrap();
    graph.validate(&mut 100_000).unwrap();
    let mut changed = false;
    for function in &mut graph.functions {
        iir::visit::expression_mut(&mut function.function.body, &mut 10_000, |expr, _| {
            if let K::Closure { body, .. } = &mut expr.kind {
                let body = std::sync::Arc::make_mut(body);
                let value = body.clone();
                body.ty = Term::Primitive(P::Never);
                body.kind = K::EffectResume(Box::new(value));
                changed = true;
            }
            Ok(())
        })
        .unwrap();
    }
    assert!(changed);
    assert!(
        graph
            .validate(&mut 100_000)
            .unwrap_err()
            .contains("lexical branch")
    );
}

