#[test]
fn normal_form_type_defaults_keep_heads_and_evaluate_inputs_once() {
    use nir::{Primitive as P, Sort, Term};
    let package = compile(
        "typealias Type=.Type'builtin; pure comptime fn Pair<T,.U:Type=T>->Type {T} comptime fn First()->Type {bool} comptime fn Second()->Type {'x''type} comptime fn Defaulted()->Type {Pair<First()>} comptime fn Ordered()->Type {Pair<.U=Second(),First()>} fn identity(value:Pair<bool>)->Pair<bool,.U=bool> {value}",
    );
    let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    let head = id(&package, "Pair");
    assert_eq!(
        engine.invoke(id(&package, "Defaulted"), vec![]).unwrap(),
        Value::Type(Term::NormalForm {
            head,
            sort: Sort::Type,
            arguments: vec![Term::Primitive(P::Bool), Term::Primitive(P::Bool)]
        })
    );
    assert_eq!(
        calls(&package, &engine)
            .iter()
            .filter(|name| name.as_str() == "First")
            .count(),
        1
    );
    assert!(!calls(&package, &engine).iter().any(|name| name == "Pair"));
    let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    assert_eq!(
        engine.invoke(id(&package, "Ordered"), vec![]).unwrap(),
        Value::Type(Term::NormalForm {
            head,
            sort: Sort::Type,
            arguments: vec![Term::Primitive(P::Bool), Term::Primitive(P::Char)]
        })
    );
    let order: Vec<_> = calls(&package, &engine)
        .into_iter()
        .filter(|name| ["First", "Second"].contains(&name.as_str()))
        .collect();
    assert_eq!(order, ["Second", "First"]);
    let identity = package
        .functions
        .iter()
        .find(|f| f.name == "identity")
        .unwrap();
    assert!(
        matches!(&identity.signature, Term::Function {parameters,result} if parameters[0].ty==**result && matches!(&**result,Term::NormalForm {head:actual,..} if *actual==head))
    );
}

#[test]
fn normal_form_defaults_select_computation_only_for_omitted_inputs() {
    use nir::{Primitive as P, Sort, Term};
    for (source, expected) in [
        (
            "pure comptime fn Head<.T:Type=bool>->Type {T} comptime fn Observed()->Type {Head<>}",
            vec![P::Bool],
        ),
        (
            "comptime fn Selected(value:Type)->Type {if value==bool {'x''type} else {bool}} pure comptime fn Head<T,.U:Type=Selected(T)>->Type {T} comptime fn Observed()->Type {Head<bool>}",
            vec![P::Bool, P::Char],
        ),
        (
            "comptime fn NeverReturns()->Type {NeverReturns()} pure comptime fn Head<.T:Type=NeverReturns()>->Type {T} comptime fn Observed()->Type {Head<.T=bool>}",
            vec![P::Bool],
        ),
    ] {
        let package = compile(&format!("typealias Type=.Type'builtin;{source}"));
        let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
        assert_eq!(
            engine.invoke(id(&package, "Observed"), vec![]).unwrap(),
            Value::Type(Term::NormalForm {
                head: id(&package, "Head"),
                sort: Sort::Type,
                arguments: expected.into_iter().map(Term::Primitive).collect()
            })
        );
        assert!(
            !calls(&package, &engine)
                .iter()
                .any(|name| name == "Head" || name == "NeverReturns")
        );
    }
}

#[test]
fn mixed_normal_form_defaults_bind_values_once_and_preserve_input_order() {
    use nir::{Sort, Term};
    let package = compile(
        "typealias Type=.Type'builtin;typealias Integer=.Integer'builtin;pure comptime fn Head<T,N:Integer,.M:Integer=(N + 1),.U:Type=T>->Type {T} comptime fn First()->Integer {4} comptime fn Last()->Integer {9} comptime fn Defaulted()->Type {Head<bool,First()>} comptime fn Ordered()->Type {Head<.M=Last(),bool,First()>} fn same(value:Head<bool,4>)->Head<bool,4,.M=5,.U=bool> {value}",
    );
    for (name, second, order) in [
        ("Defaulted", 5, vec!["First"]),
        ("Ordered", 9, vec!["Last", "First"]),
    ] {
        let mut engine = Interpreter::for_comptime(&package, Budget::default()).unwrap();
        let integer = |n| Term::Integer(comptime_runtime::Integer::from_u128(n));
        assert_eq!(
            engine.invoke(id(&package, name), vec![]).unwrap(),
            Value::Type(Term::NormalForm {
                head: id(&package, "Head"),
                sort: Sort::Type,
                arguments: vec![
                    Term::Primitive(nir::Primitive::Bool),
                    integer(4),
                    integer(second),
                    Term::Primitive(nir::Primitive::Bool)
                ]
            })
        );
        let observed: Vec<_> = calls(&package, &engine)
            .into_iter()
            .filter(|name| ["First", "Last"].contains(&name.as_str()))
            .collect();
        assert_eq!(observed, order);
        assert!(!calls(&package, &engine).iter().any(|name| name == "Head"));
    }
}

