#[test]
fn staged_function_inputs_execute_without_runtime_arguments() {
    use nir::program::{Expr, ExprKind as K, Literal};
    use nir::{Primitive, Sort, Term};
    for source in [
        "fn choose(flag:bool,value:bool)->bool {flag and value}",
        "fn choose(.flag:bool=true,value:bool)->bool {flag and value}",
        "fn choose(flag:bool,value:bool)->bool {let action=|| flag;action() and value}",
        "fn choose(flag:bool,value:bool)->bool {flag = not flag;not flag and value}",
    ] {
        let mut package = compile(source);
        let function = package
            .functions
            .iter_mut()
            .find(|f| f.name == "choose")
            .unwrap();
        let Term::Function { parameters, .. } = &mut function.signature else {
            panic!("signature")
        };
        parameters[0].sort = Sort::ComptimeValue;
        let original = function.clone();
        let constant = Expr {
            ty: Term::Primitive(Primitive::Bool),
            source: function.body.source,
            kind: K::Literal(Literal::Bool(true)),
        };
        *function =
            iir::staging::bind_inputs(function, &[Some(constant), None], &mut 10_000).unwrap();
        assert_eq!(function.parameters.len(), 1);
        assert_eq!(original.parameters.len(), 2);
        let identity = function.declaration;
        let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke(identity, vec![Value::Bool(true)]).unwrap(),
            Value::Bool(true),
            "{source}"
        );
        assert_eq!(
            vm.invoke(identity, vec![Value::Bool(false)]).unwrap(),
            Value::Bool(false),
            "{source}"
        );
    }
}

#[test]
fn staged_function_inputs_preserve_contracts_snapshots_and_defaults() {
    use nir::program::{Expr, ExprKind as K, Literal};
    use nir::{Primitive, Sort, Term};
    let mut package = compile(
        "fn choose(flag:bool,.value:bool=flag)->result:bool where requires flag and value == flag, ensures result == flag'old {value}",
    );
    let function = package
        .functions
        .iter_mut()
        .find(|f| f.name == "choose")
        .unwrap();
    assert!(!function.entry_snapshots.is_empty());
    let Term::Function { parameters, .. } = &mut function.signature else {
        panic!("signature")
    };
    parameters[0].sort = Sort::ComptimeValue;
    let constant = Expr {
        ty: Term::Primitive(Primitive::Bool),
        source: function.body.source,
        kind: K::Literal(Literal::Bool(true)),
    };
    *function = iir::staging::bind_inputs(function, &[Some(constant), None], &mut 10_000).unwrap();
    assert!(function.entry_snapshots.is_empty());
    assert_eq!(function.defaults[0].0, 0);
    let identity = function.declaration;
    let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        vm.invoke(identity, vec![Value::Bool(true)]).unwrap(),
        Value::Bool(true)
    );
    assert!(vm.invoke(identity, vec![Value::Bool(false)]).is_err());
    assert_eq!(
        vm.invoke(identity, vec![Value::Bool(true)]).unwrap(),
        Value::Bool(true)
    );
    drop(vm);
    let function = package
        .functions
        .iter_mut()
        .find(|f| f.declaration == identity)
        .unwrap();
    function.body = function.defaults[0].1.clone();
    function.defaults.clear();
    function.preconditions.clear();
    function.postconditions.clear();
    function.result_binding = None;
    function.parameters.clear();
    function.signature = Term::Function {
        parameters: vec![],
        result: Box::new(Term::Primitive(Primitive::Bool)),
    };
    let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(vm.invoke(identity, vec![]).unwrap(), Value::Bool(true));
}

#[test]
fn staged_function_inputs_reject_repeated_computation_and_recover() {
    use nir::program::{Expr, ExprKind as K, Literal};
    use nir::{Primitive, Sort, Term};
    let package = compile("fn choose(flag:bool)->bool {flag}");
    let mut function = package.functions[0].clone();
    let value = Expr {
        ty: Term::Primitive(Primitive::Bool),
        source: function.body.source,
        kind: K::Literal(Literal::Bool(true)),
    };
    assert!(iir::staging::bind_inputs(&function, &[Some(value.clone())], &mut 10_000).is_err());
    let Term::Function { parameters, .. } = &mut function.signature else {
        panic!("signature")
    };
    parameters[0].sort = Sort::ComptimeValue;
    let original = function.clone();
    let mut invalid = value.clone();
    invalid.kind = K::Local(function.parameters[0]);
    assert!(iir::staging::bind_inputs(&function, &[Some(invalid)], &mut 10_000).is_err());
    assert!(iir::staging::bind_inputs(&function, &[Some(value.clone())], &mut 0).is_err());
    let mut invalid = value.clone();
    invalid.ty = Term::Primitive(Primitive::Char);
    assert!(iir::staging::bind_inputs(&function, &[Some(invalid)], &mut 10_000).is_err());
    let good = iir::staging::bind_inputs(&function, &[Some(value)], &mut 10_000).unwrap();
    assert!(good.parameters.is_empty());
    assert_eq!(function, original);
}

#[test]
fn staged_function_inputs_bind_aggregates_and_validate_numeric_ranges() {
    use nir::program::{Expr, ExprKind as K, Literal};
    use nir::{Primitive, Sort, Term};
    let mut package = execution_support::compile_with_tuple(
        "fn choose(pair:Tuple<bool, .u8'builtin>)->bool {let (flag,number)=pair;flag and number == 7}",
    );
    let heads = package.normal_forms.clone();
    let function = package
        .functions
        .iter_mut()
        .find(|f| f.name == "choose")
        .unwrap();
    let Term::Function { parameters, .. } = &mut function.signature else {
        panic!("signature")
    };
    parameters[0].sort = Sort::ComptimeValue;
    let tuple_ty = parameters[0].ty.clone();
    let source = function.body.source;
    let constant = |number| Expr {
        ty: tuple_ty.clone(),
        source,
        kind: K::Tuple(vec![
            Expr {
                ty: Term::Primitive(Primitive::Bool),
                source,
                kind: K::Literal(Literal::Bool(true)),
            },
            Expr {
                ty: Term::Primitive(Primitive::U8),
                source,
                kind: K::Literal(Literal::UnsignedInteger(number)),
            },
        ]),
    };
    assert!(
        iir::staging::bind_inputs_with_layouts(
            heads.as_slice(),
            function,
            &[Some(constant(256))],
            &mut 10_000
        )
        .is_err()
    );
    *function = iir::staging::bind_inputs_with_layouts(
        heads.as_slice(),
        function,
        &[Some(constant(7))],
        &mut 10_000,
    )
    .unwrap();
    let identity = function.declaration;
    let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(vm.invoke(identity, vec![]).unwrap(), Value::Bool(true));
}

#[test]
fn staged_calls_keep_distinct_instances_and_runtime_evaluation_order() {
    use nir::Term;
    let package = execution_support::compile_with_tuple(
        "fn first()->bool {true} fn second()->bool {false} fn choose(flag:bool,left:bool,right:bool)->bool {if flag {left} else {right}} fn run()->Tuple<bool, bool> {(choose(true,first(),second()),choose(false,first(),second()))}",
    );
    let (graph, root) = staged_direct_call_graph(&package);
    let template = package
        .functions
        .iter()
        .find(|f| f.name == "choose")
        .unwrap();
    let keys = graph
        .functions
        .iter()
        .filter(|f| f.key.declaration == template.declaration)
        .map(|f| f.key.arguments.clone())
        .collect::<Vec<_>>();
    assert_eq!(keys.len(), 2);
    assert!(keys.contains(&vec![Term::Bool(true)]));
    assert!(keys.contains(&vec![Term::Bool(false)]));
    graph.validate(&mut 100_000).unwrap();
    let mut vm = Interpreter::from_iir(&graph, Budget::default()).unwrap();
    assert_eq!(
        vm.invoke_instance(&root, vec![]).unwrap(),
        Value::Tuple(vec![Value::Bool(true), Value::Bool(false)])
    );
    let order = vm
        .events()
        .iter()
        .filter_map(|event| match event {
            Event::EnterFunction(declaration) => package
                .functions
                .iter()
                .find(|f| f.declaration == *declaration)
                .map(|f| f.name.as_str()),
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(
        order,
        vec![
            "run", "first", "second", "choose", "first", "second", "choose"
        ]
    );
}

fn staged_direct_call_graph(package: &Package) -> (iir::Package, iir::InstanceKey) {
    use nir::program::ExprKind as K;
    use nir::{Sort, Term};
    let mut template = package
        .functions
        .iter()
        .find(|f| f.name == "choose")
        .unwrap()
        .clone();
    let Term::Function { parameters, .. } = &mut template.signature else {
        panic!("signature")
    };
    parameters[0].sort = Sort::ComptimeValue;
    let root = iir::InstanceKey {
        declaration: id(package, "run"),
        arguments: vec![],
    };
    let mut graph = iir::Package {
        roots: vec![root.clone()],
        normal_forms: package.normal_forms.clone(),
        ..Default::default()
    };
    for function in &package.functions {
        if function.declaration == template.declaration
            || package
                .normal_forms
                .iter()
                .any(|head| head.declaration == function.declaration)
        {
            continue;
        }
        let mut function = function.clone();
        iir::visit::expression_mut(&mut function.body, &mut 100_000, |expr, fuel| {
            let K::Call { callee, .. } = &mut expr.kind else {
                return Ok(());
            };
            let declaration_arguments = match &callee.kind {
                K::Function(declaration) if *declaration == template.declaration => vec![],
                K::FunctionInstance {
                    declaration,
                    arguments,
                } if *declaration == template.declaration => arguments.clone(),
                _ => return Ok(()),
            };
            let mut selected = template
                .instantiate_types(&template.type_parameters, &declaration_arguments)
                .map_err(|e| e.to_string())?;
            selected.type_parameters.clear();
            callee.ty = selected.signature.clone();
            let (instance, call) =
                iir::staging::bind_call(&selected, &declaration_arguments, expr, fuel)?;
            if !graph.functions.iter().any(|old| old.key == instance.key) {
                graph.functions.push(instance);
            }
            *expr = call;
            Ok(())
        })
        .unwrap();
        graph.functions.push(iir::FunctionInstance {
            key: iir::InstanceKey {
                declaration: function.declaration,
                arguments: vec![],
            },
            function,
        });
    }
    (graph, root)
}

#[test]
fn staged_calls_preserve_named_input_order_and_default_dependencies() {
    for (call, expected, order) in [
        (
            "choose(.right=second(),.left=first(),.flag=true)",
            true,
            vec!["run", "second", "first", "choose"],
        ),
        (
            "choose(.left=first())",
            true,
            vec!["run", "first", "choose"],
        ),
        (
            "choose(.flag=false,.left=second())",
            false,
            vec!["run", "second", "choose"],
        ),
    ] {
        let package = compile(&format!(
            "fn first()->bool {{true}} fn second()->bool {{false}} fn choose(.flag:bool=true,.left:bool=false,.right:bool=left)->bool {{if flag {{left}} else {{right}}}} fn run()->bool {{{call}}}"
        ));
        let (graph, root) = staged_direct_call_graph(&package);
        graph.validate(&mut 100_000).unwrap();
        let mut vm = Interpreter::from_iir(&graph, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke_instance(&root, vec![]).unwrap(),
            Value::Bool(expected),
            "{call}"
        );
        assert_eq!(calls(&package, &vm), order, "{call}");
    }
}

#[test]
fn staged_calls_reject_malformed_plans_without_changing_templates() {
    use nir::program::ExprKind as K;
    use nir::{Sort, Term};
    let package = compile(
        "fn choose(flag:bool,value:bool)->bool {flag and value} fn run()->bool {choose(true,true)}",
    );
    let mut template = package
        .functions
        .iter()
        .find(|f| f.name == "choose")
        .unwrap()
        .clone();
    let Term::Function { parameters, .. } = &mut template.signature else {
        panic!("signature")
    };
    parameters[0].sort = Sort::ComptimeValue;
    let mut call = None;
    iir::visit::expression(
        &package
            .functions
            .iter()
            .find(|f| f.name == "run")
            .unwrap()
            .body,
        &mut 100_000,
        |expr, _| {
            if matches!(expr.kind, K::Call { .. }) {
                call = Some(expr.clone());
            }
            Ok(())
        },
    )
    .unwrap();
    let mut call = call.unwrap();
    let K::Call { callee, .. } = &mut call.kind else {
        unreachable!()
    };
    callee.ty = template.signature.clone();
    let original = template.clone();
    for mode in 0..5 {
        let mut bad = call.clone();
        let K::Call {
            arguments,
            parameter_bindings,
            ..
        } = &mut bad.kind
        else {
            unreachable!()
        };
        match mode {
            0 => arguments[1].parameter = 0,
            1 => {
                arguments.pop();
            }
            2 => arguments[0].parameter = 99,
            3 => parameter_bindings.push(template.parameters[0]),
            _ => arguments[0].value.kind = K::Local(template.parameters[0]),
        }
        assert!(
            iir::staging::bind_call(&template, &[], &bad, &mut 10_000).is_err(),
            "mode {mode}"
        );
    }
    assert!(iir::staging::bind_call(&template, &[Term::Bool(true)], &call, &mut 10_000).is_err());
    assert!(iir::staging::bind_call(&template, &[], &call, &mut 0).is_err());
    let (instance, _) = iir::staging::bind_call(&template, &[], &call, &mut 10_000).unwrap();
    assert_eq!(instance.key.arguments, vec![Term::Bool(true)]);
    assert_eq!(template, original);
}

#[test]
fn staged_calls_retain_generic_identity_and_allow_empty_runtime_signatures() {
    use nir::{Primitive, Term};
    for (source, expected, keys) in [
        (
            "fn choose(flag:bool,left:T,right:T)->T where T {if flag {left} else {right}} fn run()->Tuple<bool, 'x''type> {(choose(true,true,false),choose(false,'a','b'))}",
            Value::Tuple(vec![Value::Bool(true), Value::Char('b')]),
            vec![
                vec![Term::Primitive(Primitive::Bool), Term::Bool(true)],
                vec![Term::Primitive(Primitive::Char), Term::Bool(false)],
            ],
        ),
        (
            "fn choose(.flag:bool=true)->bool {flag} fn run()->Tuple<bool, bool, bool> {(choose(),choose(.flag=false),choose())}",
            Value::Tuple(vec![
                Value::Bool(true),
                Value::Bool(false),
                Value::Bool(true),
            ]),
            vec![vec![Term::Bool(true)], vec![Term::Bool(false)]],
        ),
    ] {
        let package = execution_support::compile_with_tuple(source);
        let (graph, root) = staged_direct_call_graph(&package);
        let instances = graph
            .functions
            .iter()
            .filter(|instance| instance.function.name == "choose")
            .collect::<Vec<_>>();
        assert_eq!(instances.len(), keys.len());
        for key in keys {
            assert!(
                instances
                    .iter()
                    .any(|instance| instance.key.arguments == key)
            );
        }
        graph.validate(&mut 100_000).unwrap();
        let mut vm = Interpreter::from_iir(&graph, Budget::default()).unwrap();
        assert_eq!(vm.invoke_instance(&root, vec![]).unwrap(), expected);
    }
}

