#[test]
fn source_comptime_forwarding_folds_boolean_operations_and_choices() {
    for (input, expected) in [
        ("not flag", (false, true)),
        ("flag and true", (true, false)),
        ("flag or false", (true, false)),
        ("flag == false", (false, true)),
        ("if flag {false} else {true}", (false, true)),
        ("do {not flag}", (false, true)),
    ] {
        let package = execution_support::compile_with_tuple(&format!(
            "fn choose(comptime flag:bool)->bool {{flag}} fn forward(comptime flag:bool)->bool {{choose({input})}} fn run()->Tuple<bool, bool> {{(forward(true),forward(false))}}"
        ));
        let graph = luna::instantiation::instantiate(&package, "run", 100_000).unwrap();
        let mut vm = Interpreter::from_iir(&graph, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke_instance(&graph.roots[0], vec![]).unwrap(),
            Value::Tuple(vec![Value::Bool(expected.0), Value::Bool(expected.1)]),
            "{input}"
        );
        for instance in graph
            .functions
            .iter()
            .filter(|f| f.function.name == "choose")
        {
            let nir::program::ExprKind::Block { statements, .. } = &instance.function.body.kind
            else {
                panic!("bound inputs")
            };
            let nir::program::ExprKind::Let { value, .. } = &statements[0].kind else {
                panic!("binding")
            };
            assert!(
                matches!(
                    value.kind,
                    nir::program::ExprKind::Literal(nir::program::Literal::Bool(_))
                ),
                "residual computation: {value}"
            );
        }
    }
}

