#[test]
fn deferred_comptime_invocation_executes_helper_control_flow_and_contracts() {
    let source = "comptime fn compute(flag:bool)->bool {var remaining=true;var value=flag;while remaining {value=not value;remaining=false;} value} fn choose(comptime flag:bool)->bool {flag} fn forward(comptime flag:bool)->bool {choose(compute(flag))} fn run()->bool {forward(false)}";
    let package = compile(source);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    for post in [false, true] {
        let mut failed = package.clone();
        let helper = failed
            .functions
            .iter_mut()
            .find(|f| f.name == "compute")
            .unwrap();
        let predicate = nir::program::Expr {
            ty: nir::Term::Primitive(nir::Primitive::Bool),
            source: helper.body.source,
            kind: nir::program::ExprKind::Literal(nir::program::Literal::Bool(false)),
        };
        if post {
            helper.postconditions.push(predicate);
        } else {
            helper.preconditions.push(predicate);
        }
        let error = luna::instantiation::instantiate(&failed, "run", 100_000).unwrap_err();
        assert!(error.contains("staged comptime invocation"), "{error}");
    }
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
}

