#[test]
fn staged_call_preparation_evaluates_each_producer_once() {
    use nir::program::{ExprKind as K, Literal};
    use nir::{Sort, Term};
    let package = compile(
        "fn input()->bool {true} fn choose(.a:bool=false,.b:bool=a,.c:bool=not b)->bool {c} fn run()->bool {choose(.a=input())}",
    );
    let mut template = package
        .functions
        .iter()
        .find(|f| f.name == "choose")
        .unwrap()
        .clone();
    let Term::Function { parameters, .. } = &mut template.signature else {
        panic!("signature")
    };
    for parameter in parameters {
        parameter.sort = Sort::ComptimeValue;
    }
    let mut call = None;
    iir::visit::expression(
        &package
            .functions
            .iter()
            .find(|f| f.name == "run")
            .unwrap()
            .body,
        &mut 100_000,
        |expr, _| {
            if let K::Call { callee, .. } = &expr.kind {
                if matches!(callee.kind,K::Function(id) if id==template.declaration) {
                    call = Some(expr.clone());
                }
            }
            Ok(())
        },
    )
    .unwrap();
    let mut call = call.unwrap();
    let K::Call { callee, .. } = &mut call.kind else {
        unreachable!()
    };
    callee.ty = template.signature.clone();
    let mut invalid = call.clone();
    let K::Call { arguments, .. } = &mut invalid.kind else {
        unreachable!()
    };
    arguments.pop();
    let mut attempted = 0;
    assert!(
        iir::staging::bind_call_with(&template, &[], &invalid, &mut 100_000, |expr, _| {
            attempted += 1;
            Ok(expr.clone())
        })
        .is_err()
    );
    assert_eq!(
        attempted, 0,
        "invalid call plans must not execute staged producers"
    );
    let mut invocations = 0;
    let mut evaluations = 0;
    let (instance, _) =
        iir::staging::bind_call_with(&template, &[], &call, &mut 100_000, |expr, fuel| {
            evaluations += 1;
            if matches!(expr.kind, K::Call { .. }) {
                invocations += 1;
                let mut value = expr.clone();
                value.kind = K::Literal(Literal::Bool(invocations == 1));
                Ok(value)
            } else {
                iir::staging::fold_value(expr, fuel)
            }
        })
        .unwrap();
    assert_eq!(evaluations, 3);
    assert_eq!(invocations, 1);
    assert_eq!(
        instance.key.arguments,
        vec![Term::Bool(true), Term::Bool(true), Term::Bool(false)]
    );
}

