#[test]
fn deferred_comptime_bitvec_operations_preserve_width_and_order() {
    for (body, expected) in [
        ("(not byte'bitvec).as(Byte)", 0x50),
        (
            "do {let mask:Byte=15;(byte'bitvec and mask'bitvec).as(Byte)}",
            0x0f,
        ),
        (
            "do {let mask:Byte=15;(byte'bitvec or mask'bitvec).as(Byte)}",
            0xaf,
        ),
        ("(byte'bitvec[0..4] ++ byte'bitvec[4..8]).as(Byte)", 0xfa),
        ("byte'bitvec[0..4].as(Byte)", 0x0f),
        ("do {var value=byte;value'bitvec[4..8]=3;value}", 0x3f),
        (
            "do {let cell=Cell {value:byte};cell.value'bitvec[0..4]=3;cell.value}",
            0xa3,
        ),
        ("(byte'bitvec[0..0] ++ byte'bitvec).as(Byte)", 0xaf),
    ] {
        let package = compile(&format!(
            "typealias Byte=.u8'builtin;struct Cell {{value:Byte}} fn choose(comptime value:Byte)->Byte {{value}} fn forward(comptime byte:Byte)->Byte {{choose({body})}} fn run()->Byte {{forward(175)}}"
        ));
        let graph = luna::instantiation::instantiate(&package, "run", 100_000).unwrap();
        for function in &graph.functions {
            iir::visit::expression(&function.function.body, &mut 10_000, |expr, _| {
                assert!(
                    !matches!(
                        expr.kind,
                        nir::program::ExprKind::TakeBits(_)
                            | nir::program::ExprKind::BitAssign { .. }
                            | nir::program::ExprKind::BitConcat(..)
                    ),
                    "staged bit operation survived into runtime IIR"
                );
                Ok(())
            })
            .unwrap();
        }
        let mut vm = Interpreter::from_iir(&graph, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke_instance(&graph.roots[0], vec![]).unwrap(),
            Value::UnsignedInteger(expected),
            "{body}"
        );
    }
}

