#[test]
fn derived_staged_locals_forward_through_owned_closure_captures() {
    for initializer in [
        "let enabled=not flag;",
        "let enabled=flag == false;",
        "let pair=(not flag,flag);let (enabled,_)=pair;",
    ] {
        for body in [
            "let read:%{enabled:bool} comptime fn()->bool=|| enabled;read()",
            "let read:%{enabled:bool} comptime fn()->bool=|| {let nested:%{enabled:bool} comptime fn()->bool=|| enabled;nested()};read()",
            "let toggle:%{enabled:bool} comptime fn()->bool=|| {var state=enabled;let step:%{state:bool} comptime fn()->bool=|| {state=not state;state};let first=step();let second=step();first != enabled and second == enabled};toggle()",
        ] {
            let source = format!(
                "fn choose(comptime value:bool)->bool {{value}}
            fn forward(comptime flag:bool)->bool {{
                {initializer}choose(do {{{body}}})
            }}
            fn run()->Tuple<bool, bool> {{(forward(false),forward(true))}}"
            );
            let package = execution_support::compile_with_tuple(&source);
            let expected = if body.contains("toggle") {
                vec![true, true]
            } else {
                vec![true, false]
            };
            assert_eq!(
                luna::execution::interpret(&package, "run", 100_000).unwrap(),
                Value::Tuple(expected.into_iter().map(Value::Bool).collect()),
                "{body}"
            );
            let runtime = source.replace("comptime flag:", "flag:");
            assert!(compile_with_bindings(&runtime, &Default::default(), None).is_err());
            let invalidated =
                source.replace("choose(do", "let ptr=enabled.ref;ptr.* = false;choose(do");
            let package = execution_support::compile_with_tuple(&invalidated);
            let error = luna::instantiation::instantiate(&package, "run", 100_000).unwrap_err();
            assert!(error.contains("writes or address escape"), "{error}");
        }
    }
}

