#[test]
fn dependent_staged_ir_rebinds_body_annotations_before_runtime_validation() {
    let mut package = compile(
        "typealias Type=.Type'builtin;fn identity(comptime T:Type,value:bool)->bool {value} fn run()->bool {identity(bool,true)}",
    );
    let declaration = id(&package, "identity");
    let dependent = nir::Term::Bound {
        depth: 0,
        index: 0,
        sort: nir::Sort::Type,
    };
    let identity = package
        .functions
        .iter_mut()
        .find(|function| function.declaration == declaration)
        .unwrap();
    let nir::Term::Function { parameters, result } = &mut identity.signature else {
        panic!()
    };
    parameters[1].ty = dependent.clone();
    *result = Box::new(dependent.clone());
    identity
        .body
        .rewrite_types(&mut |ty| {
            Ok::<_, String>(if *ty == nir::Term::Primitive(nir::Primitive::Bool) {
                dependent.clone()
            } else {
                ty.clone()
            })
        })
        .unwrap();
    let signature = identity.signature.clone();
    for function in &mut package.functions {
        iir::visit::expression_mut(&mut function.body, &mut 10000, |expr, _| {
            if matches!(expr.kind,nir::program::ExprKind::Function(id) if id==declaration) {
                expr.ty = signature.clone();
            }
            Ok(())
        })
        .unwrap();
    }
    let original = package.clone();
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    assert_eq!(
        package, original,
        "instance binding changed the shared template"
    );
}

#[test]
fn dependent_comptime_type_inputs_elaborate_from_source() {
    let source = "typealias Type=.Type'builtin; typealias Char='x''type;
        fn identity(comptime T:Type,value:T)->T {value}
        fn forward(comptime T:Type,value:T)->T {let f:fn(T)->T=|x| x; identity(T,f(value))}
        fn copy(comptime T:Type,comptime value:T,comptime .copy:T=value)->T {copy}
        fn reordered(comptime flag:bool,comptime T:Type,comptime value:T)->T {copy(T,value)}
        fn apply(comptime T:Type,value:T,callback:fn(T)->T)->T {callback(value)}
        fn generic(value:G)->G where G {identity(G,value)}
        fn negate(value:bool)->bool {not value}
        fn run()->Tuple<bool, Char, bool, bool> {(forward(bool,true),generic('x'),reordered(true,bool,false),apply(bool,true,negate))}";
    let package = execution_support::compile_with_tuple(source);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Tuple(vec![
            Value::Bool(true),
            Value::Char('x'),
            Value::Bool(false),
            Value::Bool(false)
        ])
    );
}

