#[test]
fn dependent_comptime_type_inputs_work_in_required_invocations() {
    let package = compile(
        "typealias Type=.Type'builtin;
        comptime fn identity(comptime T:Type,value:T)->T {value}
        fn selected(comptime value:bool)->bool {value}
        fn run()->bool {selected(identity(bool,true))}",
    );
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    let original = package.clone();
    let mut vm = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    let identity = id(&package, "identity");
    let bool_type = Value::Type(nir::Term::Primitive(nir::Primitive::Bool));
    let char_type = Value::Type(nir::Term::Primitive(nir::Primitive::Char));
    assert_eq!(
        vm.invoke(identity, vec![bool_type.clone(), Value::Char('x')])
            .unwrap_err()
            .kind,
        ErrorKind::Type
    );
    assert_eq!(
        vm.invoke(identity, vec![char_type, Value::Char('x')])
            .unwrap(),
        Value::Char('x')
    );
    assert_eq!(
        vm.invoke(identity, vec![bool_type, Value::Bool(false)])
            .unwrap(),
        Value::Bool(false)
    );
    assert_eq!(
        package, original,
        "invocation specialization mutated the declaration"
    );
}

