#[test]
fn ordinary_comptime_values_defer_normal_form_default_plans_until_specialization() {
    let package = execution_support::compile_with_tuple(
        "typealias Type=.Type'builtin;typealias Integer=.Integer'builtin;
        pure comptime fn Shape<N: Integer, .storage: Integer = (N + 1)>->Type {bool}
        fn tag(comptime n:Integer,comptime .T:Type=Shape<n>)->bool {true}
        fn forward(comptime n:Integer)->bool {tag(n)}
        fn run()->Tuple<bool, bool> {(forward(4),forward(5))}",
    );
    let graph = luna::instantiation::instantiate(&package, "run", 100_000).unwrap();
    let mut widths = Vec::new();
    for instance in graph
        .functions
        .iter()
        .filter(|instance| instance.function.name == "tag")
    {
        let nir::Term::NormalForm { arguments, .. } = &instance.key.arguments[1] else {
            panic!("opaque head was lost")
        };
        assert_eq!(arguments[0], instance.key.arguments[0]);
        let nir::Term::Integer(width) = &arguments[1] else {
            panic!("storage default was not computed")
        };
        widths.push(width.to_unsigned(128).unwrap());
    }
    widths.sort();
    assert_eq!(widths, vec![5, 6]);
    let mut vm = Interpreter::from_iir(&graph, Budget::default()).unwrap();
    assert_eq!(
        vm.invoke_instance(&graph.roots[0], vec![]).unwrap(),
        Value::Tuple(vec![Value::Bool(true), Value::Bool(true)])
    );
}

#[test]
fn staged_unbounded_integer_computations_preserve_values_beyond_machine_width() {
    let package = compile(
        "typealias Integer=.Integer'builtin;
        fn tag(comptime n:Integer)->bool {true}
        fn forward(comptime n:Integer)->bool {tag(n + 1)}
        fn run()->bool {forward(340282366920938463463374607431768211455)}",
    );
    let original = package.clone();
    let graph = luna::instantiation::instantiate(&package, "run", 100_000).unwrap();
    let instance = graph
        .functions
        .iter()
        .find(|instance| instance.function.name == "tag")
        .unwrap();
    let nir::Term::Integer(value) = &instance.key.arguments[0] else {
        panic!("missing evaluated integer input")
    };
    assert_eq!(value.bit_len(), 129);
    assert_eq!(
        value
            .to_hex_literal(&mut comptime_runtime::Budget::default())
            .unwrap(),
        "0x100000000000000000000000000000000"
    );
    let mut vm = Interpreter::from_iir(&graph, Budget::default()).unwrap();
    assert_eq!(
        vm.invoke_instance(&graph.roots[0], vec![]).unwrap(),
        Value::Bool(true)
    );
    assert_eq!(package, original);
}

#[test]
fn dependent_comptime_value_inputs_of_type_execute_and_recover_in_the_interpreter() {
    let package = compile(
        "typealias Type=.Type'builtin;
        comptime fn identity(comptime T:Type,comptime value:T)->T {value}
        comptime fn observe()->bool {identity(Type,bool) == bool}
        fn selected(comptime value:bool)->bool {value}
        fn run()->bool {selected(observe())}",
    );
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    let original = package.clone();
    let mut vm = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    let declaration = id(&package, "identity");
    let type_type = Value::Type(nir::Term::Primitive(nir::Primitive::Type));
    let bool_type = Value::Type(nir::Term::Primitive(nir::Primitive::Bool));
    assert_eq!(
        vm.invoke(declaration, vec![type_type.clone(), Value::Bool(true)])
            .unwrap_err()
            .kind,
        ErrorKind::Type
    );
    assert_eq!(
        vm.invoke(declaration, vec![type_type, bool_type.clone()])
            .unwrap(),
        bool_type
    );
    assert_eq!(
        vm.invoke(declaration, vec![bool_type, Value::Bool(false)])
            .unwrap(),
        Value::Bool(false)
    );
    assert_eq!(package, original);
}

