#[test]
fn generic_callback_values_preserve_inherited_trait_evidence() {
    for clauses in ["A :- Enabled", "A, requires A :- Enabled"] {
        let package = compile(&format!(
            "trait Allowed {{fn allowed(self)->bool;}}
            trait Enabled :- Allowed {{}}
            impl Allowed for bool {{fn allowed(self)->bool {{self}}}}
            impl Enabled for bool {{}}
            fn inspect(value:G)->bool where G :- Allowed {{value.as(Allowed).allowed()}}
            fn apply(action:fn(G)->bool,value:G)->bool where G {{action(value)}}
            fn forward(value:A)->bool where {clauses} {{
                let action:fn(A)->bool=inspect;
                apply(action,value) and apply(inspect,value)
            }}
            fn run()->bool {{forward(true) and not forward(false)}}"
        ));
        assert_eq!(
            luna::execution::interpret(&package, "run", 100_000).unwrap(),
            Value::Bool(true)
        );
    }
}

