#[test]
fn ordinary_comptime_indices_in_capabilities_use_defaults_and_forwarded_evidence() {
    let package = execution_support::compile_with_tuple("typealias Type=.Type'builtin;
        trait Source {assoc Item:Type;}
        impl Source for bool {assoc Item:Type=Type;}
        trait Allowed where T {}
        pure comptime fn Tagged<T,value:T>->Type {T}
        impl Allowed<Tagged<Type,bool>> for bool {}
        fn accept(comptime A:Type,comptime value:A.as(Source).Item,
                  comptime .copy:A.as(Source).Item=value)->bool
        where requires A :- Source, requires bool :- Allowed<Tagged<A.as(Source).Item,copy>> {true}
        fn forward(comptime A:Type,comptime value:A.as(Source).Item)->bool
        where requires A :- Source, requires bool :- Allowed<Tagged<A.as(Source).Item,value>> {accept(A,value)}
        fn generic(comptime value:T,extra:G)->G where T,G,
            requires bool :- Allowed<Tagged<T,value>> {extra}
        fn run()->Tuple<bool, bool, bool> { (accept(bool,bool),forward(bool,bool),generic(bool,true)) }");
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Tuple(vec![
            Value::Bool(true),
            Value::Bool(true),
            Value::Bool(true)
        ])
    );
}

#[test]
fn inferred_comptime_capability_domains_cover_scalars_types_and_aggregates() {
    for (domain, value) in [
        ("bool", "true"),
        ("'x''type", "'x'"),
        ("Type", "bool"),
        ("Tuple<bool,bool>", "(true,false)"),
    ] {
        let package = execution_support::compile_with_tuple(&format!(
            "typealias Type=.Type'builtin;
            trait Allowed where Index {{}}
            pure comptime fn Tagged<T,value:T>->Type {{T}}
            impl Allowed<Tagged<{domain},{value}>> for bool {{}}
            fn accept(comptime value:T,extra:G)->G where T,G,
                requires bool :- Allowed<Tagged<T,value>> {{extra}}
            fn forward(comptime value:T,extra:G)->G where T,G,
                requires bool :- Allowed<Tagged<T,value>> {{accept(value,extra)}}
            fn run()->Tuple<bool, bool> {{(accept({value},true),forward({value},false))}}"
        ));
        assert_eq!(
            luna::execution::interpret(&package, "run", 100_000).unwrap(),
            Value::Tuple(vec![Value::Bool(true), Value::Bool(false)]),
            "{domain}"
        );
    }
}

#[test]
fn ordinary_capability_dependencies_ignore_conjunct_and_bound_order() {
    for constraints in [
        "requires A.as(Source).Item.as(Source).Item :- Allowed, requires A.as(Source).Item :- Source, requires A :- Source",
        "requires (A.as(Source).Item.as(Source).Item :- Allowed) and (A.as(Source).Item :- Source) and (A :- Source)",
        "requires A :- Accepts<A.as(Source).Item> + Source, requires A.as(Source).Item :- Source, requires A.as(Source).Item.as(Source).Item :- Allowed",
    ] {
        let package = compile(&format!(
            "typealias Type=.Type'builtin;
            trait Source {{assoc Item:Type;}}
            trait Allowed {{}}
            trait Accepts where T {{}}
            impl Source for bool {{assoc Item:Type=bool;}}
            impl Allowed for bool {{}}
            impl Accepts<bool> for bool {{}}
            fn accept(comptime A:Type,value:A.as(Source).Item.as(Source).Item)->bool
            where {constraints} {{true}}
            fn run()->bool {{accept(bool,true)}}"
        ));
        assert_eq!(
            luna::execution::interpret(&package, "run", 100_000).unwrap(),
            Value::Bool(true),
            "{constraints}"
        );
        let generic = compile(&format!(
            "typealias Type=.Type'builtin;
            trait Source {{assoc Item:Type;}} trait Allowed {{}} trait Accepts where T {{}}
            impl Source for bool {{assoc Item:Type=bool;}}
            impl Allowed for bool {{}} impl Accepts<bool> for bool {{}}
            fn accept(value:A.as(Source).Item.as(Source).Item)->bool
            where A, {constraints} {{true}}
            fn run()->bool {{accept<bool>(true)}}"
        ));
        assert_eq!(
            luna::execution::interpret(&generic, "run", 100_000).unwrap(),
            Value::Bool(true),
            "clause {constraints}"
        );
    }
}

#[test]
fn declaration_capability_prerequisites_are_independent_of_source_order() {
    let prefix = "typealias Type=.Type'builtin;trait Source {assoc Item:Type;} trait Allowed {}
        impl Source for bool {assoc Item:Type=bool;} impl Allowed for bool {}";
    let bounds = "requires A.as(Source).Item :- Allowed, requires A :- Source";
    for body in [
        format!(
            "struct Container where A, {bounds} {{value:A.as(Source).Item,}} fn run()->bool {{Container<bool>{{value:true}}.value}}"
        ),
        format!(
            "enum Choice where A, {bounds} {{none,some(bool),}} fn run()->bool {{Choice<bool>.some(true) match {{.some(value)=>value,.none=>false,}}}}"
        ),
        format!(
            "trait Accepts where T {{}} impl Accepts<bool> for bool {{}} typealias Alias<A :- Accepts<A.as(Source).Item> + Source> = bool; fn run()->Alias<bool> {{true}}"
        ),
        format!(
            "trait Checked where A, {bounds} {{fn get()->bool;}} impl Checked<bool> for bool {{fn get()->bool {{true}}}} fn run()->bool {{bool.as(Checked<bool>).get()}}"
        ),
    ] {
        let package = compile(&format!("{prefix} {body}"));
        assert_eq!(
            luna::execution::interpret(&package, "run", 100_000)
                .unwrap_or_else(|e| panic!("{body}: {e}")),
            Value::Bool(true),
            "{body}"
        );
    }
}

#[test]
fn implementation_capabilities_resolve_projected_subjects_and_trait_arguments() {
    for (premise, allowed) in [
        (
            "A.as(Source).Item :- Allowed",
            "trait Allowed {} impl Allowed for bool {}",
        ),
        (
            "bool :- Allowed<A.as(Source).Item>",
            "trait Allowed where T {} impl Allowed<bool> for bool {}",
        ),
        (
            "A.as(Source).Item.as(Source).Item :- Allowed",
            "trait Allowed {} impl Allowed for bool {}",
        ),
    ] {
        let package = compile(&format!("typealias Type=.Type'builtin;
            trait Source {{assoc Item:Type;}} impl Source for bool {{assoc Item:Type=bool;}}
            {allowed} trait Get {{fn get()->bool;}} struct Holder where A {{}}
            impl Get for Holder<A> where A, requires {premise}, requires A.as(Source).Item :- Source, requires A :- Source {{fn get()->bool {{true}}}}
            fn run()->bool {{Holder<bool>.as(Get).get()}}"));
        assert_eq!(
            luna::execution::interpret(&package, "run", 100_000).unwrap(),
            Value::Bool(true),
            "{premise}"
        );
    }
}

