#[test]
fn declaration_sugar_and_explicit_bounds_share_one_prerequisite_schedule() {
    let prefix =
        "typealias Type=.Type'builtin;trait Source {assoc Item:Type;} trait Accepts where T {}
        impl Source for bool {assoc Item:Type=bool;} impl Accepts<bool> for bool {}";
    for bounds in [
        "A :- Accepts<A.as(Source).Item>, requires A :- Source",
        "A :- Source, requires A :- Accepts<A.as(Source).Item>",
        "A, requires A :- Accepts<A.as(Source).Item>, requires A :- Source",
        "A :- Accepts<A.as(Source).Item> + Source",
    ] {
        for body in [
            format!(
                "fn select(value:A)->bool where {bounds} {{true}} fn run()->bool {{select<bool>(true)}}"
            ),
            format!(
                "struct Container where {bounds} {{value:bool,}} fn run()->bool {{Container<bool>{{value:true}}.value}}"
            ),
            format!(
                "enum Choice where {bounds} {{some(bool),}} fn run()->bool {{let .some(value)=Choice<bool>.some(true);value}}"
            ),
            format!(
                "trait Select where {bounds} {{fn get()->bool;}} impl Select<bool> for bool {{fn get()->bool {{true}}}} fn run()->bool {{bool.as(Select<bool>).get()}}"
            ),
            format!(
                "trait Get {{fn get()->bool;}} struct Holder where A {{}} impl Get for Holder<A> where {bounds} {{fn get()->bool {{true}}}} fn run()->bool {{Holder<bool>.as(Get).get()}}"
            ),
        ] {
            let package = compile(&format!("{prefix} {body}"));
            assert_eq!(
                luna::execution::interpret(&package, "run", 100_000).unwrap(),
                Value::Bool(true),
                "{body}"
            );
        }
    }
}

