#[test]
fn staged_trait_calls_preserve_interface_runtime_preconditions() {
    let mut package = compile(
        "typealias Type=.Type'builtin;
        trait Service {fn accept(comptime T:Type,value:bool)->bool where requires value;}
        impl Service for bool {fn accept(comptime T:Type,value:bool)->bool {true}}
        fn run()->bool {bool.as(Service).accept(bool,true)}",
    );
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    // Fault injection after source verification checks retained runtime evidence.
    let run = package
        .functions
        .iter_mut()
        .find(|f| f.name == "run")
        .unwrap();
    iir::visit::expression_mut(&mut run.body, &mut 100_000, |expr, _| {
        if let nir::program::ExprKind::Literal(nir::program::Literal::Bool(value)) = &mut expr.kind
        {
            *value = false;
        }
        Ok(())
    })
    .unwrap();
    let error = luna::execution::interpret(&package, "run", 100_000).unwrap_err();
    assert!(error.contains("ProgramContractRejected"), "{error}");
}

