#[test]
fn staged_trait_postconditions_preserve_old_inputs_and_result_bindings() {
    for staged in ["", "comptime "] {
        for implementation in ["default", "explicit", "inherited"] {
            let default = if implementation == "default" {
                " {value}"
            } else {
                ";"
            };
            let body = match implementation {
                "default" => String::new(),
                "explicit" => format!(
                    "fn keep(comptime U:Type,{staged}input:bool)->answer:bool where ensures answer == input'old {{input}}"
                ),
                _ => format!("fn keep(comptime U:Type,{staged}input:bool)->bool {{input}}"),
            };
            let mut package=compile(&format!("typealias Type=.Type'builtin;
                trait Service {{fn keep(comptime T:Type,{staged}value:bool)->result:bool where ensures result == value'old {default}}}
                impl Service for bool {{{body}}}
                fn run()->bool {{bool.as(Service).keep(bool,true)}}"));
            assert_eq!(
                luna::execution::interpret(&package, "run", 100_000).unwrap(),
                Value::Bool(true),
                "{staged} {implementation}"
            );
            let selected = package
                .implementations
                .iter()
                .find_map(|i| {
                    i.methods
                        .iter()
                        .find(|(name, _)| name == "keep")
                        .map(|(_, id)| *id)
                })
                .unwrap();
            let method = package
                .functions
                .iter_mut()
                .find(|f| f.declaration == selected)
                .unwrap();
            method.body.kind = nir::program::ExprKind::Literal(nir::program::Literal::Bool(false));
            let error = luna::execution::interpret(&package, "run", 100_000).unwrap_err();
            assert!(
                error.contains("ProgramContractRejected"),
                "{staged} {implementation}: {error}"
            );
        }
    }
}

