#[test]
fn memory_summaries_use_local_scalar_identity_without_exporting_assumptions() {
    let package = compile(include_str!(
        "../../../development/examples/proved-scalar-memory-writes.fl"
    ));
    let declaration = package
        .functions
        .iter()
        .find(|f| f.name == "replace")
        .unwrap()
        .declaration;
    let summary = elaboration::verification::memory::infer_in_package(
        &package,
        declaration,
        &[],
        &mut 100_000,
    )
    .unwrap();
    let writes = summary
        .accesses
        .iter()
        .filter(|a| a.write)
        .collect::<Vec<_>>();
    assert_eq!(writes.len(), 1);
    assert_eq!(writes[0].ty, nir::Term::Primitive(nir::Primitive::Bool));
    assert_eq!(writes[0].target.parameter, 1);
    assert_eq!(writes[0].target.fields[0].1, 0);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    let mut unproved = package.clone();
    unproved
        .functions
        .iter_mut()
        .find(|f| f.declaration == declaration)
        .unwrap()
        .requirements
        .clear();
    assert!(
        elaboration::verification::memory::infer_in_package(
            &unproved,
            declaration,
            &[],
            &mut 100_000
        )
        .is_err()
    );
    assert!(
        elaboration::verification::memory::infer_in_package(&package, declaration, &[], &mut 0)
            .is_err()
    );
    assert!(
        elaboration::verification::memory::infer_in_package(
            &package,
            declaration,
            &[],
            &mut 100_000
        )
        .is_ok()
    );
}

