#[test]
fn explicit_machine_division_and_remainder_preserve_width_failures_and_recovery() {
    use nir::program::{ExprKind as K, IntegerOp};
    for (name, signed, width) in [
        ("u8", false, 8),
        ("u16", false, 16),
        ("u32", false, 32),
        ("u64", false, 64),
        ("u128", false, 128),
        ("i8", true, 8),
        ("i16", true, 16),
        ("i32", true, 32),
        ("i64", true, 64),
        ("i128", true, 128),
    ] {
        for op in [IntegerOp::DivideTrunc, IntegerOp::RemainderTrunc] {
            let mut package = compile(&format!(
                "typealias Int=.{name}'builtin;comptime fn calculate(a:Int,b:Int)->Int {{a}}"
            ));
            let function = &mut package.functions[0];
            let left = function.body.clone();
            let right = nir::program::Expr {
                kind: K::Local(function.parameters[1]),
                ..left.clone()
            };
            function.body.kind = K::IntegerBinary {
                op,
                left: Box::new(left),
                right: Box::new(right),
            };
            let declaration = id(&package, "calculate");
            let mut vm = Interpreter::for_comptime(&package, Budget::default()).unwrap();
            if signed {
                for (a, b) in [(-7, 3), (7, -3), (-7, -3), (7, 3)] {
                    let expected = if op == IntegerOp::DivideTrunc {
                        a / b
                    } else {
                        a % b
                    };
                    assert_eq!(
                        vm.invoke(
                            declaration,
                            vec![Value::SignedInteger(a), Value::SignedInteger(b)]
                        )
                        .unwrap(),
                        Value::SignedInteger(expected)
                    );
                }
                let min = if width == 128 {
                    i128::MIN
                } else {
                    -(1i128 << (width - 1))
                };
                assert_eq!(
                    vm.invoke(
                        declaration,
                        vec![Value::SignedInteger(min), Value::SignedInteger(-1)]
                    )
                    .unwrap_err()
                    .kind,
                    ErrorKind::MachineOverflow
                );
                assert_eq!(
                    vm.invoke(
                        declaration,
                        vec![Value::SignedInteger(7), Value::SignedInteger(0)]
                    )
                    .unwrap_err()
                    .kind,
                    ErrorKind::DivisionByZero
                );
                assert_eq!(
                    vm.invoke(
                        declaration,
                        vec![Value::SignedInteger(6), Value::SignedInteger(3)]
                    )
                    .unwrap(),
                    Value::SignedInteger(if op == IntegerOp::DivideTrunc { 2 } else { 0 })
                );
            } else {
                let max = if width == 128 {
                    u128::MAX
                } else {
                    (1u128 << width) - 1
                };
                assert_eq!(
                    vm.invoke(
                        declaration,
                        vec![Value::UnsignedInteger(7), Value::UnsignedInteger(0)]
                    )
                    .unwrap_err()
                    .kind,
                    ErrorKind::DivisionByZero
                );
                assert_eq!(
                    vm.invoke(
                        declaration,
                        vec![Value::UnsignedInteger(max), Value::UnsignedInteger(3)]
                    )
                    .unwrap(),
                    Value::UnsignedInteger(if op == IntegerOp::DivideTrunc {
                        max / 3
                    } else {
                        max % 3
                    })
                );
            }
        }
    }
}

#[test]
fn explicit_machine_division_requires_nonzero_and_quotient_range_proofs() {
    use elaboration::verification::{Limits, flow};
    use nir::program::{ExprKind as K, IntegerOp};
    for op in [IntegerOp::DivideTrunc, IntegerOp::RemainderTrunc] {
        for (ty, contract, expected) in [
            ("u8", "where requires b > 0", None),
            ("u128", "where requires b != 0", None),
            ("i8", "where requires b > 0", None),
            ("i128", "where requires b < -1", None),
            ("i8", "", Some("divisor is not proven nonzero")),
            ("u8", "", Some("divisor is not proven nonzero")),
            (
                "i8",
                "where requires b < 0",
                Some("machine arithmetic range is not proven"),
            ),
        ] {
            let mut package = compile(&format!(
                "typealias Int=.{ty}'builtin;fn calculate(a:Int,b:Int)->Int {contract} {{a}}"
            ));
            let function = &mut package.functions[0];
            let left = function.body.clone();
            let right = nir::program::Expr {
                kind: K::Local(function.parameters[1]),
                ..left.clone()
            };
            function.body.kind = K::IntegerBinary {
                op,
                left: Box::new(left),
                right: Box::new(right),
            };
            let result =
                flow::analyze_in_package(&package, &package.functions[0], &mut Limits::default());
            if let Some(message) = expected {
                assert!(
                    result
                        .err()
                        .expect("expected rejection")
                        .to_string()
                        .contains(message),
                    "{ty} {contract} {op}"
                );
            } else {
                assert!(result.is_ok(), "{ty} {contract} {op}: {:?}", result.err());
            }
        }
    }
}

#[test]
fn verified_explicit_machine_division_survives_instance_materialization() {
    use nir::program::{ExprKind as K, IntegerOp};
    for op in [IntegerOp::DivideTrunc, IntegerOp::RemainderTrunc] {
        let mut package = compile(
            "typealias Int=.i8'builtin;
            fn calculate(a:Int,b:Int)->Int where requires b > 0 {a}
            fn run()->Int {calculate(-7,3)}",
        );
        let function = package
            .functions
            .iter_mut()
            .find(|f| f.name == "calculate")
            .unwrap();
        let left = function.body.clone();
        let right = nir::program::Expr {
            kind: K::Local(function.parameters[1]),
            ..left.clone()
        };
        function.body.kind = K::IntegerBinary {
            op,
            left: Box::new(left),
            right: Box::new(right),
        };
        assert_eq!(
            luna::execution::interpret(&package, "run", 100_000).unwrap(),
            Value::SignedInteger(if op == IntegerOp::DivideTrunc { -2 } else { -1 })
        );
    }
}

#[test]
fn unsigned_source_division_preserves_width_contracts_and_staged_defaults() {
    for ty in ["u8", "u16", "u32", "u64", "u128"] {
        let package=execution_support::compile_with_tuple(&format!("typealias Int=.{ty}'builtin;
            fn quotient(a:Int,b:Int)->result:Int where requires b != 0, ensures result <= a {{a / b}}
            fn checked(a:Int,b:Int)->Int {{assumes b != 0;quotient(a,b)}}
            fn configured(comptime a:Int,comptime .value:Int=a / 3)->Int {{value}}
            fn forward(comptime a:Int)->Int {{configured(a)}}
            fn run()->Tuple<Int, Int, Int> {{(checked(20,3),forward(20),configured(20,.value=9))}}"));
        assert_eq!(
            luna::execution::interpret(&package, "run", 100_000).unwrap(),
            Value::Tuple(vec![
                Value::UnsignedInteger(6),
                Value::UnsignedInteger(6),
                Value::UnsignedInteger(9)
            ])
        );
        let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke(
                id(&package, "checked"),
                vec![Value::UnsignedInteger(20), Value::UnsignedInteger(0)]
            )
            .unwrap_err()
            .kind,
            ErrorKind::ProgramContractRejected
        );
        assert_eq!(
            vm.invoke(
                id(&package, "checked"),
                vec![Value::UnsignedInteger(20), Value::UnsignedInteger(3)]
            )
            .unwrap(),
            Value::UnsignedInteger(6)
        );
    }
}

