#[test]
fn variadic_normal_heads_collect_type_lists_without_replacing_the_head() {
    use nir::Term;
    let prefix = "typealias Type = .Type'builtin; pure comptime fn List<T> -> Type { T }";
    let baseline = compile(prefix);
    let list = baseline.normal_forms[0].declaration;
    let protocols = elaboration::program::Protocols {
        meta_list: Some(list),
        ..Default::default()
    };
    let source = format!(
        "{prefix}
        pure comptime fn Tuple<...Es: List<Type>> -> Type {{ bool }}
        typealias Pair = Tuple<bool, .u8'builtin>;
        fn keep(value: Pair) -> Pair {{ value }}
        comptime fn BuildTuple() -> Type {{ Tuple<bool, .u8'builtin> }}
        comptime fn BuildEmpty() -> Type {{ Tuple<> }}"
    );
    let package = compile_with_protocols(&source, &protocols).unwrap();
    let tuple = package
        .normal_forms
        .iter()
        .find(|h| h.declaration != list)
        .unwrap();
    assert_eq!(tuple.parameters[0].kind, nir::normal_forms::Kind::Value);
    assert!(package.to_string().contains("(contextual-list-input"));
    let expected = |elements| {
        Value::Type(Term::NormalForm {
            head: tuple.declaration,
            sort: nir::Sort::Type,
            arguments: vec![Term::TypeListValue(elements)],
        })
    };
    let mut vm = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    for (name, elements) in [
        (
            "BuildTuple",
            vec![
                Term::Primitive(nir::Primitive::Bool),
                Term::Primitive(nir::Primitive::U8),
            ],
        ),
        ("BuildEmpty", vec![]),
    ] {
        let id = package
            .functions
            .iter()
            .find(|f| f.name == name)
            .unwrap()
            .declaration;
        assert_eq!(vm.invoke(id, vec![]).unwrap(), expected(elements.clone()));
        assert_eq!(
            luna::invocation::invoke(&package, name, 100_000).unwrap(),
            expected(elements)
        );
    }
    assert!(
        compile_with_protocols(&source, &Default::default())
            .unwrap_err()
            .contains("bound meta.List<T>")
    );
}

#[test]
fn variadic_normal_type_collection_evaluates_each_input_once_in_source_order() {
    use nir::{Primitive as P, Sort, Term};
    let prefix = "typealias Type = .Type'builtin; pure comptime fn List<T> -> Type { T }";
    let baseline = compile(prefix);
    let list = baseline.normal_forms[0].declaration;
    let protocols = elaboration::program::Protocols {
        meta_list: Some(list),
        ..Default::default()
    };
    let source = format!("{prefix}
        pure comptime fn Product<Tag, ...Es: List<Type>> -> Type {{ Tag }}
        comptime fn First() -> Type {{ bool }}
        comptime fn Second() -> Type {{ .u8'builtin }}
        comptime fn Build() -> Type {{ Product<Second(), First(), Second(), First()> }}
        comptime fn BuildExit() -> Type {{ Product<bool, First(), do {{ return bool; }}, Second()> }}
        typealias Empty = Product<bool>;
        typealias Open<T> = Product<T, T, bool>;
        fn keep(value: Open<T>) -> Open<T> where T {{ value }}");
    let package = compile_with_protocols(&source, &protocols).unwrap();
    let product = package
        .functions
        .iter()
        .find(|f| f.name == "Product")
        .unwrap()
        .declaration;
    let build = package
        .functions
        .iter()
        .find(|f| f.name == "Build")
        .unwrap()
        .declaration;
    let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        vm.invoke(build, vec![]).unwrap(),
        Value::Type(Term::NormalForm {
            head: product,
            sort: Sort::Type,
            arguments: vec![
                Term::Primitive(P::U8),
                Term::TypeListValue(vec![
                    Term::Primitive(P::Bool),
                    Term::Primitive(P::U8),
                    Term::Primitive(P::Bool)
                ])
            ],
        })
    );
    assert_eq!(
        calls(&package, &vm),
        vec!["Build", "Second", "First", "Second", "First"]
    );
    let mut early = Interpreter::new(&package, Budget::default()).unwrap();
    let exit = package
        .functions
        .iter()
        .find(|f| f.name == "BuildExit")
        .unwrap()
        .declaration;
    assert_eq!(
        early.invoke(exit, vec![]).unwrap(),
        Value::Type(Term::Primitive(P::Bool))
    );
    assert_eq!(calls(&package, &early), vec!["BuildExit", "First"]);
    for invalid in [
        source.replace("First(), Second(), First()", "true, Second(), First()"),
        source.replace(
            "Product<Tag, ...Es: List<Type>>",
            "Product<...Es: List<Type>, Tag>",
        ),
    ] {
        assert!(compile_with_protocols(&invalid, &protocols).is_err());
    }
    let foreign = elaboration::program::Protocols {
        meta_list: Some(nir::DeclarationId {
            package: list.package + 1,
            ..list
        }),
        ..Default::default()
    };
    assert!(
        compile_with_protocols(&source, &foreign)
            .unwrap_err()
            .contains("bound meta.List<T>")
    );
}

#[test]
fn variadic_normal_heads_forward_named_whole_type_lists_once() {
    use nir::{Primitive as P, Sort, Term};
    let prefix = "typealias Type = .Type'builtin; pure comptime fn List<T> -> Type { T }";
    let baseline = compile(prefix);
    let protocols = elaboration::program::Protocols {
        meta_list: Some(baseline.normal_forms[0].declaration),
        ..Default::default()
    };
    let source = format!("{prefix}
        pure comptime fn Tuple<...Es: List<Type>> -> Type {{ bool }}
        pure comptime fn ForwardHead<...Es: List<Type>> -> Type {{ Tuple<.Es = Es> }}
        pure comptime fn FunctionOf<...Es: List<Type>> -> Type {{ let callback: comptime fn(Tuple<.Es = Es>) -> Tuple<.Es = Es> = |value| value; callback'type }}
        comptime fn Pass(es: List<Type>) -> List<Type> {{ es }}
        comptime fn Forward(es: List<Type>) -> Type {{ Tuple<.Es = Pass(es)> }}
        pure comptime fn Product<Tag, ...Es: List<Type>> -> Type {{ Tag }}
        comptime fn ForwardTagged(es: List<Type>) -> Type {{ Product<bool, .Es = Pass(es)> }}");
    let package = compile_with_protocols(&source, &protocols).unwrap();
    let tuple = package
        .functions
        .iter()
        .find(|f| f.name == "Tuple")
        .unwrap()
        .declaration;
    let forward = package
        .functions
        .iter()
        .find(|f| f.name == "Forward")
        .unwrap()
        .declaration;
    for elements in [
        vec![],
        vec![Term::Primitive(P::U8), Term::Primitive(P::Bool)],
    ] {
        let mut vm = Interpreter::for_comptime(&package, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke(
                forward,
                vec![execution_support::type_list_value(
                    &package,
                    elements.clone()
                )]
            )
            .unwrap(),
            Value::Type(Term::NormalForm {
                head: tuple,
                sort: Sort::Type,
                arguments: vec![Term::TypeListValue(elements.clone())]
            })
        );
        assert_eq!(calls(&package, &vm), vec!["Forward", "Pass"]);
        let product = package
            .functions
            .iter()
            .find(|f| f.name == "Product")
            .unwrap()
            .declaration;
        let tagged = package
            .functions
            .iter()
            .find(|f| f.name == "ForwardTagged")
            .unwrap()
            .declaration;
        let mut vm = Interpreter::for_comptime(&package, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke(
                tagged,
                vec![execution_support::type_list_value(
                    &package,
                    elements.clone()
                )]
            )
            .unwrap(),
            Value::Type(Term::NormalForm {
                head: product,
                sort: Sort::Type,
                arguments: vec![Term::Primitive(P::Bool), Term::TypeListValue(elements)]
            })
        );
        assert_eq!(calls(&package, &vm), vec!["ForwardTagged", "Pass"]);
    }
    for (replacement, diagnostic) in [
        (".Es = Pass(es), bool", "combine a complete type-list"),
        ("bool, .Es = Pass(es)", "combine a complete type-list"),
        (".Es = Pass(es), .Es = Pass(es)", "duplicate type-list"),
        (".other = Pass(es)", "unknown named normal-form"),
    ] {
        let invalid = source.replace(".Es = Pass(es)", replacement);
        let error = compile_with_protocols(&invalid, &protocols).unwrap_err();
        assert!(error.contains(diagnostic), "{error}");
    }
    let invalid = source.replace(".Es = Pass(es)", ".Es = bool");
    assert!(compile_with_protocols(&invalid, &protocols).is_err());
}

#[test]
fn normal_type_list_named_supply_preserves_order_around_positional_anchors() {
    use nir::{Primitive as P, Sort, Term};
    let prefix = "typealias Type = .Type'builtin; pure comptime fn List<T> -> Type { T }";
    let baseline = compile(prefix);
    let protocols = elaboration::program::Protocols {
        meta_list: Some(baseline.normal_forms[0].declaration),
        ..Default::default()
    };
    for (arguments, expected_calls) in [
        (
            ".Es = Pass(es), First(), Second()",
            vec!["Build", "Pass", "First", "Second"],
        ),
        (
            "First(), .Es = Pass(es), Second()",
            vec!["Build", "First", "Pass", "Second"],
        ),
        (
            "First(), Second(), .Es = Pass(es)",
            vec!["Build", "First", "Second", "Pass"],
        ),
    ] {
        let source = format!("{prefix}
            pure comptime fn Product<A, B, ...Es: List<Type>> -> Type {{ A }}
            pure comptime fn FunctionOf<...Es: List<Type>> -> Type {{
                let callback: comptime fn(Product<.Es = Es, bool, .u8'builtin>) -> bool = |value| true;
                callback'type
            }}
            comptime fn First() -> Type {{ bool }}
            comptime fn Second() -> Type {{ .u8'builtin }}
            comptime fn Pass(es: List<Type>) -> List<Type> {{ es }}
            comptime fn Build(es: List<Type>) -> Type {{ Product<{arguments}> }}
            pure comptime fn Dependent<T, value: T, ...Es: List<Type>> -> Type {{ T }}
            comptime fn BuildDependent(es: List<Type>) -> Type {{ Dependent<.Es = Pass(es), First(), true> }}
            comptime fn BuildExit(es: List<Type>) -> Type {{ Product<.Es = do {{ Pass(es); return bool; }}, First(), Second()> }}");
        let package = compile_with_protocols(&source, &protocols).unwrap();
        let build = package
            .functions
            .iter()
            .find(|f| f.name == "Build")
            .unwrap()
            .declaration;
        let product = package
            .functions
            .iter()
            .find(|f| f.name == "Product")
            .unwrap()
            .declaration;
        let elements = vec![Term::Primitive(P::Char), Term::Primitive(P::Bool)];
        let mut vm = Interpreter::for_comptime(&package, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke(
                build,
                vec![execution_support::type_list_value(
                    &package,
                    elements.clone()
                )]
            )
            .unwrap(),
            Value::Type(Term::NormalForm {
                head: product,
                sort: Sort::Type,
                arguments: vec![
                    Term::Primitive(P::Bool),
                    Term::Primitive(P::U8),
                    Term::TypeListValue(elements)
                ]
            })
        );
        assert_eq!(calls(&package, &vm), expected_calls);
        let exit = package
            .functions
            .iter()
            .find(|f| f.name == "BuildExit")
            .unwrap()
            .declaration;
        let mut early = Interpreter::for_comptime(&package, Budget::default()).unwrap();
        assert_eq!(
            early
                .invoke(
                    exit,
                    vec![execution_support::type_list_value(&package, vec![])]
                )
                .unwrap(),
            Value::Type(Term::Primitive(P::Bool))
        );
        assert_eq!(calls(&package, &early), vec!["BuildExit", "Pass"]);
        let dependent = package
            .functions
            .iter()
            .find(|f| f.name == "Dependent")
            .unwrap()
            .declaration;
        let build_dependent = package
            .functions
            .iter()
            .find(|f| f.name == "BuildDependent")
            .unwrap()
            .declaration;
        let mut staged = Interpreter::for_comptime(&package, Budget::default()).unwrap();
        assert_eq!(
            staged
                .invoke(
                    build_dependent,
                    vec![execution_support::type_list_value(&package, vec![])]
                )
                .unwrap(),
            Value::Type(Term::NormalForm {
                head: dependent,
                sort: Sort::Type,
                arguments: vec![
                    Term::Primitive(P::Bool),
                    Term::Bool(true),
                    Term::TypeListValue(vec![])
                ]
            })
        );
        assert_eq!(
            calls(&package, &staged),
            vec!["BuildDependent", "Pass", "First"]
        );
        for (bad, diagnostic) in [
            (".Es = es, First()", "argument count mismatch"),
            (
                ".Es = es, First(), Second(), bool",
                "combine a complete type-list",
            ),
            (
                ".Es = es, First(), .Es = es, Second()",
                "duplicate type-list",
            ),
            (
                ".unknown = es, First(), Second()",
                "unknown named normal-form",
            ),
        ] {
            let invalid =
                source.replace(&format!("Product<{arguments}>"), &format!("Product<{bad}>"));
            let error = compile_with_protocols(&invalid, &protocols).unwrap_err();
            assert!(error.contains(diagnostic), "{error}");
        }
    }
}

#[test]
fn normal_type_list_spreads_preserve_elements_order_and_single_evaluation() {
    use nir::{Primitive as P, Sort, Term};
    let prefix = "typealias Type = .Type'builtin; pure comptime fn List<T> -> Type { T }";
    let baseline = compile(prefix);
    let protocols = elaboration::program::Protocols {
        meta_list: Some(baseline.normal_forms[0].declaration),
        ..Default::default()
    };
    let source = format!("{prefix}
        pure comptime fn Tuple<...Es: List<Type>> -> Type {{ bool }}
        pure comptime fn FunctionOf<...Es: List<Type>> -> Type {{
            let callback: comptime fn(Tuple<...Es>) -> bool = |value| true; callback'type
        }}
        comptime fn Pass(es: List<Type>) -> List<Type> {{ es }}
        comptime fn Build(es: List<Type>) -> Type {{ Tuple<bool, ...Pass(es), .u8'builtin, ...Pass(es)> }}
        comptime fn Forward(es: List<Type>) -> Type {{ Tuple<...Pass(es)> }}
        comptime fn BuildExit(es: List<Type>) -> Type {{ Tuple<bool, ...do {{ Pass(es); return bool; }}, ...Pass(es)> }}");
    let package = compile_with_protocols(&source, &protocols).unwrap();
    let tuple = package
        .functions
        .iter()
        .find(|f| f.name == "Tuple")
        .unwrap()
        .declaration;
    assert!(package.to_string().contains("(contextual-list-spread"));
    for elements in [
        vec![],
        vec![Term::Primitive(P::Char), Term::Primitive(P::Bool)],
    ] {
        let mut collected = vec![Term::Primitive(P::Bool)];
        collected.extend(elements.clone());
        collected.push(Term::Primitive(P::U8));
        collected.extend(elements.clone());
        for (name, expected, events) in [
            (
                "Build",
                Value::Type(Term::NormalForm {
                    head: tuple,
                    sort: Sort::Type,
                    arguments: vec![Term::TypeListValue(collected)],
                }),
                vec!["Build", "Pass", "Pass"],
            ),
            (
                "Forward",
                Value::Type(Term::NormalForm {
                    head: tuple,
                    sort: Sort::Type,
                    arguments: vec![Term::TypeListValue(elements.clone())],
                }),
                vec!["Forward", "Pass"],
            ),
            (
                "BuildExit",
                Value::Type(Term::Primitive(P::Bool)),
                vec!["BuildExit", "Pass"],
            ),
        ] {
            let entry = package
                .functions
                .iter()
                .find(|f| f.name == name)
                .unwrap()
                .declaration;
            let mut vm = Interpreter::for_comptime(&package, Budget::default()).unwrap();
            assert_eq!(
                vm.invoke(
                    entry,
                    vec![execution_support::type_list_value(
                        &package,
                        elements.clone()
                    )]
                )
                .unwrap(),
                expected
            );
            assert_eq!(calls(&package, &vm), events);
        }
    }
    let bad = source.replace("...Pass(es)", "...bool");
    assert!(compile_with_protocols(&bad, &protocols).is_err());
}

#[test]
fn bound_tuple_values_keep_normal_form_identity_through_nested_patterns() {
    use nir::{Primitive as P, Sort, Term};
    let prefix = "typealias Type = .Type'builtin; typealias Byte = .u8'builtin;
        pure comptime fn List<T> -> Type { T }
        pure comptime fn Tuple<...Es: List<Type>> -> Type { bool }";
    let list_source = prefix.split("pure comptime fn Tuple").next().unwrap();
    let baseline = compile(list_source);
    let mut protocols = elaboration::program::Protocols {
        meta_list: Some(baseline.normal_forms[0].declaration),
        ..Default::default()
    };
    let baseline = compile_with_protocols(prefix, &protocols).unwrap();
    let tuple = baseline
        .functions
        .iter()
        .find(|f| f.name == "Tuple")
        .unwrap()
        .declaration;
    protocols.tuple = Some(tuple);
    let source = format!("{prefix}
        fn pair() -> Tuple<bool, Byte> {{ (true, 9) }}
        fn nested() -> Tuple<Tuple<bool, Byte>, bool> {{ (pair(), true) }}
        comptime fn Choose() -> Type {{ Byte }}
        comptime fn StaticType() -> Type {{ Tuple<bool, Byte> }}
        comptime fn DynamicType() -> Type {{ Tuple<bool, Choose()> }}
        comptime fn KeepTuple(value: Tuple<bool, Byte>) -> Tuple<bool, Byte> {{ value }}
        comptime fn MetaType() -> Type {{ Type }}
        pure comptime fn Typed<T, value: T> -> Type {{ bool }}
        pure comptime fn Tagged<value: Tuple<bool, Byte>> -> Type {{ bool }}
        comptime fn TupleInput() -> Type {{ Tagged<(true, 9)> }}
        typealias StaticTagged = Tagged<(true, 9)>;
        comptime fn StaticTupleInput() -> Type {{ StaticTagged }}
        comptime fn PairType() -> Type {{ Tuple<bool, Byte> }}
        comptime fn DependentTupleInput() -> Type {{ Typed<PairType(), (true, 9)> }}
        comptime fn DependentType() -> Type {{ Typed<MetaType(), Tuple<bool, Choose()>> }}
        comptime fn SwapType(value: Type) -> Type {{ value match {{ (Left, Right) => Tuple<Right, Left>, _ => value }} }}
        comptime fn PatternCheck() -> bool {{
            SwapType(Tuple<Byte, bool>) == Tuple<bool, Byte>
            and SwapType(bool) == bool
            and SwapType(Tuple<bool, Byte, bool>) == Tuple<bool, Byte, bool>
        }}
        pure comptime fn Opaque<T> -> Type {{ Tuple<T, T> }}
        comptime fn Unresolved() -> Type {{ SwapType(Opaque<bool>) }}
        fn accept(flag: bool, byte: Byte) -> bool {{ flag and byte == 9 }}
        fn forward(packet: Tuple<bool, Byte>) -> bool {{ accept(...packet) }}
        fn collected(...packet: Tuple<bool, Byte>) -> bool {{ accept(...packet) }}
        fn collect(...packet: T) -> T where T {{ packet }}
        fn infer_tuple(value: Tuple<T, Byte>) -> T where T {{ let (first, second) = value; first }}
        fn generic_packet(value: T) -> Tuple<T, Byte> where T {{ (value, 9) }}
        fn inferred() -> bool {{
            let literal = infer_tuple((true, 9));
            let nested = infer_tuple(generic_packet(true));
            literal and nested
        }}
        fn abstract_pair(value: T) -> bool where T, requires T == Tuple<bool, Byte> {{
            let (flag, byte) = value; flag and byte == 9
        }}
        fn assemble() -> T where T, requires T == Tuple<bool, Byte> {{ collect<T>(true, 9) }}
        fn negated(value: T) -> bool where T, requires T == Tuple<bool, Byte> {{
            value match {{ not (false, 0) => true, _ => false }}
        }}
        fn negated_nested(value: Tuple<Tuple<bool, Byte>, bool>) -> bool {{
            value match {{ not ((false, 0), false) => true, _ => false }}
        }}
        fn defaulted(value: Tuple<T, Byte>, .flag: bool = do {{
            let (flag, byte) = value; flag and byte == 9
        }}) -> bool where T, requires T == bool {{ flag }}
        fn checked_pair(value: Tuple<bool, Byte>) -> Byte {{
            let (flag, byte) = value; assumes byte < 255; byte + 1
        }}
        fn checked_generic(value: T) -> Byte where T, requires T == Tuple<bool, Byte> {{
            let (flag, byte) = value; assumes byte < 255; byte + 1
        }}
        fn copy_bounds(value: Tuple<Byte, Byte>, choose: bool) -> Byte {{
            let (first, second) = value; assumes first <= 100 and second <= 100;
            let saved = if choose {{ value }} else {{ value }};
            let (left, right) = saved; left + right
        }}
        struct Ticket {{}}
        trait Duplicate {{}}
        trait Retire {{ fn drop(*self); }}
        impl Retire for T where T {{ fn drop(*self) {{}} }}
        trait Marked {{ fn marked(self) -> bool; }}
        impl Marked for Tuple<bool, Byte> {{ fn marked(self) -> bool {{ true }} }}
        fn marked_pair() -> bool {{ pair().as(Marked).marked() }}
        fn discard_pair(value: Tuple<Ticket, Ticket>) {{}}
        fn take_ticket(value: Ticket) {{}}
        fn own_pair(value: Tuple<Ticket, Ticket>) {{
            let (first, second) = value; take_ticket(first); take_ticket(second);
        }}
        fn own_pair_twice(value: Tuple<Ticket, Ticket>) {{
            let (first, second) = value; take_ticket(first); take_ticket(first); take_ticket(second);
        }}
        fn apply_packet(value: Tuple<fn(bool) -> bool, bool>) -> bool {{
            let (callback, input) = value; callback(input)
        }}
        effect inspect(value: Tuple<bool, Byte>) -> Byte;
        fn handled() -> Byte {{ inspect(pair())# {{
            inspect((flag, byte)) => {{ assumes byte < 255; byte + 1 }},
        }} }}
        fn run() -> bool {{ let ((flag, byte), other) = nested();
            flag and other and byte == 9 and forward(pair())
            and accept(...pair()) and accept(...(true, 9))
            and collected(true, 9) and forward(collect(true, 9))
            and abstract_pair(pair()) and forward(assemble<Tuple<bool, Byte>>())
            and negated(pair()) and negated_nested(nested())
            and inferred() and infer_tuple((true, 9)) and infer_tuple(pair()) and infer_tuple(generic_packet(true))
            and defaulted<bool>(pair()) and not defaulted<bool>(pair(), .flag=false) }}");
    let package = compile_with_protocols(&source, &protocols).unwrap();
    assert_eq!(
        package
            .normal_forms
            .iter()
            .find(|h| h.declaration == tuple)
            .unwrap()
            .role,
        nir::normal_forms::Role::Tuple
    );
    let pair = package.functions.iter().find(|f| f.name == "pair").unwrap();
    let expected = Term::NormalForm {
        head: tuple,
        sort: Sort::Type,
        arguments: vec![Term::TypeListValue(vec![
            Term::Primitive(P::Bool),
            Term::Primitive(P::U8),
        ])],
    };
    let mut saw_value = false;
    nir::visit::expression(&pair.body, &mut 10_000, |expr, _| {
        if matches!(expr.kind, nir::program::ExprKind::Tuple(_)) {
            saw_value = true;
            assert_eq!(expr.ty, expected);
        }
        Ok(())
    })
    .unwrap();
    assert!(saw_value);
    let defaulted = package
        .functions
        .iter()
        .find(|f| f.name == "defaulted")
        .unwrap();
    let mut retained_generic_tuple = false;
    for (_, value) in &defaulted.defaults {
        nir::visit::expression(value, &mut 10_000, |expr, _| {
            if let Term::NormalForm {
                head, arguments, ..
            } = &expr.ty
            {
                if *head == tuple {
                    if let [Term::TypeListValue(elements)] = arguments.as_slice() {
                        retained_generic_tuple |= elements
                            .iter()
                            .any(|field| matches!(field, Term::Rigid { .. }));
                    }
                }
            }
            Ok(())
        })
        .unwrap();
    }
    assert!(
        retained_generic_tuple,
        "default observation must preserve the stored Tuple identity and generic fields"
    );
    for (name, accepted) in [("own_pair", true), ("own_pair_twice", false)] {
        let function = package.functions.iter().find(|f| f.name == name).unwrap();
        let report = elaboration::verification::moves::analyze_in_package(
            &package,
            function,
            |ty| {
                Ok(if matches!(ty, Term::Primitive(_)) {
                    elaboration::verification::moves::Delivery::Copy
                } else {
                    elaboration::verification::moves::Delivery::Move
                })
            },
            100_000,
        );
        assert_eq!(report.is_ok(), accepted, "{name}: {report:?}");
        if let Err(error) = report {
            assert!(error.reason.contains("unavailable"), "{error}");
        }
    }
    let callback = package
        .functions
        .iter()
        .find(|f| f.name == "apply_packet")
        .unwrap();
    assert_eq!(
        elaboration::verification::moves::callable_parameter_paths(
            &package,
            &callback.signature,
            &mut 10_000,
            callback.body.source
        )
        .unwrap(),
        vec![(0, vec![0])]
    );
    let cleanup = luna::resources::analyze_with_protocols(
        &package,
        "discard_pair",
        "Duplicate",
        Some("Retire"),
        100_000,
    )
    .unwrap();
    assert_eq!(
        cleanup.report.to_string().matches("(invoke-drop ").count(),
        3,
        "the selected generic Drop applies to the tuple and both owned fields"
    );
    for name in ["checked_pair", "checked_generic", "copy_bounds", "handled"] {
        let checked = package.functions.iter().find(|f| f.name == name).unwrap();
        let report = elaboration::verification::flow::analyze_in_package(
            &package,
            checked,
            &mut elaboration::verification::Limits::default(),
        )
        .unwrap();
        assert!(!report.points.is_empty(), "{name}");
    }
    let invalid_join = source.replace(
        "let saved = if choose { value } else { value };",
        "let saved = if choose { value } else { (255, 255) };",
    );
    assert_ne!(invalid_join, source);
    let invalid_join = compile_with_protocols(&invalid_join, &protocols).unwrap_err();
    assert!(
        invalid_join.contains("machine arithmetic range is not proven"),
        "{invalid_join}"
    );
    assert_eq!(
        luna::execution::interpret(&package, "handled", 100_000).unwrap(),
        Value::UnsignedInteger(10)
    );
    assert_eq!(
        luna::execution::interpret(&package, "marked_pair", 100_000).unwrap(),
        Value::Bool(true)
    );
    for name in ["StaticType", "DynamicType"] {
        assert_eq!(
            luna::invocation::invoke(&package, name, 100_000).unwrap(),
            Value::Type(expected.clone())
        );
    }
    assert_eq!(
        luna::invocation::invoke(&package, "PatternCheck", 100_000).unwrap(),
        Value::Bool(true)
    );
    let typed = package
        .functions
        .iter()
        .find(|f| f.name == "Typed")
        .unwrap()
        .declaration;
    let tagged = package
        .functions
        .iter()
        .find(|f| f.name == "Tagged")
        .unwrap()
        .declaration;
    let payload = Term::TupleValue(vec![
        Term::Bool(true),
        Term::Integer(comptime_runtime::Integer::from_u128(9)),
    ]);
    assert_eq!(
        luna::invocation::invoke(&package, "TupleInput", 100_000).unwrap(),
        Value::Type(Term::NormalForm {
            head: tagged,
            sort: Sort::Type,
            arguments: vec![payload.clone()]
        })
    );
    assert_eq!(
        luna::invocation::invoke(&package, "StaticTupleInput", 100_000).unwrap(),
        Value::Type(Term::NormalForm {
            head: tagged,
            sort: Sort::Type,
            arguments: vec![payload.clone()]
        })
    );
    assert_eq!(
        luna::invocation::invoke(&package, "DependentTupleInput", 100_000).unwrap(),
        Value::Type(Term::NormalForm {
            head: typed,
            sort: Sort::Type,
            arguments: vec![expected.clone(), payload]
        })
    );
    assert_eq!(
        luna::invocation::invoke(&package, "DependentType", 100_000).unwrap(),
        Value::Type(Term::NormalForm {
            head: typed,
            sort: Sort::Type,
            arguments: vec![Term::Primitive(P::Type), expected.clone()]
        })
    );
    assert!(
        luna::invocation::invoke(&package, "Unresolved", 100_000)
            .unwrap_err()
            .contains("TypeContractUnresolved")
    );
    let run = package
        .functions
        .iter()
        .find(|f| f.name == "run")
        .unwrap()
        .declaration;
    let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(vm.invoke(run, vec![]).unwrap(), Value::Bool(true));
    let checked = package
        .functions
        .iter()
        .find(|f| f.name == "checked_pair")
        .unwrap()
        .declaration;
    let copy_bounds = package
        .functions
        .iter()
        .find(|f| f.name == "copy_bounds")
        .unwrap()
        .declaration;
    for branch in [false, true] {
        assert_eq!(
            vm.invoke(
                copy_bounds,
                vec![
                    Value::Tuple(vec![
                        Value::UnsignedInteger(100),
                        Value::UnsignedInteger(100)
                    ]),
                    Value::Bool(branch)
                ]
            )
            .unwrap(),
            Value::UnsignedInteger(200)
        );
    }
    assert_eq!(
        vm.invoke(
            checked,
            vec![Value::Tuple(vec![
                Value::Bool(true),
                Value::UnsignedInteger(254)
            ])]
        )
        .unwrap(),
        Value::UnsignedInteger(255)
    );
    assert_eq!(
        vm.invoke(
            checked,
            vec![Value::Tuple(vec![
                Value::Bool(true),
                Value::UnsignedInteger(255)
            ])]
        )
        .unwrap_err()
        .kind,
        ErrorKind::ProgramContractRejected
    );
    let keep = package
        .functions
        .iter()
        .find(|f| f.name == "KeepTuple")
        .unwrap()
        .declaration;
    let frozen = Term::TupleValue(vec![
        Term::Bool(true),
        Term::Integer(comptime_runtime::Integer::from_u128(9)),
    ]);
    assert_eq!(
        vm.invoke_with_normal_arguments(keep, vec![(expected.clone(), frozen.clone())])
            .unwrap(),
        Value::Tuple(vec![Value::Bool(true), Value::UnsignedInteger(9)])
    );
    for invalid in [
        Term::TupleValue(vec![]),
        Term::TupleValue(vec![Term::Bool(true), Term::Bool(false)]),
        Term::TupleValue(vec![
            Term::Bool(true),
            Term::Integer(comptime_runtime::Integer::from_u128(256)),
        ]),
    ] {
        assert!(
            vm.invoke_with_normal_arguments(keep, vec![(expected.clone(), invalid)])
                .is_err()
        );
        assert!(
            vm.invoke_with_normal_arguments(keep, vec![(expected.clone(), frozen.clone())])
                .is_ok()
        );
    }
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    // The Tuple body deliberately returns bool. Its body does not establish
    // an equality between bool and the retained Tuple application.
    let invalid = source.replace(
        "fn pair() -> Tuple<bool, Byte> { (true, 9) }",
        "fn pair() -> Tuple<bool, Byte> { true }",
    );
    assert!(compile_with_protocols(&invalid, &protocols).is_err());
    let invalid = source.replace(
        "fn pair() -> Tuple<bool, Byte> { (true, 9) }",
        "fn pair() -> Tuple<bool, Byte> { (true, false) }",
    );
    assert!(compile_with_protocols(&invalid, &protocols).is_err());
    let invalid = format!(
        "{source}
        fn reject(value: Tuple<*bool, bool>) -> bool {{
            value match {{ not (_, false) => true, _ => false }}
        }}"
    );
    let error = compile_with_protocols(&invalid, &protocols).unwrap_err();
    assert!(
        error.contains("negated pattern elaboration for this domain"),
        "{error}"
    );
}

#[test]
fn bound_tuple_spread_widths_deliver_context_to_multiple_generic_producers() {
    let source = "typealias Type=.Type'builtin; typealias Byte=.u8'builtin;
        pure comptime fn List<T> -> Type {T}
        pure comptime fn Tuple<...Es:List<Type>> -> Type {bool}
        fn packet(callback:F, number:N) -> Tuple<F,N> where F,N {(callback,number)}
        fn triple(callback:F, number:N) -> Tuple<F,N,bool> where F,N {(callback,number,true)}
        fn consume(left:fn(bool)->bool,a:Byte,right:fn(bool)->bool,b:Byte)->bool {
            left(false) and right(true) and a==9 and b==10
        }
        fn run()->bool {consume(...packet(|flag| not flag,9),...packet(|flag| flag,10))}
        fn branch(flag:bool)->bool {consume(
            ...if flag {packet(|value| not value,9)} else {packet(|value| not value,9)},
            ...packet(|value| value,10))}
        fn stop()->bool {consume(...packet(|flag| not flag,do {return true;9}),...packet(|flag| flag,10))}";
    let selectors = luna::protocols::type_constructors::Selectors {
        meta_list: Some("input.List"),
        tuple: Some("input.Tuple"),
        ..Default::default()
    };
    let package = compile_with_source_bindings(source, &Default::default(), selectors).unwrap();
    let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        vm.invoke(id(&package, "run"), vec![]).unwrap(),
        Value::Bool(true)
    );
    assert_eq!(
        calls(&package, &vm),
        vec!["run", "packet", "packet", "consume"]
    );
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    for flag in [false, true] {
        let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke(id(&package, "branch"), vec![Value::Bool(flag)])
                .unwrap(),
            Value::Bool(true)
        );
        assert_eq!(
            calls(&package, &vm),
            vec!["branch", "packet", "packet", "consume"]
        );
    }
    let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        vm.invoke(id(&package, "stop"), vec![]).unwrap(),
        Value::Bool(true)
    );
    assert_eq!(calls(&package, &vm), vec!["stop"]);
    let wrong = source.replace("...packet(|flag| flag,10)", "...packet(|flag| flag,256)");
    assert!(compile_with_source_bindings(&wrong, &Default::default(), selectors).is_err());
    let wrong = source.replace(
        "...packet(|flag| not flag,9)",
        "...triple(|flag| not flag,9)",
    );
    let error = compile_with_source_bindings(&wrong, &Default::default(), selectors).unwrap_err();
    assert!(error.contains("argument count mismatch"), "{error}");
}

#[test]
fn bound_tuple_memory_layout_preserves_callable_and_pointer_fields() {
    use elaboration::verification::memory;
    let source = "typealias Type=.Type'builtin;
        pure comptime fn List<T> -> Type {T}
        pure comptime fn Tuple<...Es:List<Type>> -> Type {bool}
        fn identity(value:bool)->bool {value}
        fn packet()->Tuple<fn(bool)->bool,bool> {(identity,true)}
        fn run()->bool {let (callback,value)=packet();callback(value)}
        fn pointer_packet(value:*bool)->Tuple<*bool,bool> {(value,true)}";
    let selectors = luna::protocols::type_constructors::Selectors {
        meta_list: Some("input.List"),
        tuple: Some("input.Tuple"),
        ..Default::default()
    };
    let package = compile_with_source_bindings(source, &Default::default(), selectors).unwrap();
    let packet =
        memory::infer_in_package(&package, id(&package, "packet"), &[], &mut 100_000).unwrap();
    assert_eq!(packet.callable_fields.len(), 1);
    assert!(packet.callable_fields.contains_key(&vec![0]));
    let run = memory::infer_in_package(&package, id(&package, "run"), &[], &mut 100_000).unwrap();
    assert!(run.accesses.is_empty());
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    let pointers =
        memory::infer_in_package(&package, id(&package, "pointer_packet"), &[], &mut 100_000)
            .unwrap();
    let targets = pointers
        .pointer_fields
        .get(&vec![0])
        .unwrap()
        .as_ref()
        .unwrap();
    assert_eq!(targets.len(), 1);
    let target = targets.first().unwrap();
    assert_eq!(target.parameter, 0);
    assert!(
        target.input_fields.is_empty() && target.through.is_empty() && target.fields.is_empty()
    );
    assert_eq!(
        pointers.signature.callable_signature(),
        package
            .functions
            .iter()
            .find(|f| f.name == "pointer_packet")
            .unwrap()
            .signature
            .callable_signature()
    );
    assert!(memory::infer_in_package(&package, id(&package, "packet"), &[], &mut 0).is_err());
    assert_eq!(
        packet,
        memory::infer_in_package(&package, id(&package, "packet"), &[], &mut 100_000).unwrap()
    );
    let mut opaque = package.clone();
    for head in &mut opaque.normal_forms {
        head.role = nir::normal_forms::Role::Opaque;
    }
    assert!(memory::infer_in_package(&opaque, id(&opaque, "packet"), &[], &mut 100_000).is_err());
}

#[test]
fn bound_tuple_stores_effectful_code_without_storing_a_computation() {
    let source = "typealias Type=.Type'builtin;
        pure comptime fn List<T> -> Type {T}
        pure comptime fn Tuple<...Es:List<Type>> -> Type {bool}
        ^attrs.effects.direct_passing effect tick()->bool;
        fn callback()->#tick bool {tick()#}
        fn packet()->Tuple<fn()->#tick bool,bool> {(callback,true)}
        fn subject()->#tick bool {let (code,flag)=packet();code() and flag}
        fn mark(seen:*bool)->bool {let prior=seen.*;assumes not prior;seen.* = true;true}
        fn run()->Tuple<bool,bool> {
            var seen=false;
            let result=subject()# {tick()=>mark(seen.ref),};
            (result,seen)
        }";
    let package = compile_with_source_bindings(
        source,
        &Default::default(),
        luna::protocols::type_constructors::Selectors {
            meta_list: Some("input.List"),
            tuple: Some("input.Tuple"),
            ..Default::default()
        },
    )
    .unwrap();
    let expected = Value::Tuple(vec![Value::Bool(true), Value::Bool(true)]);
    let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(vm.invoke(id(&package, "run"), vec![]).unwrap(), expected);
    assert_eq!(
        calls(&package, &vm)
            .iter()
            .filter(|name| name.as_str() == "mark")
            .count(),
        1
    );
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        expected
    );
}

#[test]
fn bound_tuple_staging_retains_identity_through_defaults_and_nested_forwarding() {
    let source = "typealias Type=.Type'builtin; typealias Byte=.u8'builtin;
        pure comptime fn List<T> -> Type {T}
        pure comptime fn Tuple<...Es:List<Type>> -> Type {bool}
        typealias Pair=Tuple<bool,Byte>;
        fn pair(comptime value:Pair)->Pair {value}
        fn defaulted(comptime value:Pair,comptime .other:Pair=value)->Pair {pair(other)}
        fn forward(comptime value:Pair)->Pair {
            let packet=value;
            let call=||defaulted(packet);
            call()
        }
        fn nested(comptime value:Tuple<Pair,bool>)->Tuple<Pair,bool> {value}
        comptime fn packet(flag:bool)->Pair {(flag,7)}
        fn generated(comptime flag:bool)->Pair {pair(packet(flag))}
        comptime fn nested_packet(flag:bool)->Tuple<Pair,bool> {((flag,11),false)}
        fn generated_nested(comptime flag:bool)->Tuple<Pair,bool> {nested(nested_packet(flag))}
        fn run()->Tuple<Pair,Pair,Tuple<Pair,bool>,Pair,Tuple<Pair,bool>> {
            (pair((true,7)),forward((false,9)),nested(((true,11),false)),generated(true),generated_nested(true))
        }";
    let package = compile_with_source_bindings(
        source,
        &Default::default(),
        luna::protocols::type_constructors::Selectors {
            meta_list: Some("input.List"),
            tuple: Some("input.Tuple"),
            ..Default::default()
        },
    )
    .unwrap();
    let pair = |flag, n| Value::Tuple(vec![Value::Bool(flag), Value::UnsignedInteger(n)]);
    let nested = Value::Tuple(vec![pair(true, 11), Value::Bool(false)]);
    let expected = Value::Tuple(vec![
        pair(true, 7),
        pair(false, 9),
        nested.clone(),
        pair(true, 7),
        nested,
    ]);
    let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(vm.invoke(id(&package, "run"), vec![]).unwrap(), expected);
    let graph = luna::instantiation::instantiate(&package, "run", 100_000).unwrap();
    let instances = graph
        .functions
        .iter()
        .filter(|instance| instance.function.name == "pair")
        .collect::<Vec<_>>();
    assert_eq!(instances.len(), 2);
    for instance in instances {
        assert!(
            matches!(instance.key.arguments.as_slice(),[nir::Term::TupleValue(fields)] if fields.len()==2)
        );
        let nir::Term::Function { result, .. } = &instance.function.signature else {
            panic!("callable instance")
        };
        assert!(
            matches!(result.as_ref(),nir::Term::NormalForm {head,..} if *head==id(&package,"Tuple"))
        );
    }
    let defaulted = graph
        .functions
        .iter()
        .find(|instance| instance.function.name == "defaulted")
        .unwrap();
    assert_eq!(defaulted.key.arguments.len(), 2);
    assert_eq!(defaulted.key.arguments[0], defaulted.key.arguments[1]);
    assert_eq!(
        graph
            .functions
            .iter()
            .filter(|instance| instance.function.name == "nested")
            .count(),
        1
    );
    let mut prepared = Interpreter::from_iir(&graph, Budget::default()).unwrap();
    assert_eq!(
        prepared.invoke_instance(&graph.roots[0], vec![]).unwrap(),
        expected
    );
}

#[test]
fn type_list_constants_reconstruct_and_specialize_without_tuple_coercion() {
    let source="typealias Type=.Type'builtin;typealias Byte=.u8'builtin;
        pure comptime fn List<T>->Type {T}
        pure comptime fn Tuple<...Es:List<Type>>->Type {bool}
        comptime fn elements(T:Type)->List<Type> {
            T match {Tuple<Es> => Es,_ => elements(T)}
        }
        comptime fn pass(values:List<Type>)->List<Type> {values}
        fn accept(comptime values:List<Type>)->bool {true}
        fn forward(comptime values:List<Type>,comptime .other:List<Type> = pass(values))->bool {accept(other)}
        fn route(comptime T:Type)->bool {forward(elements(T))}
        typealias Combined=Tuple<Byte,...elements(Tuple<bool>),...elements(Tuple<>),Byte>;
        fn mixed()->Tuple<Byte,bool,Byte> {let value:Combined=(7,true,9);value}
        fn run()->bool {forward(elements(Tuple<bool,Byte>)) and route(Tuple<>)}";
    let package = compile_with_source_bindings(
        source,
        &Default::default(),
        luna::protocols::type_constructors::Selectors {
            meta_list: Some("input.List"),
            tuple: Some("input.Tuple"),
            ..Default::default()
        },
    )
    .unwrap();
    let graph = luna::instantiation::instantiate(&package, "run", 100_000).unwrap();
    let selected = graph
        .functions
        .iter()
        .filter(|instance| instance.function.name == "accept")
        .collect::<Vec<_>>();
    assert_eq!(selected.len(), 2);
    assert!(selected.iter().all(|instance| matches!(
        instance.key.arguments.as_slice(),
        [nir::Term::TypeListValue(_)]
    )));
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    assert_eq!(
        luna::execution::interpret(&package, "mixed", 100_000).unwrap(),
        Value::Tuple(vec![
            Value::UnsignedInteger(7),
            Value::Bool(true),
            Value::UnsignedInteger(9)
        ])
    );
    let mut vm = Interpreter::from_iir(&graph, Budget::default()).unwrap();
    assert_eq!(
        vm.invoke_instance(&graph.roots[0], vec![]).unwrap(),
        Value::Bool(true)
    );
}

#[test]
fn bound_tuple_copy_requires_declared_capability_and_checks_components() {
    let source="typealias Type=.Type'builtin;
        pure comptime fn List<T>->Type {T}
        pure comptime fn Tuple<...Es:List<Type>>->Type {bool}
        trait Duplicate {} trait Retire {fn drop(*self);}
        impl Duplicate for Tuple<bool,bool> {}
        fn read(value:Tuple<bool,bool>)->bool {let (a,b)=value;a and b}
        fn run()->bool {let original=(true,true);let copied=original;read(original) and read(copied)}";
    let selectors = luna::protocols::type_constructors::Selectors {
        meta_list: Some("input.List"),
        tuple: Some("input.Tuple"),
        ..Default::default()
    };
    let package = compile_with_source_bindings(source, &Default::default(), selectors).unwrap();
    assert_eq!(
        luna::execution::interpret_with_protocols(&package, "run", "Duplicate", "Retire", 100_000)
            .unwrap(),
        Value::Bool(true)
    );
    let unrelated =
        format!("{source} struct Other {{}} impl Retire for Other {{fn drop(*self) {{}}}}");
    let package = compile_with_source_bindings(&unrelated, &Default::default(), selectors).unwrap();
    assert_eq!(
        luna::execution::interpret_with_protocols(&package, "run", "Duplicate", "Retire", 100_000)
            .unwrap(),
        Value::Bool(true)
    );
    let missing = source.replace("impl Duplicate for Tuple<bool,bool> {}", "");
    let package = compile_with_source_bindings(&missing, &Default::default(), selectors).unwrap();
    assert!(
        luna::execution::interpret_with_protocols(&package, "run", "Duplicate", "Retire", 100_000)
            .is_err()
    );
    let custom = format!("{source} impl Retire for Tuple<bool,bool> {{fn drop(*self) {{}}}}");
    let package = compile_with_source_bindings(&custom, &Default::default(), selectors).unwrap();
    let error =
        luna::execution::interpret_with_protocols(&package, "run", "Duplicate", "Retire", 100_000)
            .unwrap_err();
    assert!(error.contains("Drop responsibility"), "{error}");
    let component = "typealias Type=.Type'builtin;
        pure comptime fn List<T>->Type {T}
        pure comptime fn Tuple<...Es:List<Type>>->Type {bool}
        trait Duplicate {} trait Retire {fn drop(*self);}
        struct Token {}
        impl Duplicate for Tuple<Token,bool> {}
        fn consume(value:Tuple<Token,bool>) {}
        fn run() {let original=(Token {},true);consume(original);consume(original);}";
    let package = compile_with_source_bindings(component, &Default::default(), selectors).unwrap();
    let error =
        luna::execution::interpret_with_protocols(&package, "run", "Duplicate", "Retire", 100_000)
            .unwrap_err();
    assert!(error.contains("no Copy capability"), "{error}");
}

