#[test]
fn scalar_comptime_inputs_specialize_normal_annotations_during_direct_invocation() {
    let package = compile(
        "typealias Type=.Type'builtin;typealias Integer=.Integer'builtin;
        pure comptime fn Shape<N:Integer,Flag:bool>->Type {bool}
        fn make(comptime n:Integer,comptime flag:bool)->fn(Shape<n,flag>)->bool {|value|true}
        fn accept(callback:fn(Shape<3,true>)->bool)->bool {true}
        fn run()->bool {let a=make(3,true);let b=make(7,false);accept(a)}",
    );
    let mut raw = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        raw.invoke(id(&package, "run"), vec![]).unwrap(),
        Value::Bool(true)
    );
    assert_eq!(
        raw.invoke(
            id(&package, "make"),
            vec![Value::Bool(true), Value::Bool(true)]
        )
        .unwrap_err()
        .kind,
        ErrorKind::Type
    );
    for (n, flag) in [(3, true), (7, false)] {
        let integer = comptime_runtime::Integer::from_u128(n);
        let callback = raw
            .invoke(
                id(&package, "make"),
                vec![Value::Integer(integer), Value::Bool(flag)],
            )
            .unwrap();
        let accepted = raw.invoke(id(&package, "accept"), vec![callback]);
        if flag {
            assert_eq!(accepted.unwrap(), Value::Bool(true));
        } else {
            assert_eq!(accepted.unwrap_err().kind, ErrorKind::Type);
        }
    }
    let graph = luna::instantiation::instantiate(&package, "run", 100_000).unwrap();
    let mut prepared = Interpreter::from_iir(&graph, Budget::default()).unwrap();
    assert_eq!(
        prepared.invoke_instance(&graph.roots[0], vec![]).unwrap(),
        Value::Bool(true)
    );
}

