#[test]
fn public_implementation_methods_are_retained_and_private_access_is_not_assumed() {
    let package = compile(
        "struct Flag {} impl Flag {pub fn read(self)->bool {true}} fn run()->bool {Flag {}.read()}",
    );
    assert!(
        package
            .functions
            .iter()
            .any(|function| function.name == "read")
    );
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    let failure=compile_with_bindings("struct Flag {} impl Flag {private fn hidden(self)->bool {true}} fn run()->bool {Flag {}.hidden()}",&Default::default(),None).unwrap_err();
    assert!(
        failure.contains("private trait/implementation member visibility"),
        "{failure}"
    );
}

