#[test]
fn partial_callable_results_constrain_nested_nominal_producers() {
    let source = "typealias Byte=.u8'builtin;
        enum Result where T,E {ok(T),err(E)}
        fn build(value:T,marker:E)->Result<T,E> where T,E {.ok(value)}
        fn consume(callback:fn(bool)->Result<T,Byte>)->Result<T,Byte> where T {callback(true)}
        fn forward(value:T)->T where T {value}
        fn run()->bool {
            let result=consume(|value| build(not value,9));
            result match {.ok(value)=>not value,.err(_)=>false}
        }";
    for replacement in [
        "|value| build(not value,9)",
        "|value| {build(not value,9)}",
        "forward(|value| build(not value,9))",
        "|value| if value {build(not value,9)} else {build(true,8)}",
    ] {
        let source = source.replace("|value| build(not value,9)", replacement);
        let package = compile(&source);
        let graph = luna::instantiation::instantiate(&package, "run", 100_000).unwrap();
        let build = graph
            .functions
            .iter()
            .find(|function| function.function.name == "build")
            .unwrap();
        assert_eq!(
            build.key.arguments,
            vec![
                nir::Term::Primitive(nir::Primitive::Bool),
                nir::Term::Primitive(nir::Primitive::U8)
            ]
        );
        let mut vm = Interpreter::from_iir(&graph, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke_instance(&graph.roots[0], vec![]).unwrap(),
            Value::Bool(true)
        );
    }
    assert!(
        compile_with_bindings(
            &source.replace("build(not value,9)", "build(not value,true)"),
            &Default::default(),
            None
        )
        .is_err()
    );
}

#[test]
fn partial_enum_payload_context_infers_types_and_checks_declaration_contracts() {
    let source="typealias Byte=.u8'builtin;
        enum Result where T,E {ok(T),err(E)}
        fn consume(callback:fn(bool)->Result<T,Byte>)->Result<T,Byte> where T {callback(true)}
        fn forward(value:T)->T where T {value}
        fn run()->bool {let result=consume(CALLBACK);result match {.ok(value)=>not value,.err(_)=>false}}";
    for callback in [
        "|value| .ok(not value)",
        "|value| {.ok(not value)}",
        "forward(|value| .ok(not value))",
        "|value| if value {.ok(not value)} else {.err(9)}",
    ] {
        let package = compile(&source.replace("CALLBACK", callback));
        assert_eq!(
            luna::execution::interpret(&package, "run", 100_000).unwrap(),
            Value::Bool(true)
        );
    }
    let repeated = "typealias Byte=.u8'builtin;
        enum Pair where T,E {pair(T,T,E)}
        fn accept(value:Pair<T,Byte>)->bool where T {true}
        fn run()->bool {accept(.pair(9,7,8))}";
    assert_eq!(
        luna::execution::interpret(&compile(repeated), "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    for invalid in [
        repeated.replace(".pair(9,7,8)", ".pair(true,7,8)"),
        repeated.replace(".pair(9,7,8)", ".pair(9,7,true)"),
        source.replace("CALLBACK", "|value| .missing(value)"),
        source.replace("CALLBACK", "|value| .err(9)"),
        source.replace("CALLBACK", "|value| .ok(value,value)"),
    ] {
        assert!(
            compile_with_bindings(&invalid, &Default::default(), None).is_err(),
            "{invalid}"
        );
    }
    let constrained = "typealias Byte=.u8'builtin;
        enum Checked where T,E, requires T == bool {value(T,E)}
        fn accept(value:Checked<T,Byte>)->bool where T, requires T == bool {true}
        fn run()->bool {accept(.value(true,9))}";
    assert_eq!(
        luna::execution::interpret(&compile(constrained), "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    assert!(
        compile_with_bindings(
            &constrained.replace(".value(true,9)", ".value(8,9)"),
            &Default::default(),
            None
        )
        .is_err()
    );
}

