#[test]
fn partial_enum_packet_widths_come_from_checked_generic_results() {
    let selectors = luna::protocols::type_constructors::Selectors {
        meta_list: Some("input.List"),
        tuple: Some("input.Tuple"),
        ..Default::default()
    };
    let prefix = "typealias Type=.Type'builtin;
        pure comptime fn List<T> -> Type {T}
        pure comptime fn Tuple<...Es:List<Type>> -> Type {bool}
        typealias Byte=.u8'builtin;
        enum Packet where T,E {data(T,T,E)}
        fn forward(value:T)->T where T {value}
        fn typed()->Tuple<Byte, Byte> {(6,7)}
        fn accept(value:Packet<T,Byte>)->bool where T {true}";
    for (expression, trace) in [
        (
            ".data(...forward((9,)),...forward(typed()))",
            vec!["run", "forward", "typed", "forward", "accept"],
        ),
        (
            ".data(...forward(typed()),...forward((9,)))",
            vec!["run", "typed", "forward", "forward", "accept"],
        ),
    ] {
        let source = format!("{prefix} fn run()->bool {{accept({expression})}}");
        let package =
            compile_with_source_bindings(&source, &Default::default(), selectors).unwrap();
        let graph = luna::instantiation::instantiate(&package, "run", 100_000).unwrap();
        let mut vm = Interpreter::from_iir(&graph, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke_instance(&graph.roots[0], vec![]).unwrap(),
            Value::Bool(true)
        );
        assert_eq!(calls(&package, &vm), trace);
        let instances = graph
            .functions
            .iter()
            .filter(|function| function.function.name == "forward")
            .collect::<Vec<_>>();
        assert_eq!(instances.len(), 2);
        for function in instances {
            let [nir::Term::NormalForm { arguments, .. }] = &function.key.arguments[..] else {
                panic!("Tuple identity")
            };
            let [nir::Term::TypeListValue(elements)] = &arguments[..] else {
                panic!("single list argument")
            };
            assert!(
                elements
                    .iter()
                    .all(|ty| *ty == nir::Term::Primitive(nir::Primitive::U8))
            );
        }
        assert!(
            compile_with_source_bindings(
                &source.replace("forward((9,))", "forward((9,8))"),
                &Default::default(),
                selectors
            )
            .is_err()
        );
        assert!(
            compile_with_source_bindings(
                &source.replace("forward((9,))", "forward(true)"),
                &Default::default(),
                selectors
            )
            .is_err()
        );
    }
}

#[test]
fn partial_callback_context_reaches_explicit_and_early_returns() {
    let source="typealias Byte=.u8'builtin;
        enum Result where T,E {ok(T),err(E)}
        fn consume(callback:fn(bool)->Result<T,Byte>,flag:bool)->Result<T,Byte> where T {callback(flag)}
        fn run()->bool {let result=consume(CALLBACK,FLAG);result match {.ok(value)=>not value,.err(marker)=>marker == 9}}";
    for callback in [
        "|value| {return .ok(not value);}",
        "|value| {if value {return .ok(false);} return .err(9);}",
        "|value| {let inner=|x:bool| {return not x;};return .ok(inner(value));}",
    ] {
        let package = compile(&source.replace("CALLBACK", callback).replace("FLAG", "true"));
        assert_eq!(
            luna::execution::interpret(&package, "run", 100_000).unwrap(),
            Value::Bool(true)
        );
    }
    let callback = "|value| {if value {return .ok(false);} return .err(9);}";
    let package = compile(
        &source
            .replace("CALLBACK", callback)
            .replace("FLAG", "false"),
    );
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    for invalid in [
        callback.replace(".err(9)", ".err(true)"),
        callback.replace(".err(9)", ".ok(9)"),
    ] {
        assert!(
            compile_with_bindings(
                &source.replace("CALLBACK", &invalid).replace("FLAG", "true"),
                &Default::default(),
                None
            )
            .is_err()
        );
    }
}

#[test]
fn checked_pointer_predicates_do_not_reuse_facts_after_writes() {
    use elaboration::verification::{self as v, optimization};
    for source in [
        "fn run()->bool {let flag=true;let pointer=flag.ref;assumes pointer.*;pointer.* = false;assumes pointer.*;true}",
        "struct Cell {flag:bool} fn run()->bool {let cell=Cell {flag:true};let pointer=cell.ref;assumes pointer.flag.*;pointer.flag.* = false;assumes pointer.flag.*;true}",
        "fn run()->bool {var flag=true;assumes flag.ref.*;flag=false;assumes flag.ref.*;true}",
    ] {
        let baseline = compile(source);
        let mut optimized = baseline.clone();
        let report = optimization::elide_proven_checks(&mut optimized, &mut v::Limits::default());
        for package in [&baseline, &optimized] {
            let mut vm = Interpreter::new(package, Budget::default()).unwrap();
            assert_eq!(
                vm.invoke(id(package, "run"), vec![]).unwrap_err().kind,
                ErrorKind::ProgramContractRejected,
                "{source}: {report}"
            );
        }
    }
}

#[test]
fn bound_tuple_dynamic_syntax_checks_independent_formation_requirements() {
    let selectors = luna::protocols::type_constructors::Selectors {
        meta_list: Some("input.List"),
        tuple: Some("input.Tuple"),
        ..Default::default()
    };
    for expression in ["Tuple<bool, Choose()>", "Tuple<bool, do {Choose()}>"] {
        let source = format!(
            "typealias Type=.Type'builtin;
            pure comptime fn List<T> -> Type {{T}}
            pure comptime fn Tuple<...Es:List<Type>> -> Type
                where requires bool == .u8'builtin {{bool}}
            comptime fn Choose() -> Type {{bool}}
            comptime fn Build() -> Type {{{expression}}}"
        );
        let error = compile_with_source_bindings(&source, &Default::default(), selectors)
            .expect_err(expression);
        assert!(error.contains("requirement"), "{expression}: {error}");
        let valid = source.replace("bool == .u8'builtin", "bool == bool");
        let package = compile_with_source_bindings(&valid, &Default::default(), selectors).unwrap();
        let mut vm = Interpreter::for_comptime(&package, Budget::default()).unwrap();
        let expected = Value::Type(nir::Term::NormalForm {
            head: id(&package, "Tuple"),
            sort: nir::Sort::Type,
            arguments: vec![nir::Term::TypeListValue(vec![
                nir::Term::Primitive(nir::Primitive::Bool),
                nir::Term::Primitive(nir::Primitive::Bool),
            ])],
        });
        assert_eq!(vm.invoke(id(&package, "Build"), vec![]).unwrap(), expected);
        assert_eq!(calls(&package, &vm), vec!["Build", "Choose"]);
        assert_eq!(
            luna::invocation::invoke(&package, "Build", 100_000).unwrap(),
            expected
        );
    }
}

#[test]
fn bound_tuple_syntax_checks_known_block_inputs_before_invocation() {
    let selectors = luna::protocols::type_constructors::Selectors {
        meta_list: Some("input.List"),
        tuple: Some("input.Tuple"),
        ..Default::default()
    };
    for expression in [
        "Tuple<bool, do {.u8'builtin}>",
        "Tuple<bool, do {let T=.u8'builtin;T}>",
    ] {
        let source = format!(
            "typealias Type=.Type'builtin;
            pure comptime fn List<T> -> Type {{T}}
            pure comptime fn Probe<...Ts:List<Type>> -> Type {{bool}}
            pure comptime fn Tuple<...Es:List<Type>> -> Type
                where requires Probe<...Es> == Probe<bool,bool> {{bool}}
            comptime fn Build() -> Type {{{expression}}}"
        );
        let error = compile_with_source_bindings(&source, &Default::default(), selectors)
            .expect_err(expression);
        assert!(error.contains("requirement"), "{expression}: {error}");
    }
}

#[test]
fn bound_tuple_deferred_list_contracts_check_values_and_recover() {
    let selectors = luna::protocols::type_constructors::Selectors {
        meta_list: Some("input.List"),
        tuple: Some("input.Tuple"),
        ..Default::default()
    };
    for expression in [
        "Tuple<bool, Choose(flag)>",
        "Tuple<bool, (Choose(flag))>",
        "Tuple<bool, do {let ty=Choose(flag);ty}>",
    ] {
        let source = format!(
            "typealias Type=.Type'builtin;
            pure comptime fn List<T> -> Type {{T}}
            pure comptime fn Probe<...Ts:List<Type>> -> Type {{bool}}
            pure comptime fn Tuple<...Es:List<Type>> -> Type
                where requires Probe<...Es> == Probe<bool,bool> {{bool}}
            comptime fn Choose(flag:bool) -> Type {{if flag {{bool}} else {{.u8'builtin}}}}
            comptime fn Build(flag:bool) -> Type {{{expression}}}
            comptime fn Good() -> Type {{Build(true)}}
            comptime fn Bad() -> Type {{Build(false)}}"
        );
        let package =
            compile_with_source_bindings(&source, &Default::default(), selectors).unwrap();
        let mut vm = Interpreter::for_comptime(&package, Budget::default()).unwrap();
        assert!(
            vm.invoke(id(&package, "Build"), vec![Value::Bool(false)])
                .is_err(),
            "{expression}"
        );
        let expected = Value::Type(nir::Term::NormalForm {
            head: id(&package, "Tuple"),
            sort: nir::Sort::Type,
            arguments: vec![nir::Term::TypeListValue(vec![
                nir::Term::Primitive(nir::Primitive::Bool),
                nir::Term::Primitive(nir::Primitive::Bool),
            ])],
        });
        assert_eq!(
            vm.invoke(id(&package, "Build"), vec![Value::Bool(true)])
                .unwrap(),
            expected
        );
        assert_eq!(
            calls(&package, &vm),
            vec!["Build", "Choose", "Build", "Choose"]
        );
        assert_eq!(
            luna::invocation::invoke(&package, "Good", 100_000).unwrap(),
            expected
        );
        assert!(luna::invocation::invoke(&package, "Bad", 100_000).is_err());
    }
}

#[test]
fn comptime_type_list_indexing_preserves_elements_and_checks_bounds() {
    let source = "typealias Type=.Type'builtin;typealias Integer=.Integer'builtin;
        pure comptime fn List<T>->Type {List<T>}
        pure comptime fn Tuple<...Es:List<Type>>->Type {Tuple<...Es>}
        comptime fn elements(T:Type)->List<Type> {T match {Tuple<Es> => Es,_=>elements(T)}}
        comptime fn Pick(values:List<Type>,index:Integer)->Type {values[index]}
        comptime fn pass(values:List<Type>)->List<Type> {values}
        comptime fn position()->Integer {1}
        comptime fn Select(values:List<Type>)->Type {pass(values)[position()]}
        typealias Byte=Pick(elements(Tuple<bool,.u8'builtin>),1);
        fn run()->Byte {7}";
    let package = compile_with_source_bindings(
        source,
        &Default::default(),
        luna::protocols::type_constructors::Selectors {
            meta_list: Some("input.List"),
            tuple: Some("input.Tuple"),
            ..Default::default()
        },
    )
    .unwrap();
    let mut vm = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    assert!(package.to_string().contains("(type-list-index (values"));
    let tuple = package
        .normal_forms
        .iter()
        .find(|head| head.role == nir::normal_forms::Role::Tuple)
        .unwrap()
        .declaration;
    let opaque = nir::Term::NormalForm {
        head: tuple,
        sort: nir::Sort::Type,
        arguments: vec![nir::Term::TypeListValue(vec![nir::Term::Primitive(
            nir::Primitive::Bool,
        )])],
    };
    let types = vec![
        nir::Term::Primitive(nir::Primitive::Bool),
        nir::Term::Primitive(nir::Primitive::U8),
        opaque,
    ];
    for (index, expected) in types.iter().enumerate() {
        assert_eq!(
            vm.invoke(
                id(&package, "Pick"),
                vec![
                    execution_support::type_list_value(&package, types.clone()),
                    Value::Integer(comptime_runtime::Integer::from_u128(index as u128))
                ]
            )
            .unwrap(),
            Value::Type(expected.clone())
        );
    }
    for index in [-1, 3] {
        let error = vm
            .invoke(
                id(&package, "Pick"),
                vec![
                    execution_support::type_list_value(&package, types.clone()),
                    Value::Integer(comptime_runtime::Integer::from_i128(index)),
                ],
            )
            .unwrap_err();
        assert_eq!(
            error.kind,
            comptime_interpretor::ErrorKind::IndexOutOfBounds
        );
        assert!(error.source.is_some());
    }
    assert_eq!(
        vm.invoke(
            id(&package, "Pick"),
            vec![
                execution_support::type_list_value(&package, vec![]),
                Value::Integer(comptime_runtime::Integer::from_u128(0))
            ]
        )
        .unwrap_err()
        .kind,
        comptime_interpretor::ErrorKind::IndexOutOfBounds
    );
    let mut ordered = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    assert_eq!(
        ordered
            .invoke(
                id(&package, "Select"),
                vec![execution_support::type_list_value(&package, types.clone())]
            )
            .unwrap(),
        Value::Type(nir::Term::Primitive(nir::Primitive::U8))
    );
    assert_eq!(calls(&package, &ordered), ["Select", "pass", "position"]);
    assert_eq!(
        vm.invoke(
            id(&package, "Pick"),
            vec![
                execution_support::type_list_value(&package, types),
                Value::Integer(comptime_runtime::Integer::from_u128(0))
            ]
        )
        .unwrap(),
        Value::Type(nir::Term::Primitive(nir::Primitive::Bool))
    );
    assert_eq!(
        luna::execution::interpret(&package, "run", 100000).unwrap(),
        Value::UnsignedInteger(7)
    );
}

#[test]
fn comptime_type_list_indexing_prepared_calls_and_nonlocal_exit() {
    let source="typealias Type=.Type'builtin;typealias Integer=.Integer'builtin;
        pure comptime fn List<T>->Type {List<T>}
        pure comptime fn Tuple<...Es:List<Type>>->Type {Tuple<...Es>}
        comptime fn elements(T:Type)->List<Type> {T match {Tuple<Es> => Es,_=>elements(T)}}
        comptime fn Pick(values:List<Type>,index:Integer)->Type {values[index]}
        comptime fn Good()->Type {let es=elements(Tuple<bool,.u8'builtin>);let first=es[0];es[1]}
        comptime fn Escape()->Type {elements(Tuple<>)[do {return bool;0}]}
        comptime fn Bad()->Type {Pick(elements(Tuple<bool>),1)}
        comptime fn Empty()->Type {Pick(elements(Tuple<>),0)}
        comptime fn Negative()->Type {Pick(elements(Tuple<bool>),-1)}
        comptime fn Huge()->Type {Pick(elements(Tuple<bool>),340282366920938463463374607431768211456)}";
    let selectors = luna::protocols::type_constructors::Selectors {
        meta_list: Some("input.List"),
        tuple: Some("input.Tuple"),
        ..Default::default()
    };
    let package = compile_with_source_bindings(source, &Default::default(), selectors).unwrap();
    for (entry, expected) in [
        ("Good", nir::Primitive::U8),
        ("Escape", nir::Primitive::Bool),
    ] {
        assert_eq!(
            luna::invocation::invoke(&package, entry, 100_000).unwrap(),
            Value::Type(nir::Term::Primitive(expected))
        );
    }
    for entry in ["Bad", "Empty", "Negative", "Huge"] {
        let error = luna::invocation::invoke(&package, entry, 100_000).unwrap_err();
        assert!(error.contains("IndexOutOfBounds"), "{entry}: {error}");
    }
    for expression in [
        "Pick(elements(Tuple<bool>),-1)",
        "Pick(elements(Tuple<>),0)",
    ] {
        let invalid =
            format!("{source} typealias Invalid={expression};fn use_invalid(value:Invalid) {{}}");
        let error =
            compile_with_source_bindings(&invalid, &Default::default(), selectors).unwrap_err();
        assert!(error.contains("IndexOutOfBounds"), "{expression}: {error}");
    }
}

#[test]
fn comptime_type_list_indexing_rejects_wrong_input_types_and_runtime_escape() {
    let prefix = "typealias Type=.Type'builtin;
        pure comptime fn List<T>->Type {List<T>}
        pure comptime fn Tuple<...Es:List<Type>>->Type {Tuple<...Es>}";
    let selectors = luna::protocols::type_constructors::Selectors {
        meta_list: Some("input.List"),
        tuple: Some("input.Tuple"),
        ..Default::default()
    };
    for body in [
        "comptime fn Bad(es:List<Type>)->Type {es[true]}",
        "comptime fn Bad(es:List<bool>)->Type {es[0]}",
        "fn bad(es:List<Type>)->Type {es[0]}",
    ] {
        assert!(
            compile_with_source_bindings(
                &format!("{prefix}{body}"),
                &Default::default(),
                selectors
            )
            .is_err(),
            "{body}"
        );
    }
    let source = format!("{prefix} comptime fn Bad(es:List<Type>)->Type {{es[0]}}");
    assert!(
        compile_with_source_bindings(&source, &Default::default(), Default::default()).is_err(),
        "a same-spelled unbound List must not grant indexing authority"
    );
}

#[test]
fn type_list_indexing_specializes_runtime_parameter_and_result_types() {
    let source="typealias Type=.Type'builtin;typealias Integer=.Integer'builtin;
        pure comptime fn List<T>->Type {List<T>}
        pure comptime fn Tuple<...Es:List<Type>>->Type {Tuple<...Es>}
        comptime fn elements(T:Type)->List<Type> {T match {Tuple<Es> => Es,_=>elements(T)}}
        comptime fn First(es:List<Type>)->Type {es[0]}
        fn identity(comptime es:List<Type>,value:defer First(es))->defer First(es) {value}
        fn byte()->.u8'builtin {identity(elements(Tuple<.u8'builtin,bool>),7)}
        fn flag()->bool {identity(elements(Tuple<bool,.u8'builtin>),true)}
        fn nested()->Tuple<bool,.u8'builtin> {identity(elements(Tuple<Tuple<bool,.u8'builtin>>),(true,9))}";
    let selectors = luna::protocols::type_constructors::Selectors {
        meta_list: Some("input.List"),
        tuple: Some("input.Tuple"),
        ..Default::default()
    };
    let package = compile_with_source_bindings(source, &Default::default(), selectors).unwrap();
    for (entry, expected) in [
        ("byte", Value::UnsignedInteger(7)),
        ("flag", Value::Bool(true)),
        (
            "nested",
            Value::Tuple(vec![Value::Bool(true), Value::UnsignedInteger(9)]),
        ),
    ] {
        assert_eq!(
            luna::execution::interpret(&package, entry, 100_000).unwrap(),
            expected
        );
        let graph = luna::instantiation::instantiate(&package, entry, 100_000).unwrap();
        let specialized = graph
            .functions
            .iter()
            .find(|f| f.function.name == "identity")
            .unwrap();
        let nir::Term::Function { parameters, result } =
            specialized.function.signature.callable_signature()
        else {
            panic!("signature")
        };
        assert_eq!(parameters.last().unwrap().ty, **result);
        if entry == "nested" {
            assert!(
                matches!(result.as_ref(),nir::Term::NormalForm {head,..} if *head==id(&package,"Tuple"))
            );
        }
    }
}

#[test]
fn type_list_indexing_direct_type_annotations_preserve_opaque_identity() {
    let source="typealias Type=.Type'builtin;
        pure comptime fn List<T>->Type {List<T>}
        pure comptime fn Tuple<...Es:List<Type>>->Type {Tuple<...Es>}
        comptime fn elements(T:Type)->List<Type> {T match {Tuple<Es> => Es,_=>elements(T)}}
        typealias Byte=elements(Tuple<bool,.u8'builtin>)[1];
        fn byte()->Byte {7}
        fn nested(value:elements(Tuple<Tuple<bool,.u8'builtin>>)[0])->Tuple<bool,.u8'builtin> {value}
        fn run()->Tuple<bool,.u8'builtin> {nested((true,byte()))}";
    let selectors = luna::protocols::type_constructors::Selectors {
        meta_list: Some("input.List"),
        tuple: Some("input.Tuple"),
        ..Default::default()
    };
    let package = compile_with_source_bindings(source, &Default::default(), selectors).unwrap();
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Tuple(vec![Value::Bool(true), Value::UnsignedInteger(7)])
    );
    let signature = &package
        .functions
        .iter()
        .find(|f| f.name == "nested")
        .unwrap()
        .signature;
    let nir::Term::Function { parameters, result } = signature.callable_signature() else {
        panic!("signature")
    };
    assert_eq!(parameters[0].ty, **result);
    assert!(
        matches!(result.as_ref(),nir::Term::NormalForm {head,..} if *head==id(&package,"Tuple"))
    );
    for index in ["-1", "2"] {
        let invalid = source.replace("[1]", &format!("[{index}]"));
        let error =
            compile_with_source_bindings(&invalid, &Default::default(), selectors).unwrap_err();
        assert!(error.contains("IndexOutOfBounds"), "{error}");
    }
    for annotation in ["es[0]", "First(es)"] {
        let pending = format!(
            "{source} comptime fn First(es:List<Type>)->Type {{es[0]}}
            fn pending(comptime es:List<Type>,value:{annotation}) {{}}"
        );
        let error =
            compile_with_source_bindings(&pending, &Default::default(), selectors).unwrap_err();
        assert!(
            error.contains("invocation-time type elaboration is not yet implemented"),
            "{error}"
        );
        assert!(!error.contains("MissingBinding"), "{error}");
    }
}

#[test]
fn pending_type_computations_wait_resume_and_publish_opaque_types_once() {
    use elaboration::type_computations::{Error, Input, Session, State};
    use elaboration::{InferenceContext, InferenceTerm as I};
    let source = "typealias Type=.Type'builtin;typealias Integer=.Integer'builtin;
        pure comptime fn List<T>->Type {List<T>}
        pure comptime fn Tuple<...Es:List<Type>>->Type {Tuple<...Es>}
        comptime fn Pick(es:List<Type>,index:Integer)->Type {es[index]}
        comptime fn Pass(T:Type)->Type {T}
        fn runtime()->bool {true}";
    let package = compile_with_source_bindings(
        source,
        &Default::default(),
        luna::protocols::type_constructors::Selectors {
            meta_list: Some("input.List"),
            tuple: Some("input.Tuple"),
            ..Default::default()
        },
    )
    .unwrap();
    let list_type = nir::Term::NormalForm {
        head: id(&package, "List"),
        sort: nir::Sort::Type,
        arguments: vec![nir::Term::Primitive(nir::Primitive::Type)],
    };
    let nested = nir::Term::NormalForm {
        head: id(&package, "Tuple"),
        sort: nir::Sort::Type,
        arguments: vec![nir::Term::TypeListValue(vec![nir::Term::Primitive(
            nir::Primitive::Bool,
        )])],
    };
    let mut context = InferenceContext::default();
    let input = context.fresh(nir::Sort::ComptimeValue);
    let alias = context.fresh(nir::Sort::ComptimeValue);
    let mut session = Session::new(&package, &context, Budget::default()).unwrap();
    let arguments = |value, index| {
        vec![
            Input {
                ty: I::Stable(list_type.clone()),
                value,
            },
            Input {
                ty: I::Stable(nir::Term::Primitive(nir::Primitive::Integer)),
                value: I::Stable(nir::Term::Integer(comptime_runtime::Integer::from_i128(
                    index,
                ))),
            },
        ]
    };
    let output = session
        .enqueue(
            &mut context,
            id(&package, "Pick"),
            arguments(I::Meta(input), 0),
        )
        .unwrap();
    let next = session
        .enqueue(
            &mut context,
            id(&package, "Pass"),
            vec![Input {
                ty: I::Stable(nir::Term::Primitive(nir::Primitive::Type)),
                value: I::Meta(output),
            }],
        )
        .unwrap();
    let budget = session.remaining_steps();
    assert!(
        matches!(session.resume(&mut context,output).unwrap(),State::Waiting(ids) if ids.contains(&input))
    );
    assert_eq!(session.remaining_steps(), budget);
    context.assign(input, I::Meta(alias)).unwrap();
    assert!(
        matches!(session.resume(&mut context,output).unwrap(),State::Waiting(ids) if ids.contains(&alias) && !ids.contains(&input))
    );
    assert!(context.freeze(&I::Meta(output)).is_err());
    assert!(
        matches!(session.resume(&mut context,next).unwrap(),State::Waiting(ids) if ids.contains(&output))
    );
    context
        .assign(
            alias,
            I::Stable(nir::Term::TypeListValue(vec![nested.clone()])),
        )
        .unwrap();
    assert!(
        matches!(session.resume(&mut context,output).unwrap(),State::Complete(ty) if *ty==nested)
    );
    assert_eq!(context.freeze(&I::Meta(output)).unwrap(), nested);
    let remaining = session.remaining_steps();
    assert!(remaining < budget);
    session.resume(&mut context, output).unwrap();
    assert_eq!(
        session.remaining_steps(),
        remaining,
        "completed computation must not execute again"
    );
    assert!(
        matches!(session.resume(&mut context,next).unwrap(),State::Complete(ty) if *ty==nested)
    );
    let bad = session
        .enqueue(
            &mut context,
            id(&package, "Pick"),
            arguments(I::Meta(input), -1),
        )
        .unwrap();
    assert!(
        matches!(session.resume(&mut context,bad).unwrap(),State::Failed(Error::Invocation(e)) if e.kind==ErrorKind::IndexOutOfBounds)
    );
    let remaining = session.remaining_steps();
    session.resume(&mut context, bad).unwrap();
    assert_eq!(
        session.remaining_steps(),
        remaining,
        "failure must not replay a call"
    );
    assert!(context.freeze(&I::Meta(bad)).is_err());
    let dependent = session
        .enqueue(
            &mut context,
            id(&package, "Pass"),
            vec![Input {
                ty: I::Stable(nir::Term::Primitive(nir::Primitive::Type)),
                value: I::Meta(bad),
            }],
        )
        .unwrap();
    assert!(
        matches!(session.resume(&mut context,dependent).unwrap(),State::Failed(Error::DependencyFailed(id)) if *id==bad)
    );
    assert_eq!(
        session.remaining_steps(),
        remaining,
        "failed producer must fail its consumer without invocation"
    );
    let good = session
        .enqueue(
            &mut context,
            id(&package, "Pick"),
            arguments(I::Meta(input), 0),
        )
        .unwrap();
    assert!(matches!(
        session.resume(&mut context, good).unwrap(),
        State::Complete(_)
    ));
    assert!(matches!(
        session.enqueue(&mut context, id(&package, "Tuple"), vec![]),
        Err(Error::InvalidTarget)
    ));
    assert!(matches!(
        session.enqueue(&mut context, id(&package, "runtime"), vec![]),
        Err(Error::InvalidTarget)
    ));
    assert!(matches!(
        session.resume(&mut context.trial(), good),
        Err(Error::SpeculativeContext)
    ));
    assert!(matches!(
        session.resume(&mut InferenceContext::default(), good),
        Err(Error::ForeignContext)
    ));
    assert!(
        session
            .to_string()
            .starts_with("(type-computations (computation (output")
    );
    assert!(
        session
            .to_string()
            .contains("(failed (type-computation-error")
    );

    let domain = context.fresh(nir::Sort::Type);
    let typed = session
        .enqueue(
            &mut context,
            id(&package, "Pass"),
            vec![Input {
                ty: I::Meta(domain),
                value: I::Stable(nested.clone()),
            }],
        )
        .unwrap();
    assert!(
        matches!(session.resume(&mut context,typed).unwrap(),State::Waiting(ids) if ids.contains(&domain))
    );
    let mut candidate = context.trial();
    candidate
        .assign(
            domain,
            I::Stable(nir::Term::Primitive(nir::Primitive::Type)),
        )
        .unwrap();
    context.commit(candidate).unwrap();
    assert!(
        matches!(session.resume(&mut context,typed).unwrap(),State::Complete(ty) if *ty==nested)
    );

    let collision = session
        .enqueue(
            &mut context,
            id(&package, "Pass"),
            vec![Input {
                ty: I::Stable(nir::Term::Primitive(nir::Primitive::Type)),
                value: I::Stable(nested.clone()),
            }],
        )
        .unwrap();
    context.assign(collision, I::Stable(nested)).unwrap();
    let remaining = session.remaining_steps();
    assert!(
        matches!(session.resume(&mut context,collision).unwrap(),State::Failed(Error::Inference(elaboration::InferenceError::AlreadyAssigned(id))) if *id==collision)
    );
    assert_eq!(
        session.remaining_steps(),
        remaining,
        "publication conflict must precede invocation"
    );
    let waiting = context.fresh(nir::Sort::Type);
    let cycle_a = session
        .enqueue(
            &mut context,
            id(&package, "Pass"),
            vec![Input {
                ty: I::Stable(nir::Term::Primitive(nir::Primitive::Type)),
                value: I::Meta(waiting),
            }],
        )
        .unwrap();
    let cycle_b = session
        .enqueue(
            &mut context,
            id(&package, "Pass"),
            vec![Input {
                ty: I::Stable(nir::Term::Primitive(nir::Primitive::Type)),
                value: I::Meta(cycle_a),
            }],
        )
        .unwrap();
    context.assign(waiting, I::Meta(cycle_b)).unwrap();
    assert!(matches!(
        session.resume(&mut context, cycle_a).unwrap(),
        State::Failed(Error::DependencyCycle(_))
    ));
    assert!(
        matches!(session.resume(&mut context,cycle_b).unwrap(),State::Failed(Error::DependencyFailed(id)) if *id==cycle_a)
    );
    assert_eq!(
        session.remaining_steps(),
        remaining,
        "dependency cycles must not invoke either body"
    );
}

#[test]
fn defer_closed_type_computations_and_explicit_unsupported_boundaries() {
    let source = "typealias Type=.Type'builtin;
        comptime fn Select(flag:bool)->Type {if flag {.u8'builtin} else {bool}}
        typealias Byte=defer Select(true);
        fn identity(value:defer Select(true))->defer Select(true) {value}
        fn run()->Byte {identity(7)}";
    let package = compile(source);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::UnsignedInteger(7)
    );
    let pending = "typealias Type=.Type'builtin;
        comptime fn Select(flag:bool)->Type {if flag {.u8'builtin} else {bool}}
        fn identity(comptime flag:bool,value:defer Select(flag))->defer Select(flag) {value}";
    let package = compile_with_protocols(
        &format!("{pending} fn run()->.u8'builtin {{identity(true,7)}}"),
        &Default::default(),
    )
    .unwrap();
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::UnsignedInteger(7)
    );
    let error =
        compile_with_protocols("fn run()->bool {defer true}", &Default::default()).unwrap_err();
    assert!(
        error.contains("deferred value computation requires instantiation support"),
        "{error}"
    );
    let error =
        compile_with_protocols("fn run()->defer true {true}", &Default::default()).unwrap_err();
    assert!(!error.is_empty());
}

#[test]
fn explicit_defer_defaults_retain_order_and_execute_only_selected_inputs() {
    let package=execution_support::compile_with_tuple("typealias Type=.Type'builtin;typealias Integer=.Integer'builtin;
        comptime fn next(n:Integer)->Integer {n + 1}
        pure comptime fn Shape<N:Integer,.size:Integer=defer next(N),.end:Integer=defer next(size)>->Type {bool}
        comptime fn Build()->Type {Shape<4>}
        comptime fn Override()->Type {Shape<4,.size=10,.end=20>}
        fn tag(comptime n:Integer,comptime .T:Type=defer Shape<n>)->bool {true}
        fn forward(comptime n:Integer)->bool {tag(n)}
        fn run()->Tuple<bool, bool> {(forward(4),forward(9))}");
    let original = package.clone();
    let shape = id(&package, "Shape");
    let expected = |values: &[u128]| {
        Value::Type(nir::Term::NormalForm {
            head: shape,
            sort: nir::Sort::Type,
            arguments: values
                .iter()
                .map(|v| nir::Term::Integer(comptime_runtime::Integer::from_u128(*v)))
                .collect(),
        })
    };
    for (entry, result, trace) in [
        ("Build", expected(&[4, 5, 6]), vec!["Build", "next", "next"]),
        ("Override", expected(&[4, 10, 20]), vec!["Override"]),
    ] {
        let mut vm = Interpreter::for_comptime(&package, Budget::default()).unwrap();
        assert_eq!(vm.invoke(id(&package, entry), vec![]).unwrap(), result);
        assert_eq!(calls(&package, &vm), trace);
        assert_eq!(
            luna::invocation::invoke(&package, entry, 100_000).unwrap(),
            result
        );
    }
    let graph = luna::instantiation::instantiate(&package, "run", 100_000).unwrap();
    let mut inputs = graph
        .functions
        .iter()
        .filter(|f| f.function.name == "tag")
        .map(|f| {
            let nir::Term::NormalForm {
                head, arguments, ..
            } = &f.key.arguments[1]
            else {
                panic!("normal-form identity")
            };
            assert_eq!(*head, shape);
            assert_eq!(arguments[0], f.key.arguments[0]);
            arguments
                .iter()
                .map(|term| {
                    let nir::Term::Integer(n) = term else {
                        panic!("Integer")
                    };
                    n.to_unsigned(128).unwrap()
                })
                .collect::<Vec<_>>()
        })
        .collect::<Vec<_>>();
    inputs.sort();
    assert_eq!(inputs, vec![vec![4, 5, 6], vec![9, 10, 11]]);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Tuple(vec![Value::Bool(true), Value::Bool(true)])
    );
    assert_eq!(
        package, original,
        "instances must not overwrite the saved default plan"
    );
}

#[test]
fn explicit_defer_type_clause_defaults_check_contracts_and_skip_overrides() {
    let source = "typealias Type=.Type'builtin;
        comptime fn Select(T:Type)->Type {if T==bool {bool} else {.u8'builtin}}
        comptime fn Poison()->Type {Poison()}
        struct Box where T,.Stored:Type=defer Select(T) {value:Stored}
        struct Guarded where .Stored:Type=defer Poison() {value:Stored}
        fn run()->bool {let box=Box<bool> {value:true};box.value}
        fn safe()->bool {let box=Guarded<.Stored=bool> {value:true};box.value}";
    let package = compile(source);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    assert_eq!(
        luna::execution::interpret(&package, "safe", 100_000).unwrap(),
        Value::Bool(true)
    );
    for bad in [
        "struct Bad where T,.Stored:Type=defer true {value:Stored}",
        "struct Bad where T,.Stored:Type=defer Missing(T) {value:Stored}",
        "struct Bad where .A:Type=defer B,.B:Type=bool {value:A}",
    ] {
        assert!(
            compile_with_protocols(&format!("{source}{bad}"), &Default::default()).is_err(),
            "{bad}"
        );
    }
    let selected = format!("{source} typealias Must=Guarded<>;fn consume(value:Must) {{}}");
    let error = compile_with_protocols(&selected, &Default::default()).unwrap_err();
    assert!(
        error.contains("DepthExhausted"),
        "selected recursive default must run and fail within budget: {error}"
    );
    let error = compile_with_protocols(
        "fn tag(comptime flag:bool)->bool {flag} fn runtime(flag:bool)->bool {tag(defer flag)}",
        &Default::default(),
    )
    .unwrap_err();
    assert!(
        !error.is_empty(),
        "defer cannot read a future runtime value"
    );
}

#[test]
fn residual_type_invocations_recreate_isolated_waiters_without_runtime_dependencies() {
    use elaboration::type_computations::{Error, Session, State};
    use elaboration::{InferenceContext, InferenceTerm as I};
    use nir::type_computations::{Input, Invocation};
    let package = compile(
        "typealias Type=.Type'builtin;
        comptime fn Select(flag:bool)->Type {if flag {.u8'builtin} else {bool}}",
    );
    let plan = Invocation::new(
        id(&package, "Select"),
        vec![nir::Sort::ComptimeValue, nir::Sort::Runtime],
        vec![Input {
            ty: nir::Term::Primitive(nir::Primitive::Bool),
            value: nir::Term::Bound {
                depth: 0,
                index: 0,
                sort: nir::Sort::ComptimeValue,
            },
        }],
        &mut 100,
    )
    .unwrap();
    let saved = plan.clone();
    let mut left = InferenceContext::default();
    let mut right = InferenceContext::default();
    let a = left.fresh(nir::Sort::ComptimeValue);
    let b = right.fresh(nir::Sort::ComptimeValue);
    let unused_a = left.fresh(nir::Sort::Runtime);
    let unused_b = right.fresh(nir::Sort::Runtime);
    let mut first = Session::new(&package, &left, Budget::default()).unwrap();
    let mut second = Session::new(&package, &right, Budget::default()).unwrap();
    let output_a = first
        .enqueue_residual(&mut left, &plan, &[I::Meta(a), I::Meta(unused_a)])
        .unwrap();
    let output_b = second
        .enqueue_residual(&mut right, &plan, &[I::Meta(b), I::Meta(unused_b)])
        .unwrap();
    assert_ne!(output_a, output_b);
    assert!(
        matches!(first.resume(&mut left,output_a).unwrap(),State::Waiting(ids) if ids.len()==1 && ids.contains(&a))
    );
    right.assign(b, I::Stable(nir::Term::Bool(false))).unwrap();
    assert!(
        matches!(second.resume(&mut right,output_b).unwrap(),State::Complete(ty) if *ty==nir::Term::Primitive(nir::Primitive::Bool))
    );
    assert!(left.freeze(&I::Meta(output_a)).is_err());
    left.assign(a, I::Stable(nir::Term::Bool(true))).unwrap();
    assert!(
        matches!(first.resume(&mut left,output_a).unwrap(),State::Complete(ty) if *ty==nir::Term::Primitive(nir::Primitive::U8))
    );
    assert_eq!(
        plan, saved,
        "an instance must not mutate its frozen residual"
    );
    assert!(left.freeze(&I::Meta(unused_a)).is_err());
    let invalid = first.enqueue_residual(
        &mut left,
        &plan,
        &[
            I::Stable(nir::Term::Primitive(nir::Primitive::Bool)),
            I::Meta(unused_a),
        ],
    );
    assert!(matches!(
        invalid,
        Err(Error::Inference(
            elaboration::InferenceError::WrongSort { .. }
        ))
    ));
}

#[test]
fn residual_list_calls_capture_source_construction_and_resume_after_inputs_arrive() {
    use elaboration::type_computations::{Session, State};
    use elaboration::{InferenceContext, InferenceTerm as I};
    use nir::type_computations::Invocation;
    let source = "typealias Type=.Type'builtin; typealias Byte=.u8'builtin;
        pure comptime fn List<T>->Type {T}
        comptime fn Select(values:List<bool>)->Type {if values[0] {bool} else {Byte}}
        comptime fn SelectNested(values:List<List<bool>>)->Type {Select(values[0])}
        comptime fn First(values:List<Type>)->Type {values[0]}
        comptime fn Flags(comptime flag:bool)->Type {Select([flag,false])}
        comptime fn NestedFlags(comptime flag:bool)->Type {SelectNested([[flag],[false]])}
        comptime fn Types(comptime T:Type)->Type {First([T,bool])}
        comptime fn Body(comptime flag:bool)->Type {Select([do {flag},false])}";
    let package = compile_with_source_bindings(
        source,
        &Default::default(),
        luna::protocols::type_constructors::Selectors {
            meta_list: Some("input.List"),
            ..Default::default()
        },
    )
    .unwrap();
    for (name, input, expected) in [
        ("Flags", nir::Term::Bool(true), nir::Primitive::Bool),
        ("Flags", nir::Term::Bool(false), nir::Primitive::U8),
        ("NestedFlags", nir::Term::Bool(false), nir::Primitive::U8),
        (
            "Types",
            nir::Term::Primitive(nir::Primitive::Char),
            nir::Primitive::Char,
        ),
    ] {
        let template = package.functions.iter().find(|f| f.name == name).unwrap();
        let nir::Term::Function { parameters, .. } = template.signature.callable_signature() else {
            panic!("signature")
        };
        let captures = template
            .parameters
            .iter()
            .copied()
            .zip(parameters.iter().cloned())
            .collect::<Vec<_>>();
        let residual = Invocation::from_call(&template.body, &captures, &mut 10000).unwrap();
        let saved = residual.clone();
        assert_eq!(
            residual.dependencies().iter().copied().collect::<Vec<_>>(),
            vec![0]
        );
        let mut context = InferenceContext::default();
        let argument = context.fresh(input.sort());
        let mut session = Session::new(&package, &context, Budget::default()).unwrap();
        let output = session
            .enqueue_residual(&mut context, &residual, &[I::Meta(argument)])
            .unwrap();
        assert!(matches!(
            session.resume(&mut context, output).unwrap(),
            State::Waiting(_)
        ));
        context.assign(argument, I::Stable(input)).unwrap();
        assert!(
            matches!(session.resume(&mut context, output).unwrap(), State::Complete(ty)
            if *ty == nir::Term::Primitive(expected)),
            "{name}"
        );
        assert_eq!(residual, saved);
    }
    let template = package.functions.iter().find(|f| f.name == "Body").unwrap();
    let nir::Term::Function { parameters, .. } = template.signature.callable_signature() else {
        panic!("signature")
    };
    let captures = template
        .parameters
        .iter()
        .copied()
        .zip(parameters.iter().cloned())
        .collect::<Vec<_>>();
    assert!(Invocation::from_call(&template.body, &captures, &mut 10000).is_err());
}

#[test]
fn checked_type_calls_capture_residuals_from_source_and_preserve_argument_routing() {
    use elaboration::type_computations::{Session, State};
    use elaboration::{InferenceContext, InferenceTerm as I};
    use nir::type_computations::Invocation;
    let source="typealias Type=.Type'builtin;
        comptime fn Select(.first:bool=false,.second:bool=false)->Type {if first {if second {.u8'builtin} else {bool}} else {.char'builtin}}
        comptime fn Template(comptime flag:bool)->Type {Select(.second=false,.first=flag)}
        comptime fn Nested(comptime flag:bool)->Type {Select(.first=flag,.second=do {flag})}
        comptime fn Effectful(comptime flag:bool)->Type {let copy=flag;Select(.first=copy,.second=false)}
        typealias Integer=.Integer'builtin;
        comptime fn Width(n:Integer)->Type {if n==340282366920938463463374607431768211456 {bool} else {.u8'builtin}}
        comptime fn Numeric()->Type {Width(340282366920938463463374607431768211456)}";
    let package = compile(source);
    let template = package
        .functions
        .iter()
        .find(|f| f.name == "Template")
        .unwrap();
    let nir::Term::Function { parameters, .. } = template.signature.callable_signature() else {
        panic!("signature")
    };
    let captures = template
        .parameters
        .iter()
        .copied()
        .zip(parameters.iter().cloned())
        .collect::<Vec<_>>();
    let residual = Invocation::from_call(&template.body, &captures, &mut 10_000).unwrap();
    assert_eq!(residual.target(), id(&package, "Select"));
    assert_eq!(
        residual.inputs()[0].value,
        nir::Term::Bound {
            depth: 0,
            index: 0,
            sort: nir::Sort::ComptimeValue
        }
    );
    assert_eq!(residual.inputs()[1].value, nir::Term::Bool(false));
    let mut context = InferenceContext::default();
    let flag = context.fresh(nir::Sort::ComptimeValue);
    let mut session = Session::new(&package, &context, Budget::default()).unwrap();
    let output = session
        .enqueue_residual(&mut context, &residual, &[I::Meta(flag)])
        .unwrap();
    assert!(matches!(
        session.resume(&mut context, output).unwrap(),
        State::Waiting(_)
    ));
    context
        .assign(flag, I::Stable(nir::Term::Bool(true)))
        .unwrap();
    assert!(
        matches!(session.resume(&mut context,output).unwrap(),State::Complete(ty) if *ty==nir::Term::Primitive(nir::Primitive::Bool))
    );
    let numeric = package
        .functions
        .iter()
        .find(|f| f.name == "Numeric")
        .unwrap();
    let numeric = Invocation::from_call(&numeric.body, &[], &mut 10_000).unwrap();
    assert!(matches!(&numeric.inputs()[0].value,nir::Term::Integer(value) if value.bit_len()==129));
    let result = session
        .enqueue_residual(&mut context, &numeric, &[])
        .unwrap();
    assert!(
        matches!(session.resume(&mut context,result).unwrap(),State::Complete(ty) if *ty==nir::Term::Primitive(nir::Primitive::Bool))
    );
    for name in ["Nested", "Effectful"] {
        let function = package.functions.iter().find(|f| f.name == name).unwrap();
        let nir::Term::Function { parameters, .. } = function.signature.callable_signature() else {
            panic!("signature")
        };
        let captures = function
            .parameters
            .iter()
            .copied()
            .zip(parameters.iter().cloned())
            .collect::<Vec<_>>();
        assert!(
            Invocation::from_call(&function.body, &captures, &mut 10_000).is_err(),
            "{name}: a saved code body must not be discarded"
        );
    }
}

#[test]
fn residual_complete_bodies_preserve_control_flow_local_state_and_single_execution() {
    use elaboration::type_computations::{Error, Session, State};
    use elaboration::{InferenceContext, InferenceTerm as I};
    use nir::type_computations::Invocation;
    let package = compile(
        "typealias Type=.Type'builtin;
        comptime fn Poison()->Type {Poison()}
        comptime fn First(T:Type)->Type {T}
        comptime fn Second(T:Type)->Type {T}
        comptime fn Body(flag:bool)->Type {
            let selected=if flag {First(bool)} else {Poison()};
            Second(selected)
        }
        fn runtime()->bool {true}
        pure comptime fn Head<T>->Type {T}",
    );
    let saved = package.clone();
    let body = package.functions.iter().find(|f| f.name == "Body").unwrap();
    let plan = Invocation::from_function(body, &mut 10_000).unwrap();
    assert_eq!(plan.scope(), &[nir::Sort::ComptimeValue]);
    let mut context = InferenceContext::default();
    let flag = context.fresh(nir::Sort::ComptimeValue);
    let mut session = Session::new(
        &package,
        &context,
        Budget {
            steps: 10_000,
            depth: 16,
        },
    )
    .unwrap();
    let output = session
        .enqueue_residual(&mut context, &plan, &[I::Meta(flag)])
        .unwrap();
    assert!(matches!(
        session.resume(&mut context, output).unwrap(),
        State::Waiting(_)
    ));
    assert!(
        session.events().is_empty(),
        "waiting must not run either branch"
    );
    context
        .assign(flag, I::Stable(nir::Term::Bool(true)))
        .unwrap();
    assert!(
        matches!(session.resume(&mut context,output).unwrap(),State::Complete(ty) if *ty==nir::Term::Primitive(nir::Primitive::Bool))
    );
    let entries = session
        .events()
        .iter()
        .filter_map(|event| match event {
            Event::EnterFunction(function) => Some(*function),
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(
        entries,
        vec![
            id(&package, "Body"),
            id(&package, "First"),
            id(&package, "Second")
        ]
    );
    let before = session.events().len();
    session.resume(&mut context, output).unwrap();
    assert_eq!(session.events().len(), before);
    let bad = session
        .enqueue_residual(&mut context, &plan, &[I::Stable(nir::Term::Bool(false))])
        .unwrap();
    assert!(
        matches!(session.resume(&mut context,bad).unwrap(),State::Failed(Error::Invocation(error)) if error.kind==ErrorKind::DepthExhausted)
    );
    let before = session.events().len();
    session.resume(&mut context, bad).unwrap();
    assert_eq!(session.events().len(), before);
    let recovered = session
        .enqueue_residual(&mut context, &plan, &[I::Stable(nir::Term::Bool(true))])
        .unwrap();
    assert!(matches!(
        session.resume(&mut context, recovered).unwrap(),
        State::Complete(_)
    ));
    let pass = package
        .functions
        .iter()
        .find(|f| f.name == "First")
        .unwrap();
    let pass = Invocation::from_function(pass, &mut 10_000).unwrap();
    assert_eq!(pass.scope(), &[nir::Sort::Type]);
    let opaque = nir::Term::NormalForm {
        head: id(&package, "Head"),
        sort: nir::Sort::Type,
        arguments: vec![nir::Term::Primitive(nir::Primitive::Bool)],
    };
    let forwarded = session
        .enqueue_residual(&mut context, &pass, &[I::Stable(opaque.clone())])
        .unwrap();
    assert!(
        matches!(session.resume(&mut context,forwarded).unwrap(),State::Complete(ty) if *ty==opaque)
    );
    assert_eq!(package, saved);
    for name in ["runtime", "Head"] {
        let function = package.functions.iter().find(|f| f.name == name).unwrap();
        assert!(
            Invocation::from_function(function, &mut 10_000).is_err(),
            "{name}"
        );
    }
    let mut wrong_phase = body.clone();
    wrong_phase.phase = nir::program::FunctionPhase::Runtime;
    assert!(Invocation::from_function(&wrong_phase, &mut 10_000).is_err());
    let mut missing_binding = body.clone();
    missing_binding.parameters.clear();
    assert!(Invocation::from_function(&missing_binding, &mut 10_000).is_err());
    assert!(matches!(
        Invocation::from_function(body, &mut 0),
        Err(nir::type_computations::Error::Budget)
    ));
}

#[test]
fn checked_expression_entries_share_required_and_residual_invocation_representation() {
    use elaboration::type_computations::{Session, State};
    use elaboration::{InferenceContext, InferenceTerm as I};
    use nir::type_computations::{Invocation, expression_entry};
    let mut package = compile(
        "typealias Type=.Type'builtin;
        comptime fn Select(flag:bool)->Type {if flag {bool} else {.u8'builtin}}
        comptime fn Template(comptime flag:bool)->Type {let selected=Select(flag);selected}",
    );
    let template = package
        .functions
        .iter()
        .find(|f| f.name == "Template")
        .unwrap();
    let nir::Term::Function { parameters, .. } = template.signature.callable_signature() else {
        panic!("signature")
    };
    let captures = template
        .parameters
        .iter()
        .copied()
        .zip(parameters.iter().cloned())
        .collect();
    let entry = expression_entry(
        nir::DeclarationId {
            package: 0,
            local: u32::MAX,
        },
        "<saved-defer>".into(),
        template.body.clone(),
        captures,
        &mut 10_000,
    )
    .unwrap();
    let plan = Invocation::from_function(&entry, &mut 10_000).unwrap();
    package.functions.push(entry);
    nir::phases::validate(&package).unwrap();
    let original = package.clone();
    for (flag, expected) in [(true, nir::Primitive::Bool), (false, nir::Primitive::U8)] {
        let mut context = InferenceContext::default();
        let mut session = Session::new(&package, &context, Budget::default()).unwrap();
        let output = session
            .enqueue_residual(&mut context, &plan, &[I::Stable(nir::Term::Bool(flag))])
            .unwrap();
        assert!(
            matches!(session.resume(&mut context,output).unwrap(),State::Complete(ty) if *ty==nir::Term::Primitive(expected))
        );
    }
    assert_eq!(package, original);
}

#[test]
fn residual_capture_analysis_discovers_only_lexical_source_inputs() {
    let package = compile(
        "typealias Type=.Type'builtin;
        comptime fn Select(flag:bool)->Type {if flag {bool} else {.u8'builtin}}
        comptime fn Template(comptime flag:bool)->Type {
            let copy=flag;
            let choose=|| Select(copy);
            choose()
        }",
    );
    let function = package
        .functions
        .iter()
        .find(|f| f.name == "Template")
        .unwrap();
    let free = nir::free_bindings::collect(&function.body, &mut 10_000).unwrap();
    assert_eq!(free.into_iter().collect::<Vec<_>>(), function.parameters);
    let result = nir::type_computations::expression_entry(
        nir::DeclarationId {
            package: 0,
            local: u32::MAX,
        },
        "missing".into(),
        function.body.clone(),
        vec![],
        &mut 10_000,
    );
    assert!(
        matches!(result,Err(nir::type_computations::Error::MissingCapture(id)) if id==function.parameters[0])
    );
}

#[test]
fn compact_residual_entries_prune_unused_runtime_inputs_and_execute_captured_closures() {
    use elaboration::type_computations::{Session, State};
    use elaboration::{InferenceContext, InferenceTerm as I};
    use nir::type_computations::{Invocation, capture_entry};
    let mut package = compile(
        "typealias Type=.Type'builtin;
        comptime fn Select(flag:bool)->Type {if flag {bool} else {.u8'builtin}}
        comptime fn Template(unused:bool,comptime flag:bool)->Type {
            let copy=flag;
            let choose=|| Select(copy);
            choose()
        }",
    );
    let template = package
        .functions
        .iter()
        .find(|f| f.name == "Template")
        .unwrap();
    let nir::Term::Function { parameters, .. } = template.signature.callable_signature() else {
        panic!("signature")
    };
    let available = template
        .parameters
        .iter()
        .copied()
        .zip(parameters.iter().cloned())
        .collect::<Vec<_>>();
    assert_eq!(available[0].1.sort, nir::Sort::Runtime);
    let entry = capture_entry(
        nir::DeclarationId {
            package: 0,
            local: u32::MAX,
        },
        "<compact-defer>".into(),
        template.body.clone(),
        &available,
        &mut 10_000,
    )
    .unwrap();
    assert_eq!(entry.slots, vec![1]);
    assert_eq!(entry.function.parameters, vec![template.parameters[1]]);
    let compact = Invocation::from_function(&entry.function, &mut 10_000).unwrap();
    assert_eq!(compact.scope(), &[nir::Sort::ComptimeValue]);
    let plan = entry.invocation(&mut 10_000).unwrap();
    assert_eq!(
        plan.scope(),
        &[nir::Sort::Runtime, nir::Sort::ComptimeValue]
    );
    package.functions.push(entry.function);
    nir::phases::validate(&package).unwrap();
    let saved = package.clone();
    for (flag, expected) in [(true, nir::Primitive::Bool), (false, nir::Primitive::U8)] {
        let mut context = InferenceContext::default();
        let flag_input = context.fresh(nir::Sort::ComptimeValue);
        let unused = context.fresh(nir::Sort::Runtime);
        let mut session = Session::new(&package, &context, Budget::default()).unwrap();
        let output = session
            .enqueue_residual(&mut context, &plan, &[I::Meta(unused), I::Meta(flag_input)])
            .unwrap();
        assert!(
            matches!(session.resume(&mut context,output).unwrap(),State::Waiting(inputs) if inputs.iter().copied().collect::<Vec<_>>()==vec![flag_input])
        );
        assert!(session.events().is_empty());
        context
            .assign(flag_input, I::Stable(nir::Term::Bool(flag)))
            .unwrap();
        assert!(
            matches!(session.resume(&mut context,output).unwrap(),State::Complete(ty) if *ty==nir::Term::Primitive(expected))
        );
        let count = session.events().len();
        session.resume(&mut context, output).unwrap();
        assert_eq!(session.events().len(), count);
    }
    assert_eq!(package, saved);
}

#[test]
fn compact_residual_entries_preserve_tuple_head_and_single_collected_type_list() {
    use elaboration::type_computations::{Session, State};
    use elaboration::{InferenceContext, InferenceTerm as I};
    use nir::type_computations::capture_entry;
    use nir::{Primitive, Sort, Term};
    let mut package = compile_with_source_bindings(
        "typealias Type=.Type'builtin;
        pure comptime fn List<T>->Type {List<T>}
        pure comptime fn Tuple<...Es:List<Type>>->Type {Tuple<...Es>}
        comptime fn Template(unused:bool,comptime T:Type)->Type {Tuple<T,bool>}",
        &Default::default(),
        luna::protocols::type_constructors::Selectors {
            meta_list: Some("input.List"),
            tuple: Some("input.Tuple"),
            ..Default::default()
        },
    )
    .unwrap();
    let template = package
        .functions
        .iter()
        .find(|f| f.name == "Template")
        .unwrap();
    let Term::Function { parameters, .. } = template.signature.callable_signature() else {
        panic!("signature")
    };
    let available = template
        .parameters
        .iter()
        .copied()
        .zip(parameters.iter().cloned())
        .collect::<Vec<_>>();
    let entry = capture_entry(
        nir::DeclarationId {
            package: 0,
            local: u32::MAX,
        },
        "<tuple-defer>".into(),
        template.body.clone(),
        &available,
        &mut 10_000,
    )
    .unwrap();
    assert_eq!(entry.slots, vec![1]);
    let plan = entry.invocation(&mut 10_000).unwrap();
    assert_eq!(plan.scope(), &[Sort::Runtime, Sort::Type]);
    package.functions.push(entry.function);
    nir::phases::validate(&package).unwrap();
    let head = package
        .normal_forms
        .iter()
        .find(|head| head.role == nir::normal_forms::Role::Tuple)
        .unwrap()
        .declaration;
    let mut context = InferenceContext::default();
    let unused = context.fresh(Sort::Runtime);
    let mut session = Session::new(&package, &context, Budget::default()).unwrap();
    let output = session
        .enqueue_residual(
            &mut context,
            &plan,
            &[I::Meta(unused), I::Stable(Term::Primitive(Primitive::U8))],
        )
        .unwrap();
    let expected = Term::NormalForm {
        head,
        sort: Sort::Type,
        arguments: vec![Term::TypeListValue(vec![
            Term::Primitive(Primitive::U8),
            Term::Primitive(Primitive::Bool),
        ])],
    };
    assert!(
        matches!(session.resume(&mut context,output).unwrap(),State::Complete(ty) if *ty==expected)
    );
    assert!(
        !session
            .events()
            .iter()
            .any(|event| matches!(event,Event::EnterFunction(id) if *id==head)),
        "forming a normal head must not execute Tuple's body"
    );
    let subject = nir::DeclarationId {
        package: u64::MAX,
        local: 1,
    };
    let refinement = elaboration::gradual::Refinement {
        subject,
        requirement: elaboration::ptc::Formula::kind(
            Term::Rigid {
                declaration: subject,
                sort: Sort::Type,
            },
            elaboration::ptc::TypeKind::Tuple,
        ),
    };
    let types = elaboration::ptc::Context::from_package(&package).unwrap();
    let description = elaboration::gradual::Description::Known(I::Meta(output));
    assert!(matches!(
        refinement
            .check(
                &description,
                &context,
                &types,
                &mut elaboration::ptc::Budget::default()
            )
            .unwrap(),
        elaboration::gradual::RefinementCheck::Checked(elaboration::ptc::Outcome::Entailed(_))
    ));
    let scalar =
        elaboration::gradual::Description::Known(I::Stable(Term::Primitive(Primitive::Bool)));
    assert!(matches!(
        refinement
            .check(
                &scalar,
                &context,
                &types,
                &mut elaboration::ptc::Budget::default()
            )
            .unwrap(),
        elaboration::gradual::RefinementCheck::Checked(elaboration::ptc::Outcome::NotEntailed(_))
    ));
}

#[test]
fn demanded_type_computations_drive_shared_dependencies_without_replay() {
    use elaboration::type_computations::{Error, Input, Session, State};
    use elaboration::{InferenceContext, InferenceTerm as I};
    use nir::{Primitive, Sort, Term};
    let package = compile(
        "typealias Type=.Type'builtin;
        comptime fn Select(flag:bool)->Type {if flag {bool} else {.u8'builtin}}
        comptime fn Left(T:Type)->Type {T}
        comptime fn Right(T:Type)->Type {T}
        comptime fn Join(A:Type,B:Type)->Type {A}
        comptime fn Unused()->Type {Unused()}",
    );
    let type_input = |value| Input {
        ty: I::Stable(Term::Primitive(Primitive::Type)),
        value,
    };
    let mut context = InferenceContext::default();
    let flag = context.fresh(Sort::ComptimeValue);
    let mut session = Session::new(&package, &context, Budget::default()).unwrap();
    let first = session
        .enqueue(
            &mut context,
            id(&package, "Select"),
            vec![Input {
                ty: I::Stable(Term::Primitive(Primitive::Bool)),
                value: I::Meta(flag),
            }],
        )
        .unwrap();
    let left = session
        .enqueue(
            &mut context,
            id(&package, "Left"),
            vec![type_input(I::Meta(first))],
        )
        .unwrap();
    let right = session
        .enqueue(
            &mut context,
            id(&package, "Right"),
            vec![type_input(I::Meta(first))],
        )
        .unwrap();
    let output = session
        .enqueue(
            &mut context,
            id(&package, "Join"),
            vec![type_input(I::Meta(left)), type_input(I::Meta(right))],
        )
        .unwrap();
    let unused = session
        .enqueue(&mut context, id(&package, "Unused"), vec![])
        .unwrap();
    assert!(matches!(
        session
            .resume_dependencies(&mut context, output, &mut 100)
            .unwrap(),
        State::Waiting(_)
    ));
    assert!(session.events().is_empty());
    context.assign(flag, I::Stable(Term::Bool(true))).unwrap();
    assert!(matches!(
        session.resume_dependencies(&mut context, output, &mut 3),
        Err(Error::SchedulingBudget)
    ));
    assert!(
        session.events().is_empty(),
        "planning must finish before invocation"
    );
    assert!(
        matches!(session.resume_dependencies(&mut context,output,&mut 100).unwrap(),State::Complete(ty) if *ty==Term::Primitive(Primitive::Bool))
    );
    let entered = session
        .events()
        .iter()
        .filter_map(|event| match event {
            Event::EnterFunction(id) => Some(*id),
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(
        entered,
        vec![
            id(&package, "Select"),
            id(&package, "Left"),
            id(&package, "Right"),
            id(&package, "Join")
        ]
    );
    assert!(matches!(session.state(unused), Some(State::Waiting(_))));
    let events = session.events().len();
    session
        .resume_dependencies(&mut context, output, &mut 0)
        .unwrap();
    assert_eq!(session.events().len(), events);
}

#[test]
fn demanded_type_computations_propagate_failure_and_preflight_cycles() {
    use elaboration::type_computations::{Error, Input, Session, State};
    use elaboration::{InferenceContext, InferenceTerm as I};
    use nir::{Primitive, Sort, Term};
    let package = compile(
        "typealias Type=.Type'builtin;
        comptime fn Poison()->Type {Poison()}
        comptime fn Pass(T:Type)->Type {T}
        comptime fn Join(A:Type,B:Type)->Type {A}
        comptime fn Ready()->Type {bool}",
    );
    let input = |value| Input {
        ty: I::Stable(Term::Primitive(Primitive::Type)),
        value,
    };
    let mut context = InferenceContext::default();
    let mut session = Session::new(
        &package,
        &context,
        Budget {
            steps: 10_000,
            depth: 8,
        },
    )
    .unwrap();
    let poison = session
        .enqueue(&mut context, id(&package, "Poison"), vec![])
        .unwrap();
    let output = session
        .enqueue(
            &mut context,
            id(&package, "Pass"),
            vec![input(I::Meta(poison))],
        )
        .unwrap();
    assert!(
        matches!(session.resume_dependencies(&mut context,output,&mut 100).unwrap(),State::Failed(Error::DependencyFailed(id)) if *id==poison)
    );
    assert!(!session.events().iter().any(
        |event| matches!(event,Event::EnterFunction(function) if *function==id(&package,"Pass"))
    ));
    let events = session.events().len();
    session
        .resume_dependencies(&mut context, output, &mut 0)
        .unwrap();
    assert_eq!(session.events().len(), events);
    let ready = session
        .enqueue(&mut context, id(&package, "Ready"), vec![])
        .unwrap();
    let alias = context.fresh(Sort::Type);
    let a = session
        .enqueue(
            &mut context,
            id(&package, "Pass"),
            vec![input(I::Meta(alias))],
        )
        .unwrap();
    let b = session
        .enqueue(&mut context, id(&package, "Pass"), vec![input(I::Meta(a))])
        .unwrap();
    context.assign(alias, I::Meta(b)).unwrap();
    let cycle = session
        .enqueue(
            &mut context,
            id(&package, "Join"),
            vec![input(I::Meta(ready)), input(I::Meta(a))],
        )
        .unwrap();
    assert!(matches!(
        session
            .resume_dependencies(&mut context, cycle, &mut 100)
            .unwrap(),
        State::Failed(Error::DependencyCycle(_))
    ));
    assert_eq!(
        session.events().len(),
        events,
        "cyclic demand must not execute its ready sibling"
    );
    assert!(matches!(session.state(ready), Some(State::Waiting(_))));
    assert!(
        matches!(session.resume_dependencies(&mut context,ready,&mut 100).unwrap(),State::Complete(ty) if *ty==Term::Primitive(Primitive::Bool))
    );
}

#[test]
fn failed_type_demands_do_not_execute_unneeded_siblings() {
    use elaboration::type_computations::{Error, Input, Session, State};
    use elaboration::{InferenceContext, InferenceTerm as I};
    use nir::{Primitive, Term};
    let package = compile(
        "typealias Type=.Type'builtin;
        comptime fn Poison()->Type {Poison()}
        comptime fn Ready()->Type {bool}
        comptime fn Pass(T:Type)->Type {T}
        comptime fn Join(A:Type,B:Type)->Type {A}",
    );
    let input = |value| Input {
        ty: I::Stable(Term::Primitive(Primitive::Type)),
        value,
    };
    for previously_failed in [false, true] {
        let mut context = InferenceContext::default();
        let mut session = Session::new(
            &package,
            &context,
            Budget {
                steps: 10_000,
                depth: 8,
            },
        )
        .unwrap();
        let poison = session
            .enqueue(&mut context, id(&package, "Poison"), vec![])
            .unwrap();
        if previously_failed {
            assert!(matches!(
                session.resume(&mut context, poison).unwrap(),
                State::Failed(_)
            ));
        }
        let (forwarded, ready) = if previously_failed {
            // Cached failure must be found even with an earlier ready sibling.
            let ready = session
                .enqueue(&mut context, id(&package, "Ready"), vec![])
                .unwrap();
            let forwarded = session
                .enqueue(
                    &mut context,
                    id(&package, "Pass"),
                    vec![input(I::Meta(poison))],
                )
                .unwrap();
            (forwarded, ready)
        } else {
            let forwarded = session
                .enqueue(
                    &mut context,
                    id(&package, "Pass"),
                    vec![input(I::Meta(poison))],
                )
                .unwrap();
            let ready = session
                .enqueue(&mut context, id(&package, "Ready"), vec![])
                .unwrap();
            (forwarded, ready)
        };
        let output = session
            .enqueue(
                &mut context,
                id(&package, "Join"),
                vec![input(I::Meta(forwarded)), input(I::Meta(ready))],
            )
            .unwrap();
        assert!(
            matches!(session.resume_dependencies(&mut context,output,&mut 100).unwrap(),State::Failed(Error::DependencyFailed(failed)) if *failed==forwarded)
        );
        assert!(
            matches!(session.state(forwarded),Some(State::Failed(Error::DependencyFailed(failed))) if *failed==poison)
        );
        assert!(matches!(session.state(ready), Some(State::Waiting(_))));
        assert!(!session.events().iter().any(|event|matches!(event,Event::EnterFunction(function) if *function==id(&package,"Ready") || *function==id(&package,"Pass") || *function==id(&package,"Join"))));
        // A skipped sibling remains independently usable, rather than inheriting
        // a failure from a computation on which it never depended.
        assert!(
            matches!(session.resume_dependencies(&mut context,ready,&mut 100).unwrap(),State::Complete(ty) if *ty==Term::Primitive(Primitive::Bool))
        );
    }
}

#[test]
fn deferred_type_descriptions_wait_for_invocation_without_becoming_any() {
    use elaboration::gradual::{self, Compatibility as C, Description as D};
    use elaboration::ptc::{Budget as ProofBudget, Context, Outcome};
    use elaboration::type_computations::{Input, Session};
    use elaboration::{InferenceContext, InferenceTerm as I};
    use nir::{Primitive, Sort, Term};
    let package = compile(
        "typealias Type=.Type'builtin;
        comptime fn Select(flag:bool)->Type {if flag {bool} else {.u8'builtin}}",
    );
    let mut context = InferenceContext::default();
    let flag = context.fresh(Sort::ComptimeValue);
    let mut session = Session::new(&package, &context, Budget::default()).unwrap();
    let output = session
        .enqueue(
            &mut context,
            id(&package, "Select"),
            vec![Input {
                ty: I::Stable(Term::Primitive(Primitive::Bool)),
                value: I::Meta(flag),
            }],
        )
        .unwrap();
    let description = D::Known(I::Meta(output));
    let types = Context::default();
    assert!(
        matches!(gradual::compatible(&description,&D::Any,&context,&types,&mut ProofBudget::default()).unwrap(),C::Waiting(ids) if ids.contains(&output))
    );
    assert!(session.events().is_empty());
    context.assign(flag, I::Stable(Term::Bool(false))).unwrap();
    session
        .resume_dependencies(&mut context, output, &mut 100)
        .unwrap();
    let byte = D::Known(I::Stable(Term::Primitive(Primitive::U8)));
    let boolean = D::Known(I::Stable(Term::Primitive(Primitive::Bool)));
    assert!(matches!(
        gradual::compatible(
            &description,
            &byte,
            &context,
            &types,
            &mut ProofBudget::default()
        )
        .unwrap(),
        C::Exact(Outcome::Entailed(_))
    ));
    assert!(matches!(
        gradual::compatible(
            &description,
            &boolean,
            &context,
            &types,
            &mut ProofBudget::default()
        )
        .unwrap(),
        C::Exact(Outcome::NotEntailed(_))
    ));
    assert!(matches!(
        gradual::compatible(
            &description,
            &D::Any,
            &context,
            &types,
            &mut ProofBudget::default()
        )
        .unwrap(),
        C::Gradual
    ));
}

#[test]
fn completed_source_type_refinements_check_subjects_and_preserve_representation() {
    let package=compile("typealias Type=.Type'builtin;
        typealias Flag=refines {Itself == bool} bool;
        typealias Nested=refines {Itself == bool} (refines {Itself == bool} Flag);
        fn keep(value:refines {Itself == Flag} bool)->Nested {value}
        comptime fn Selected()->Type {refines {Itself == bool} bool}
        fn run()->bool {let value:refines {Itself == bool and not (Itself == .u8'builtin)} bool=true;keep(value)}");
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    let mut vm = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    assert_eq!(
        vm.invoke(id(&package, "Selected"), vec![]).unwrap(),
        Value::Type(nir::Term::Primitive(nir::Primitive::Bool))
    );
    for source in [
        "typealias Bad=refines {Itself == .u8'builtin} bool;fn run(value:Bad) {}",
        "fn run(value:refines {false} bool) {}",
        "typealias Bad=refines {1 == 2} bool;fn run(value:Bad) {}",
        "fn run(value:Itself) {}",
    ] {
        assert!(
            compile_with_protocols(source, &Default::default()).is_err(),
            "{source}"
        );
    }
}

#[test]
fn completed_source_type_refinements_keep_tuple_identity_and_lexical_subjects() {
    let source = "typealias Type=.Type'builtin;
        pure comptime fn List<T>->Type {List<T>}
        pure comptime fn Tuple<...Es:List<Type>>->Type {Tuple<...Es>}
        typealias Pair=refines {Itself == Tuple<bool,.u8'builtin>} Tuple<bool,.u8'builtin>;
        typealias Flag=refines {Itself == bool and
            (refines {Itself == .u8'builtin} .u8'builtin) == .u8'builtin and Itself == bool} bool;
        fn keep(value:Pair)->Pair {value}
        fn run()->Pair {let flag:Flag=true;keep((flag,7))}";
    let package = compile_with_source_bindings(
        source,
        &Default::default(),
        luna::protocols::type_constructors::Selectors {
            meta_list: Some("input.List"),
            tuple: Some("input.Tuple"),
            ..Default::default()
        },
    )
    .unwrap();
    let head = package
        .normal_forms
        .iter()
        .find(|head| head.role == nir::normal_forms::Role::Tuple)
        .unwrap()
        .declaration;
    let function = package.functions.iter().find(|f| f.name == "keep").unwrap();
    let nir::Term::Function { parameters, result } = function.signature.callable_signature() else {
        panic!("signature")
    };
    assert_eq!(parameters[0].ty, **result);
    assert!(
        matches!(&**result,nir::Term::NormalForm {head:actual,arguments,..} if *actual==head && arguments.len()==1 && matches!(arguments[0],nir::Term::TypeListValue(_)))
    );
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Tuple(vec![Value::Bool(true), Value::UnsignedInteger(7)])
    );
}

#[test]
fn completed_source_type_refinements_use_implementation_evidence() {
    let package = compile(
        "trait Marked {} struct Marker {} impl Marked for Marker {}
        fn run()->bool {let value:refines {Itself :- Marked} Marker=Marker {};true}",
    );
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    let error = compile_with_protocols(
        "trait Marked {} struct Marker {}
        fn run()->bool {let value:refines {Itself :- Marked} Marker=Marker {};true}",
        &Default::default(),
    )
    .unwrap_err();
    assert!(
        error.contains("type refinement requirement is not established"),
        "{error}"
    );
}

#[test]
fn source_signature_refinements_wait_for_the_complete_implementation_world() {
    for declarations in [
        "trait Marked {} struct Marker {} impl Marked for Marker {}",
        "impl Marked for Marker {} struct Marker {} trait Marked {}",
    ] {
        let source=format!("{declarations}
            trait Consumer {{fn consume(value:refines {{Itself :- Marked}} Marker)->bool;}}
            struct Service {{}}
            impl Consumer for Service {{fn consume(value:refines {{Itself :- Marked}} Marker)->bool {{true}}}}
            fn run()->bool {{Service.as(Consumer).consume(Marker {{}})}}");
        let package = compile(&source);
        assert_eq!(
            luna::execution::interpret(&package, "run", 100_000).unwrap(),
            Value::Bool(true)
        );
    }
    let missing = "trait Marked {} struct Marker {}
        trait Consumer {fn consume(value:refines {Itself :- Marked} Marker)->bool;}
        struct Service {} impl Consumer for Service {fn consume(value:Marker)->bool {true}}
        fn run()->bool {true}";
    let error = compile_with_protocols(missing, &Default::default()).unwrap_err();
    assert!(
        error.contains("type refinement requirement is not established"),
        "{error}"
    );
    let missing_impl = "trait Marked {} struct Marker {}
        trait Consumer {fn consume(value:Marker)->bool;}
        struct Service {} impl Consumer for Service {
            fn consume(value:refines {Itself :- Marked} Marker)->bool {true}
        } fn run()->bool {true}";
    let error = compile_with_protocols(missing_impl, &Default::default()).unwrap_err();
    assert!(
        error.contains("type refinement requirement is not established"),
        "{error}"
    );
    let denied = "trait Marked {} struct Marker {} impl Marked for Marker {}
        trait Consumer {fn consume(value:refines {not (Itself :- Marked)} Marker)->bool;}
        fn run()->bool {true}";
    let error = compile_with_protocols(denied, &Default::default()).unwrap_err();
    assert!(
        error.contains("type refinement requirement is not established"),
        "{error}"
    );
}

#[test]
fn executable_source_type_refinements_invoke_predicates_and_preserve_short_circuiting() {
    let prefix = "typealias Type=.Type'builtin;
        comptime fn accepted(T:Type)->bool {T == bool}
        comptime fn poison(T:Type)->bool {poison(T)}";
    let source = format!(
        "{prefix}
        typealias Flag=refines {{accepted(Itself)}} bool;
        typealias Lazy=refines {{accepted(Itself) or poison(Itself)}} Flag;
        typealias Branch=refines {{if accepted(Itself) {{true}} else {{poison(Itself)}}}} Lazy;
        fn run()->Branch {{let value:refines {{accepted(Itself) and (1 == 1)}} bool=true;value}}"
    );
    let package = compile(&source);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    let false_case =
        format!("{prefix} fn run(value:refines {{accepted(Itself)}} .u8'builtin) {{}}");
    let error = compile_with_protocols(&false_case, &Default::default()).unwrap_err();
    assert!(
        error.contains("type refinement predicate evaluated to false"),
        "{error}"
    );
    let selected = format!(
        "{prefix} fn run(value:refines {{accepted(Itself) or poison(Itself)}} .u8'builtin) {{}}"
    );
    let error = compile_with_protocols(&selected, &Default::default()).unwrap_err();
    assert!(
        error.contains("DepthExhausted") || error.contains("BudgetExhausted"),
        "{error}"
    );
    let wrong = "typealias Type=.Type'builtin;comptime fn bad(T:Type)->Type {T}
        fn run(value:refines {bad(Itself)} bool) {}";
    assert!(compile_with_protocols(wrong, &Default::default()).is_err());
}

#[test]
fn mixed_source_refinements_execute_decidable_trait_atoms_with_boolean_control_flow() {
    let prefix = "typealias Type=.Type'builtin;trait Marked {} impl Marked for bool {}
        comptime fn accepted(T:Type)->bool {T == bool}
        comptime fn poison(T:Type)->bool {poison(T)}";
    let package=compile(&format!("{prefix}
        typealias Flag=refines {{(Itself :- Marked) and accepted(Itself)}} bool;
        typealias Lazy=refines {{(Itself :- Marked) or poison(Itself)}} Flag;
        typealias Branch=refines {{if Itself :- Marked {{accepted(Itself)}} else {{poison(Itself)}}}} Lazy;
        fn run()->Branch {{true}}"));
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    let false_case = format!(
        "{prefix} fn run(value:refines {{not (Itself :- Marked) and poison(Itself)}} bool) {{}}"
    );
    let error = compile_with_protocols(&false_case, &Default::default()).unwrap_err();
    assert!(
        error.contains("type refinement predicate evaluated to false"),
        "{error}"
    );
    assert!(
        !error.contains("DepthExhausted"),
        "short circuit must skip poison: {error}"
    );
    let unknown = "typealias Type=.Type'builtin;trait Missing {}
        comptime fn accepted(T:Type)->bool {true}
        fn run(value:refines {(Itself :- Missing) and accepted(Itself)} bool) {}";
    let error = compile_with_protocols(unknown, &Default::default()).unwrap_err();
    assert!(
        error.contains("type refinement predicate evaluated to false"),
        "{error}"
    );
    // A completed world can supply a real exclusion proof for a closed type.
    let negative = unknown.replace("(Itself :- Missing) and", "not (Itself :- Missing) and");
    compile(&negative);
}

#[test]
fn mixed_source_refinements_use_explicit_negative_type_evidence() {
    let package = compile(
        "typealias Type=.Type'builtin;trait Marked {}
        comptime fn accepted()->bool {true}
        fn witness(value:T)->T where T, requires not (T :- Marked) {
            let checked:refines {not (Itself :- Marked) and accepted()} T=value;
            checked
        }
        fn run()->bool {true}",
    );
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    let missing = "typealias Type=.Type'builtin;trait Marked {}
        comptime fn accepted()->bool {true}
        fn witness(value:T)->T where T {
            let checked:refines {not (Itself :- Marked) and accepted()} T=value;
            checked
        }";
    let error = compile_with_protocols(missing, &Default::default()).unwrap_err();
    assert!(error.contains("no established Boolean value"), "{error}");
}

#[test]
fn abstract_type_inputs_flow_through_comptime_refinement_predicates() {
    let source="typealias Type=.Type'builtin;trait Marked {}
        comptime fn accepted(T:Type)->bool {true}
        comptime fn same(T:Type)->bool {T == T}
        comptime fn is_bool(T:Type)->bool {T == bool}
        comptime fn Echo(T:Type)->Type {T}
        fn forward(value:Echo(T))->Echo(T) where T {value}
        fn known(value:T)->T where T, requires T == bool {
            let checked:refines {is_bool(Itself)} T=value;checked
        }
        fn witness(value:T)->T where T, requires not (T :- Marked) {
            let checked:refines {not (Itself :- Marked) and same(Echo(Itself)) and accepted(Itself)} T=value;
            checked
        }
        fn run()->bool {known(forward(witness(true)))}";
    let package = compile(source);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    let unresolved = "typealias Type=.Type'builtin;
        comptime fn is_bool(T:Type)->bool {T == bool}
        fn witness(value:T)->T where T {let checked:refines {is_bool(Itself)} T=value;checked}";
    let error = compile_with_protocols(unresolved, &Default::default()).unwrap_err();
    assert!(
        error.contains("TypeContractUnresolved"),
        "must not guess false: {error}"
    );
}

#[test]
fn abstract_type_values_require_a_scope_and_cannot_discriminate_or_freeze() {
    let package = compile(
        "typealias Type=.Type'builtin;
        pure comptime fn Head<T>->Type {T}
        comptime fn Pass(T:Type)->Type {T}
        comptime fn Staged(comptime T:Type)->Type {T}
        comptime fn same(A:Type,B:Type)->bool {A == B}
        comptime fn inspect(T:Type)->bool {T match {Head<X> => true,_=>false}}
        comptime fn wildcard(T:Type)->bool {T match {_=>true}}",
    );
    let a = nir::DeclarationId {
        package: 77,
        local: 1,
    };
    let b = nir::DeclarationId {
        package: 77,
        local: 2,
    };
    let mut default = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    assert_eq!(
        default
            .invoke(id(&package, "Pass"), vec![Value::TypeParameter(a)])
            .unwrap_err()
            .kind,
        ErrorKind::Type
    );
    assert!(
        Interpreter::new(&package, Budget::default())
            .unwrap()
            .with_abstract_type_parameters(&[a])
            .is_err()
    );
    let mut scoped = Interpreter::for_comptime(&package, Budget::default())
        .unwrap()
        .with_abstract_type_parameters(&[a, b])
        .unwrap();
    assert_eq!(
        scoped
            .invoke(id(&package, "Pass"), vec![Value::TypeParameter(a)])
            .unwrap(),
        Value::TypeParameter(a)
    );
    assert_eq!(
        scoped
            .invoke(id(&package, "Staged"), vec![Value::TypeParameter(a)])
            .unwrap(),
        Value::TypeParameter(a)
    );
    assert_eq!(
        scoped
            .invoke(
                id(&package, "same"),
                vec![Value::TypeParameter(a), Value::TypeParameter(a)]
            )
            .unwrap(),
        Value::Bool(true)
    );
    assert_eq!(
        scoped
            .invoke(
                id(&package, "same"),
                vec![Value::TypeParameter(a), Value::TypeParameter(b)]
            )
            .unwrap_err()
            .kind,
        ErrorKind::TypeContractUnresolved
    );
    assert_eq!(
        scoped
            .invoke(id(&package, "inspect"), vec![Value::TypeParameter(a)])
            .unwrap_err()
            .kind,
        ErrorKind::TypeContractUnresolved
    );
    assert_eq!(
        scoped
            .invoke(id(&package, "wildcard"), vec![Value::TypeParameter(a)])
            .unwrap(),
        Value::Bool(true)
    );
    let foreign = nir::DeclarationId {
        package: 77,
        local: 3,
    };
    assert_eq!(
        scoped
            .invoke(id(&package, "Pass"), vec![Value::TypeParameter(foreign)])
            .unwrap_err()
            .kind,
        ErrorKind::Type
    );
    assert!(
        Value::TypeParameter(a)
            .into_normal_term(&mut comptime_runtime::Budget {
                steps: 100,
                max_limbs: 128
            })
            .is_err()
    );
    assert!(
        Value::TypeParameter(a)
            .to_string()
            .starts_with("(abstract-type-input")
    );
}

#[test]
fn abstract_compound_type_descriptions_preserve_tuple_heads_and_scope() {
    let source="typealias Type=.Type'builtin;
        pure comptime fn List<T>->Type {List<T>}
        pure comptime fn Tuple<...Es:List<Type>>->Type {Tuple<...Es>}
        pure comptime fn Identity<T>->Type {T}
        comptime fn Pair(T:Type)->Type {Tuple<T,bool>}
        comptime fn Pointer(T:Type)->Type {*T}
        comptime fn Echo(T:Type)->Type {T}
        comptime fn same(A:Type,B:Type)->bool {A == B}
        comptime fn inspect(T:Type)->bool {T match {Tuple<Es> => true,_=>false}}
        comptime fn First(T:Type)->Type {T match {Tuple<Es> => Es[0],_=>T}}
        comptime fn inspect_first(T:Type)->bool {inspect(First(T))}
        fn keep(value:Echo(Tuple<T,bool>))->Tuple<T,bool> where T {
            let checked:refines {same(Pair(T),Itself) and same(First(Itself),T)} Tuple<T,bool> = value;
            checked
        }
        fn run()->Tuple<bool,bool> {keep((true,false))}";
    let package = compile_with_source_bindings(
        source,
        &Default::default(),
        luna::protocols::type_constructors::Selectors {
            meta_list: Some("input.List"),
            tuple: Some("input.Tuple"),
            ..Default::default()
        },
    )
    .unwrap();
    let head = package
        .normal_forms
        .iter()
        .find(|h| h.role == nir::normal_forms::Role::Tuple)
        .unwrap()
        .declaration;
    let parameter = nir::DeclarationId {
        package: 77,
        local: 1,
    };
    let rigid = nir::Term::Rigid {
        declaration: parameter,
        sort: nir::Sort::Type,
    };
    let pair = nir::Term::NormalForm {
        head,
        sort: nir::Sort::Type,
        arguments: vec![nir::Term::TypeListValue(vec![
            rigid.clone(),
            nir::Term::Primitive(nir::Primitive::Bool),
        ])],
    };
    let mut scoped = Interpreter::for_comptime(&package, Budget::default())
        .unwrap()
        .with_abstract_type_parameters(&[parameter])
        .unwrap();
    assert_eq!(
        scoped
            .invoke(id(&package, "Pair"), vec![Value::TypeParameter(parameter)])
            .unwrap(),
        Value::Type(pair.clone())
    );
    assert_eq!(
        scoped
            .invoke(
                id(&package, "Pointer"),
                vec![Value::TypeParameter(parameter)]
            )
            .unwrap(),
        Value::Type(nir::Term::Pointer(Box::new(rigid)))
    );
    assert_eq!(
        scoped
            .invoke(id(&package, "Echo"), vec![Value::Type(pair.clone())])
            .unwrap(),
        Value::Type(pair.clone())
    );
    assert_eq!(
        scoped
            .invoke(
                id(&package, "same"),
                vec![Value::Type(pair.clone()), Value::Type(pair.clone())]
            )
            .unwrap(),
        Value::Bool(true)
    );
    assert_eq!(
        scoped
            .invoke(id(&package, "inspect"), vec![Value::Type(pair.clone())])
            .unwrap(),
        Value::Bool(true)
    );
    assert_eq!(
        scoped
            .invoke(
                id(&package, "inspect_first"),
                vec![Value::Type(pair.clone())]
            )
            .unwrap_err()
            .kind,
        ErrorKind::TypeContractUnresolved
    );
    let foreign = nir::Term::Pointer(Box::new(nir::Term::Rigid {
        declaration: nir::DeclarationId {
            package: 77,
            local: 2,
        },
        sort: nir::Sort::Type,
    }));
    assert_eq!(
        scoped
            .invoke(id(&package, "Echo"), vec![Value::Type(foreign)])
            .unwrap_err()
            .kind,
        ErrorKind::Type
    );
    let identity = id(&package, "Identity");
    let opaque = nir::Term::NormalForm {
        head: identity,
        sort: nir::Sort::Type,
        arguments: vec![pair.clone()],
    };
    assert_eq!(
        scoped
            .invoke(
                id(&package, "same"),
                vec![Value::Type(opaque), Value::Type(pair.clone())]
            )
            .unwrap_err()
            .kind,
        ErrorKind::TypeContractUnresolved
    );
    let mut closed = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    assert_eq!(
        closed
            .invoke(id(&package, "Echo"), vec![Value::Type(pair.clone())])
            .unwrap_err()
            .kind,
        ErrorKind::Type
    );
    assert!(Value::Type(pair.clone()).immutable_copy_work().is_none());
    assert!(
        Value::Type(pair)
            .into_normal_term(&mut comptime_runtime::Budget {
                steps: 1000,
                max_limbs: 128
            })
            .is_err()
    );
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Tuple(vec![Value::Bool(true), Value::Bool(false)])
    );
}

#[test]
fn abstract_type_admission_preserves_nested_formation_requirements() {
    use comptime_interpretor::ContractOutcome;
    use nir::{DeclarationId, Primitive, Sort, Term};
    let source = "typealias Type=.Type'builtin;
        pure comptime fn List<T>->Type {List<T>}
        pure comptime fn Tuple<...Es:List<Type>>->Type {Tuple<...Es>}
        pure comptime fn Checked<T>->Type where requires T == bool {T}
        struct Nominal where T, requires T == bool {}
        effect read()->T where T, requires T == bool;
        comptime fn elements(T:Type)->List<Type> {T match {Tuple<Es> => Es,_=>elements(T)}}";
    let package = compile_with_source_bindings(
        source,
        &Default::default(),
        luna::protocols::type_constructors::Selectors {
            meta_list: Some("input.List"),
            tuple: Some("input.Tuple"),
            ..Default::default()
        },
    )
    .unwrap();
    let parameter = DeclarationId {
        package: 77,
        local: 1,
    };
    let rigid = Term::Rigid {
        declaration: parameter,
        sort: Sort::Type,
    };
    let tuple = Term::NormalForm {
        head: id(&package, "Tuple"),
        sort: Sort::Type,
        arguments: vec![Term::TypeListValue(vec![
            rigid.clone(),
            Term::Primitive(Primitive::Bool),
        ])],
    };
    let list = Term::NormalForm {
        head: id(&package, "List"),
        sort: Sort::Type,
        arguments: vec![Term::Primitive(Primitive::Type)],
    };
    let mut scoped = Interpreter::for_comptime(&package, Budget::default())
        .unwrap()
        .with_abstract_type_parameters(&[parameter])
        .unwrap();
    scoped
        .validate_immutable_input(
            &Value::Type(tuple.clone()),
            &Term::Primitive(Primitive::Type),
        )
        .unwrap();
    scoped
        .validate_immutable_input(
            &execution_support::type_list_value(&package, vec![rigid.clone(), tuple.clone()]),
            &list,
        )
        .unwrap();
    let checked = Term::NormalForm {
        head: id(&package, "Checked"),
        sort: Sort::Type,
        arguments: vec![rigid.clone()],
    };
    let nominal = Term::Nominal {
        declaration: package
            .structs
            .iter()
            .find(|s| s.name == "Nominal")
            .unwrap()
            .declaration,
        arguments: vec![rigid.clone()],
    };
    let expected =
        nir::program::TypePredicate::Equal(rigid.clone(), Term::Primitive(Primitive::Bool));
    let prove = |predicate: &nir::program::TypePredicate| {
        if *predicate == expected {
            ContractOutcome::Satisfied
        } else {
            ContractOutcome::Unknown
        }
    };
    let mut proven = Interpreter::for_comptime(&package, Budget::default())
        .unwrap()
        .with_abstract_type_parameters(&[parameter])
        .unwrap()
        .with_type_solver(&prove);
    let computation = Term::computation(
        vec![nir::effects::Operation {
            declaration: package
                .effects
                .iter()
                .find(|e| e.name == "read")
                .unwrap()
                .declaration,
            arguments: vec![rigid.clone()],
        }],
        Term::Primitive(Primitive::Bool),
    );
    let callable = Term::Function {
        parameters: vec![],
        result: Box::new(computation),
    };
    for constrained in [checked, nominal, callable] {
        let nested = execution_support::type_list_value(
            &package,
            vec![Term::Pointer(Box::new(constrained))],
        );
        assert_eq!(
            scoped
                .validate_immutable_input(&nested, &list)
                .unwrap_err()
                .kind,
            ErrorKind::TypeContractUnresolved
        );
        proven.validate_immutable_input(&nested, &list).unwrap();
    }
    // Permission to transport a Type description never admits runtime storage of T.
    assert_eq!(
        proven
            .validate_immutable_input(&Value::Bool(true), &rigid)
            .unwrap_err()
            .kind,
        ErrorKind::Type
    );
    let foreign = Term::Rigid {
        declaration: DeclarationId {
            package: 77,
            local: 2,
        },
        sort: Sort::Type,
    };
    assert_eq!(
        proven
            .validate_immutable_input(
                &execution_support::type_list_value(&package, vec![foreign]),
                &list
            )
            .unwrap_err()
            .kind,
        ErrorKind::Type
    );
    scoped
        .validate_immutable_input(&Value::Type(tuple), &Term::Primitive(Primitive::Type))
        .unwrap();
}

#[test]
fn scoped_type_computations_resume_with_declaration_evidence_without_replay() {
    use comptime_interpretor::ContractOutcome;
    use elaboration::type_computations::{Error, Input, Session, State};
    use elaboration::{InferenceContext, InferenceTerm as I};
    use nir::{DeclarationId, Primitive, Sort, Term};
    let source = "typealias Type=.Type'builtin;
        pure comptime fn List<T>->Type {List<T>}
        pure comptime fn Tuple<...Es:List<Type>>->Type {Tuple<...Es>}
        comptime fn Selected(T:Type)->Type {if T == bool {Tuple<T,bool>} else {.u8'builtin}}
        comptime fn First(T:Type)->Type {T match {Tuple<Es> => Es[0],_=>T}}
        comptime fn Pass(T:Type)->Type {T}";
    let package = compile_with_source_bindings(
        source,
        &Default::default(),
        luna::protocols::type_constructors::Selectors {
            meta_list: Some("input.List"),
            tuple: Some("input.Tuple"),
            ..Default::default()
        },
    )
    .unwrap();
    let declaration = DeclarationId {
        package: 77,
        local: 1,
    };
    let rigid = Term::Rigid {
        declaration,
        sort: Sort::Type,
    };
    let expected =
        nir::program::TypePredicate::Equal(rigid.clone(), Term::Primitive(Primitive::Bool));
    let prove = |predicate: &nir::program::TypePredicate| {
        if *predicate == expected {
            ContractOutcome::Satisfied
        } else {
            ContractOutcome::Unknown
        }
    };
    let argument = |value| {
        vec![Input {
            ty: I::Stable(Term::Primitive(Primitive::Type)),
            value,
        }]
    };
    let mut context = InferenceContext::default();
    let input = context.fresh(Sort::Type);
    let mut session = Session::new_in_scope(
        &package,
        &context,
        Budget::default(),
        &[],
        &[declaration],
        Some(&prove),
    )
    .unwrap();
    let selected = session
        .enqueue(
            &mut context,
            id(&package, "Selected"),
            argument(I::Meta(input)),
        )
        .unwrap();
    let first = session
        .enqueue(
            &mut context,
            id(&package, "First"),
            argument(I::Meta(selected)),
        )
        .unwrap();
    assert!(matches!(
        session
            .resume_dependencies(&mut context, first, &mut 100)
            .unwrap(),
        State::Waiting(_)
    ));
    assert!(session.events().is_empty());
    context.assign(input, I::Stable(rigid.clone())).unwrap();
    assert!(
        matches!(session.resume_dependencies(&mut context,first,&mut 100).unwrap(),State::Complete(ty) if *ty==rigid)
    );
    let tuple = Term::NormalForm {
        head: id(&package, "Tuple"),
        sort: Sort::Type,
        arguments: vec![Term::TypeListValue(vec![
            rigid.clone(),
            Term::Primitive(Primitive::Bool),
        ])],
    };
    assert_eq!(context.freeze(&I::Meta(selected)).unwrap(), tuple);
    let before = session.remaining_steps();
    let events = session.events().len();
    session
        .resume_dependencies(&mut context, first, &mut 0)
        .unwrap();
    assert_eq!(session.events().len(), events);
    assert_eq!(session.remaining_steps(), before);
    // The same registered input without the declaration fact cannot select a branch.
    let mut other = InferenceContext::default();
    let mut unknown = Session::new_in_scope(
        &package,
        &other,
        Budget::default(),
        &[],
        &[declaration],
        None,
    )
    .unwrap();
    let output = unknown
        .enqueue(
            &mut other,
            id(&package, "Selected"),
            argument(I::Stable(rigid.clone())),
        )
        .unwrap();
    assert!(
        matches!(unknown.resume(&mut other,output).unwrap(),State::Failed(Error::Invocation(e)) if e.kind==ErrorKind::TypeContractUnresolved)
    );
    let events = unknown.events().len();
    unknown.resume(&mut other, output).unwrap();
    assert_eq!(unknown.events().len(), events);
    let foreign = Term::Rigid {
        declaration: DeclarationId {
            package: 77,
            local: 2,
        },
        sort: Sort::Type,
    };
    let rejected = unknown
        .enqueue(
            &mut other,
            id(&package, "Pass"),
            argument(I::Stable(foreign)),
        )
        .unwrap();
    assert!(
        matches!(unknown.resume(&mut other,rejected).unwrap(),State::Failed(Error::Invocation(e)) if e.kind==ErrorKind::Type)
    );
    let allowed = unknown
        .enqueue(
            &mut other,
            id(&package, "Pass"),
            argument(I::Stable(rigid.clone())),
        )
        .unwrap();
    assert!(
        matches!(unknown.resume(&mut other,allowed).unwrap(),State::Complete(ty) if *ty==rigid)
    );
}

#[test]
fn deferred_signature_tasks_wait_resolve_tuple_types_and_preserve_execution_order() {
    use elaboration::type_computations::{Error, Session, State};
    use elaboration::{InferenceContext, InferenceTerm as I};
    use nir::deferred_signatures::{Annotation as A, Input, Signature};
    use nir::type_computations::{Input as Argument, Invocation};
    use nir::{Primitive, Sort, Term};
    let source = "typealias Type=.Type'builtin;
        pure comptime fn List<T>->Type {List<T>}
        pure comptime fn Tuple<...Es:List<Type>>->Type {Tuple<...Es>}
        comptime fn First(es:List<Type>)->Type {es[0]}
        comptime fn Later(es:List<Type>)->Type {es[9]}
        fn runtime()->bool {true}";
    let package = compile_with_source_bindings(
        source,
        &Default::default(),
        luna::protocols::type_constructors::Selectors {
            meta_list: Some("input.List"),
            tuple: Some("input.Tuple"),
            ..Default::default()
        },
    )
    .unwrap();
    let list = Term::NormalForm {
        head: id(&package, "List"),
        sort: Sort::Type,
        arguments: vec![Term::Primitive(Primitive::Type)],
    };
    let nested = Term::NormalForm {
        head: id(&package, "Tuple"),
        sort: Sort::Type,
        arguments: vec![Term::TypeListValue(vec![
            Term::Primitive(Primitive::Bool),
            Term::Primitive(Primitive::U8),
        ])],
    };
    let invocation = |name| {
        Invocation::new(
            id(&package, name),
            vec![Sort::ComptimeValue, Sort::Runtime],
            vec![Argument {
                ty: list.clone(),
                value: Term::Bound {
                    depth: 0,
                    index: 0,
                    sort: Sort::ComptimeValue,
                },
            }],
            &mut 1000,
        )
        .unwrap()
    };
    let schema = |first, result, computations| {
        Signature::new(
            vec![
                Input {
                    sort: Sort::ComptimeValue,
                    annotation: A::Known(list.clone()),
                },
                Input {
                    sort: Sort::Runtime,
                    annotation: A::Computed(first),
                },
            ],
            A::Computed(result),
            computations,
            &mut 1000,
        )
        .unwrap()
    };
    let mut context = InferenceContext::default();
    let es = context.fresh(Sort::ComptimeValue);
    let runtime = context.fresh(Sort::Runtime);
    let mut session = Session::new(&package, &context, Budget::default()).unwrap();
    let before = session.to_string();
    let invalid = schema(0, 1, vec![invocation("First"), invocation("runtime")]);
    assert!(matches!(
        session.enqueue_signature(&mut context, invalid, &[I::Meta(es), I::Meta(runtime)]),
        Err(Error::InvalidTarget)
    ));
    assert_eq!(
        session.to_string(),
        before,
        "preflight must not enqueue a prefix of an invalid signature"
    );
    let mut task = session
        .enqueue_signature(
            &mut context,
            schema(0, 0, vec![invocation("First")]),
            &[I::Meta(es), I::Meta(runtime)],
        )
        .unwrap();
    assert!(
        matches!(session.resume_signature(&mut context,&mut task,&mut 1000).unwrap(),State::Waiting(inputs) if inputs.contains(&es) && !inputs.contains(&runtime))
    );
    assert!(session.events().is_empty());
    context
        .assign(es, I::Stable(Term::TypeListValue(vec![nested.clone()])))
        .unwrap();
    assert!(matches!(
        session.resume_signature(&mut context, &mut task, &mut 0),
        Err(Error::SchedulingBudget)
    ));
    assert!(session.events().is_empty());
    // Invocation may finish before publication runs out of structural fuel.
    for limit in 1..1000 {
        assert!(matches!(
            session.resume_signature(&mut context, &mut task, &mut { limit }),
            Err(Error::SchedulingBudget)
        ));
        if !session.events().is_empty() {
            break;
        }
    }
    assert_eq!(
        session
            .events()
            .iter()
            .filter(|e| matches!(e,Event::EnterFunction(f) if *f==id(&package,"First")))
            .count(),
        1
    );
    let State::Complete(signature) = session
        .resume_signature(&mut context, &mut task, &mut 1000)
        .unwrap()
    else {
        panic!("signature")
    };
    let Term::Function { parameters, result } = signature else {
        panic!("function")
    };
    assert_eq!(parameters[0].sort, Sort::ComptimeValue);
    assert_eq!(parameters[1].ty, nested);
    assert_eq!(**result, nested);
    assert_eq!(
        session
            .events()
            .iter()
            .filter(|e| matches!(e,Event::EnterFunction(f) if *f==id(&package,"First")))
            .count(),
        1
    );
    let events = session.events().len();
    session
        .resume_signature(&mut context, &mut task, &mut 0)
        .unwrap();
    assert_eq!(session.events().len(), events);
    assert!(
        task.to_string()
            .starts_with("(signature-task (deferred-signature")
    );
    let mut foreign = Session::new(&package, &context, Budget::default()).unwrap();
    assert!(matches!(
        foreign.resume_signature(&mut context, &mut task, &mut 1000),
        Err(Error::ForeignSession)
    ));
    for values in [vec![], vec![Term::Primitive(Primitive::Bool)]] {
        let empty = values.is_empty();
        let mut context = InferenceContext::default();
        let runtime = context.fresh(Sort::Runtime);
        let mut session = Session::new(&package, &context, Budget::default()).unwrap();
        // Storage order differs from annotation order: First must still run first.
        let mut task = session
            .enqueue_signature(
                &mut context,
                schema(1, 0, vec![invocation("Later"), invocation("First")]),
                &[I::Stable(Term::TypeListValue(values)), I::Meta(runtime)],
            )
            .unwrap();
        let first = session
            .resume_signature_annotation(&mut context, &mut task, 1, &mut 1000)
            .unwrap();
        if empty {
            assert!(matches!(
                first,
                elaboration::type_computations::AnnotationState::Failed(Error::DependencyFailed(_))
            ));
        } else {
            assert!(matches!(
                first,
                elaboration::type_computations::AnnotationState::Ready(Term::Primitive(
                    Primitive::Bool
                ))
            ));
        }
        assert_eq!(
            session
                .events()
                .iter()
                .filter_map(|event| match event {
                    Event::EnterFunction(f) => Some(*f),
                    _ => None,
                })
                .collect::<Vec<_>>(),
            vec![id(&package, "First")]
        );
        assert!(matches!(
            session
                .resume_signature(&mut context, &mut task, &mut 1000)
                .unwrap(),
            State::Failed(Error::DependencyFailed(_))
        ));
        let entered = session
            .events()
            .iter()
            .filter_map(|event| match event {
                Event::EnterFunction(f) => Some(*f),
                _ => None,
            })
            .collect::<Vec<_>>();
        let expected = if empty {
            vec![id(&package, "First")]
        } else {
            vec![id(&package, "First"), id(&package, "Later")]
        };
        assert_eq!(entered, expected);
        let events = session.events().len();
        session
            .resume_signature(&mut context, &mut task, &mut 0)
            .unwrap();
        assert_eq!(session.events().len(), events);
        assert!(matches!(
            session
                .resume_signature_annotation(&mut context, &mut task, 0, &mut 0)
                .unwrap(),
            elaboration::type_computations::AnnotationState::Failed(Error::DependencyFailed(_))
        ));
        assert_eq!(session.events().len(), events);
    }
}

#[test]
fn type_computations_charge_input_expansion_before_invocation() {
    use elaboration::type_computations::{Error, Input, Session, State};
    use elaboration::{InferenceContext, InferenceError, InferenceTerm as I};
    use nir::{Parameter, Primitive, Sort, Term};
    let package = compile("typealias Type=.Type'builtin;comptime fn Pass(T:Type)->Type {T}");
    let wide = Term::Function {
        parameters: vec![
            Parameter {
                sort: Sort::Runtime,
                ty: Term::Primitive(Primitive::Bool)
            };
            1024
        ],
        result: Box::new(Term::Primitive(Primitive::Bool)),
    };
    let mut context = InferenceContext::default();
    let mut session = Session::new(
        &package,
        &context,
        Budget {
            steps: 128,
            depth: 128,
        },
    )
    .unwrap();
    let output = session
        .enqueue(
            &mut context,
            id(&package, "Pass"),
            vec![Input {
                ty: I::Stable(Term::Primitive(Primitive::Type)),
                value: I::Stable(wide),
            }],
        )
        .unwrap();
    assert!(matches!(
        session.resume(&mut context, output).unwrap(),
        State::Failed(Error::Inference(InferenceError::Budget))
    ));
    assert!(
        session.events().is_empty(),
        "argument preparation must fail before executing the function"
    );
    let remaining = session.remaining_steps();
    assert!(matches!(
        session.resume(&mut context, output).unwrap(),
        State::Failed(_)
    ));
    assert_eq!(remaining, session.remaining_steps());
    assert!(session.events().is_empty());
    assert_eq!(
        context.freeze(&I::Meta(output)),
        Err(InferenceError::Unresolved(output))
    );
}

#[test]
fn deferred_signature_annotations_advance_only_the_demanded_prefix() {
    use elaboration::type_computations::{AnnotationState as S, Error, Session, State};
    use elaboration::{InferenceContext, InferenceTerm as I};
    use nir::deferred_signatures::{Annotation as A, Input, Signature};
    use nir::type_computations::{Input as Argument, Invocation};
    use nir::{Primitive, Sort, Term};
    let package = compile(
        "typealias Type=.Type'builtin;
        comptime fn First(T:Type)->Type {T}
        comptime fn Later(T:Type)->Type {T}",
    );
    // Two staged inputs interleaved with their runtime consumers. The second
    // Type need not be inferred before checking the first runtime argument.
    let scope = vec![Sort::Type, Sort::Runtime, Sort::Type, Sort::Runtime];
    let invocation = |name, slot| {
        Invocation::new(
            id(&package, name),
            scope.clone(),
            vec![Argument {
                ty: Term::Primitive(Primitive::Type),
                value: Term::Bound {
                    depth: 0,
                    index: slot,
                    sort: Sort::Type,
                },
            }],
            &mut 1000,
        )
        .unwrap()
    };
    let signature = Signature::new(
        vec![
            Input {
                sort: Sort::Type,
                annotation: A::Known(Term::Primitive(Primitive::Type)),
            },
            Input {
                sort: Sort::Runtime,
                annotation: A::Computed(1),
            },
            Input {
                sort: Sort::Type,
                annotation: A::Known(Term::Primitive(Primitive::Type)),
            },
            Input {
                sort: Sort::Runtime,
                annotation: A::Computed(0),
            },
        ],
        A::Computed(0),
        vec![invocation("Later", 2), invocation("First", 0)],
        &mut 1000,
    )
    .unwrap();
    let mut context = InferenceContext::default();
    let first = context.fresh(Sort::Type);
    let first_value = context.fresh(Sort::Runtime);
    let later = context.fresh(Sort::Type);
    let later_value = context.fresh(Sort::Runtime);
    let mut session = Session::new(&package, &context, Budget::default()).unwrap();
    let mut task = session
        .enqueue_signature(
            &mut context,
            signature,
            &[
                I::Meta(first),
                I::Meta(first_value),
                I::Meta(later),
                I::Meta(later_value),
            ],
        )
        .unwrap();
    assert!(matches!(
        session.resume_signature_annotation(&mut context, &mut task, 5, &mut 1000),
        Err(Error::InvalidAnnotation(5))
    ));
    assert!(matches!(
        session.resume_signature_annotation(&mut context, &mut task, 0, &mut 0),
        Err(Error::SchedulingBudget)
    ));
    assert!(session.events().is_empty());
    let ready = session
        .resume_signature_annotation(&mut context, &mut task, 0, &mut 1000)
        .unwrap();
    assert!(ready.to_string().starts_with("(annotation-ready "));
    assert!(matches!(ready, S::Ready(Term::Primitive(Primitive::Type))));
    let mut admitted = Vec::new();
    assert!(
        matches!(session.resume_signature_annotation_checked(&mut context,&mut task,3,&mut 1000,
        |slot,_,_| {admitted.push(slot);Ok::<(),String>(())}).unwrap(),
        S::Waiting(inputs) if inputs.len()==1 && inputs.contains(&first))
    );
    assert_eq!(
        admitted,
        vec![0],
        "waiting annotations cannot be admitted or bypassed"
    );
    assert!(
        matches!(session.resume_signature_annotation(&mut context,&mut task,2,&mut 1000).unwrap(),
        S::Waiting(inputs) if inputs.len()==1 && inputs.contains(&first)),
        "known later annotation must not bypass an earlier waiting computation"
    );
    assert!(session.events().is_empty());
    context
        .assign(first, I::Stable(Term::Primitive(Primitive::Bool)))
        .unwrap();
    assert!(matches!(
        session
            .resume_signature_annotation(&mut context, &mut task, 1, &mut 1000)
            .unwrap(),
        S::Ready(Term::Primitive(Primitive::Bool))
    ));
    let entered = |session: &Session<'_>| {
        session
            .events()
            .iter()
            .filter_map(|event| match event {
                Event::EnterFunction(id) => Some(*id),
                _ => None,
            })
            .collect::<Vec<_>>()
    };
    assert_eq!(entered(&session), vec![id(&package, "First")]);
    assert!(
        matches!(task.state(), State::Waiting(_)),
        "a resolved prefix is not a complete signature"
    );
    assert!(
        matches!(session.resume_signature_annotation(&mut context,&mut task,3,&mut 1000).unwrap(),
        S::Waiting(inputs) if inputs.len()==1 && inputs.contains(&later))
    );
    // Earlier results remain usable while a later annotation waits.
    assert!(matches!(
        session
            .resume_signature_annotation(&mut context, &mut task, 1, &mut 1000)
            .unwrap(),
        S::Ready(Term::Primitive(Primitive::Bool))
    ));
    assert_eq!(entered(&session), vec![id(&package, "First")]);
    let mut foreign = Session::new(&package, &context, Budget::default()).unwrap();
    assert!(matches!(
        foreign.resume_signature_annotation(&mut context, &mut task, 0, &mut 1000),
        Err(Error::ForeignSession)
    ));
    context
        .assign(later, I::Stable(Term::Primitive(Primitive::U8)))
        .unwrap();
    assert!(matches!(
        session
            .resume_signature_annotation(&mut context, &mut task, 4, &mut 1000)
            .unwrap(),
        S::Ready(Term::Primitive(Primitive::U8))
    ));
    assert_eq!(
        entered(&session),
        vec![id(&package, "First"), id(&package, "Later")]
    );
    let State::Complete(signature) = session
        .resume_signature(&mut context, &mut task, &mut 1000)
        .unwrap()
    else {
        panic!("signature")
    };
    let Term::Function { parameters, result } = signature else {
        panic!("function")
    };
    assert_eq!(parameters[1].ty, Term::Primitive(Primitive::Bool));
    assert_eq!(parameters[3].ty, Term::Primitive(Primitive::U8));
    assert_eq!(**result, Term::Primitive(Primitive::U8));
    assert!(matches!(
        session
            .resume_signature_annotation(&mut context, &mut task, 3, &mut 0)
            .unwrap(),
        S::Ready(Term::Primitive(Primitive::U8))
    ));
    assert_eq!(
        entered(&session),
        vec![id(&package, "First"), id(&package, "Later")]
    );
}

#[test]
fn explicit_comptime_type_inputs_flow_through_signature_computations() {
    let package=compile("typealias Type=.Type'builtin;
        comptime fn Echo(T:Type)->Type {T}
        fn identity(comptime T:Type,value:Echo(T))->Echo(T) {let checked:Echo(T)=value;checked}
        comptime fn Choose(T:Type)->Type {if T == bool {bool} else {.u8'builtin}}
        fn known(comptime T:Type,value:T)->T where requires T == bool {let checked:Choose(T)=value;checked}
        fn flag()->bool {known(bool,identity(bool,true))}
        fn byte()->.u8'builtin {identity(.u8'builtin,7)}");
    assert_eq!(
        luna::execution::interpret(&package, "flag", 100_000).unwrap(),
        Value::Bool(true)
    );
    assert_eq!(
        luna::execution::interpret(&package, "byte", 100_000).unwrap(),
        Value::UnsignedInteger(7)
    );
}

#[test]
fn explicit_comptime_type_signature_computations_preserve_slots_and_nested_binders() {
    use nir::{Primitive, Sort, Term};
    let source = "typealias Type=.Type'builtin;
        pure comptime fn List<T>->Type {List<T>}
        pure comptime fn Tuple<...Es:List<Type>>->Type {Tuple<...Es>}
        pure comptime fn Identity<T>->Type {T}
        comptime fn Echo(T:Type)->Type {T}
        comptime fn Wrapped(T:Type)->Type {Identity<T>}
        fn wrapped(comptime T:Type,value:Echo(Identity<T>))->Wrapped(T) {value}
        comptime fn Pair(T:Type)->Type {Tuple<T,bool>}
        comptime fn Second(A:Type,B:Type)->Type {B}
        comptime fn Callable(T:Type)->Type {(fn(T)->T)}
        fn mixed(unused:bool,comptime A:Type,comptime B:Type,value:Second(A,B))->Second(A,B) {value}
        fn pair(comptime T:Type,value:Echo(Tuple<T,bool>))->Pair(T) {value}
        fn apply(comptime T:Type,callback:Callable(T),value:T)->T {callback(value)}
        fn invert(flag:bool)->bool {not flag}
        fn flag()->bool {mixed(false,.u8'builtin,bool,true)}
        fn byte()->.u8'builtin {mixed(true,bool,.u8'builtin,7)}
        fn nested()->Tuple<.u8'builtin,bool> {pair(.u8'builtin,(7,true))}
        fn applied()->bool {apply(bool,invert,false)}";
    let package = compile_with_source_bindings(
        source,
        &Default::default(),
        luna::protocols::type_constructors::Selectors {
            meta_list: Some("input.List"),
            tuple: Some("input.Tuple"),
            ..Default::default()
        },
    )
    .unwrap();
    for (entry, expected) in [
        ("flag", Value::Bool(true)),
        ("byte", Value::UnsignedInteger(7)),
        (
            "nested",
            Value::Tuple(vec![Value::UnsignedInteger(7), Value::Bool(true)]),
        ),
        ("applied", Value::Bool(true)),
    ] {
        assert_eq!(
            luna::execution::interpret(&package, entry, 100_000).unwrap(),
            expected
        );
    }
    let mixed = &package
        .functions
        .iter()
        .find(|f| f.name == "mixed")
        .unwrap()
        .signature;
    let Term::Function { parameters, result } = mixed.callable_signature() else {
        panic!("signature")
    };
    assert_eq!(
        parameters[3].ty,
        Term::Bound {
            depth: 0,
            index: 2,
            sort: Sort::Type
        }
    );
    assert_eq!(**result, parameters[3].ty);
    let apply = &package
        .functions
        .iter()
        .find(|f| f.name == "apply")
        .unwrap()
        .signature;
    let Term::Function { parameters, .. } = apply.callable_signature() else {
        panic!("signature")
    };
    let Term::Function { parameters, result } = &parameters[1].ty else {
        panic!("callback signature")
    };
    assert_eq!(
        parameters[0].ty,
        Term::Bound {
            depth: 1,
            index: 0,
            sort: Sort::Type
        }
    );
    assert_eq!(**result, parameters[0].ty);
    let pair = &package
        .functions
        .iter()
        .find(|f| f.name == "pair")
        .unwrap()
        .signature;
    let Term::Function { parameters, result } = pair.callable_signature() else {
        panic!("signature")
    };
    let expected = Term::NormalForm {
        head: id(&package, "Tuple"),
        sort: Sort::Type,
        arguments: vec![Term::TypeListValue(vec![
            Term::Bound {
                depth: 0,
                index: 0,
                sort: Sort::Type,
            },
            Term::Primitive(Primitive::Bool),
        ])],
    };
    assert_eq!(parameters[1].ty, expected);
    assert_eq!(**result, expected);
    let wrapped = &package
        .functions
        .iter()
        .find(|f| f.name == "wrapped")
        .unwrap()
        .signature;
    let Term::Function { parameters, result } = wrapped.callable_signature() else {
        panic!("signature")
    };
    assert_eq!(parameters[1].ty, **result);
    assert!(
        matches!(&**result,Term::NormalForm {head,arguments,..} if *head==id(&package,"Identity") && arguments==&vec![Term::Bound {depth:0,index:0,sort:Sort::Type}])
    );
}

#[test]
fn explicit_comptime_type_signature_computations_do_not_guess_observations() {
    for body in ["if A == B {A} else {B}", "A match {Head<T> => T,_=>B}"] {
        let source = format!(
            "typealias Type=.Type'builtin;
            pure comptime fn Head<T>->Type {{T}}
            comptime fn Select(A:Type,B:Type)->Type {{{body}}}
            fn pending(comptime A:Type,comptime B:Type,value:Select(A,B)) {{}}"
        );
        let error = compile_with_protocols(&source, &Default::default()).unwrap_err();
        assert!(
            error.contains("TypeContractUnresolved"),
            "unknown Type observations must stay unresolved: {error}"
        );
    }
    let runtime = "typealias Type=.Type'builtin;comptime fn Echo(T:Type)->Type {T}
        fn pending(T:Type,value:Echo(T)) {}";
    assert!(
        compile_with_protocols(runtime, &Default::default()).is_err(),
        "runtime Type inputs must not acquire comptime availability"
    );
}

#[test]
fn explicit_comptime_type_inputs_support_predicates_and_type_list_results() {
    use nir::{Primitive, Sort, Term};
    let source = "typealias Type=.Type'builtin;
        pure comptime fn List<T>->Type {List<T>}
        pure comptime fn Tuple<...Es:List<Type>>->Type {Tuple<...Es>}
        comptime fn same(T:Type)->bool {T == T}
        comptime fn is_bool(T:Type)->bool {T == bool}
        comptime fn elements(T:Type)->List<Type> {T match {Tuple<Es> => Es,_=>elements(T)}}
        fn checked(comptime T:Type,value:refines {same(Itself)} T)->T {value}
        fn known(comptime T:Type,value:T)->T where requires T == bool {
            let checked:refines {is_bool(Itself)} T=value;checked
        }
        fn pair(comptime T:Type,value:Tuple<...elements(Tuple<T,bool>)>)->Tuple<T,bool> {value}
        fn generic(value:Tuple<...elements(Tuple<T,bool>)>)->Tuple<T,bool> where T {value}
        fn flag()->bool {known(bool,checked(bool,true))}
        fn run()->Tuple<.u8'builtin,bool> {generic(pair(.u8'builtin,(7,checked(bool,true))))}";
    let selectors = luna::protocols::type_constructors::Selectors {
        meta_list: Some("input.List"),
        tuple: Some("input.Tuple"),
        ..Default::default()
    };
    let package = compile_with_source_bindings(source, &Default::default(), selectors).unwrap();
    assert_eq!(
        luna::execution::interpret(&package, "flag", 100_000).unwrap(),
        Value::Bool(true)
    );
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Tuple(vec![Value::UnsignedInteger(7), Value::Bool(true)])
    );
    let pair = &package
        .functions
        .iter()
        .find(|f| f.name == "pair")
        .unwrap()
        .signature;
    let Term::Function { parameters, result } = pair.callable_signature() else {
        panic!("signature")
    };
    let expected = Term::NormalForm {
        head: id(&package, "Tuple"),
        sort: Sort::Type,
        arguments: vec![Term::TypeListValue(vec![
            Term::Bound {
                depth: 0,
                index: 0,
                sort: Sort::Type,
            },
            Term::Primitive(Primitive::Bool),
        ])],
    };
    assert_eq!(parameters[1].ty, expected);
    assert_eq!(**result, expected);
    let missing = source.replace("where requires T == bool", "");
    let error = compile_with_source_bindings(&missing, &Default::default(), selectors).unwrap_err();
    assert!(
        error.contains("TypeContractUnresolved"),
        "must not manufacture evidence for the refinement: {error}"
    );
}

#[test]
fn explicit_comptime_type_defaults_preserve_computed_types_and_overrides() {
    let source="typealias Type=.Type'builtin;
        pure comptime fn List<T>->Type {List<T>}
        pure comptime fn Tuple<...Es:List<Type>>->Type {Tuple<...Es>}
        comptime fn Echo(T:Type)->Type {T}
        comptime fn same(T:Type)->bool {T == T}
        comptime fn is_bool(T:Type)->bool {T == bool}
        comptime fn elements(T:Type)->List<Type> {T match {Tuple<Es> => Es,_=>elements(T)}}
        fn identity(comptime T:Type,comptime .P:Type=Echo(Tuple<T,bool>),value:P)->P {value}
        fn list_identity(comptime T:Type,comptime .Es:List<Type> = elements(Tuple<T,bool>),value:Tuple<...Es>)->Tuple<...Es> {value}
        fn checked(comptime T:Type,comptime .ok:bool=same(T))->bool {ok}
        fn observed(comptime T:Type,comptime .ok:bool=is_bool(T))->bool {ok}
        fn override_forward(comptime T:Type)->bool {observed(T,.ok=false)}
        fn forward(comptime T:Type,value:Tuple<T,bool>)->Tuple<T,bool> {identity(T,value)}
        fn forward_list(comptime T:Type,value:Tuple<T,bool>)->Tuple<T,bool> {list_identity(T,value)}
        fn recursive(comptime T:Type,comptime .P:Type=Echo(T),value:P,again:bool)->P {
            if again {recursive(P,value,false)} else {value}
        }
        fn pair()->Tuple<.u8'builtin,bool> {forward(.u8'builtin,(7,true))}
        fn list_pair()->Tuple<.u8'builtin,bool> {forward_list(.u8'builtin,(7,true))}
        fn recursive_flag()->bool {recursive(.u8'builtin,.P=bool,true,true)}
        fn skipped_observation()->bool {override_forward(bool)}
        fn flag()->bool {identity(.u8'builtin,.P=bool,true)}
        fn checked_flag()->bool {checked(bool)}
        fn override_predicate()->bool {checked(bool,.ok=false)}";
    let selectors = luna::protocols::type_constructors::Selectors {
        meta_list: Some("input.List"),
        tuple: Some("input.Tuple"),
        ..Default::default()
    };
    let package = compile_with_source_bindings(source, &Default::default(), selectors).unwrap();
    for (entry, expected) in [
        (
            "pair",
            Value::Tuple(vec![Value::UnsignedInteger(7), Value::Bool(true)]),
        ),
        (
            "list_pair",
            Value::Tuple(vec![Value::UnsignedInteger(7), Value::Bool(true)]),
        ),
        ("recursive_flag", Value::Bool(true)),
        ("skipped_observation", Value::Bool(false)),
        ("flag", Value::Bool(true)),
        ("checked_flag", Value::Bool(true)),
        ("override_predicate", Value::Bool(false)),
    ] {
        assert_eq!(
            luna::execution::interpret(&package, entry, 100_000).unwrap(),
            expected
        );
    }
    // The Boolean does not determine a type, so this call can retain the
    // default until its staged input becomes concrete. It must then observe
    // bool accurately, rather than using the explicit override above.
    let omitted = source.replace("observed(T,.ok=false)", "observed(T)");
    let package = compile_with_source_bindings(&omitted, &Default::default(), selectors).unwrap();
    assert_eq!(
        luna::execution::interpret(&package, "skipped_observation", 100_000).unwrap(),
        Value::Bool(true)
    );
}

#[test]
fn required_type_defaults_capture_closures_and_nested_function_type_slots() {
    let source = "typealias Type=.Type'builtin;
        comptime fn Callable(T:Type)->Type {(fn(T)->T)}
        fn keep(comptime T:Type,comptime .F:Type=do {
            let make=|| Callable(T);
            make()
        },value:F)->F {value}
        fn forward(unused:bool,comptime T:Type,callback:fn(T)->T)->fn(T)->T {
            keep(T,callback)
        }
        fn flag()->bool {let callback=forward(false,bool,|value|value);callback(true)}
        fn byte()->.u8'builtin {let callback=forward(true,.u8'builtin,|value|value);callback(7)}";
    let package = compile(source);
    for (entry, expected) in [
        ("flag", Value::Bool(true)),
        ("byte", Value::UnsignedInteger(7)),
    ] {
        assert_eq!(
            luna::execution::interpret(&package, entry, 100_000).unwrap(),
            expected
        );
        luna::instantiation::instantiate(&package, entry, 100_000).unwrap();
    }
    // Mentioning an ordinary runtime input in the captured closure still
    // cannot turn it into a required comptime value.
    let runtime = source.replace(
        "keep(T,callback)",
        "keep(T,.F=do {let make=|| if unused {Callable(T)} else {Callable(T)};make()},callback)",
    );
    assert!(compile_with_protocols(&runtime, &Default::default()).is_err());
}

#[test]
fn source_type_refinements_use_if_and_short_circuit_path_facts() {
    let source="typealias Type=.Type'builtin;
        pure comptime fn List<T>->Type {List<T>}
        pure comptime fn Tuple<...Es:List<Type>>->Type {Tuple<...Es>}
        comptime fn first(pair:Tuple<U,bool>)->U where U {let (value,_)=pair;value}
        comptime fn partial()->bool where T {
            let result=first(if T == bool {
                let witness:Type=refines {Itself == bool} T;(true,false)
            } else {
                let witness:Type=refines {not (Itself == bool)} T;(false,true)
            });result
        }
        comptime fn branch()->bool where T {
            if T == bool {
                let witness:Type=refines {Itself == bool} T;true
            } else {
                let witness:Type=refines {not (Itself == bool)} T;false
            }
        }
        comptime fn short_and()->bool where T {
            T == bool and do {let witness:Type=refines {Itself == bool} T;true}
        }
        comptime fn short_or()->bool where T {
            T == bool or do {let witness:Type=refines {not (Itself == bool)} T;false}
        }
        comptime fn mixed(flag:bool)->bool where T {
            if flag and T == bool {
                let witness:Type=refines {Itself == bool} T;true
            } else {false}
        }
        comptime fn negative(flag:bool)->bool where T {
            if flag or T == bool {true} else {
                let witness:Type=refines {not (Itself == bool)} T;false
            }
        }
        comptime fn nested()->bool where A,B {
            if A == B {if B == bool {let witness:Type=refines {Itself == bool} A;true} else {false}}
            else {false}
        }
        const FLAG:bool=branch<bool>() and short_and<bool>() and short_or<bool>() and mixed<bool>(true) and negative<bool>(false) and nested<bool,bool>() and partial<bool>();
        const BYTE:bool=branch<.u8'builtin>() or short_and<.u8'builtin>() or short_or<.u8'builtin>() or mixed<.u8'builtin>(true) or negative<.u8'builtin>(false) or nested<.u8'builtin,bool>() or partial<.u8'builtin>();
        comptime fn flag()->bool {FLAG}
        comptime fn byte()->bool {BYTE}";
    let package = compile_with_source_bindings(
        source,
        &Default::default(),
        luna::protocols::type_constructors::Selectors {
            meta_list: Some("input.List"),
            tuple: Some("input.Tuple"),
            ..Default::default()
        },
    )
    .unwrap();
    for (entry, expected) in [("flag", true), ("byte", false)] {
        let mut interpreter = Interpreter::for_comptime(&package, Budget::default()).unwrap();
        assert_eq!(
            interpreter.invoke(id(&package, entry), vec![]).unwrap(),
            Value::Bool(expected)
        );
    }
    for body in [
        "if T == bool {true} else {let witness:Type=refines {Itself == bool} T;false}",
        "if T == bool {let witness:Type=refines {Itself == bool} T;true} else {false};let leaked:Type=refines {Itself == bool} T;true",
        "T == bool or do {let witness:Type=refines {Itself == bool} T;true}",
        "if flag or T == bool {let witness:Type=refines {Itself == bool} T;true} else {false}",
        "if flag and T == bool {true} else {let witness:Type=refines {not (Itself == bool)} T;false}",
        "if is_bool(T) {let witness:Type=refines {Itself == bool} T;true} else {false}",
    ] {
        let invalid = format!(
            "typealias Type=.Type'builtin;comptime fn is_bool(T:Type)->bool {{T == bool}} comptime fn bad(flag:bool)->bool where T {{{body}}}"
        );
        let error = compile_with_protocols(&invalid, &Default::default()).unwrap_err();
        assert!(
            error.contains("type refinement requirement is not established"),
            "invalid path fact {body}: {error}"
        );
    }
}

#[test]
fn when_type_refinements_keep_prior_failures_local_to_later_arms() {
    let prefix="typealias Type=.Type'builtin;typealias Integer=.Integer'builtin;
        comptime fn classify()->bool where T {
            when {
                T == bool => {let witness:Type=refines {Itself == bool} T;true},
                do {let prior:Type=refines {not (Itself == bool)} T;T == .u8'builtin} => {
                    let witness:Type=refines {Itself == .u8'builtin and not (Itself == bool)} T;false
                },
                else => {let witness:Type=refines {not (Itself == bool) and not (Itself == .u8'builtin)} T;false}
            }
        }
        comptime fn counted()->Integer where T {
            var count:Integer=0;
            when {
                do {count = count + 1;T == bool} => {let witness:Type=refines {Itself == bool} T;()},
                do {count = count + 1;T == .u8'builtin} => {let witness:Type=refines {not (Itself == bool)} T;()},
                else => (),
            };count
        }
        const RESULT:bool=classify<bool>() and not classify<.u8'builtin>() and not classify<.u16'builtin>()
            and counted<bool>() == 1 and counted<.u8'builtin>() == 2 and counted<.u16'builtin>() == 2;
        comptime fn run()->bool {RESULT}";
    let package = compile(prefix);
    let mut vm = Interpreter::for_comptime(&package, Budget::default()).unwrap();
    assert_eq!(
        vm.invoke(id(&package, "run"), vec![]).unwrap(),
        Value::Bool(true)
    );
    for body in [
        "when {T == bool=>true,else=>{let invalid:Type=refines {Itself == bool} T;false}}",
        "when {T == bool=>{let valid:Type=refines {Itself == bool} T;true},else=>false};let leaked:Type=refines {Itself == bool} T;true",
        "when {T == bool=>true,T == .u8'builtin=>{let invalid:Type=refines {Itself == bool} T;false},else=>false}",
    ] {
        let source =
            format!("typealias Type=.Type'builtin;comptime fn bad()->bool where T {{{body}}}");
        let error = compile_with_protocols(&source, &Default::default()).unwrap_err();
        assert!(
            error.contains("type refinement requirement is not established"),
            "{body}: {error}"
        );
    }
}

