#[test]
fn bitvec_runtime_windows_infer_width_and_prove_endpoints() {
    let source="typealias Bits=.BitVec'builtin<16>;typealias Window=.BitVec'builtin<4>;typealias Byte=.u8'builtin;
        fn window(bits:Bits,start:Byte)->Window {assumes start <= 12;bits[start..(start + 4)]}
        fn inferred(bits:Bits,start:Byte)->Window {assumes start <= 12;let part=bits[start..(start + 4)];part}
        fn empty(bits:Bits,start:Byte)->.BitVec'builtin<0> {assumes start <= 16;bits[start..start]}
        fn run()->Window {let bits:Bits=0xABCD;window(bits,4)}
        fn infer_run()->Window {let bits:Bits=0xABCD;inferred(bits,4)}
        fn empty_run()->.BitVec'builtin<0> {let bits:Bits=0xABCD;empty(bits,16)}
        fn lower_constant()->Window {let bits:Bits=0xABCD;let hi:Byte=4;bits[0..hi]}
        fn upper_constant()->Window {let bits:Bits=0xABCD;let lo:Byte=12;bits[lo..16]}
        comptime fn ct(bits:Bits,start:.Integer'builtin)->Window {bits[start..(start + 4)]}
        comptime fn computed()->Window {let bits:Bits=0xABCD;ct(bits,4)}";
    let package = compile(source);
    for (entry, expected) in [
        ("run", 12),
        ("infer_run", 12),
        ("lower_constant", 13),
        ("upper_constant", 10),
    ] {
        let Value::BitVec(bits) = luna::execution::interpret(&package, entry, 100_000).unwrap()
        else {
            panic!("bits")
        };
        assert_eq!(bits.words(), &[expected], "{entry}");
    }
    let Value::BitVec(bits) = luna::execution::interpret(&package, "empty_run", 100_000).unwrap()
    else {
        panic!("bits")
    };
    assert_eq!(bits.width(), 0);
    let Value::BitVec(bits) = luna::invocation::invoke(&package, "computed", 100_000).unwrap()
    else {
        panic!("bits")
    };
    assert_eq!(bits.words(), &[12]);
    assert!(
        format!(
            "{}",
            package
                .functions
                .iter()
                .find(|f| f.name == "inferred")
                .unwrap()
                .body
        )
        .contains("(bit-window")
    );
    for body in [
        "fn bad(bits:Bits,i:Byte)->Window {bits[i..(i + 4)]}",
        "fn bad(bits:Bits,i:Byte)->Window {assumes i <= 13;bits[i..(i + 4)]}",
        "fn bad(bits:Bits,i:.i16'builtin)->Window {assumes i <= 12;bits[i..(i + 4)]}",
        "fn bad(bits:Bits,i:Byte)->Window {assumes i <= 12;bits[i..(i + 3)]}",
        "fn bad(bits:Bits,i:Byte)->.BitVec'builtin<0> {assumes i <= 17;bits[i..i]}",
        "fn bad(bits:Bits,lo:Byte,hi:Byte)->Window {assumes lo <= 16 and hi <= 16;bits[lo..hi]}",
    ] {
        assert!(
            compile_with_protocols(&format!("{source}{body}"), &Default::default()).is_err(),
            "accepted {body}"
        );
    }
}

#[test]
fn bitvec_runtime_windows_freeze_operands_and_keep_endpoint_order() {
    let source="typealias Bits=.BitVec'builtin<8>;typealias Window=.BitVec'builtin<4>;typealias Byte=.u8'builtin;
        fn operand()->Bits {0b10100100}
        fn lower()->result:Byte where ensures result == 2 {2}
        fn upper()->result:Byte where ensures result == 6 {6}
        fn run()->Window {operand()[lower()..upper()]}
        fn clear(p:*Bits)->result:Byte where ensures result == 6 {p.* = 0b00000000;6}
        fn snapshot()->Window {var bits:Bits=0b10100100;let lo:Byte=2;bits[lo..clear(bits.ref)]}
        fn changing()->Window {let bits:Bits=0b10100100;var lo:Byte=2;bits[lo..do {lo=100;let hi:Byte=6;hi}]}";
    let package = compile(source);
    for entry in ["run", "snapshot", "changing"] {
        let graph = luna::instantiation::instantiate(&package, entry, 100_000).unwrap();
        let mut vm = Interpreter::from_iir(&graph, Budget::default()).unwrap();
        let Value::BitVec(bits) = vm.invoke_instance(&graph.roots[0], vec![]).unwrap() else {
            panic!("bits")
        };
        assert_eq!(bits.words(), &[9], "{entry}");
        if entry == "run" {
            assert_eq!(
                calls(&package, &vm),
                vec!["run", "operand", "lower", "upper"]
            );
        }
    }
    let bad =
        "fn bad()->Window {let bits:Bits=0b10100100;var lo:Byte=2;bits[lo..do {lo=4;lo + 4}]}";
    let error = compile_with_protocols(&format!("{source}{bad}"), &Default::default()).unwrap_err();
    assert!(error.contains("constant width"), "{error}");
}

#[test]
fn bitvec_runtime_windows_use_cubic_widths_contracts_and_late_checks() {
    let source="typealias Bits=.BitVec'builtin<16>;typealias Window=.BitVec'builtin<4>;typealias Byte=.u8'builtin;
        fn cubic(bits:Bits,i:Byte)->Window {assumes i <= 2;let view=bits[(i * i * i)..(i * i * i + 4)];view}
        fn late(bits:Bits,i:Byte)->Window {bits[i..do {assumes i <= 12;i + 4}]}
        fn related(bits:Bits,lo:Byte,hi:Byte)->Window
            where requires lo <= 12, requires hi == lo + 4 {bits[lo..hi]}
        fn run()->Window {let bits:Bits=0xABCD;cubic(bits,2)}
        fn late_run()->Window {let bits:Bits=0xABCD;late(bits,4)}
        fn related_run()->Window {let bits:Bits=0xABCD;related(bits,4,8)}
        fn exit_upper()->Window {let bits:Bits=0xABCD;bits[0..do {return 0b1010;}]}
        fn exit_lower()->Window {let bits:Bits=0xABCD;bits[(do {return 0b1010;})..4]}";
    let package = compile(source);
    for (entry, expected) in [
        ("run", 11),
        ("late_run", 12),
        ("related_run", 12),
        ("exit_upper", 10),
        ("exit_lower", 10),
    ] {
        let Value::BitVec(bits) = luna::execution::interpret(&package, entry, 100_000).unwrap()
        else {
            panic!("bits")
        };
        assert_eq!(bits.words(), &[expected], "{entry}");
    }
    let wrong = "fn bad(bits:Bits,lo:Byte,hi:Byte)->Window {assumes lo <= 12 and hi <= 16;let part=bits[lo..hi];part}";
    let error =
        compile_with_protocols(&format!("{source}{wrong}"), &Default::default()).unwrap_err();
    assert!(error.contains("width is not comptime-known"), "{error}");
}

#[test]
fn bitvec_runtime_windows_reject_malformed_ranges_and_recover() {
    use nir::program::{ExprKind as K, Literal};
    let source="typealias Bits=.BitVec'builtin<8>;typealias Window=.BitVec'builtin<4>;
        fn run()->Window {let bits:Bits=0b10100100;let start:.i128'builtin=2;bits[start..(start + 4)]}";
    for (lo, hi, kind) in [
        (6, 2, ErrorKind::IndexOutOfBounds),
        (-1, 3, ErrorKind::IndexOutOfBounds),
        (6, 10, ErrorKind::IndexOutOfBounds),
        (2, 7, ErrorKind::Type),
        (i128::MAX, i128::MAX, ErrorKind::IndexOutOfBounds),
    ] {
        let mut package = compile(source);
        nir::visit::expression_mut(&mut package.functions[0].body, &mut 10_000, |expr, _| {
            if let K::BitWindow { start, end, .. } = &mut expr.kind {
                start.kind = K::Literal(Literal::SignedInteger(lo));
                end.kind = K::Literal(Literal::SignedInteger(hi));
            }
            Ok(())
        })
        .unwrap();
        let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
        assert_eq!(
            vm.invoke(id(&package, "run"), vec![]).unwrap_err().kind,
            kind
        );
        assert!(elaboration::verification::flow::validate_machine_operations(&package).is_err());
    }
    let package=compile("typealias Bits=.BitVec'builtin<16>;typealias Window=.BitVec'builtin<4>;
        fn window(bits:Bits,start:.u8'builtin)->Window {assumes start <= 12;bits[start..(start + 4)]}");
    let input = Value::BitVec(
        comptime_runtime::bitvec::BitVec::from_words(16, &[0xABCD], &mut Default::default())
            .unwrap(),
    );
    let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        vm.invoke(
            id(&package, "window"),
            vec![input.clone(), Value::UnsignedInteger(13)]
        )
        .unwrap_err()
        .kind,
        ErrorKind::ProgramContractRejected
    );
    let Value::BitVec(bits) = vm
        .invoke(
            id(&package, "window"),
            vec![input, Value::UnsignedInteger(4)],
        )
        .unwrap()
    else {
        panic!("bits")
    };
    assert_eq!(bits.words(), &[12]);
}

