#[test]
fn external_pointer_observations_check_call_inputs_after_argument_effects() {
    let prefix = "typealias Byte=.u8'builtin;
        fn checked(p:*Byte,flag:bool)->Byte where requires p.* < 255 {p.* + 1}
        fn forward(p:*Byte)->Byte where requires p.* < 255 {checked(p,true)}";
    let source = format!(
        "{prefix}
        fn run()->Byte {{let good:Byte=41;let bad:Byte=255;var pointer=good.ref;
            checked(pointer,do {{pointer=bad.ref;true}})}}
        fn forwarded()->Byte {{let good:Byte=41;forward(good.ref)}}"
    );
    let package = compile(&source);
    for entry in ["run", "forwarded"] {
        assert_eq!(
            luna::execution::interpret(&package, entry, 100_000).unwrap(),
            Value::UnsignedInteger(42)
        );
    }
    for body in [
        "fn bad()->Byte {var value:Byte=41;checked(value.ref,do {value=255;true})}",
        "fn bad(p:*Byte)->Byte where requires p.* < 255 {checked(p,do {p.* = 255;true})}",
        "fn bad(p:*Byte,q:*Byte)->Byte where requires p.* < 255 {checked(p,do {q.* = 255;true})}",
        "fn bad()->Byte {let value:Byte=255;checked(value.ref,true)}",
    ] {
        let failure =
            compile_with_protocols(&format!("{prefix}{body}"), &Default::default()).unwrap_err();
        assert!(failure.contains("precondition"), "{body}: {failure}");
    }
}

#[test]
fn total_boolean_trees_preserve_refinement_and_effectful_short_circuit_boundaries() {
    let source = "typealias Byte=.u8'builtin;
        fn guarded(a:Byte,b:Byte,c:Byte,flag:bool)->Byte {
            if flag and not (a == 255 or b == 255 or c == 255) {a + 1} else {0}
        }
        fn probe(p:*bool)->bool {p.* = true;true}
        fn run()->bool {
            var touched=false;
            let a:Byte=41;let b:Byte=1;let c:Byte=2;
            let skipped=(a == 0 or b == 0 or c == 0) and probe(touched.ref);
            let clean=not touched and not skipped;
            let called=(a == 41 and b == 1 and c == 2) and probe(touched.ref);
            clean and called and touched
                and guarded(41,1,2,true)==42
                and guarded(255,1,2,true)==0
                and guarded(41,255,2,true)==0
                and guarded(41,1,255,true)==0
                and guarded(41,1,2,false)==0
        }";
    let package = compile(source);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    let invalid = source.replace("a == 255 or b == 255", "a == 254 or b == 255");
    let error = compile_with_protocols(&invalid, &Default::default()).unwrap_err();
    assert!(error.contains("not proven"), "{error}");
}

#[test]
fn short_circuit_relations_do_not_outlive_operand_writes() {
    let prefix = "typealias Byte=.u8'builtin;fn next(value:Byte)->Byte where requires value < 255 {value + 1}";
    for condition in [
        "value < 255 and do {value=254;true}",
        "value == 255 or do {value=254;true}",
    ] {
        let source = format!(
            "{prefix}fn run()->bool {{var value:Byte=0;
            ({condition}) and next(value)==255}}"
        );
        let package = compile(&source);
        assert_eq!(
            luna::execution::interpret(&package, "run", 100_000).unwrap(),
            Value::Bool(true)
        );
        let invalid = source.replace("value=254", "value=255");
        let failure = compile_with_protocols(&invalid, &Default::default()).unwrap_err();
        assert!(failure.contains("precondition"), "{failure}");
    }
}

#[test]
fn external_pointer_observations_cross_readonly_defaults() {
    let prefix = "typealias Byte=.u8'builtin;
        fn checked(p:*Byte,.flag:bool=true)->Byte where requires p.* < 255 {p.* + 1}
        fn alias(p:*Byte,.q:*Byte=p)->Byte where requires q.* < 255 {q.* + 1}
        fn forward(p:*Byte)->Byte where requires p.* < 255 {checked(p)}
        fn forward_alias(p:*Byte)->Byte where requires p.* < 255 {alias(p)}";
    let source = format!(
        "{prefix}
        fn run()->Byte {{let value:Byte=41;checked(value.ref)}}
        fn direct_alias()->Byte {{let value:Byte=41;alias(value.ref)}}
        fn forwarded()->Byte {{let value:Byte=41;forward(value.ref)}}
        fn forwarded_alias()->Byte {{let value:Byte=41;forward_alias(value.ref)}}"
    );
    let package = compile(&source);
    for entry in ["run", "direct_alias", "forwarded", "forwarded_alias"] {
        assert_eq!(
            luna::execution::interpret(&package, entry, 100_000).unwrap(),
            Value::UnsignedInteger(42)
        );
    }
    assert!(
        compile_with_protocols(
            &source.replace("value:Byte=41", "value:Byte=255"),
            &Default::default()
        )
        .unwrap_err()
        .contains("precondition")
    );
    for default in ["do {p.* = 255;true}", "write(p)"] {
        let invalid = format!(
            "typealias Byte=.u8'builtin;fn write(p:*Byte)->bool {{p.* = 255;true}}
            fn checked(p:*Byte,.flag:bool={default})->Byte where requires p.* < 255 {{p.* + 1}}
            fn run()->Byte {{let value:Byte=41;checked(value.ref)}}"
        );
        assert!(
            compile_with_protocols(&invalid, &Default::default())
                .unwrap_err()
                .contains("P3 stability")
        );
    }
}

#[test]
fn external_pointer_observations_reject_effectful_default_ir() {
    use elaboration::verification::{Limits, flow};
    use nir::program::{Expr, ExprKind as K, Literal, Place};
    let source="typealias Byte=.u8'builtin;
        fn checked(p:*Byte,other:*Byte,.flag:bool=true,.q:*Byte=p)->Byte where requires q.* < 255 {q.* + 1}
        fn run()->Byte {let value:Byte=41;let bad:Byte=255;checked(value.ref,bad.ref)}";
    for rebind in [false, true] {
        let mut package = compile(source);
        let function = package
            .functions
            .iter_mut()
            .find(|f| f.name == "run")
            .unwrap();
        let K::Block {
            result: Some(call), ..
        } = &mut function.body.kind
        else {
            panic!("block")
        };
        let K::Call {
            arguments,
            parameter_bindings,
            ..
        } = &mut call.kind
        else {
            panic!("call")
        };
        let pointer_type = arguments[0].value.ty.clone();
        let default = arguments.iter_mut().find(|a| a.parameter == 2).unwrap();
        let span = default.value.source;
        let write = if rebind {
            K::Assign {
                place: Place {
                    root: parameter_bindings[0],
                    fields: vec![],
                },
                value: Box::new(Expr {
                    source: span,
                    ty: pointer_type,
                    kind: K::Local(parameter_bindings[1]),
                }),
            }
        } else {
            K::WritePointer {
                pointer: Box::new(Expr {
                    source: span,
                    ty: pointer_type,
                    kind: K::Local(parameter_bindings[0]),
                }),
                value: Box::new(Expr {
                    source: span,
                    ty: nir::Term::Primitive(nir::Primitive::U8),
                    kind: K::Literal(Literal::UnsignedInteger(255)),
                }),
            }
        };
        default.value.kind = K::Block {
            statements: vec![Expr {
                source: span,
                ty: nir::Term::Primitive(nir::Primitive::Void),
                kind: write,
            }],
            result: Some(Box::new(Expr {
                source: span,
                ty: default.value.ty.clone(),
                kind: K::Literal(Literal::Bool(true)),
            })),
        };
        let function = package.functions.iter().find(|f| f.name == "run").unwrap();
        let failure = flow::analyze_in_package(&package, function, &mut Limits::default())
            .err()
            .expect("effectful default cannot reuse input observations");
        assert!(failure.to_string().contains("precondition"), "{failure}");
    }
}

#[test]
fn external_pointer_observations_survive_proved_readonly_calls() {
    let source = "typealias Byte=.u8'builtin;
        fn read(p:*Byte)->Byte {p.*}
        fn identity(value:T)->T where T {value}
        fn defaulted(.flag:bool=true)->bool {flag}
        fn next(p:*Byte)->Byte where requires p.* < 255 {p.* + 1}
        fn stable(p:*Byte)->result:bool where ensures result {
            let before=p.*;read(p);identity(true);defaulted();before == p.*
        }
        fn forward(p:*Byte)->Byte where requires p.* < 255 {read(p);next(p)}
        fn run()->bool {let value:Byte=41;stable(value.ref) and forward(value.ref)==42}";
    let package = compile(source);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    for call in ["write(q)", "unknown(q)", "write(do {q})"] {
        let invalid = format!(
            "typealias Byte=.u8'builtin;
            fn write(p:*Byte) {{p.* = 0;}}
            fn rejected(p:*Byte,q:*Byte,unknown:fn(*Byte))->result:bool where ensures result {{
                let before=p.*;{call};before == p.*
            }}"
        );
        let failure = compile_with_protocols(&invalid, &Default::default()).unwrap_err();
        assert!(failure.contains("postcondition"), "{failure}");
    }
    let invalid = "typealias Byte=.u8'builtin;
        fn read(p:*Byte)->Byte {p.*}
        fn rejected(p:*Byte,q:*Byte)->result:bool where ensures result {
            let before=p.*;read(do {q.* = 0;q});before == p.*
        }";
    assert!(
        compile_with_protocols(invalid, &Default::default())
            .unwrap_err()
            .contains("postcondition")
    );
}

#[test]
fn external_pointer_observations_track_nested_field_paths() {
    let source="typealias Byte=.u8'builtin;
        struct Inner {value:Byte,other:Byte}
        struct Outer {left:Inner,right:Inner}
        fn next(p:*Byte)->Byte where requires p.* < 255 {p.* + 1}
        fn read(p:*Outer)->result:Byte where ensures result == p.left.value.* {p.left.value.*}
        fn stable(p:*Outer)->result:bool where ensures result {
            let before=p.left.value.*;let other=p.right.value.*;before == p.left.value.*
        }
        fn forward(p:*Outer)->Byte where requires p.left.value.* < 255 {next(p.left.value)}
        fn forward_outer(p:*Outer)->Byte where requires p.left.value.* < 255 {forward(p)}
        fn default_outer(p:*Outer,.q:*Outer=p)->Byte where requires q.left.value.* < 255 {forward(q)}
        fn run()->bool {let value=Outer {left:Inner {value:41,other:7},right:Inner {value:255,other:0}};
            stable(value.ref) and read(value.ref)==41 and forward_outer(value.ref)==42 and default_outer(value.ref)==42}";
    let package = compile(source);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    // Reassigning the same origin preserves the address despite changing the
    // local binding version. A genuinely different origin must not inherit it.
    let rebound = source
        .replace(
            "let before=p.left.value.*;",
            "var pointer=p;let before=pointer.left.value.*;",
        )
        .replace(
            "let other=p.right.value.*;before == p.left.value.*",
            "pointer=p;before == pointer.left.value.*",
        );
    let package = compile(&rebound);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    let different = rebound
        .replace("fn stable(p:*Outer)", "fn stable(p:*Outer,q:*Outer)")
        .replace("pointer=p;before", "pointer=q;before")
        .replace("stable(value.ref)", "stable(value.ref,value.ref)");
    for invalid in [
        different,
        source.replace("{p.left.value.*}", "{p.right.value.*}"),
        source.replace("next(p.left.value)", "next(p.right.value)"),
        source.replace("let other=p.right.value.*;", "p.right.value.* = 0;"),
    ] {
        assert!(
            compile_with_protocols(&invalid, &Default::default()).is_err(),
            "accepted {invalid}"
        );
    }
    let invalid=format!("{source}
        fn checked(p:*Outer,flag:bool)->Byte where requires p.left.value.* < 255 {{p.left.value.* + 1}}
        fn rejected()->Byte {{var value=Outer {{left:Inner {{value:41,other:7}},right:Inner {{value:0,other:0}}}};
            checked(value.ref,do {{value.left.value=255;true}})}}");
    assert!(
        compile_with_protocols(&invalid, &Default::default())
            .unwrap_err()
            .contains("precondition")
    );
}

#[test]
fn external_pointer_observations_track_anonymous_field_paths() {
    let source="comptime fn schema(...fields:T)->T where T {fields}
        fn make(...fields:T)->T where T {fields}
        const SAMPLE=schema {flag:true,nested:schema {other:false}};typealias Options=SAMPLE'type;
        fn checked(p:*bool)->bool where requires p.* {p.*}
        fn read(p:*Options)->result:bool where ensures result == p.nested.other.* {p.nested.other.*}
        fn forward(p:*Options)->bool where requires p.flag.* {checked(p.flag)}
        fn outer(p:*Options)->bool where requires p.flag.* {forward(p)}
        fn run()->bool {let value=make {flag:true,nested:make {other:false}};assumes value.flag;outer(value.ref) and not read(value.ref)}";
    let package = compile(source);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    for invalid in [
        source.replace("checked(p.flag)", "checked(p.nested.other)"),
        source.replace("{p.nested.other.*}", "{p.flag.*}"),
    ] {
        assert!(compile_with_protocols(&invalid, &Default::default()).is_err());
    }
}

#[test]
fn readonly_pointer_postconditions_export_result_bounds_and_relations() {
    let source="typealias Byte=.u8'builtin;
        struct Cell {value:Byte}
        fn read(p:*Byte)->result:Byte where ensures result == p.* {p.*}
        fn field(p:*Cell)->result:Byte where ensures result == p.value.* {p.value.*}
        fn with_default(p:*Byte,.q:*Byte=p)->result:Byte where ensures result == q.* {q.*}
        fn forward(p:*Byte)->result:Byte where requires p.* < 255, ensures result == p.* + 1 {read(p) + 1}
        fn equal(p:*Byte)->result:bool where ensures result {let before=p.*;read(p)==before}
        fn run()->bool {let value:Byte=41;let cell=Cell {value:41};
            let a:Byte=read(value.ref) + 1;let b:Byte=field(cell.ref) + 1;
            let c:Byte=with_default(value.ref) + 1;
            a==42 and b==42 and c==42 and equal(value.ref) and forward(value.ref)==42}";
    let package = compile(source);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    for invalid in [
        source.replace("ensures result == p.* {p.*}", "ensures result <= p.* {p.*}"),
        source.replace("value:Byte=41", "value:Byte=255"),
        source.replace("Cell {value:41}", "Cell {value:255}"),
    ] {
        assert!(
            compile_with_protocols(&invalid, &Default::default()).is_err(),
            "accepted {invalid}"
        );
    }
    let invalid = "typealias Byte=.u8'builtin;
        fn read(p:*Byte,flag:bool)->result:Byte where ensures result == p.* {p.*}
        fn rejected()->Byte {var value:Byte=41;read(value.ref,do {value=255;true}) + 1}";
    assert!(compile_with_protocols(invalid, &Default::default()).is_err());
    let invalid = "typealias Byte=.u8'builtin;
        fn set(p:*Byte)->result:Byte where ensures result == p.* {p.* = 255;p.*}
        fn rejected()->Byte {let value:Byte=41;set(value.ref) + 1}";
    assert!(compile_with_protocols(invalid, &Default::default()).is_err());
}

#[test]
fn readonly_pointer_postconditions_do_not_reuse_rebound_parameter_addresses() {
    use elaboration::verification::{Limits, flow};
    use nir::program::{Expr, ExprKind as K, Place};
    let mut package = compile(
        "typealias Byte=.u8'builtin;
        fn read(p:*Byte,q:*Byte)->result:Byte where ensures result == p.* {p.*}
        fn run()->Byte {let good:Byte=41;let bad:Byte=255;read(good.ref,bad.ref) + 1}",
    );
    let function = package
        .functions
        .iter_mut()
        .find(|f| f.name == "read")
        .unwrap();
    let K::Block { statements, .. } = &mut function.body.kind else {
        panic!("block")
    };
    statements.insert(
        0,
        Expr {
            source: function.body.source,
            ty: nir::Term::Primitive(nir::Primitive::Void),
            kind: K::Assign {
                place: Place {
                    root: function.parameters[0],
                    fields: vec![],
                },
                value: Box::new(Expr {
                    source: function.body.source,
                    ty: nir::Term::Pointer(Box::new(nir::Term::Primitive(nir::Primitive::U8))),
                    kind: K::Local(function.parameters[1]),
                }),
            },
        },
    );
    let function = package.functions.iter().find(|f| f.name == "run").unwrap();
    let error = flow::analyze_in_package(&package, function, &mut Limits::default())
        .err()
        .expect("rebound input is not the entry address");
    assert_eq!(error.reason, flow::Reason::MissingMachineProof);
}

#[test]
fn external_pointer_writes_establish_scalar_postconditions() {
    let source="typealias Byte=.u8'builtin;
        struct Cell {value:Byte}
        fn set(p:*Byte) where ensures p.* == 41 {p.* = 41;}
        fn set_field(p:*Cell) where ensures p.value.* == 41 {p.value.* = 41;}
        fn clear(p:*bool) where ensures not p.* {p.* = false;}
        fn increment(p:*Byte)->Byte {p.* = 41;p.* + 1}
        fn bounded(p:*Byte,value:Byte)->Byte where requires value < 255 {p.* = value;p.* + 1}
        fn run()->bool {let value:Byte=0;let cell=Cell {value:0};let flag=true;
            set(value.ref);set_field(cell.ref);clear(flag.ref);
            value==41 and cell.value==41 and not flag and increment(value.ref)==42 and bounded(value.ref,41)==42}";
    let package = compile(source);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    for invalid in [
        source.replace("p.* = 41;", "p.* = 40;"),
        source.replace("p.value.* = 41;", "p.value.* = 40;"),
        source.replace("p.* = false;", "p.* = true;"),
    ] {
        assert!(
            compile_with_protocols(&invalid, &Default::default()).is_err(),
            "accepted {invalid}"
        );
    }
    for body in ["p.* = 41;q.* = 0;", "p.* = 41;write(q);"] {
        let invalid = format!(
            "typealias Byte=.u8'builtin;fn write(p:*Byte) {{p.* = 0;}}
            fn rejected(p:*Byte,q:*Byte) where ensures p.* == 41 {{{body}}}"
        );
        assert!(
            compile_with_protocols(&invalid, &Default::default())
                .unwrap_err()
                .contains("postcondition")
        );
    }
    // WritePointer saves its address before the RHS. Rebinding the alias
    // does not redirect this write, so the original pointee contract is valid.
    let captured="typealias Byte=.u8'builtin;
        fn set(p:*Byte,q:*Byte) where ensures p.* == 41 {
            var pointer=p;pointer.* = do {pointer=q;41};
        }
        fn entry()->bool {let first:Byte=0;let second:Byte=9;set(first.ref,second.ref);first == 41 and second == 9}";
    let package = compile(captured);
    assert_eq!(
        luna::execution::interpret(&package, "entry", 100_000).unwrap(),
        Value::Bool(true)
    );
    let rebound = "typealias Byte=.u8'builtin;
        fn rejected(p:*Byte,q:*Byte)->result:Byte where ensures result == 41 {
            var pointer=p;pointer.* = do {pointer=q;41};pointer.*
        }";
    assert!(
        compile_with_protocols(rebound, &Default::default())
            .unwrap_err()
            .contains("postcondition")
    );
}

#[test]
fn writing_pointer_postconditions_refine_known_caller_targets() {
    let source = "typealias Byte=.u8'builtin;
        struct Cell {value:Byte}
        fn set(p:*Byte) where ensures p.* == 41 {p.* = 41;}
        fn field(p:*Cell) where ensures p.value.* == 41 {p.value.* = 41;}
        fn alias(p:*Byte,.q:*Byte=p) where ensures q.* == 41 {q.* = 41;}
        fn clear(p:*bool) where ensures not p.* {p.* = false;}
        fn run()->bool {let value:Byte=255;let cell=Cell {value:255};let flag=true;
            set(value.ref);field(cell.ref);clear(flag.ref);
            let first:Byte=value + 1;let second:Byte=cell.value + 1;
            alias(value.ref);let third:Byte=value + 1;
            first==42 and second==42 and third==42 and not flag}";
    let package = compile(source);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    let forgotten = "typealias Byte=.u8'builtin;
        fn fill(p:*Byte) where requires p.* < 255, ensures p.* == 255 {p.* = 255;}
        fn rejected()->Byte {let value:Byte=41;fill(value.ref);value + 1}";
    assert!(compile_with_protocols(forgotten, &Default::default()).is_err());
    let ambiguous = "typealias Byte=.u8'builtin;
        fn set(p:*Byte) where ensures p.* == 41 {p.* = 41;}
        fn rejected(flag:bool)->Byte {let left:Byte=255;let right:Byte=255;
            let pointer=if flag {left.ref} else {right.ref};set(pointer);left + 1}";
    assert!(compile_with_protocols(ambiguous, &Default::default()).is_err());
    let rebound = "typealias Byte=.u8'builtin;
        fn set(p:*Byte,flag:bool) where ensures p.* == 41 {p.* = 41;}
        fn run()->Byte {let first:Byte=255;let second:Byte=255;var pointer=first.ref;
            set(pointer,do {pointer=second.ref;true});first + 1}";
    let package = compile(rebound);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::UnsignedInteger(42)
    );
    assert!(
        compile_with_protocols(
            &rebound.replace("first + 1", "second + 1"),
            &Default::default()
        )
        .is_err()
    );
}

#[test]
fn writing_pointer_postconditions_export_joint_result_memory_relations() {
    let source = "typealias Byte=.u8'builtin;struct Cell {value:Byte}
        fn set(p:*Byte,flag:bool)->result:Byte
            where ensures result == p.* and p.* < 255 {
                p.* = if flag {41} else {42};p.*
            }
        fn field(p:*Cell)->result:Byte where ensures p.value.* == 41 and result == p.value.* {
            p.value.* = 41;p.value.*
        }
        fn alias(p:*Byte,.q:*Byte=p)->result:Byte where ensures q.* == 41 and result == q.* {
            q.* = 41;q.*
        }
        fn equal(flag:bool)->result:bool where ensures result {
            var value:Byte=255;let got=set(value.ref,flag);got == value
        }
        fn run()->bool {let value:Byte=255;let cell=Cell {value:255};
            let a:Byte=set(value.ref,true) + 1;let b:Byte=value + 1;
            let c:Byte=field(cell.ref) + 1;let d:Byte=cell.value + 1;
            let e:Byte=alias(value.ref) + 1;
            a==42 and b==42 and c==42 and d==42 and e==42 and equal(true) and equal(false)}";
    let package = compile(source);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    for invalid in [
        source.replace("result == p.* and", "result <= p.* and"),
        source.replace("got == value", "do {value=0;got == value}"),
        source.replace("result == p.* and p.* < 255", "result == p.*"),
    ] {
        let failure = compile_with_protocols(&invalid, &Default::default()).unwrap_err();
        assert!(failure.contains("not proven"), "{failure}");
    }
}

#[test]
fn deferred_runtime_signatures_wait_admit_and_erase_staged_inputs() {
    use elaboration::type_computations::{
        AdmissionError, Error, RuntimeSignatureState as R, Session,
    };
    use elaboration::{InferenceContext, InferenceTerm as I};
    use nir::deferred_signatures::{Annotation as A, Input, Signature};
    use nir::type_computations::{Input as Argument, Invocation};
    use nir::{Parameter, Primitive as P, Sort, Term};
    let package = compile_with_source_bindings(
        "typealias Type=.Type'builtin;
        pure comptime fn List<T>->Type {List<T>}
        pure comptime fn Tuple<...Es:List<Type>>->Type {Tuple<...Es>}
        comptime fn First(es:List<Type>)->Type {es[0]}",
        &Default::default(),
        luna::protocols::type_constructors::Selectors {
            meta_list: Some("input.List"),
            tuple: Some("input.Tuple"),
            ..Default::default()
        },
    )
    .unwrap();
    let list = Term::NormalForm {
        head: id(&package, "List"),
        sort: Sort::Type,
        arguments: vec![Term::Primitive(P::Type)],
    };
    let pair = Term::NormalForm {
        head: id(&package, "Tuple"),
        sort: Sort::Type,
        arguments: vec![Term::TypeListValue(vec![
            Term::Primitive(P::Bool),
            Term::Primitive(P::U8),
        ])],
    };
    let schema = || {
        Signature::new(
            vec![
                Input {
                    sort: Sort::ComptimeValue,
                    annotation: A::Known(list.clone()),
                },
                Input {
                    sort: Sort::Runtime,
                    annotation: A::Computed(0),
                },
            ],
            A::Computed(0),
            vec![
                Invocation::new(
                    id(&package, "First"),
                    vec![Sort::ComptimeValue, Sort::Runtime],
                    vec![Argument {
                        ty: list.clone(),
                        value: Term::Bound {
                            depth: 0,
                            index: 0,
                            sort: Sort::ComptimeValue,
                        },
                    }],
                    &mut 1000,
                )
                .unwrap(),
            ],
            &mut 1000,
        )
        .unwrap()
    };
    let mut context = InferenceContext::default();
    let es = context.fresh(Sort::ComptimeValue);
    let runtime = context.fresh(Sort::Runtime);
    let mut session = Session::new(&package, &context, Budget::default()).unwrap();
    let mut task = session
        .enqueue_signature(&mut context, schema(), &[I::Meta(es), I::Meta(runtime)])
        .unwrap();
    let definition = task.definition_signature(&mut 1000).unwrap();
    assert!(
        matches!(session.resume_runtime_signature_checked(&mut context,&mut task,&mut 1000,|_,_,_|Ok::<_,&str>(())).unwrap(),
        R::Waiting(inputs) if inputs.contains(&es) && !inputs.contains(&runtime))
    );
    assert!(session.events().is_empty());
    context
        .assign(es, I::Stable(Term::TypeListValue(vec![pair.clone()])))
        .unwrap();
    assert!(matches!(
        session.resume_runtime_signature_checked(&mut context, &mut task, &mut 0, |_, _, _| Ok::<
            _,
            &str,
        >(
            ()
        )),
        Err(AdmissionError::Computation(Error::SchedulingBudget))
    ));
    assert!(matches!(
        session.resume_runtime_signature_checked(
            &mut context,
            &mut task,
            &mut 1000,
            |slot, _, _| if slot == 0 {
                Err("input rejected")
            } else {
                Ok(())
            }
        ),
        Err(AdmissionError::Rejected { slot: 0, .. })
    ));
    assert!(session.events().is_empty());
    let expected = Term::Function {
        parameters: vec![Parameter {
            sort: Sort::Runtime,
            ty: pair.clone(),
        }],
        result: Box::new(pair),
    };
    let ready = session
        .resume_runtime_signature_checked(&mut context, &mut task, &mut 1000, |_, _, _| {
            Ok::<_, &str>(())
        })
        .unwrap();
    assert!(
        ready
            .to_string()
            .starts_with("(runtime-signature-ready (function")
    );
    assert!(matches!(ready,R::Ready(signature) if signature==expected));
    let events = session.events().len();
    assert_eq!(
        session
            .events()
            .iter()
            .filter(|event| matches!(event,Event::EnterFunction(f) if *f==id(&package,"First")))
            .count(),
        1
    );
    let mut admitted = 0;
    assert!(matches!(
        session.resume_runtime_signature_checked(&mut context, &mut task, &mut 3, |_, _, _| {
            admitted += 1;
            Ok::<_, &str>(())
        }),
        Err(AdmissionError::Computation(Error::SchedulingBudget))
    ));
    assert_eq!(
        admitted, 3,
        "all annotations were admitted before publication exhausted its budget"
    );
    assert_eq!(session.events().len(), events);
    assert!(matches!(
        session.resume_runtime_signature_checked(
            &mut context,
            &mut task,
            &mut 1000,
            |slot, _, _| if slot == 1 {
                Err("argument rejected")
            } else {
                Ok(())
            }
        ),
        Err(AdmissionError::Rejected { slot: 1, .. })
    ));
    assert!(
        matches!(session.resume_runtime_signature_checked(&mut context,&mut task,&mut 1000,|_,_,_|Ok::<_,&str>(())).unwrap(),R::Ready(signature) if signature==expected)
    );
    assert_eq!(session.events().len(), events);
    assert_eq!(
        task.definition_description(1, &mut 1000).unwrap(),
        elaboration::gradual::FrozenDescription::Any
    );
    assert_eq!(task.definition_signature(&mut 1000).unwrap(), definition);
    let mut failed = session
        .enqueue_signature(
            &mut context,
            schema(),
            &[I::Stable(Term::TypeListValue(vec![])), I::Meta(runtime)],
        )
        .unwrap();
    assert!(matches!(
        session
            .resume_runtime_signature_checked(&mut context, &mut failed, &mut 1000, |_, _, _| Ok::<
                _,
                &str,
            >(
                ()
            ))
            .unwrap(),
        R::Failed(_)
    ));
    let events = session.events().len();
    assert!(matches!(
        session
            .resume_runtime_signature_checked(&mut context, &mut failed, &mut 0, |_, _, _| Ok::<
                _,
                &str,
            >(
                ()
            ))
            .unwrap(),
        R::Failed(_)
    ));
    assert_eq!(session.events().len(), events);
}

#[test]
fn deferred_runtime_signatures_substitute_before_removing_type_parameters() {
    use elaboration::type_computations::{
        AdmissionError, Error, RuntimeSignatureState as R, Session,
    };
    use elaboration::{InferenceContext, InferenceTerm as I};
    use nir::deferred_signatures::{Annotation as A, Input, Signature};
    use nir::{Parameter, Primitive as P, Sort, Term};
    let package = compile("fn entry()->bool {true}");
    let callable = |ty| Term::Function {
        parameters: vec![Parameter {
            sort: Sort::Runtime,
            ty: Term::Primitive(P::Bool),
        }],
        result: Box::new(ty),
    };
    let schema = Signature::new(
        vec![
            Input {
                sort: Sort::Type,
                annotation: A::Known(Term::Primitive(P::Type)),
            },
            Input {
                sort: Sort::Runtime,
                annotation: A::Known(callable(Term::Bound {
                    depth: 1,
                    index: 0,
                    sort: Sort::Type,
                })),
            },
        ],
        A::Known(Term::Bound {
            depth: 0,
            index: 0,
            sort: Sort::Type,
        }),
        vec![],
        &mut 1000,
    )
    .unwrap();
    let mut context = InferenceContext::default();
    let runtime = context.fresh(Sort::Runtime);
    let mut session = Session::new(&package, &context, Budget::default()).unwrap();
    let mut task = session
        .enqueue_signature(
            &mut context,
            schema,
            &[I::Stable(Term::Primitive(P::U8)), I::Meta(runtime)],
        )
        .unwrap();
    let expected = Term::Function {
        parameters: vec![Parameter {
            sort: Sort::Runtime,
            ty: callable(Term::Primitive(P::U8)),
        }],
        result: Box::new(Term::Primitive(P::U8)),
    };
    assert!(
        matches!(session.resume_runtime_signature_checked(&mut context,&mut task,&mut 1000,|_,_,_|Ok::<_,&str>(())).unwrap(),R::Ready(signature) if signature==expected)
    );
    assert!(session.events().is_empty());
    let mut foreign = InferenceContext::default();
    assert!(matches!(
        session.resume_runtime_signature_checked(
            &mut foreign,
            &mut task,
            &mut 1000,
            |_, _, _| Ok::<_, &str>(())
        ),
        Err(AdmissionError::Computation(Error::ForeignContext))
    ));
    let mut other = Session::new(&package, &context, Budget::default()).unwrap();
    assert!(matches!(
        other.resume_runtime_signature_checked(&mut context, &mut task, &mut 1000, |_, _, _| Ok::<
            _,
            &str,
        >(
            ()
        )),
        Err(AdmissionError::Computation(Error::ForeignSession))
    ));
}

#[test]
fn deferred_type_capture_distinguishes_runtime_parameters_from_pending_comptime_inputs() {
    let prefix = "typealias Type=.Type'builtin;
        comptime fn Pick(flag:bool)->Type {if flag {bool} else {.u8'builtin}}";
    for declaration in [
        "fn bad(flag:bool,value:defer Pick(flag)) {}",
        "fn bad(flag:bool)->defer Pick(flag) {true}",
        "fn bad(flag:bool,value:Pick(flag)) {}",
        "fn bad(flag:bool) {let value:defer Pick(flag)=true;}",
    ] {
        let failure =
            compile_with_protocols(&format!("{prefix}{declaration}"), &Default::default())
                .unwrap_err();
        assert!(
            failure.contains("cannot read a runtime parameter"),
            "{declaration}: {failure}"
        );
        assert!(
            !failure.contains("not yet implemented"),
            "illegal phase dependency is not an implementation gap: {failure}"
        );
    }
    for annotation in ["Pick(flag)"] {
        let declaration = format!("fn pending(comptime flag:bool,value:{annotation}) {{}}");
        let failure =
            compile_with_protocols(&format!("{prefix}{declaration}"), &Default::default())
                .unwrap_err();
        assert!(
            failure.contains("invocation-time type elaboration is not yet implemented"),
            "{failure}"
        );
        assert!(
            !failure.contains("cannot read a runtime parameter"),
            "{failure}"
        );
    }
    // Ordinary arguments of an invoked comptime body are available to that
    // invocation; their syntax alone does not make them future runtime reads.
    let package = compile(&format!(
        "{prefix}
        comptime fn Deferred(flag:bool)->Type {{defer Pick(flag)}}
        typealias Byte=Deferred(false);
        fn run()->Byte {{9}}"
    ));
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::UnsignedInteger(9)
    );
}

#[test]
fn writing_pointer_postconditions_refine_external_paths_and_forward_results() {
    let source="typealias Byte=.u8'builtin;struct Cell {value:Byte,other:Byte}
        fn set(p:*Byte) where ensures p.* == 41 {p.* = 41;}
        fn field(p:*Cell) where ensures p.value.* == 41 {p.value.* = 41;}
        fn alias(p:*Byte,.q:*Byte=p) where ensures q.* == 41 {q.* = 41;}
        fn clear(p:*bool) where ensures not p.* {p.* = false;}
        fn choose(p:*Byte,flag:bool)->result:Byte where ensures result == p.* and p.* < 255 {
            p.* = if flag {41} else {42};p.*
        }
        fn forward(p:*Byte)->Byte {set(p);p.* + 1}
        fn outer(p:*Byte)->Byte {alias(p);p.* + 1}
        fn fields(p:*Cell)->Byte {field(p);p.value.* + 1}
        fn projection(p:*Cell)->Byte {set(p.value);p.value.* + 1}
        fn cleared(p:*bool)->result:bool where ensures result {clear(p);not p.*}
        fn equal(p:*Byte,flag:bool)->result:bool where ensures result {let got=choose(p,flag);got == p.*}
        fn run()->bool {let value:Byte=255;let cell=Cell {value:255,other:255};let flag=true;
            forward(value.ref)==42 and outer(value.ref)==42 and fields(cell.ref)==42
                and projection(cell.ref)==42 and cleared(flag.ref) and equal(value.ref,true) and equal(value.ref,false)}";
    let package = compile(source);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    for invalid in [
        source.replace("field(p);p.value.* + 1", "field(p);p.other.* + 1"),
        source.replace("set(p);p.* + 1", "set(p);p.* = 255;p.* + 1"),
        source.replace("got == p.*", "do {p.* = 0;got == p.*}"),
    ] {
        let failure = compile_with_protocols(&invalid, &Default::default()).unwrap_err();
        assert!(failure.contains("not proven"), "{failure}");
    }
}

#[test]
fn external_postconditions_do_not_reuse_rebound_addresses_or_unproved_aliases() {
    let prefix = "typealias Byte=.u8'builtin;
        fn set(p:*Byte,flag:bool) where ensures p.* == 41 {p.* = 41;}";
    for body in [
        "fn bad(p:*Byte,q:*Byte)->Byte {set(p,true);q.* + 1}",
        "fn bad(p:*Byte,q:*Byte)->Byte {set(p,true);q.* = 255;p.* + 1}",
        "fn bad(p:*Byte,q:*Byte)->Byte {var pointer=p;set(pointer,do {pointer=q;true});pointer.* + 1}",
    ] {
        let failure =
            compile_with_protocols(&format!("{prefix}{body}"), &Default::default()).unwrap_err();
        assert!(failure.contains("not proven"), "{body}: {failure}");
    }
    let pointer_write = "typealias Byte=.u8'builtin;
        fn change(p:*Byte,slot:**Byte,next:*Byte) where ensures p.* == 41 {
            p.* = 41;slot.* = next;assumes p.* == 41;
        }
        fn bad(p:*Byte,q:*Byte)->Byte {var pointer=p;change(pointer,pointer.ref,q);pointer.* + 1}";
    let failure = compile_with_protocols(pointer_write, &Default::default()).unwrap_err();
    assert!(failure.contains("not proven"), "{failure}");
}

#[test]
fn memory_postconditions_export_relations_without_a_scalar_result() {
    let source = "typealias Byte=.u8'builtin;
        fn synchronize(p:*Byte,q:*Byte) where ensures p.* == q.* {
            q.* = p.*;assumes p.* == q.*;
        }
        fn ordered(p:*Byte,q:*Byte) where ensures p.* < q.* {
            p.* = 3;q.* = 4;assumes p.* < q.*;
        }
        fn equal(p:*Byte,q:*Byte)->result:bool where ensures result {
            synchronize(p,q);p.* == q.*
        }
        fn compare(p:*Byte,q:*Byte)->result:bool where ensures result {
            ordered(p,q);p.* < q.*
        }
        fn difference(p:*Byte,q:*Byte)->Byte {ordered(p,q);q.* - p.*}
        fn local()->result:bool where ensures result {
            var a:Byte=255;let b:Byte=0;synchronize(a.ref,b.ref);a == b
        }
        fn run()->bool {let a:Byte=17;let b:Byte=23;
            equal(a.ref,b.ref) and equal(a.ref,a.ref) and compare(a.ref,b.ref)
                and difference(a.ref,b.ref)==1 and local()}";
    let package = compile(source);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    for invalid in [
        source.replace(
            "synchronize(p,q);p.* == q.*",
            "synchronize(p,q);p.* = 0;p.* == q.*",
        ),
        source.replace("ordered(p,q);p.* < q.*", "ordered(p,q);q.* = 0;p.* < q.*"),
        source.replace("ordered(p,q);q.* - p.*", "ordered(p,q);p.* - q.*"),
        source.replace(
            "synchronize(a.ref,b.ref);a == b",
            "synchronize(a.ref,b.ref);a=0;a == b",
        ),
    ] {
        let failure = compile_with_protocols(&invalid, &Default::default()).unwrap_err();
        assert!(failure.contains("not proven"), "{failure}");
    }
}

#[test]
fn writing_memory_contracts_preserve_entry_snapshot_relations_through_wrappers() {
    let source="typealias Byte=.u8'builtin;
        fn put(p:*Byte,n:Byte) where ensures p.* == n'old {p.* = n;}
        fn forward(p:*Byte,n:Byte) where ensures p.* == n'old {put(p,n);}
        fn outer(p:*Byte,n:Byte) where ensures p.* == n'old {forward(p,n);}
        fn square(p:*Byte,n:Byte) where requires n <= 15, ensures p.* == n'old * n'old {p.* = n * n;}
        fn squared(p:*Byte,n:Byte) where requires n <= 15, ensures p.* == n'old * n'old {square(p,n);}
        fn cube(p:*Byte,n:Byte) where requires n <= 6, ensures p.* == n'old * n'old * n'old {p.* = n * n * n;}
        fn cubed(p:*Byte,n:Byte) where requires n <= 6, ensures p.* == n'old * n'old * n'old {cube(p,n);}
        fn run()->bool {let a:Byte=0;outer(a.ref,41);let first=a==41;
            squared(a.ref,12);let second=a==144;cubed(a.ref,6);first and second and a==216}";
    let package = compile(source);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    compile(&format!(
        "{source} fn changed(p:*Byte,n:Byte) where ensures p.* == n'old {{let saved=n;n=0;put(p,saved);}}"
    ));
    let changed = format!(
        "{source} fn rejected(p:*Byte,n:Byte) where ensures p.* == n {{let saved=n;n=0;put(p,saved);}}"
    );
    let failure = compile_with_protocols(&changed, &Default::default()).unwrap_err();
    assert!(
        failure.contains("postcondition") && failure.contains("not proven"),
        "{failure}"
    );
    for invalid in [
        source.replace("{put(p,n);}", "{put(p,n);p.* = 0;}"),
        source.replace("{square(p,n);}", "{put(p,n);}"),
        source.replace("{cube(p,n);}", "{square(p,n);}"),
    ] {
        let failure = compile_with_protocols(&invalid, &Default::default()).unwrap_err();
        assert!(
            failure.contains("postcondition") && failure.contains("not proven"),
            "{failure}"
        );
    }
}

