#[test]
fn local_only_loops_preserve_external_memory_facts() {
    let source="typealias Byte=.u8'builtin;
        fn read(p:*Byte)->Byte {p.*}
        fn counted(p:*Byte,count:Byte)->result:bool where ensures result {
            let before=p.*;var remaining=count;
            while remaining > 0 {remaining=remaining - 1;read(p);}
            before == p.*
        }
        fn bounded(p:*Byte,count:Byte)->Byte where requires p.* < 255 {
            var remaining=count;while remaining > 0 {remaining=remaining - 1;}
            p.* + 1
        }
        fn run()->bool {let value:Byte=41;counted(value.ref,0) and counted(value.ref,3) and bounded(value.ref,3)==42}";
    let package = compile(source);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    for body in [
        "fn bad(alias:fn(*Byte)->*Byte,count:Byte)->result:bool where ensures result {var value:Byte=41;let pointer=alias(value.ref);let before=pointer.*;var n=count;while n > 0 {n=n - 1;value=0;}before == pointer.*}",
        "fn bad(p:*Byte,q:*Byte,count:Byte)->result:bool where ensures result {let before=p.*;var n=count;while n > 0 {n=n - 1;q.* = 0;}before == p.*}",
        "fn bad(p:*Byte,q:*Byte,count:Byte)->result:bool where ensures result {var pointer=p;let before=pointer.*;var n=count;while n > 0 {n=n - 1;pointer=q;}before == pointer.*}",
        "fn bad(p:*Byte,q:*Byte,count:Byte)->Byte where requires p.* < 255 {var pointer=p;var n=count;while n > 0 {let next:Byte=pointer.* + 1;pointer=q;n=n - 1;}0}",
    ] {
        let failure = compile_with_protocols(
            &format!("typealias Byte=.u8'builtin;{body}"),
            &Default::default(),
        )
        .unwrap_err();
        assert!(failure.contains("not proven"), "{failure}");
    }
}

