#[test]
fn aggregate_result_contracts_preserve_written_memory_relations() {
    let source="typealias Byte=.u8'builtin;
        struct Output {value:Byte,input:Byte}
        struct Wrapped {inner:Output}
        fn set(p:*Byte,n:Byte)->result:Output where requires n < 255,
            ensures result.value == p.* and result.input == n'old and p.* < 255 {
                p.* = n;Output {value:p.*,input:n}
            }
        fn nested(p:*Byte,n:Byte)->result:Wrapped where requires n < 255,
            ensures result.inner.value == p.* and result.inner.input == n'old {
                p.* = n;Wrapped {inner:Output {value:p.*,input:n}}
            }
        fn same(p:*Byte,n:Byte)->result:bool where requires n < 255, ensures result {
            let got=set(p,n);got.value == p.* and got.input == n
        }
        fn deep(p:*Byte,n:Byte)->result:bool where requires n < 255, ensures result {
            let got=nested(p,n);got.inner.value == p.* and got.inner.input == n
        }
        fn next(p:*Byte,n:Byte)->Byte where requires n < 255 {set(p,n).value + 1}
        fn run()->bool {let value:Byte=255;same(value.ref,41) and deep(value.ref,41) and next(value.ref,41)==42}";
    let package = compile(source);
    assert_eq!(
        luna::execution::interpret(&package, "run", 100_000).unwrap(),
        Value::Bool(true)
    );
    for invalid in [
        source.replace("result.value == p.*", "result.value <= p.*"),
        source.replace("let got=set(p,n);", "let got=set(p,n);p.* = 0;"),
        source.replace("result.inner.input == n'old", "result.inner.input <= n'old"),
    ] {
        let failure = compile_with_protocols(&invalid, &Default::default()).unwrap_err();
        assert!(failure.contains("not proven"), "{failure}");
    }
}

