#[test]
fn divergent_loop_constant_match_keeps_only_reachable_breaks() {
    for body in [
        "while true {true match {true=>continue,false=>break}}",
        "while true {(not true) match {true=>break,false=>continue}}",
        "while true {true match {_=>continue}}",
        "while true {true match {true or false=>continue}}",
        "while true {(true,(false,true)) match {(true,(false,_))=>continue,_=>break}}",
        "while true {'x' match {'x'=>continue,_=>break}}",
        "while true {Number {value:9} match {{value:9}=>continue,_=>break}}",
        "while true {Packet {flag:true} match {{flag:true}=>continue,_=>break}}",
        "while true {Choice.some((true,false)) match {.none=>break,.some((true,false))=>continue,_=>break}}",
    ] {
        let package = execution_support::compile_with_tuple(&format!(
            "struct Packet {{flag:bool,}} struct Number {{value:.u8'builtin,}} enum Choice {{none,some(Tuple<bool,bool>)}} fn entry()->bool {{{body}}}"
        ));
        let mut vm = Interpreter::new(
            &package,
            Budget {
                steps: 100,
                ..Default::default()
            },
        )
        .unwrap();
        assert_eq!(
            vm.invoke(id(&package, "entry"), vec![]).unwrap_err().kind,
            ErrorKind::StepsExhausted,
            "{body}"
        );
    }
    for body in [
        "while true {flag match {true=>continue,false=>break}}",
        "while true {true match {true=>break,false=>continue}}",
        "while true {(true,flag) match {(true,true)=>continue,_=>break}}",
        "while true {(true,false) match {(true,true)=>continue,_=>break}}",
    ] {
        assert!(
            compile_with_protocols(
                &format!("fn entry(flag:bool)->bool {{{body}}}"),
                &Default::default()
            )
            .is_err(),
            "{body}"
        );
    }
    let package = execution_support::compile_with_tuple(
        "fn entry()->bool {while true {true match {true=>break,false=>continue}}true}",
    );
    assert_eq!(
        luna::execution::interpret(&package, "entry", 10_000).unwrap(),
        Value::Bool(true)
    );
}

#[test]
fn divergent_loop_executable_patterns_keep_lexical_exits() {
    for body in [
        "while true {true match {x and (do {break;}) is _=>continue,_=>continue}}",
        "while true {true match {true if do {break;}=>continue,_=>continue}}",
        "while true {(true,false) match {(true,_) if do {break;}=>continue,_=>continue}}",
        "var flag=true;while true {(true,do {break while flag;false}) match {(true,_)=>continue,_=>continue}}",
    ] {
        let package = compile(&format!("fn entry()->bool {{{body}true}}"));
        assert_eq!(
            luna::execution::interpret(&package, "entry", 10_000).unwrap(),
            Value::Bool(true),
            "{body}"
        );
    }
}

#[test]
fn compound_assignment_updates_local_fields_and_pointer_targets() {
    let package=compile("typealias Byte=.u8'builtin;struct Counter {value:Byte}
        fn update(pointer:*Byte) {assumes pointer.* < 100;pointer.* += 2;pointer.* *= 2;pointer.* -= 1;pointer.* /= 3;}
        fn entry()->bool {var value:Byte=4;value += 2;value *= 3;value -= 6;value /= 2;
            let counter=Counter {value:3};counter.value += 2;update(counter.value.ref);
            value == 6 and counter.value == 4}");
    assert_eq!(
        luna::execution::interpret(&package, "entry", 100_000).unwrap(),
        Value::Bool(true)
    );
}

#[test]
fn compound_assignment_evaluates_pointer_target_once_before_rhs() {
    let package=compile("typealias Byte=.u8'builtin;
        fn target(pointer:*Byte,hits:*Byte)->*Byte {assumes hits.* < 255;hits.* = hits.* + 1;pointer}
        fn entry()->bool {var value:Byte=3;var hits:Byte=0;
            target(value.ref,hits.ref).* += do {value=10;2};
            value == 5 and hits == 1}");
    assert_eq!(
        luna::execution::interpret(&package, "entry", 100_000).unwrap(),
        Value::Bool(true)
    );
}

#[test]
fn compound_assignment_preserves_mutability_and_range_checks() {
    for source in [
        "fn entry() {let value:.u8'builtin=1;value += 1;}",
        "fn entry() {var value:.u8'builtin=255;value += 1;}",
        "fn entry(pointer:*.u8'builtin) {pointer.* += 1;}",
        "fn entry() {var value:bool=true;value += false;}",
    ] {
        assert!(
            compile_with_protocols(source, &Default::default()).is_err(),
            "{source}"
        );
    }
}

#[test]
fn compound_assignment_alias_proofs_expire_on_rebinding_or_writes() {
    let valid = "typealias Byte=.u8'builtin;
        fn update(pointer:*Byte) {assumes pointer.* < 100;let alias=pointer;alias.* += 1;}
        fn entry()->bool {var value:Byte=3;update(value.ref);value == 4}";
    let package = compile(valid);
    assert_eq!(
        luna::execution::interpret(&package, "entry", 100_000).unwrap(),
        Value::Bool(true)
    );
    for body in [
        "assumes pointer.* < 100;var alias=pointer;alias=other;alias.* += 1;",
        "assumes pointer.* < 100;let alias=pointer;other.* = 255;alias.* += 1;",
        "assumes pointer.* < 100;var alias=pointer;if flag {alias=other;}alias.* += 1;",
    ] {
        let source = format!(
            "typealias Byte=.u8'builtin;fn update(pointer:*Byte,other:*Byte,flag:bool) {{{body}}}"
        );
        assert!(
            compile_with_protocols(&source, &Default::default()).is_err(),
            "{body}"
        );
    }
    for target in ["value", "pointer.*"] {
        let package = compile(&format!(
            "fn entry()->bool {{var value:.u8'builtin=3;let pointer=value.ref;{target} += do {{return true;}};}}"
        ));
        assert_eq!(
            luna::execution::interpret(&package, "entry", 100_000).unwrap(),
            Value::Bool(true)
        );
    }
}

#[test]
fn compound_remainder_assignment_runs_at_runtime_and_comptime() {
    for prefix in ["", "comptime "] {
        let package = compile(&format!(
            "typealias Byte=.u8'builtin;
            {prefix}fn calculate()->Byte {{var value:Byte=19;value %= 7;value}}
            {prefix}fn entry()->bool {{calculate() == 5}}"
        ));
        if prefix.is_empty() {
            assert_eq!(
                luna::execution::interpret(&package, "entry", 100_000).unwrap(),
                Value::Bool(true)
            );
        } else {
            assert_eq!(
                luna::invocation::invoke(&package, "entry", 100_000).unwrap(),
                Value::Bool(true)
            );
        }
    }
    let package = compile(
        "typealias Byte=.u8'builtin;
        fn update(pointer:*Byte,divisor:Byte) where requires divisor != 0 {pointer.* %= divisor;}
        fn entry()->bool {var value:Byte=19;update(value.ref,7);value == 5}",
    );
    assert_eq!(
        luna::execution::interpret(&package, "entry", 100_000).unwrap(),
        Value::Bool(true)
    );
    for source in [
        "fn entry() {var value:.u8'builtin=19;value %= 0;}",
        "fn entry() {let value:.u8'builtin=19;value %= 7;}",
        "fn entry() {var value:.i8'builtin=19;value %= 7;}",
    ] {
        assert!(
            compile_with_protocols(source, &Default::default()).is_err(),
            "{source}"
        );
    }
}

#[test]
fn literal_suffix_uses_explicit_protocol_and_contextual_result() {
    let source = "typealias Symbol=.Symbol'builtin; typealias Integer=.Integer'builtin;
        trait Convert where suffix:Symbol,R {comptime fn literal_into(comptime value:Self)->R;}
        impl Convert<.flag,bool> for Integer {comptime fn literal_into(comptime value:Integer)->bool {value == 42}}
        comptime fn run()->bool {42flag}";
    let package = compile_with_source_bindings(
        source,
        &Default::default(),
        luna::protocols::type_constructors::Selectors {
            literal_into: Some("input.Convert"),
            ..Default::default()
        },
    )
    .unwrap();
    let mut vm = Interpreter::new(&package, Budget::default()).unwrap();
    assert_eq!(
        vm.invoke(id(&package, "run"), vec![]).unwrap(),
        Value::Bool(true)
    );
    assert!(
        compile_with_protocols(source, &Default::default())
            .unwrap_err()
            .contains("bound LiteralInto")
    );
}

#[test]
fn literal_suffix_runtime_conversions_preserve_input_and_contracts() {
    for (ty, literal, expected) in [
        ("char", "'x'flag", "'x'"),
        ("str", "\"yes\"flag", "\"yes\""),
    ] {
        let source = format!("typealias Symbol=.Symbol'builtin;typealias Source=.{ty}'builtin;
            trait Convert where suffix:Symbol,R {{fn literal_into(comptime value:Self)->R;}}
            impl Convert<.flag,bool> for Source {{fn literal_into(comptime value:Source)->bool {{value == {expected}}}}}
            fn run()->bool {{{literal}}}");
        let selectors = luna::protocols::type_constructors::Selectors {
            literal_into: Some("input.Convert"),
            ..Default::default()
        };
        let package =
            compile_with_source_bindings(&source, &Default::default(), selectors).unwrap();
        assert_eq!(
            Interpreter::new(&package, Budget::default())
                .unwrap()
                .invoke(id(&package, "run"), vec![])
                .unwrap(),
            Value::Bool(true)
        );
        let invalid = source.replace("suffix:Symbol", "suffix");
        assert!(compile_with_source_bindings(&invalid, &Default::default(), selectors).is_err());
        let runtime_input = source.replace("comptime value:", "value:");
        let error = compile_with_source_bindings(&runtime_input, &Default::default(), selectors)
            .unwrap_err();
        assert!(
            error.contains("LiteralInto requires fn literal_into"),
            "{error}"
        );
        let missing = source.replace(".flag,bool", ".other,bool");
        assert!(compile_with_source_bindings(&missing, &Default::default(), selectors).is_err());
    }
}

