#[test]
fn memoized_nominal_value_index_keys_execute_protocols_and_preserve_type_identity() {
    use comptime_executor::Context;
    let package = compile(
        "const eq_key_phase={comptime_phase:true}; trait Eq {^eq_key_phase comptime fn eq(self,other:Self)->bool;}
         const hash_key_phase={comptime_phase:true}; trait Hash {^hash_key_phase comptime fn hash(self)->.u8'builtin;}
         struct Config {enabled:bool}
         struct Key where config:Config {value:bool}
         comptime impl Eq for Key<config> where config:Config {
             comptime fn eq(self,other:Self)->bool {self.value == other.value}
         }
         comptime impl Hash for Key<config> where config:Config {
             comptime fn hash(self)->.u8'builtin {0}
         }
         typealias Type=.Type'builtin; pure comptime fn Inspect(value:Key<Config{enabled:true}>)->Type {if value.value {bool} else {.u8'builtin}}",
    );
    let config = package
        .structs
        .iter()
        .find(|s| s.name == "Config")
        .unwrap()
        .declaration;
    let key = package
        .structs
        .iter()
        .find(|s| s.name == "Key")
        .unwrap()
        .declaration;
    let make = |enabled, value| Value::Record {
        declaration: key,
        arguments: vec![nir::Term::NominalValue {
            ty: Box::new(nir::Term::Nominal {
                declaration: config,
                arguments: vec![],
            }),
            variant: None,
            fields: vec![nir::Term::Bool(enabled)],
        }],
        fields: vec![Value::Bool(value)],
    };
    let mut invocation = memoized(&package, "Inspect", vec![], 8).unwrap();
    let mut context = Context::new(100_000);
    for (value, reused) in [(true, false), (false, false), (true, true), (false, true)] {
        let result = invocation
            .invoke(vec![make(true, value)], &mut context)
            .unwrap();
        assert_eq!(
            *result.value,
            Value::Type(nir::Term::Primitive(if value {
                nir::Primitive::Bool
            } else {
                nir::Primitive::U8
            }))
        );
        assert_eq!(result.reused, reused);
    }
    assert!(
        invocation
            .invoke(vec![make(false, true)], &mut context)
            .is_err()
    );
    assert_eq!(invocation.cached_results(), 2);
    let recovered = invocation
        .invoke(vec![make(true, true)], &mut context)
        .unwrap();
    assert!(recovered.reused);
    assert_eq!(
        *recovered.value,
        Value::Type(nir::Term::Primitive(nir::Primitive::Bool))
    );
    let mut exhausted = Context::new(0);
    assert!(
        invocation
            .invoke(vec![make(true, true)], &mut exhausted)
            .is_err()
    );
    assert_eq!(invocation.cached_results(), 2);
    let result = invocation
        .invoke(vec![make(true, false)], &mut context)
        .unwrap();
    assert!(result.reused);
    assert_eq!(
        *result.value,
        Value::Type(nir::Term::Primitive(nir::Primitive::U8))
    );
}

#[test]
fn concrete_runtime_entry_signatures_recheck_comptime_storage_after_substitution() {
    let package = compile(
        "fn consume(value:T) where T {} fn pointer(value:*T) where T {} struct Box where T {value:T} fn boxed(value:Box<T>) where T {} fn errors(value:!bool T) where T {}",
    );
    for entry in ["consume", "pointer", "boxed", "errors"] {
        for (primitive, accepted) in [
            (nir::Primitive::Bool, true),
            (nir::Primitive::Type, false),
            (nir::Primitive::Integer, false),
            (nir::Primitive::Float, false),
        ] {
            let result = elaboration::materialization::instantiate(
                &package,
                &[iir::InstanceKey {
                    declaration: id(&package, entry),
                    arguments: vec![nir::Term::Primitive(primitive)],
                }],
                Default::default(),
                Default::default(),
            );
            if accepted {
                result.unwrap();
            } else {
                assert!(
                    result.unwrap_err().contains("comptime-only"),
                    "{entry}: {primitive}"
                );
            }
        }
    }
}

#[test]
fn independent_iir_validation_uses_concrete_nominal_storage_not_phantom_arguments() {
    let package = compile(
        "struct Box where T {value:T} struct Phantom where T {flag:bool}
        fn boxed(value:Box<T>) where T {} fn phantom(value:Phantom<T>) where T {}",
    );
    let instantiate = |entry, argument| {
        elaboration::materialization::instantiate(
            &package,
            &[iir::InstanceKey {
                declaration: id(&package, entry),
                arguments: vec![argument],
            }],
            Default::default(),
            Default::default(),
        )
        .unwrap()
    };
    let mut graph = instantiate("boxed", nir::Term::Primitive(nir::Primitive::Bool));
    graph.validate(&mut 100_000).unwrap();
    let definition = graph
        .nominals
        .iter_mut()
        .find_map(|n| match &mut n.definition {
            iir::NominalDefinition::Struct(s) if s.name == "Box" => Some(s),
            _ => None,
        })
        .unwrap();
    definition.fields[0].1 = nir::Term::Primitive(nir::Primitive::Type);
    assert!(
        graph
            .validate(&mut 100_000)
            .unwrap_err()
            .contains("comptime-only")
    );
    let phantom = instantiate("phantom", nir::Term::Primitive(nir::Primitive::Type));
    phantom.validate(&mut 100_000).unwrap();
    let mut direct = phantom.clone();
    let nir::Term::Function { parameters, .. } = &mut direct.functions[0].function.signature else {
        unreachable!()
    };
    parameters[0].ty = nir::Term::Primitive(nir::Primitive::Type);
    assert!(
        direct
            .validate(&mut 100_000)
            .unwrap_err()
            .contains("comptime-only")
    );
}

#[test]
fn independent_iir_validation_rejects_comptime_local_storage_in_runtime_bodies() {
    let package = compile("fn entry() {}");
    let mut graph = luna::instantiation::instantiate(&package, "entry", 100_000).unwrap();
    let body = &mut graph.functions[0].function.body;
    let source = body.source;
    body.kind = nir::program::ExprKind::Block {
        statements: vec![nir::program::Expr {
            source,
            ty: nir::Term::Primitive(nir::Primitive::Void),
            kind: nir::program::ExprKind::Let {
                binding: nir::program::LocalId {
                    owner: 900,
                    index: 1,
                },
                value: Box::new(nir::program::Expr {
                    source,
                    ty: nir::Term::Primitive(nir::Primitive::Type),
                    kind: nir::program::ExprKind::TypeValue(nir::Term::Primitive(
                        nir::Primitive::Bool,
                    )),
                }),
            },
        }],
        result: None,
    };
    assert!(
        graph
            .validate(&mut 100_000)
            .unwrap_err()
            .contains("comptime-only")
    );
}

#[test]
fn comptime_key_membership_is_independent_of_callable_execution() {
    use elaboration::key_protocols::Operation;
    let ty = nir::Term::Primitive(nir::Primitive::Bool);
    let runtime = compile(
        "trait KeyCompare {comptime fn eq(self,other:Self)->bool;} impl KeyCompare for bool {comptime fn eq(self,other:bool)->bool {true}}",
    );
    assert!(
        key_method(&runtime, &ty, "KeyCompare", Operation::Eq)
            .unwrap_err()
            .contains("comptime trait membership")
    );
    let absent = compile(
        "const staged={comptime_phase:true}; trait KeyCompare {^staged comptime fn eq(self,other:Self)->bool {true}} impl KeyCompare for bool {}",
    );
    assert!(
        key_method(&absent, &ty, "KeyCompare", Operation::Eq)
            .unwrap_err()
            .contains("lacks comptime trait phase")
    );
}

#[test]
fn comptime_key_selection_never_falls_back_to_a_broader_phase() {
    use elaboration::key_protocols::Operation;
    let package = compile(
        "const staged={comptime_phase:true}; trait KeyCompare {^staged comptime fn eq(self,other:Self)->bool {true}} struct Cell where T {} comptime impl KeyCompare for Cell<T> where T {} impl KeyCompare for Cell<bool> {}",
    );
    let ty = nir::Term::Nominal {
        declaration: package.structs[0].declaration,
        arguments: vec![nir::Term::Primitive(nir::Primitive::Bool)],
    };
    assert!(
        key_method(&package, &ty, "KeyCompare", Operation::Eq)
            .unwrap_err()
            .contains("lacks comptime trait phase")
    );
    let other = nir::Term::Nominal {
        declaration: package.structs[0].declaration,
        arguments: vec![nir::Term::Primitive(nir::Primitive::U8)],
    };
    assert!(key_method(&package, &other, "KeyCompare", Operation::Eq).is_ok());
}

#[test]
fn memoized_invocation_non_type_results_skip_key_protocols() {
    let package = compile(
        "const eq_key_phase={comptime_phase:true};
        trait Eq {^eq_key_phase comptime fn eq(self,other:Self)->bool;}
        const hash_key_phase={comptime_phase:true};
        trait Hash {^hash_key_phase comptime fn hash(self)->.u8'builtin;}
        comptime impl Eq for bool {comptime fn eq(self,other:bool)->bool {assumes false;false}}
        comptime impl Hash for bool {comptime fn hash(self)->.u8'builtin {assumes false;0}}
        pure comptime fn negate(value:bool)->bool {not value}",
    );
    let mut call = memoized(&package, "negate", vec![], 8).unwrap();
    let mut remaining = None;
    for _ in 0..3 {
        let mut context = comptime_executor::Context::new(100_000);
        let result = call.invoke(vec![Value::Bool(true)], &mut context).unwrap();
        assert_eq!(*result.value, Value::Bool(false));
        assert!(!result.reused);
        assert_eq!(call.cached_results(), 0);
        if let Some(previous) = remaining {
            assert_eq!(context.remaining(), previous);
        }
        remaining = Some(context.remaining());
    }
    let bare = compile("pure comptime fn negate(value:bool)->bool {not value}");
    let mut call = memoized(&bare, "negate", vec![], 8).unwrap();
    assert_eq!(
        *call
            .invoke(
                vec![Value::Bool(true)],
                &mut comptime_executor::Context::new(100_000)
            )
            .unwrap()
            .value,
        Value::Bool(false)
    );
}

#[test]
fn memoized_invocation_admits_only_bound_type_results() {
    use nir::{Primitive, Term};
    let package = compile(
        "typealias Type=.Type'builtin;
        const eq_key_phase={comptime_phase:true};
        trait Eq {^eq_key_phase comptime fn eq(self,other:Self)->bool;}
        const hash_key_phase={comptime_phase:true};
        trait Hash {^hash_key_phase comptime fn hash(self)->.u8'builtin;}
        comptime impl Eq for Type {comptime fn eq(self,other:Type)->bool {self == other}}
        comptime impl Hash for Type {comptime fn hash(self)->.u8'builtin {0}}
        pure comptime fn keep(comptime T:Type,value:T)->T {value}
        pure comptime fn Make()->Type {bool}
        comptime fn Impure()->Type {bool}",
    );
    assert!(memoized(&package, "Impure", vec![], 8).is_err());
    let mut call = memoized(&package, "keep", vec![], 8).unwrap();
    let ty = |p| Value::Type(Term::Primitive(p));
    let mut context = comptime_executor::Context::new(1_000_000);
    for reused in [false, true] {
        let result = call
            .invoke(vec![ty(Primitive::Type), ty(Primitive::Bool)], &mut context)
            .unwrap();
        assert_eq!(*result.value, ty(Primitive::Bool));
        assert_eq!(result.reused, reused);
    }
    for _ in 0..2 {
        let result = call
            .invoke(vec![ty(Primitive::Bool), Value::Bool(true)], &mut context)
            .unwrap();
        assert_eq!(*result.value, Value::Bool(true));
        assert!(!result.reused);
        assert_eq!(call.cached_results(), 1);
    }
    assert!(
        call.invoke(vec![ty(Primitive::Type), ty(Primitive::Bool)], &mut context)
            .unwrap()
            .reused
    );
    let mut make = memoized(&package, "Make", vec![], 8).unwrap();
    assert!(!make.invoke(vec![], &mut context).unwrap().reused);
    assert!(make.invoke(vec![], &mut context).unwrap().reused);
}
